--
-- Name: hr_skill_level; Type: TABLE; Schema: public; Owner: odoo
--

CREATE TABLE public.hr_skill_level (
    id integer NOT NULL,
    skill_type_id integer,
    level_progress integer,
    create_uid integer,
    write_uid integer,
    name character varying NOT NULL,
    default_level boolean,
    create_date timestamp without time zone,
    write_date timestamp without time zone,
    CONSTRAINT hr_skill_level_check_level_progress CHECK (((level_progress >= 0) AND (level_progress <= 100)))
);


ALTER TABLE public.hr_skill_level OWNER TO odoo;

--
-- Name: TABLE hr_skill_level; Type: COMMENT; Schema: public; Owner: odoo
--

