COPY public.digest_tip (id, sequence, group_id, create_uid, write_uid, name, tip_description, create_date, write_date) FROM stdin;
1	800	1	1	1	{"en_US": "Tip: Speed up your workflow with shortcuts", "es_AR": "Consejo: acelere su flujo de trabajo con atajos"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Speed up your workflow with shortcuts</p>\\n    <p class=\\"tip_content\\">Press ALT in any screen to highlight shortcuts for every button in the screen. It is useful to process multiple documents in batch.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-alt-shortcuts.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_AR": "<div>\\n    <p class=\\"tip_title\\">Consejo: acelere su flujo de trabajo con atajos</p>\\n    <p class=\\"tip_content\\">Presione ALT en cualquier pantalla para destacar atajos para cada botón en la pantalla. Es útil para procesar varios documentos en lote. </p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-alt-shortcuts.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-10-23 14:02:44.270491	2026-10-23 14:02:44.270491
2	2100	1	1	1	{"en_US": "Tip: Click on an avatar to chat with a user", "es_AR": "Consejo: haga clic en un avatar para chatear con un usuario"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Click on an avatar to chat with a user</p>\\n    <p class=\\"tip_content\\">Have a question about a document? Click on the responsible user's picture to start a conversation. If his avatar has a green dot, he is online.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-avatar.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_AR": "<div>\\n    <p class=\\"tip_title\\">Consejo: haga clic en un avatar para chatear con un usuario</p>\\n    <p class=\\"tip_content\\">¿Tiene una pregunta sobre el documento? Haga clic en la fotografía del usuario responsable para iniciar una conversación. Si el avatar tiene un punto verde significa que el usuario está en línea.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-avatar.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-10-23 14:02:44.270491	2026-10-23 14:02:44.270491
3	2300	1	1	1	{"en_US": "Tip: A calculator in Odoo", "es_AR": "Consejo: una calculadora en Odoo"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: A calculator in Odoo</p>\\n    <p class=\\"tip_content\\">When editing a number, you can use formulae by typing the `=` character. This is useful when computing a margin or a discount on a quotation, sale order or invoice.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-calculator.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_AR": "<div>\\n    <p class=\\"tip_title\\">Consejo: una calculadora en Odoo</p>\\n    <p class=\\"tip_content\\">Cuando edite un número, puede utilizar fórmulas al escribir el carácter `=`. Esto es útil cuando calcula un margen o un descuento en una cotización, orden de venta o factura.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-calculator.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-10-23 14:02:44.270491	2026-10-23 14:02:44.270491
4	2400	1	1	1	{"en_US": "Tip: How to ping users in internal notes?", "es_AR": "Consejo: ¿cómo notificar usuarios en las notas internas?"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: How to ping users in internal notes?</p>\\n    <p class=\\"tip_content\\">Type \\"@\\" to notify someone in a message, or \\"#\\" to link to a channel. Try to notify @OdooBot to test the feature.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-notifications.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_AR": "<div>\\n    <p class=\\"tip_title\\">Consejo: ¿cómo notificar usuarios en las notas internas?</p>\\n    <p class=\\"tip_content\\">Escriba \\"@\\" para enviar una notificación a alguien por medio de un mensaje, o \\"#\\" para vincular un canal. Intente enviar una notificación a @OdooBot para probar esta función.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-notifications.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-10-23 14:02:44.270491	2026-10-23 14:02:44.270491
5	2500	1	1	1	{"en_US": "Tip: Knowledge is power", "es_AR": "Consejo: el conocimiento es poder"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Knowledge is power</p>\\n    <p class=\\"tip_content\\">When following documents, use the pencil icon to fine-tune the information you want to receive.\\nFollow a project / sales team to keep track of this project's tasks / this team's opportunities.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-following.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_AR": "<div>\\n    <p class=\\"tip_title\\">Consejo: el conocimiento es poder</p>\\n    <p class=\\"tip_content\\">Cuando siga documentos, use el icono de lápiz para ajustar la información que desea recibir.\\nSiga un proyecto o un equipo de ventas para llevar el seguimiento de las tareas de este proyecto o las oportunidades de este equipo.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-following.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-10-23 14:02:44.270491	2026-10-23 14:02:44.270491
6	700	23	1	1	{"en_US": "Tip: No need to print, put in an envelop and post your invoices", "es_AR": "Consejo: no es necesario que imprima, ponga en un sobre y envíe sus facturas"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: No need to print, put in an envelop and post your invoices</p>\\n    <p class=\\"tip_content\\">Use the “<i>Send by Post</i>” option to post invoices automatically. For the cost of a local stamp, we do all the manual work: your invoice will be printed in the right country, put in an envelop and sent by snail mail. Use this feature from the list view to post hundreds of invoices in bulk.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/account/static/src/img/invoice-stamps.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_AR": "<div>\\n    <p class=\\"tip_title\\">Consejo: no es necesario que imprima, ponga en un sobre y envíe sus facturas</p>\\n    <p class=\\"tip_content\\">Utilice la opción \\"<i>enviar por correo</i>\\" para registrar facturas automáticamente. Por el costo de un sello local, hacemos todo el trabajo manual: su factura se imprimirá en el país correcto, se colocará en un sobre y se enviará por correo postal. Utilice esta función de la vista de lista para registrar cientos de facturas de forma masiva.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/account/static/src/img/invoice-stamps.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-10-23 14:02:50.18711	2026-10-27 18:37:36.443122
8	2000	34	1	1	{"en_US": "Tip: Never miss a purchase order", "es_AR": "Consejo: nunca pierda una orden de compra"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Never miss a purchase order</p>\\n    <p class=\\"tip_content\\">When sending a purchase order by email, Odoo asks the vendor to acknowledge the reception of the order. When the vendor acknowledges the order by clicking on a button in the email, the information is added on the purchase order. Use filters to track orders that have not been acknowledged.</p>\\n</div>\\n            ", "es_AR": "<div>\\n    <p class=\\"tip_title\\">Consejo: nunca pierda una orden de compra</p>\\n    <p class=\\"tip_content\\">Odoo le solicita al proveedor que confirme la recepción de la orden de compra cuando la envía por correo electrónico. La información se agrega a la orden de compra cuando el proveedor acepta a través del botón en el correo. Utilice filtros para llevar seguimiento de las órdenes sin confirmar.</p>\\n</div>\\n            "}	2026-10-30 14:04:17.038965	2026-10-30 14:04:17.038965
11	1000	47	1	1	{"en_US": "Tip: Speed up inventory operations with barcodes", "es_AR": "Consejo: acelere las operaciones de inventario con códigos de barras"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Speed up inventory operations with barcodes</p>\\n    <table class=\\"tip_twocol\\">\\n        <tr>\\n            <td class=\\"tip_twocol_left\\" style=\\"width: 45%;\\">\\n                <img src=\\"https://download.odoocdn.com/digests/stock/static/src/img/barcode.gif\\" class=\\"tip_twocol_img\\" width=\\"240\\">\\n            </td>\\n            <td style=\\"width: 55%;\\">\\n                <p class=\\"tip_content\\" style=\\"margin: 0;\\">Enjoy a quick-paced experience with the Odoo barcode app. It is blazing fast and works even without a stable internet connection. It supports all flows: inventory adjustments, batch picking, moving lots or pallets, low inventory checks, etc. Go to the \\"Apps\\" menu to activate the barcode interface.</p>\\n            </td>\\n        </tr>\\n    </table>\\n    <div style=\\"clear: both;\\"></div>\\n</div>\\n            ", "es_AR": "<div>\\n    <p class=\\"tip_title\\">Consejo: acelere las operaciones de inventario con códigos de barras</p>\\n    <table class=\\"tip_twocol\\">\\n        <tr>\\n            <td class=\\"tip_twocol_left\\" style=\\"width: 45%;\\">\\n                <img src=\\"https://download.odoocdn.com/digests/stock/static/src/img/barcode.gif\\" class=\\"tip_twocol_img\\" width=\\"240\\">\\n            </td>\\n            <td style=\\"width: 55%;\\">\\n                <p class=\\"tip_content\\" style=\\"margin: 0;\\">Disfrute de una experiencia de ritmo rápido con la aplicación Código de barras de Odoo. Es increíblemente rápida y funciona incluso sin una conexión a internet estable. Es compatible con todos los flujos: ajustes de inventario, recolección por lotes, movimientos por lotes o pallets, controles de inventario bajo, etc. Vaya al menú \\"Aplicaciones\\" para activar la interfaz de código de barras.</p>\\n            </td>\\n        </tr>\\n    </table>\\n    <div style=\\"clear: both;\\"></div>\\n</div>\\n            "}	2026-10-30 14:36:05.772217	2026-10-30 14:36:05.772217
9	2200	40	1	1	{"en_US": "Tip: Odoo supports configurable products", "es_AR": "Consejo: Odoo permite configurar los productos"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Odoo supports configurable products</p>\\n    <p class=\\"tip_content\\">Struggling with a complex product catalog? Try out the Product Configurator to help sales configure a product with different options: colors, size, capacity, etc. Make sale orders encoding easier and error-proof.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/sale_management/static/src/img/milk-Sales-configure-products.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_AR": "<div>\\n    <p class=\\"tip_title\\">Consejo: Odoo permite configurar los productos</p>\\n    <p class=\\"tip_content\\">¿Se le dificulta gestionar un catálogo complejo? Use el configurador de producto para ayudar a que ventas configure las diferentes opciones de productos: colores, tamaño, capacidad, etc. Facilite y evite errores al codificar órdenes de venta.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/sale_management/static/src/img/milk-Sales-configure-products.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-10-30 14:24:33.935295	2026-10-30 14:24:33.935295
