234	\N	\N	2026-10-30 15:05:20.129478	1		{"en_US": "Features for Italian eCommerce eInvoicing", "es_AR": "Funciones para la facturación electrónica y el comercio electrónico en Italia"}	l10n_it_edi_website_sale	Odoo S.A.	/base/static/description/icon.png	uninstalled	\N	{"en_US": "Italy eCommerce eInvoicing", "es_AR": "Facturación electrónica en Comercio electrónico para Italia"}	41	{"en_US": "\\nContains features for Italian eCommerce eInvoicing\\n", "es_AR": "\\nContiene todas las funciones para la facturación electrónica de comercio electrónico en Italia.\\n"}	f	f	f	OEEL-1	100	t	f	\N	\N	\N	\N				official	\N
