roup_public_id\\" invisible=\\"channel_type != 'channel'\\"/>\\n                                    <field name=\\"group_ids\\" widget=\\"many2many_tags\\" invisible=\\"channel_type != 'channel'\\" string=\\"Auto Subscribe Groups\\"/>\\n                                </group>\\n                            </page>\\n                            <page string=\\"Members\\" name=\\"members\\">\\n                                <field name=\\"channel_type\\" invisible=\\"1\\"/>\\n                                <field name=\\"channel_member_ids\\" mode=\\"tree\\" context=\\"{'active_test': False}\\" readonly=\\"channel_type == 'chat'\\">\\n                                    <tree string=\\"Members\\" editable=\\"bottom\\">\\n                                        <field name=\\"partner_id\\" readonly=\\"id or guest_id\\" required=\\"not guest_id\\"/>\\n                                        <field name=\\"guest_id\\" readonly=\\"id or partner_id\\" required=\\"not partner_id\\"/>\\n                                    </tree>\\n                                </field>\\n                            </page>\\n                            <page string=\\"Integrations\\" invisible=\\"1\\" name=\\"discuss_channel_integrations\\"/>\\n                        </notebook>\\n                    </sheet>\\n                </form>", "es_AR": "<form string=\\"Formulario del canal de correo\\">\\n                    <sheet>\\n                        <div class=\\"oe_button_box\\" name=\\"button_box\\"/>\\n                        <field name=\\"avatar_128\\" invisible=\\"1\\"/>\\n                        <field name=\\"is_editable\\" invisible=\\"1\\"/>\\n                        <field name=\\"image_128\\" widget=\\"image\\" class=\\"oe_avatar\\" options=\\"{'size': [90, 90], 'preview_image':'avatar_128'}\\" readonly=\\"not is_editable\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Archivado\\" bg_color=\\"text-bg-danger\\" invisible=\\"active\\"/>\\n                        <div class=\\"oe_title\\">\\n                            <label for=\\"name\\" string=\\"Nombre del grupo\\"/>\\n                            <h1>\\n                                #<field name=\\"name\\" class=\\"oe_inline\\" default_focus=\\"1\\" placeholder=\\"Por ejemplo, asistencia\\" readonly=\\"0\\"/>\\n                            </h1>\\n                        </div>\\n                        <group class=\\"o_label_nowrap\\">\\n                            <field name=\\"active\\" invisible=\\"1\\"/>\\n                            <field name=\\"channel_type\\" groups=\\"base.group_no_one\\"/>\\n                            <field name=\\"description\\" placeholder=\\"Temas abordados en este grupo...\\"/>\\n                        </group>\\n                        <group class=\\"o_label_nowrap\\" groups=\\"base.group_no_one\\">\\n                            <field name=\\"sfu_channel_uuid\\"/>\\n                            <field name=\\"sfu_server_url\\"/>\\n                        </group>\\n                        <notebook>\\n                            <page string=\\"Privacidad\\" name=\\"privacy\\">\\n                                <group class=\\"o_label_nowrap\\">\\n                                    <field name=\\"group_public_id\\" invisible=\\"channel_type != 'channel'\\"/>\\n                                    <field name=\\"group_ids\\" widget=\\"many2many_tags\\" invisible=\\"channel_type != 'channel'\\" string=\\"Grupos de suscripción automática\\"/>\\n                                </group>\\n                            </page>\\n                            <page string=\\"Miembros\\" name=\\"members\\">\\n                                <field name=\\"channel_type\\" invisible=\\"1\\"/>\\n                                <field name=\\"channel_member_ids\\" mode=\\"tree\\" context=\\"{'active_test': False}\\" readonly=\\"channel_type == 'chat'\\">\\n                                    <tree string=\\"Miembros\\" editable=\\"bottom\\">\\n                                        <field name=\\"partner_id\\" readonly=\\"id or guest_id\\" required=\\"not guest_id\\"/>\\n                                        <field name=\\"guest_id\\" readonly=\\"id or partner_id\\" required=\\"not partner_id\\"/>\\n                                    </tree>\\n                                </field>\\n                            </page>\\n                            <page string=\\"Integraciones\\" invisible=\\"1\\" name=\\"discuss_channel_integrations\\"/>\\n                        </notebook>\\n                    </sheet>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Mail Channel Form">\n                    <sheet>\n                        <div class="oe_button_box" name="button_box"/>\n                        <field name="avatar_128" invisible="1"/>\n                        <field name="is_editable" invisible="1"/>\n                        <field name="image_128" widget="image" class="oe_avatar" options="{'size': [90, 90], 'preview_image':'avatar_128'}" readonly="not is_editable"/>\n                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>\n                        <div class="oe_title">\n                            <label for="name" string="Group Name"/>\n                            <h1>\n                                #<field name="name" class="oe_inline" default_focus="1" placeholder="e.g. support" readonly="0"/>\n                            </h1>\n                        </div>\n                        <group class="o_label_nowrap">\n                            <field name="active" invisible="1"/>\n                            <field name="channel_type" groups="base.group_no_one"/>\n                            <field name="description" placeholder="Topics discussed in this group..."/>\n                        </group>\n                        <group class="o_label_nowrap" groups="base.group_no_one">\n                            <field name="sfu_channel_uuid"/>\n                            <field name="sfu_server_url"/>\n                        </group>\n                        <notebook>\n                            <page string="Privacy" name="privacy">\n                                <group class="o_label_nowrap">\n                                    <field name="group_public_id" invisible="channel_type != 'channel'"/>\n                                    <field name="group_ids" widget="many2many_tags" invisible="channel_type != 'channel'" string="Auto Subscribe Groups"/>\n                                </group>\n                            </page>\n                            <page string="Members" name="members">\n                                <field name="channel_type" invisible="1"/>\n                                <field name="channel_member_ids" mode="tree" context="{'active_test': False}" readonly="channel_type == 'chat'">\n                                    <tree string="Members" editable="bottom">\n                                        <field name="partner_id" readonly="id or guest_id" required="not guest_id"/>\n                                        <field name="guest_id" readonly="id or partner_id" required="not partner_id"/>\n                                    </tree>\n                                </field>\n                            </page>\n                            <page string="Integrations" invisible="1" name="discuss_channel_integrations"/>\n                        </notebook>\n                    </sheet>\n                </form>\n            	f	t	2026-10-23 14:02:28.100935	2026-10-23 14:02:28.100935	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
17	16	\N	1	1	Server Action	ir.actions.server	\N	form	base/views/ir_actions_views.xml	primary	{"en_US": "<form string=\\"Server Action\\">\\n                    <header>\\n                        <field name=\\"binding_model_id\\" invisible=\\"1\\"/>\\n                        <button name=\\"create_action\\" string=\\"Create Contextual Action\\" type=\\"object\\" class=\\"btn-primary\\" invisible=\\"binding_model_id\\" help=\\"Display an option in the 'More' top-menu in order to run this action.\\"/>\\n                        <button name=\\"unlink_action\\" string=\\"Remove Contextual Action\\" type=\\"object\\" invisible=\\"not binding_model_id\\" help=\\"Remove 'More' top-menu contextual action related to this action\\"/>\\n                        <button name=\\"run\\" string=\\"Run\\" type=\\"object\\" class=\\"btn-primary\\" invisible=\\"model_name != 'ir.actions.server' or state != 'code'\\" help=\\"Run this action manually.\\"/>\\n                    </header>\\n                    <sheet>\\n                        <h1 class=\\"oe_title\\">\\n                            <field name=\\"name\\" placeholder=\\"e.g. Mass archive contacts\\"/>\\n                        </h1>\\n                        <div class=\\"d-flex flex-column\\">\\n                            <label for=\\"state\\"/>\\n                            <field name=\\"state\\" widget=\\"selection_badge\\" options=\\"{'size': 'sm'}\\"/>\\n                        </div>\\n                        <group string=\\"Technical Settings\\" groups=\\"base.group_no_one\\">\\n                            <group>\\n                                <field name=\\"model_id\\" options=\\"{'no_create': True, 'no_open': True}\\"/>\\n                                <field name=\\"groups_id\\" widget=\\"many2many_tags\\"/>\\n                            </group>\\n                        </group>\\n                        <separator string=\\"Action Details\\" groups=\\"base.group_no_one\\"/>\\n                        <div class=\\"d-flex flex-row flex-wrap gap-2\\" invisible=\\"state != 'object_write'\\">\\n                            <field name=\\"evaluation_type\\" class=\\"oe_inline\\"/>\\n                            <field name=\\"update_path\\" widget=\\"DynamicModelFieldSelectorChar\\" class=\\"oe_inline\\" options=\\"{'model': 'model_name'}\\"/>\\n                            <field name=\\"update_field_id\\" invisible=\\"1\\"/>\\n                            <field name=\\"value_field_to_show\\" invisible=\\"1\\"/>\\n                            <field name=\\"update_related_model_id\\" invisible=\\"1\\"/>\\n                            <field name=\\"update_field_type\\" invisible=\\"1\\"/>\\n                            <span invisible=\\"evaluation_type != 'value' or update_field_type not in ['one2many', 'many2many']\\">by</span>\\n                            <field name=\\"update_m2m_operation\\" class=\\"oe_inline\\" invisible=\\"evaluation_type != 'value' or update_field_type not in ['one2many', 'many2many']\\" required=\\"update_field_type in ['one2many', 'many2many']\\"/>\\n                            <span invisible=\\"evaluation_type != 'value' or update_field_type in ['one2many', 'many2many']\\">to</span>\\n                            <field name=\\"value\\" class=\\"oe_inline\\" placeholder=\\"Set a value...\\" invisible=\\"update_field_id == False or value_field_to_show != 'value' or evaluation_type != 'value'\\" string=\\"Custom Value\\"/>\\n                            <field name=\\"resource_ref\\" class=\\"oe_inline\\" placeholder=\\"Choose a value...\\" string=\\"Custom Value\\" options=\\"{'model_field': 'update_related_model_id', 'no_create': True, 'no_open': True}\\" invisible=\\" update_field_id == False or value_field_to_show != 'resource_ref' or evaluation_type == 'equation' or update_m2m_operation == 'clear'\\"/>\\n                            <field name=\\"selection_value\\" class=\\"oe_inline\\" placeholder=\\"Choose a value...\\" options=\\"{'no_create': True, 'no_open': True}\\" invisible=\\" update_field_id == False or value_field_to_show != 'selection_value' or evaluation_type == 'equation'\\"/>\\n                            <field name=\\"update_boolean_value\\" class=\\"oe_inline\\" invisible=\\"evaluation_type != 'value' or value_field_to_show != 'update_boolean_value'\\" required=\\"value_field_to_show == 'update_boolean_value'\\"/>\\n                            <span invisible=\\"update_field_id != False or evaluation_type == 'equation'\\" class=\\"text-muted\\">Set a value...</span>\\n                            <span invisible=\\"evaluation_type != 'equation'\\">\\n                                to this Python expression:\\n                            </span>\\n                            <div class=\\"w-100 d-flex flex-row gap-3\\" invisible=\\"evaluation_type != 'equation'\\">\\n                                <field name=\\"value\\" class=\\"w-50\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\" string=\\"Expression\\"/>\\n                                <div class=\\"w-50 opacity-75\\">\\n                                    <span colspan=\\"2\\" class=\\"text-muted\\"> Available variables: </span>\\n                                        <ul colspan=\\"2\\" class=\\"text-muted\\">\\n                                            <li><code>env</code>: environment on which the action is triggered</li>\\n                                            <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>\\n                                            <li><code>record</code>: record on which the action is triggered</li>\\n                                            <li><code>records</code>: recordset of all records on which the action is triggered in multi mode</li>\\n                                            <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>\\n                                            <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>\\n                                        </ul>\\n                                </div>\\n                            </div>\\n                        </div>\\n                        <group name=\\"action_wrapper\\">\\n                            <group name=\\"action_content\\">\\n                                <field name=\\"model_name\\" invisible=\\"1\\"/>\\n                                <field name=\\"available_model_ids\\" invisible=\\"1\\"/>\\n                                <field name=\\"model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" groups=\\"!base.group_no_one\\" invisible=\\"context.get('default_model_id')\\" domain=\\"[('id', 'in', available_model_ids)]\\"/>\\n\\n                                <field name=\\"type\\" invisible=\\"1\\"/>\\n                                <field name=\\"crud_model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" invisible=\\"state != 'object_create'\\" required=\\"state == 'object_create'\\"/>\\n                                <field name=\\"crud_model_name\\" invisible=\\"1\\"/>\\n                                <field name=\\"value\\" widget=\\"char\\" string=\\"Name\\" invisible=\\"state != 'object_create'\\" help=\\"The name of the record to create\\" placeholder=\\"e.g. Follow-up\\"/>\\n                                <field name=\\"link_field_id\\" domain=\\"[('model_id', '=', model_id), ('relation', '=', crud_model_name),                                     ('ttype', 'in', ['many2one', 'one2many', 'many2many'])]\\" placeholder=\\"Select a field to link the record to\\" options=\\"{'no_create': True, 'no_open': True}\\" invisible=\\"state != 'object_create'\\" context=\\"{'default_model_id': model_id, 'default_relation': crud_model_name}\\"/>\\n                                    <field name=\\"webhook_url\\" string=\\"URL\\" invisible=\\"state != 'webhook'\\" placeholder=\\"e.g. https://maker.ifttt.com/use/...\\"/>\\n                                    <field name=\\"webhook_field_ids\\" string=\\"Fields\\" invisible=\\"state != 'webhook'\\" widget=\\"many2many_tags\\" context=\\"{'hide_model': 1}\\" domain=\\"[('model_id', '=', model_id)]\\" placeholder=\\"Select fields to include in the request...\\"/>\\n                                </group>\\n                                <group invisible=\\"state != 'webhook'\\">\\n                                    <label for=\\"webhook_sample_payload\\"/>\\n                                    <field name=\\"webhook_sample_payload\\" string=\\"Sample Payload\\" nolabel=\\"1\\" colspan=\\"2\\" readonly=\\"1\\" widget=\\"code\\" options=\\"{'mode': 'js'}\\"/>\\n                                </group>\\n                        </group>\\n                        <field name=\\"child_ids\\" domain=\\"[('model_id', '=', model_id)]\\" invisible=\\"state != 'multi'\\"/>\\n                        <p class=\\"oe_grey\\" invisible=\\"state != 'multi'\\">\\n                            If several child actions return an action, only the last one will be executed.\\n                            This may happen when having server actions executing code that returns an action, or server actions returning a client action.\\n                        </p>\\n                        <notebook invisible=\\"state != 'code'\\">\\n                            <page string=\\"Code\\">\\n                                <field name=\\"code\\" invisible=\\"state != 'code'\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\" placeholder=\\"Enter Python code here. Help about Python expression is available in the help tab of this document.\\"/>\\n                            </page>\\n                            <page string=\\"Help\\">\\n                                <p>The following variables can be used:</p>\\n                                <ul>\\n                                    <li><code>env</code>: environment on which the action is triggered</li>\\n                                    <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>\\n                                    <li><code>record</code>: record on which the action is triggered; may be be void</li>\\n                                    <li><code>records</code>: recordset of all records on which the action is triggered in multi mode; may be void</li>\\n                                    <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>\\n                                    <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>\\n                                    <li><code>log(message, level='info')</code>: logging function to record debug information in <code>ir.logging</code> table</li>\\n                                    <li><code>_logger.info(message)</code>: logger to emit messages in server logs</li>\\n                                    <li><code>UserError</code>: exception class for raising user-facing warning messages</li>\\n                                    <li><code>Command</code>: x2many commands namespace</li>\\n                                    <li>To return an action, assign: <code>action = {...}</code></li>\\n                                </ul>\\n                                <div>\\n                                    <p>Example of Python code:</p>\\n<pre style=\\"white-space: pre-wrap\\">partner_name = record.name + '_code'\\nenv['res.partner'].create({'name': partner_name})\\n    </pre>\\n                                </div>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                </form>", "es_AR": "<form string=\\"Acción del servidor\\">\\n                    <header>\\n                        <field name=\\"binding_model_id\\" invisible=\\"1\\"/>\\n                        <button name=\\"create_action\\" string=\\"Crear acción contextual\\" type=\\"object\\" class=\\"btn-primary\\" invisible=\\"binding_model_id\\" help=\\"Mostrar una opción en el menú superior &quot;Más&quot; para ejecutar esta acción.\\"/>\\n                        <button name=\\"unlink_action\\" string=\\"Eliminar la acción contextual\\" type=\\"object\\" invisible=\\"not binding_model_id\\" help=\\"Elimine la acción contextual del menú superior &quot;Más&quot; relacionada con esta acción\\"/>\\n                        <button name=\\"run\\" string=\\"Ejecutar\\" type=\\"object\\" class=\\"btn-primary\\" invisible=\\"model_name != 'ir.actions.server' or state != 'code'\\" help=\\"Ejecutar esta acción de forma manual\\"/>\\n                    </header>\\n                    <sheet>\\n                        <h1 class=\\"oe_title\\">\\n                            <field name=\\"name\\" placeholder=\\"Por ejemplo, Archivar contactos de forma masiva\\"/>\\n                        </h1>\\n                        <div class=\\"d-flex flex-column\\">\\n                            <label for=\\"state\\"/>\\n                            <field name=\\"state\\" widget=\\"selection_badge\\" options=\\"{'size': 'sm'}\\"/>\\n                        </div>\\n                        <group string=\\"Ajustes técnicos\\" groups=\\"base.group_no_one\\">\\n                            <group>\\n                                <field name=\\"model_id\\" options=\\"{'no_create': True, 'no_open': True}\\"/>\\n                                <field name=\\"groups_id\\" widget=\\"many2many_tags\\"/>\\n                            </group>\\n                        </group>\\n                        <separator string=\\"Detalles de la acción\\" groups=\\"base.group_no_one\\"/>\\n                        <div class=\\"d-flex flex-row flex-wrap gap-2\\" invisible=\\"state != 'object_write'\\">\\n                            <field name=\\"evaluation_type\\" class=\\"oe_inline\\"/>\\n                            <field name=\\"update_path\\" widget=\\"DynamicModelFieldSelectorChar\\" class=\\"oe_inline\\" options=\\"{'model': 'model_name'}\\"/>\\n                            <field name=\\"update_field_id\\" invisible=\\"1\\"/>\\n                            <field name=\\"value_field_to_show\\" invisible=\\"1\\"/>\\n                            <field name=\\"update_related_model_id\\" invisible=\\"1\\"/>\\n                            <field name=\\"update_field_type\\" invisible=\\"1\\"/>\\n                            <span invisible=\\"evaluation_type != 'value' or update_field_type not in ['one2many', 'many2many']\\">por</span>\\n                            <field name=\\"update_m2m_operation\\" class=\\"oe_inline\\" invisible=\\"evaluation_type != 'value' or update_field_type not in ['one2many', 'many2many']\\" required=\\"update_field_type in ['one2many', 'many2many']\\"/>\\n                            <span invisible=\\"evaluation_type != 'value' or update_field_type in ['one2many', 'many2many']\\">para</span>\\n                            <field name=\\"value\\" class=\\"oe_inline\\" placeholder=\\"Establezca un valor...\\" invisible=\\"update_field_id == False or value_field_to_show != 'value' or evaluation_type != 'value'\\" string=\\"Valor personalizado\\"/>\\n                            <field name=\\"resource_ref\\" class=\\"oe_inline\\" placeholder=\\"Elija un valor...\\" string=\\"Valor personalizado\\" options=\\"{'model_field': 'update_related_model_id', 'no_create': True, 'no_open': True}\\" invisible=\\" update_field_id == False or value_field_to_show != 'resource_ref' or evaluation_type == 'equation' or update_m2m_operation == 'clear'\\"/>\\n                            <field name=\\"selection_value\\" class=\\"oe_inline\\" placeholder=\\"Elija un valor...\\" options=\\"{'no_create': True, 'no_open': True}\\" invisible=\\" update_field_id == False or value_field_to_show != 'selection_value' or evaluation_type == 'equation'\\"/>\\n                            <field name=\\"update_boolean_value\\" class=\\"oe_inline\\" invisible=\\"evaluation_type != 'value' or value_field_to_show != 'update_boolean_value'\\" required=\\"value_field_to_show == 'update_boolean_value'\\"/>\\n                            <span invisible=\\"update_field_id != False or evaluation_type == 'equation'\\" class=\\"text-muted\\">Indique un valor...</span>\\n                            <span invisible=\\"evaluation_type != 'equation'\\">\\n                                para esta expresión de Python:\\n                            </span>\\n                            <div class=\\"w-100 d-flex flex-row gap-3\\" invisible=\\"evaluation_type != 'equation'\\">\\n                                <field name=\\"value\\" class=\\"w-50\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\" string=\\"Expresión\\"/>\\n                                <div class=\\"w-50 opacity-75\\">\\n                                    <span colspan=\\"2\\" class=\\"text-muted\\"> Variables disponibles: </span>\\n                                        <ul colspan=\\"2\\" class=\\"text-muted\\">\\n                                            <li><code>env</code>: entorno en el que se activa la acción.</li>\\n                                            <li><code>model</code>: modelo del registro en el cual se activa la acción. Es un conjunto de registros vacío.</li>\\n                                            <li><code>record</code>: registro en el que se realiza la acción</li>\\n                                            <li><code>records</code>: conjunto de todos los registros en los que la acción se realiza en modo múltiple</li>\\n                                            <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: bibliotecas útiles de Python</li>\\n                                            <li><code>float_compare()</code>: función de utilidad para comparar números basada en una precisión específica.</li>\\n                                        </ul>\\n                                </div>\\n                            </div>\\n                        </div>\\n                        <group name=\\"action_wrapper\\">\\n                            <group name=\\"action_content\\">\\n                                <field name=\\"model_name\\" invisible=\\"1\\"/>\\n                                <field name=\\"available_model_ids\\" invisible=\\"1\\"/>\\n                                <field name=\\"model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" groups=\\"!base.group_no_one\\" invisible=\\"context.get('default_model_id')\\" domain=\\"[('id', 'in', available_model_ids)]\\"/>\\n\\n                                <field name=\\"type\\" invisible=\\"1\\"/>\\n                                <field name=\\"crud_model_id\\" options=\\"{'no_create': True, 'no_open': True}\\" invisible=\\"state != 'object_create'\\" required=\\"state == 'object_create'\\"/>\\n                                <field name=\\"crud_model_name\\" invisible=\\"1\\"/>\\n                                <field name=\\"value\\" widget=\\"char\\" string=\\"Nombre\\" invisible=\\"state != 'object_create'\\" help=\\"El nombre del registro a crear\\" placeholder=\\"Por ejemplo, Seguimiento\\"/>\\n                                <field name=\\"link_field_id\\" domain=\\"[('model_id', '=', model_id), ('relation', '=', crud_model_name),                                     ('ttype', 'in', ['many2one', 'one2many', 'many2many'])]\\" placeholder=\\"Seleccione un campo al cual vincular el registro\\" options=\\"{'no_create': True, 'no_open': True}\\" invisible=\\"state != 'object_create'\\" context=\\"{'default_model_id': model_id, 'default_relation': crud_model_name}\\"/>\\n                                    <field name=\\"webhook_url\\" string=\\"URL\\" invisible=\\"state != 'webhook'\\" placeholder=\\"Por ejemplo, https://maker.ifttt.com/use/...\\"/>\\n                                    <field name=\\"webhook_field_ids\\" string=\\"Campos\\" invisible=\\"state != 'webhook'\\" widget=\\"many2many_tags\\" context=\\"{'hide_model': 1}\\" domain=\\"[('model_id', '=', model_id)]\\" placeholder=\\"Seleccione los campos a incluir en la solicitud...\\"/>\\n                                </group>\\n                                <group invisible=\\"state != 'webhook'\\">\\n                                    <label for=\\"webhook_sample_payload\\"/>\\n                                    <field name=\\"webhook_sample_payload\\" string=\\"Carga efectiva de ejemplo\\" nolabel=\\"1\\" colspan=\\"2\\" readonly=\\"1\\" widget=\\"code\\" options=\\"{'mode': 'js'}\\"/>\\n                                </group>\\n                        </group>\\n                        <field name=\\"child_ids\\" domain=\\"[('model_id', '=', model_id)]\\" invisible=\\"state != 'multi'\\"/>\\n                        <p class=\\"oe_grey\\" invisible=\\"state != 'multi'\\">\\n                            Si varias acciones subordinadas devuelven una acción, solo se ejecutará la última.\\n                             Esto puede ocurrir cuando hay acciones del servidor que ejecutan código que devuelve una acción o acciones del servidor que devuelven una acción del cliente.\\n                        </p>\\n                        <notebook invisible=\\"state != 'code'\\">\\n                            <page string=\\"Código\\">\\n                                <field name=\\"code\\" invisible=\\"state != 'code'\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\" placeholder=\\"Introduzca código Python aquí. En la pestaña de ayuda de este documento hay ayuda disponible sobre las expresiones de Python.\\"/>\\n                            </page>\\n                            <page string=\\"Ayuda\\">\\n                                <p>Puede usar las siguientes variables:</p>\\n                                <ul>\\n                                    <li><code>env</code>: entorno en el que se activa la acción.</li>\\n                                    <li><code>model</code>: modelo del registro en el cual se activa la acción. Es un conjunto de registros vacío.</li>\\n                                    <li><code>record</code>: registro en el que se realiza la acción; puede estar vacía</li>\\n                                    <li><code>records</code>: conjunto de todos los registros en los que la acción se realiza en modo múltiple; puede estar vacía</li>\\n                                    <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: bibliotecas útiles de Python</li>\\n                                    <li><code>float_compare()</code>: función de utilidad para comparar números basada en una precisión específica.</li>\\n                                    <li><code>log(message, level='info')</code>: función de registro para registrar información de depuración en la tabla <code>ir.logging</code></li>\\n                                    <li><code>_logger.info(message)</code>: registrador para emitir mensajes en los registros del servidor</li>\\n                                    <li><code>UserError</code>: clase de excepción para generar mensajes de advertencia dirigidos al usuario</li>\\n                                    <li><code>Command</code>: espacios de nombres de comandos x2many</li>\\n                                    <li>Para devolver una acción, asigne: <code>action = {...}</code></li>\\n                                </ul>\\n                                <div>\\n                                    <p>Ejemplo de código Python:</p>\\n<pre style=\\"white-space: pre-wrap\\">partner_name = record.name + '_code'\\nenv['res.partner'].create({'name': partner_name})\\n    </pre>\\n                                </div>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Server Action">\n                    <header>\n                        <field name="binding_model_id" invisible="1"/>\n                        <button name="create_action" string="Create Contextual Action" type="object" class="btn-primary" invisible="binding_model_id" help="Display an option in the 'More' top-menu in order to run this action."/>\n                        <button name="unlink_action" string="Remove Contextual Action" type="object" invisible="not binding_model_id" help="Remove 'More' top-menu contextual action related to this action"/>\n                        <button name="run" string="Run" type="object" class="btn-primary" invisible="model_name != 'ir.actions.server' or state != 'code'" help="Run this action manually."/>\n                    </header>\n                    <sheet>\n                        <h1 class="oe_title">\n                            <field name="name" placeholder="e.g. Mass archive contacts"/>\n                        </h1>\n                        <div class="d-flex flex-column">\n                            <label for="state"/>\n                            <field name="state" widget="selection_badge" options="{'size': 'sm'}"/>\n                        </div>\n                        <group string="Technical Settings" groups="base.group_no_one">\n                            <group>\n                                <field name="model_id" options="{'no_create': True, 'no_open': True}"/>\n                                <field name="groups_id" widget="many2many_tags"/>\n                            </group>\n                        </group>\n                        <separator string="Action Details" groups="base.group_no_one"/>\n                        <div class="d-flex flex-row flex-wrap gap-2" invisible="state != 'object_write'">\n                            <field name="evaluation_type" class="oe_inline"/>\n                            <field name="update_path" widget="DynamicModelFieldSelectorChar" class="oe_inline" options="{'model': 'model_name'}"/>\n                            <field name="update_field_id" invisible="1"/>\n                            <field name="value_field_to_show" invisible="1"/>\n                            <field name="update_related_model_id" invisible="1"/>\n                            <field name="update_field_type" invisible="1"/>\n                            <span invisible="evaluation_type != 'value' or update_field_type not in ['one2many', 'many2many']">by</span>\n                            <field name="update_m2m_operation" class="oe_inline" invisible="evaluation_type != 'value' or update_field_type not in ['one2many', 'many2many']" required="update_field_type in ['one2many', 'many2many']"/>\n                            <span invisible="evaluation_type != 'value' or update_field_type in ['one2many', 'many2many']">to</span>\n                            <field name="value" class="oe_inline" placeholder="Set a value..." invisible="update_field_id == False or value_field_to_show != 'value' or evaluation_type != 'value'" string="Custom Value"/>\n                            <field name="resource_ref" class="oe_inline" placeholder="Choose a value..." string="Custom Value" options="{'model_field': 'update_related_model_id', 'no_create': True, 'no_open': True}" invisible=" update_field_id == False or value_field_to_show != 'resource_ref' or evaluation_type == 'equation' or update_m2m_operation == 'clear'"/>\n                            <field name="selection_value" class="oe_inline" placeholder="Choose a value..." options="{'no_create': True, 'no_open': True}" invisible=" update_field_id == False or value_field_to_show != 'selection_value' or evaluation_type == 'equation'"/>\n                            <field name="update_boolean_value" class="oe_inline" invisible="evaluation_type != 'value' or value_field_to_show != 'update_boolean_value'" required="value_field_to_show == 'update_boolean_value'"/>\n                            <span invisible="update_field_id != False or evaluation_type == 'equation'" class="text-muted">Set a value...</span>\n                            <span invisible="evaluation_type != 'equation'">\n                                to this Python expression:\n                            </span>\n                            <div class="w-100 d-flex flex-row gap-3" invisible="evaluation_type != 'equation'">\n                                <field name="value" class="w-50" widget="code" options="{'mode': 'python'}" string="Expression"/>\n                                <div class="w-50 opacity-75">\n                                    <span colspan="2" class="text-muted"> Available variables: </span>\n                                        <ul colspan="2" class="text-muted">\n                                            <li><code>env</code>: environment on which the action is triggered</li>\n                                            <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>\n                                            <li><code>record</code>: record on which the action is triggered</li>\n                                            <li><code>records</code>: recordset of all records on which the action is triggered in multi mode</li>\n                                            <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>\n                                            <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>\n                                        </ul>\n                                </div>\n                            </div>\n                        </div>\n                        <group name="action_wrapper">\n                            <group name="action_content">\n                                <field name="model_name" invisible="1"/>\n                                <field name="available_model_ids" invisible="1"/>\n                                <field name="model_id" options="{'no_create': True, 'no_open': True}" groups="!base.group_no_one" invisible="context.get('default_model_id')" domain="[('id', 'in', available_model_ids)]"/>\n\n                                <field name="type" invisible="1"/>\n                                <field name="crud_model_id" options="{'no_create': True, 'no_open': True}" invisible="state != 'object_create'" required="state == 'object_create'"/>\n                                <field name="crud_model_name" invisible="1"/>\n                                <field name="value" widget="char" string="Name" invisible="state != 'object_create'" help="The name of the record to create" placeholder="e.g. Follow-up"/>\n                                <field name="link_field_id" domain="[('model_id', '=', model_id), ('relation', '=', crud_model_name),                                     ('ttype', 'in', ['many2one', 'one2many', 'many2many'])]" placeholder="Select a field to link the record to" options="{'no_create': True, 'no_open': True}" invisible="state != 'object_create'" context="{'default_model_id': model_id, 'default_relation': crud_model_name}"/>\n                                    <field name="webhook_url" string="URL" invisible="state != 'webhook'" placeholder="e.g. https://maker.ifttt.com/use/..."/>\n                                    <field name="webhook_field_ids" string="Fields" invisible="state != 'webhook'" widget="many2many_tags" context="{'hide_model': 1}" domain="[('model_id', '=', model_id)]" placeholder="Select fields to include in the request..."/>\n                                </group>\n                                <group invisible="state != 'webhook'">\n                                    <label for="webhook_sample_payload"/>\n                                    <field name="webhook_sample_payload" string="Sample Payload" nolabel="1" colspan="2" readonly="1" widget="code" options="{'mode': 'js'}"/>\n                                </group>\n                        </group>\n                        <field name="child_ids" domain="[('model_id', '=', model_id)]" invisible="state != 'multi'"/>\n                        <p class="oe_grey" invisible="state != 'multi'">\n                            If several child actions return an action, only the last one will be executed.\n                            This may happen when having server actions executing code that returns an action, or server actions returning a client action.\n                        </p>\n                        <notebook invisible="state != 'code'">\n                            <page string="Code">\n                                <field name="code" invisible="state != 'code'" widget="code" options="{'mode': 'python'}" placeholder="Enter Python code here. Help about Python expression is available in the help tab of this document."/>\n                            </page>\n                            <page string="Help">\n                                <p>The following variables can be used:</p>\n                                <ul>\n                                    <li><code>env</code>: environment on which the action is triggered</li>\n                                    <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>\n                                    <li><code>record</code>: record on which the action is triggered; may be be void</li>\n                                    <li><code>records</code>: recordset of all records on which the action is triggered in multi mode; may be void</li>\n                                    <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>\n                                    <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>\n                                    <li><code>log(message, level='info')</code>: logging function to record debug information in <code>ir.logging</code> table</li>\n                                    <li><code>_logger.info(message)</code>: logger to emit messages in server logs</li>\n                                    <li><code>UserError</code>: exception class for raising user-facing warning messages</li>\n                                    <li><code>Command</code>: x2many commands namespace</li>\n                                    <li>To return an action, assign: <code>action = {...}</code></li>\n                                </ul>\n                                <div>\n                                    <p>Example of Python code:</p>\n<pre style="white-space: pre-wrap">partner_name = record.name + '_code'\nenv['res.partner'].create({'name': partner_name})\n    </pre>\n                                </div>\n                            </page>\n                        </notebook>\n                    </sheet>\n                </form>\n            	f	t	2026-10-23 13:35:08.517897	2026-10-23 13:35:08.517897	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
