\\"index\\" groups=\\"base.group_no_one\\"/>\\n                                    <field name=\\"state\\" groups=\\"base.group_no_one\\"/>\\n                                </tree>\\n                                <form string=\\"Descripción de campos\\">\\n                                    <group>\\n                                        <group>\\n                                            <field name=\\"name\\"/>\\n                                            <field name=\\"field_description\\"/>\\n                                        </group>\\n                                        <group>\\n                                            <field name=\\"ttype\\"/>\\n                                            <field name=\\"help\\"/>\\n                                        </group>\\n                                    </group>\\n                                    <notebook>\\n                                        <page name=\\"base\\" string=\\"Propiedades\\">\\n                                            <group string=\\"Propiedades base\\">\\n                                                <group>\\n                                                    <field name=\\"required\\"/>\\n                                                    <field name=\\"readonly\\"/>\\n                                                    <field name=\\"store\\" groups=\\"base.group_no_one\\"/>\\n                                                    <field name=\\"index\\" groups=\\"base.group_no_one\\"/>\\n                                                    <field name=\\"copied\\" groups=\\"base.group_no_one\\"/>\\n                                                </group>\\n                                                <group>\\n                                                    <field name=\\"translate\\" invisible=\\"ttype not in ['char', 'text', 'html']\\" readonly=\\"ttype not in ['char', 'text', 'html']\\"/>\\n                                                    <field name=\\"size\\" groups=\\"base.group_no_one\\" invisible=\\"ttype not in ['char', 'reference']\\" readonly=\\"ttype not in ['char', 'reference']\\"/>\\n                                                    <field name=\\"relation\\" invisible=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" readonly=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" required=\\"ttype in ['many2one', 'one2many', 'many2many']\\"/>\\n                                                    <field name=\\"on_delete\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2one'\\" readonly=\\"ttype != 'many2one'\\"/>\\n                                                    <field name=\\"relation_field\\" invisible=\\"ttype != 'one2many'\\" readonly=\\"ttype != 'one2many'\\" required=\\"ttype == 'one2many'\\"/>\\n                                                    <field name=\\"relation_table\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                                    <field name=\\"column1\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                                    <field name=\\"column2\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                                    <field name=\\"domain\\" groups=\\"base.group_no_one\\" invisible=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" readonly=\\"ttype not in ['many2one', 'one2many', 'many2many']\\"/>\\n                                                </group>\\n                                            </group>\\n                                            <group invisible=\\"ttype not in ['selection', 'reference']\\" readonly=\\"ttype not in ['selection', 'reference']\\">\\n                                                <field name=\\"selection_ids\\">\\n                                                    <tree editable=\\"bottom\\">\\n                                                        <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                                        <field name=\\"value\\"/>\\n                                                        <field name=\\"name\\"/>\\n                                                    </tree>\\n                                                </field>\\n                                            </group>\\n                                            <group string=\\"Propiedades avanzadas\\" groups=\\"base.group_no_one\\">\\n                                                <field name=\\"related\\"/>\\n                                                <field name=\\"depends\\" required=\\"compute not in [False, '']\\"/>\\n                                                <field name=\\"compute\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\"/>\\n                                            </group>\\n                                            <div groups=\\"base.group_no_one\\">\\n                                                <h3>Cómo definir un campo calculado</h3>\\n                                                <p>Los campos calculados se definen con los campos\\n                                                <strong>Dependencias</strong> y <strong>Calcular</strong>.</p>\\n                                                <p>El campo <strong>Dependencias</strong> enumera los campos de los que\\n                                                depende el campo actual. Es una lista de nombres de campos\\n                                                separados por comas, como <code>nombre, tamaño</code>. También se puede referir a \\n                                                campos accesibles a través de otros campos relacionales, por ejemplo\\n                                                <code>partner_id.company_id.name</code>.</p>\\n                                                <p>El campo <strong>Calcular</strong> es el código Python\\n                                                para calcular el valor del campo en un conjunto de registros. El valor del\\n                                                campo se debe asignar a cada registro con una asignación\\n                                                similar a la de un diccionario.</p>\\n                                                <pre>\\n    for record in self:\\n        record['size'] = len(record.name)\\n</pre>\\n                                                <p>Las únicas variables predefinidas son</p>\\n                                                <ul>\\n                                                    <li><code>self</code> (el conjunto de registros para calcular)</li>\\n                                                    <li><code>datetime</code> (Módulo Python)</li>\\n                                                    <li><code>dateutil</code> (Módulo Python)</li>\\n                                                    <li><code>time</code> (Módulo Python)</li>\\n                                                </ul>\\n                                                <p>Se puede acceder a otras funciones a través de <code>self</code>, como\\n<code>self.env</code>, etc.</p>\\n                                            </div>\\n                                        </page>\\n                                        <page name=\\"groups\\" string=\\"Permisos de acceso\\">\\n                                            <field name=\\"groups\\"/>\\n                                        </page>\\n                                        <page name=\\"misc\\" string=\\"Misceláneo\\" groups=\\"base.group_no_one\\">\\n                                            <group>\\n                                                <field name=\\"state\\"/>\\n                                                <field name=\\"modules\\"/>\\n                                            </group>\\n                                        </page>\\n                                    </notebook>\\n                                </form>\\n                            </field>\\n                            <button groups=\\"base.group_no_one\\" icon=\\"fa-align-justify\\" name=\\"18\\" string=\\"Crear un menú\\" type=\\"action\\" target=\\"new\\"/>\\n                        </page>\\n                        <page string=\\"Permisos de acceso\\" name=\\"access_rights\\">\\n                            <field name=\\"access_ids\\">\\n                                <tree string=\\"Permisos de acceso\\" editable=\\"top\\" decoration-warning=\\"not group_id and                                                          (perm_read or perm_write or                                                           perm_create or perm_unlink)\\">\\n                                    <field name=\\"name\\"/>\\n                                    <field name=\\"group_id\\"/>\\n                                    <field name=\\"perm_read\\"/>\\n                                    <field name=\\"perm_write\\"/>\\n                                    <field name=\\"perm_create\\"/>\\n                                    <field name=\\"perm_unlink\\"/>\\n                                </tree>\\n                            </field>\\n                        </page>\\n                        <page string=\\"Reglas de registro\\" name=\\"record_rules\\">\\n                            <field name=\\"rule_ids\\">\\n                                <tree string=\\"Reglas de registro\\" editable=\\"top\\" decoration-info=\\"not groups\\">\\n                                    <field name=\\"name\\"/>\\n                                    <field name=\\"groups\\" widget=\\"many2many_tags\\" options=\\"{'no_create':True}\\"/>\\n                                    <field name=\\"domain_force\\"/>\\n                                    <field name=\\"perm_read\\"/>\\n                                    <field name=\\"perm_write\\"/>\\n                                    <field name=\\"perm_create\\"/>\\n                                    <field name=\\"perm_unlink\\"/>\\n                                </tree>\\n                            </field>\\n                        </page>\\n                        <page string=\\"Notas\\" name=\\"notes\\" groups=\\"base.group_no_one\\">\\n                            <field name=\\"info\\"/>\\n                        </page>\\n                        <page string=\\"Vistas\\" name=\\"views\\" groups=\\"base.group_no_one\\">\\n                            <field name=\\"view_ids\\"/>\\n                        </page>\\n                    </notebook>\\n                  </sheet>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Model Description">\n                  <header><!-- used for override --></header>\n                  <sheet>\n                    <group>\n                        <group>\n                            <field name="id" invisible="1"/>\n                            <field name="name"/>\n                            <field name="model" readonly="id"/>\n                            <field name="order"/>\n                            <field name="transient" readonly="id" groups="base.group_no_one"/>\n                        </group>\n                        <group>\n                            <field name="state" readonly="1" groups="base.group_no_one"/>\n                            <field name="modules" groups="base.group_no_one"/>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string="Fields" name="fields">\n                            <field name="field_id">\n                                <tree string="Fields Description">\n                                    <field name="name"/>\n                                    <field name="field_description"/>\n                                    <field name="ttype"/>\n                                    <field name="required"/>\n                                    <field name="readonly"/>\n                                    <field name="index" groups="base.group_no_one"/>\n                                    <field name="state" groups="base.group_no_one"/>\n                                </tree>\n                                <form string="Fields Description">\n                                    <group>\n                                        <group>\n                                            <field name="name"/>\n                                            <field name="field_description"/>\n                                        </group>\n                                        <group>\n                                            <field name="ttype"/>\n                                            <field name="help"/>\n                                        </group>\n                                    </group>\n                                    <notebook>\n                                        <page name="base" string="Properties">\n                                            <group string="Base Properties">\n                                                <group>\n                                                    <field name="required"/>\n                                                    <field name="readonly"/>\n                                                    <field name="store" groups="base.group_no_one"/>\n                                                    <field name="index" groups="base.group_no_one"/>\n                                                    <field name="copied" groups="base.group_no_one"/>\n                                                </group>\n                                                <group>\n                                                    <field name="translate" invisible="ttype not in ['char', 'text', 'html']" readonly="ttype not in ['char', 'text', 'html']"/>\n                                                    <field name="size" groups="base.group_no_one" invisible="ttype not in ['char', 'reference']" readonly="ttype not in ['char', 'reference']"/>\n                                                    <field name="relation" invisible="ttype not in ['many2one', 'one2many', 'many2many']" readonly="ttype not in ['many2one', 'one2many', 'many2many']" required="ttype in ['many2one', 'one2many', 'many2many']"/>\n                                                    <field name="on_delete" groups="base.group_no_one" invisible="ttype != 'many2one'" readonly="ttype != 'many2one'"/>\n                                                    <field name="relation_field" invisible="ttype != 'one2many'" readonly="ttype != 'one2many'" required="ttype == 'one2many'"/>\n                                                    <field name="relation_table" groups="base.group_no_one" invisible="ttype != 'many2many' or state != 'manual'" readonly="ttype != 'many2many' or state != 'manual'"/>\n                                                    <field name="column1" groups="base.group_no_one" invisible="ttype != 'many2many' or state != 'manual'" readonly="ttype != 'many2many' or state != 'manual'"/>\n                                                    <field name="column2" groups="base.group_no_one" invisible="ttype != 'many2many' or state != 'manual'" readonly="ttype != 'many2many' or state != 'manual'"/>\n                                                    <field name="domain" groups="base.group_no_one" invisible="ttype not in ['many2one', 'one2many', 'many2many']" readonly="ttype not in ['many2one', 'one2many', 'many2many']"/>\n                                                </group>\n                                            </group>\n                                            <group invisible="ttype not in ['selection', 'reference']" readonly="ttype not in ['selection', 'reference']">\n                                                <field name="selection_ids">\n                                                    <tree editable="bottom">\n                                                        <field name="sequence" widget="handle"/>\n                                                        <field name="value"/>\n                                                        <field name="name"/>\n                                                    </tree>\n                                                </field>\n                                            </group>\n                                            <group string="Advanced Properties" groups="base.group_no_one">\n                                                <field name="related"/>\n                                                <field name="depends" required="compute not in [False, '']"/>\n                                                <field name="compute" widget="code" options="{'mode': 'python'}"/>\n                                            </group>\n                                            <div groups="base.group_no_one">\n                                                <h3>How to define a computed field</h3>\n                                                <p>Computed fields are defined with the fields\n                                                <strong>Dependencies</strong> and <strong>Compute</strong>.</p>\n                                                <p>The field <strong>Dependencies</strong> lists the fields that\n                                                the current field depends on. It is a comma-separated list of\n                                                field names, like <code>name, size</code>. You can also refer to\n                                                fields accessible through other relational fields, for instance\n                                                <code>partner_id.company_id.name</code>.</p>\n                                                <p>The field <strong>Compute</strong> is the Python code to\n                                                compute the value of the field on a set of records. The value of\n                                                the field must be assigned to each record with a dictionary-like\n                                                assignment.</p>\n                                                <pre>\n    for record in self:\n        record['size'] = len(record.name)\n</pre>\n                                                <p>The only predefined variables are</p>\n                                                <ul>\n                                                    <li><code>self</code> (the set of records to compute)</li>\n                                                    <li><code>datetime</code> (Python module)</li>\n                                                    <li><code>dateutil</code> (Python module)</li>\n                                                    <li><code>time</code> (Python module)</li>\n                                                </ul>\n                                                <p>Other features are accessible through <code>self</code>, like\n                                                <code>self.env</code>, etc.</p>\n                                            </div>\n                                        </page>\n                                        <page name="groups" string="Access Rights">\n                                            <field name="groups"/>\n                                        </page>\n                                        <page name="misc" string="Miscellaneous" groups="base.group_no_one">\n                                            <group>\n                                                <field name="state"/>\n                                                <field name="modules"/>\n                                            </group>\n                                        </page>\n                                    </notebook>\n                                </form>\n                            </field>\n                            <button groups="base.group_no_one" icon="fa-align-justify" name="18" string="Create a Menu" type="action" target="new"/>\n                        </page>\n                        <page string="Access Rights" name="access_rights">\n                            <field name="access_ids">\n                                <tree string="Access Rights" editable="top" decoration-warning="not group_id and                                                          (perm_read or perm_write or                                                           perm_create or perm_unlink)">\n                                    <field name="name"/>\n                                    <field name="group_id"/>\n                                    <field name="perm_read"/>\n                                    <field name="perm_write"/>\n                                    <field name="perm_create"/>\n                                    <field name="perm_unlink"/>\n                                </tree>\n                            </field>\n                        </page>\n                        <page string="Record Rules" name="record_rules">\n                            <field name="rule_ids">\n                                <tree string="Record Rules" editable="top" decoration-info="not groups">\n                                    <field name="name"/>\n                                    <field name="groups" widget="many2many_tags" options="{'no_create':True}"/>\n                                    <field name="domain_force"/>\n                                    <field name="perm_read"/>\n                                    <field name="perm_write"/>\n                                    <field name="perm_create"/>\n       