erties\\">\\n                                    <group>\\n                                        <field name=\\"sanitize\\" invisible=\\"ttype != 'html'\\" readonly=\\"ttype != 'html'\\"/>\\n                                        <field name=\\"sanitize_overridable\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"sanitize_tags\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"sanitize_attributes\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                    </group>\\n                                    <group>\\n                                        <field name=\\"sanitize_style\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"sanitize_form\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"strip_style\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"strip_classes\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                    </group>\\n                                </group>\\n                                <group invisible=\\"ttype not in ['selection', 'reference']\\" readonly=\\"ttype not in ['selection', 'reference']\\">\\n                                    <field name=\\"selection_ids\\">\\n                                        <tree editable=\\"bottom\\">\\n                                            <field