ega_menu\\" t-elif=\\"False\\" t-attf-class=\\"dropdown-menu o_mega_menu #{submenu.mega_menu_classes}\\" data-name=\\"Mega Menu\\" t-field=\\"submenu.mega_menu_content\\" role=\\"menuitem\\"/>\\n        <ul t-else=\\"\\" t-attf-class=\\"dropdown-menu #{dropdown_menu_classes}\\" role=\\"menu\\">\\n            <t t-foreach=\\"submenu.child_id\\" t-as=\\"submenu\\">\\n                <t t-call=\\"website.submenu\\">\\n                    <t t-set=\\"item_class\\" t-value=\\"None\\"/>\\n                    <t t-set=\\"link_class\\" t-valuef=\\"dropdown-item\\"/>\\n                </t>\\n            </t>\\n        </ul>\\n    </li>\\n</t>"}	<?xml version="1.0"?>\n<t name="Submenu" t-name="website.submenu">\n    <t t-set="show_dropdown" t-value="(submenu.is_mega_menu and submenu.is_visible) or submenu.child_id.filtered(lambda menu: menu.is_visible)"/>\n    <li t-if="submenu.is_visible and not (submenu.child_id or submenu.is_mega_menu)" t-attf-class="#{item_class or ''}" role="presentation">\n        <a t-att-href="submenu._clean_url()" t-attf-class="#{link_class or ''} #{submenu._is_active() and 'active'}" role="menuitem" t-ignore="true" t-att-target="'_blank' if submenu.new_window else None">\n            <span t-field="submenu.name"/>\n        </a>\n    </li>\n    <li t-elif="show_dropdown" t-attf-class="#{item_class or ''} dropdown #{submenu.is_mega_menu and 'position-static'}" role="presentation">\n        <a t-attf-class="#{link_class or ''} dropdown-toggle #{submenu.is_mega_menu and 'o_mega_menu_toggle'} #{submenu._is_active() and 'active'} #{dropdown_toggler_classes}" data-bs-toggle="dropdown" href="#" t-att-data-bs-display="'static' if submenu.is_mega_menu else None" role="menuitem">\n            <span t-field="submenu.name"/>\n        </a>\n        <div t-if="submenu.is_mega_menu and not is_mobile" t-attf-class="dropdown-menu o_mega_menu #{submenu.mega_menu_classes}" data-name="Mega Menu" t-field="submenu.mega_menu_content"/>\n        <!--\n            TODO remove the next two if elements in master, this was made to not\n            have to change the "else" element in stable and prevent xpath fails\n            on the existing elements.\n            -> The first one render nothing (case submenu.is_mega_menu and is_mobile)\n            -> The second one is never considered (t-elif evaluated first)\n        -->\n        <t t-elif="submenu.is_mega_menu"/>\n        <div t-if="submenu.is_mega_menu" t-elif="False" t-attf-class="dropdown-menu o_mega_menu #{submenu.mega_menu_classes}" data-name="Mega Menu" t-field="submenu.mega_menu_content" role="menuitem"/>\n        <ul t-else="" t-attf-class="dropdown-menu #{dropdown_menu_classes}" role="menu">\n            <t t-foreach="submenu.child_id" t-as="submenu">\n                <t t-call="website.submenu">\n                    <t t-set="item_class" t-value="None"/>\n                    <t t-set="link_class" t-valuef="dropdown-item"/>\n                </t>\n            </t>\n        </ul>\n    </li>\n</t>\n\n	f	t	2026-10-30 15:04:32.762047	2026-10-30 15:04:32.762047	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f
