125	1	\N	1	1	res.partner.form	res.partner	\N	form	base/views/res_partner_views.xml	primary	{"en_US": "<form string=\\"Partners\\">\\n                <div class=\\"alert alert-warning oe_edit_only\\" role=\\"alert\\" name=\\"warning_tax\\" invisible=\\"not same_vat_partner_id\\">\\n                  A partner with the same <span><span class=\\"o_vat_label\\">Tax ID</span></span> already exists (<field name=\\"same_vat_partner_id\\" context=\\"{'show_address': False, 'show_vat': False}\\"/>), are you sure to create a new one?\\n                </div>\\n                <div class=\\"alert alert-warning oe_edit_only\\" role=\\"alert\\" name=\\"warning_company\\" invisible=\\"not same_company_registry_partner_id\\">\\n                  A partner with the same <span><span class=\\"o_vat_label\\">Company Registry</span></span> already exists (<field name=\\"same_company_registry_partner_id\\" context=\\"{'show_address': False, 'show_vat': False}\\"/>), are you sure to create a new one?\\n                </div>\\n                <sheet>\\n                    <div class=\\"oe_button_box\\" name=\\"button_box\\"/>\\n                    <widget name=\\"web_ribbon\\" title=\\"Archived\\" bg_color=\\"text-bg-danger\\" invisible=\\"active\\"/>\\n                    <field name=\\"avatar_128\\" invisible=\\"1\\"/>\\n                    <field name=\\"image_1920\\" widget=\\"image\\" class=\\"oe_avatar\\" options=\\"{&quot;preview_image&quot;: &quot;avatar_128&quot;}\\"/>\\n                    <div class=\\"oe_title mb24\\">\\n                        <field name=\\"is_company\\" invisible=\\"1\\"/>\\n                        <field name=\\"commercial_partner_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"active\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"country_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_type\\" widget=\\"radio\\" options=\\"{'horizontal': true}\\"/>\\n                        <h1>\\n                            <field id=\\"company\\" options=\\"{'line_breaks': False}\\" widget=\\"text\\" class=\\"text-break\\" name=\\"name\\" default_focus=\\"1\\" placeholder=\\"e.g. Lumber Inc\\" invisible=\\"not is_company\\" required=\\"type == 'contact'\\"/>\\n                            <field id=\\"individual\\" options=\\"{'line_breaks': False}\\" widget=\\"text\\" class=\\"text-break\\" name=\\"name\\" default_focus=\\"1\\" placeholder=\\"e.g. Brandom Freeman\\" invisible=\\"is_company\\" required=\\"type == 'contact'\\"/>\\n                        </h1>\\n                        <div class=\\"o_row\\">\\n                            <field name=\\"parent_id\\" widget=\\"res_partner_many2one\\" placeholder=\\"Company Name...\\" domain=\\"[('is_company', '=', True)]\\" context=\\"{'default_is_company': True, 'show_vat': True, 'default_user_id': user_id}\\" invisible=\\"((is_company and not parent_id) or company_name) and company_name != ''\\"/>\\n                                <field name=\\"company_name\\" invisible=\\"not company_name or company_name == '' or is_company\\"/>\\n                                <button name=\\"create_company\\" icon=\\"fa-plus-square\\" string=\\"Create company\\" type=\\"object\\" class=\\"oe_edit_only btn-link\\" invisible=\\"is_company or company_name == '' or not company_name\\"/>\\n                        </div>\\n                    </div>\\n\\n                    <group>\\n                        <group>\\n                            <span class=\\"o_form_label o_td_label\\" name=\\"address_name\\">\\n                                <field name=\\"type\\" invisible=\\"is_company\\" readonly=\\"user_ids\\" required=\\"not is_company\\" class=\\"fw-bold\\"/>\\n                                <b invisible=\\"not is_company\\">Address</b>\\n                            </span>\\n                            <div class=\\"o_address_format\\">\\n                                <field name=\\"street\\" placeholder=\\"Street...\\" class=\\"o_address_street\\" readonly=\\"type == 'contact' and parent_id\\"/>\\n                                <field name=\\"street2\\" placeholder=\\"Street 2...\\" class=\\"o_address_street\\" readonly=\\"type == 'contact' and parent_id\\"/>\\n                                <field name=\\"city\\" placeholder=\\"City\\" class=\\"o_address_city\\" readonly=\\"type == 'contact' and parent_id\\"/>\\n                                <field name=\\"state_id\\" class=\\"o_address_state\\" placeholder=\\"State\\" options=\\"{'no_open': True, 'no_quick_create': True}\\" readonly=\\"type == 'contact' and parent_id\\" context=\\"{'country_id': country_id, 'default_country_id': country_id, 'zip': zip}\\"/>\\n                                <field name=\\"zip\\" placeholder=\\"ZIP\\" class=\\"o_address_zip\\" readonly=\\"type == 'contact' and parent_id\\"/>\\n                                <div name=\\"partner_address_country\\" class=\\"d-flex justify-content-between\\">\\n                                    <field name=\\"country_id\\" placeholder=\\"Country\\" class=\\"o_address_country\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\" readonly=\\"type == 'contact' and parent_id\\"/>\\n                                </div>\\n                            </div>\\n                            <field name=\\"vat\\" placeholder=\\"e.g. BE0477472701\\" readonly=\\"parent_id\\"/>\\n                        </group>\\n                        <group>\\n                            <field name=\\"function\\" placeholder=\\"e.g. Sales Director\\" invisible=\\"is_company\\"/>\\n                            <field name=\\"phone\\" widget=\\"phone\\"/>\\n                            <field name=\\"mobile\\" widget=\\"phone\\"/>\\n                            <field name=\\"user_ids\\" invisible=\\"1\\"/>\\n                            <field name=\\"email\\" widget=\\"email\\" context=\\"{'gravatar_image': True}\\" required=\\"user_ids\\"/>\\n                            <field name=\\"website\\" string=\\"Website\\" widget=\\"url\\" placeholder=\\"e.g. https://www.odoo.com\\"/>\\n                            <field name=\\"title\\" options=\\"{&quot;no_open&quot;: True}\\" placeholder=\\"e.g. Mister\\" invisible=\\"is_company\\"/>\\n                            <field name=\\"active_lang_count\\" invisible=\\"1\\"/>\\n                            <field name=\\"lang\\" invisible=\\"active_lang_count &lt;= 1\\"/>\\n                            <field name=\\"category_id\\" widget=\\"many2many_tags\\" options=\\"{'color_field': 'color', 'no_create_edit': True}\\" placeholder=\\"e.g. &quot;B2B&quot;, &quot;VIP&quot;, &quot;Consulting&quot;, ...\\"/>\\n                        </group>\\n                    </group>\\n\\n                    <notebook colspan=\\"4\\">\\n                        <page string=\\"Contacts &amp; Addresses\\" name=\\"contact_addresses\\" autofocus=\\"autofocus\\">\\n                            <field name=\\"child_ids\\" mode=\\"kanban\\" context=\\"{'default_parent_id': id, 'default_street': street, 'default_street2': street2, 'default_city': city, 'default_state_id': state_id, 'default_zip': zip, 'default_country_id': country_id, 'default_lang': lang, 'default_user_id': user_id, 'default_type': 'other'}\\">\\n                                <kanban>\\n                                    <field name=\\"id\\"/>\\n                                    <field name=\\"color\\"/>\\n                                    <field name=\\"name\\"/>\\n                                    <field name=\\"title\\"/>\\n                                    <field name=\\"type\\"/>\\n                                    <field name=\\"email\\"/>\\n                                    <field name=\\"parent_id\\"/>\\n                                    <field name=\\"is_company\\"/>\\n                                    <field name=\\"function\\"/>\\n                                    <field name=\\"phone\\"/>\\n                                    <field name=\\"street\\"/>\\n                                    <field name=\\"street2\\"/>\\n                                    <field name=\\"zip\\"/>\\n                                    <field name=\\"city\\"/>\\n                                    <field name=\\"country_id\\"/>\\n                                    <field name=\\"mobile\\"/>\\n                                    <field name=\\"state_id\\"/>\\n                                    <field name=\\"image_128\\"/>\\n                                    <field name=\\"avatar_128\\"/>\\n                                    <field name=\\"lang\\"/>\\n                                    <!-- fields in form x2many view to diminish requests -->\\n                                    <field name=\\"comment\\"/>\\n                                    <field name=\\"display_name\\"/>\\n                                    <templates>\\n                                        <t t-name=\\"kanban-box\\">\\n                                            <t t-set=\\"color\\" t-value=\\"kanban_color(record.color.raw_value)\\"/>\\n                                            <div t-att-class=\\"color + (record.title.raw_value == 1 ? ' oe_kanban_color_alert' : '') + ' oe_kanban_global_click'\\">\\n                                                <div class=\\"o_kanban_image\\">\\n                                                    <img alt=\\"Contact image\\" t-att-src=\\"kanban_image('res.partner', 'avatar_128', record.id.raw_value)\\"/>\\n                                                </div>\\n                                                <div class=\\"oe_kanban_details\\">\\n                                                    <field name=\\"name\\"/>\\n                                                    <div t-if=\\"record.function.raw_value\\"><field name=\\"function\\"/></div>\\n                                                    <div t-if=\\"record.email.raw_value\\"><field name=\\"email\\" widget=\\"email\\"/></div>\\n                                                    <div t-if=\\"record.type.raw_value != 'contact'\\">\\n                                                        <div>\\n                                                            <field name=\\"zip\\"/><t t-if=\\"record.city\\"> </t>\\n                                                            <field name=\\"city\\"/>\\n                                                        </div>\\n                                                        <field t-if=\\"record.state_id.raw_value\\" name=\\"state_id\\"/><t t-if=\\"record.country_id\\"> </t>\\n                                                        <field name=\\"country_id\\"/>\\n                                                    </div>\\n                                                    <div t-if=\\"record.phone.raw_value\\">Phone: <t t-esc=\\"record.phone.value\\"/></div>\\n                                                    <div t-if=\\"record.mobile.raw_value\\">Mobile: <t t-esc=\\"record.mobile.value\\"/></div>\\n                                                </div>\\n                                            </div>\\n                                        </t>\\n                                    </templates>\\n                                </kanban>\\n                                <form string=\\"Contact / Address\\">\\n                                    <sheet>\\n                                        <field name=\\"type\\" required=\\"1\\" widget=\\"radio\\" options=\\"{'horizontal': true}\\"/>\\n                                        <field name=\\"parent_id\\" invisible=\\"1\\"/>\\n                                        <div class=\\"text-muted oe_edit_only\\">\\n                                            <p class=\\"mb-0\\" invisible=\\"type != 'contact'\\">\\n                                                <span>Use this to organize the contact details of employees of a given company (e.g. CEO, CFO, ...).</span>\\n                                            </p>\\n                                            <p class=\\"mb-0\\" invisible=\\"type != 'invoice'\\">\\n                                                <span>Preferred address for all invoices. Selected by default when you invoice an order that belongs to this company.</span>\\n                                            </p>\\n                                            <p class=\\"mb-0\\" invisible=\\"type != 'delivery'\\">\\n                                                <span>Preferred address for all deliveries. Selected by default when you deliver an order that belongs to this company.</span>\\n                                            </p>\\n                                            <p class=\\"mb-0\\" invisible=\\"type != 'other'\\">\\n                                                <span>Other address for the company (e.g. subsidiary, ...)</span>\\n                                            </p>\\n                                        </div>\\n                                        <hr/>\\n                                        <group>\\n                                            <group>\\n                                                <field name=\\"name\\" string=\\"Contact Name\\" required=\\"type == 'contact'\\"/>\\n                                                <field name=\\"title\\" options=\\"{'no_open': True}\\" placeholder=\\"e.g. Mr.\\" invisible=\\"type != 'contact'\\"/>\\n                                                <field name=\\"function\\" placeholder=\\"e.g. Sales Director\\" invisible=\\"type != 'contact'\\"/>\\n                                                <label for=\\"street\\" string=\\"Address\\" invisible=\\"type == 'contact'\\"/>\\n                                                <div invisible=\\"type == 'contact'\\">\\n                                                    <div class=\\"o_address_format\\" name=\\"div_address\\">\\n                                                        <field name=\\"street\\" placeholder=\\"Street...\\" class=\\"o_address_street\\"/>\\n                                                        <field name=\\"street2\\" placeholder=\\"Street 2...\\" class=\\"o_address_street\\"/>\\n                                                        <field name=\\"city\\" placeholder=\\"City\\" class=\\"o_address_city\\"/>\\n                                                        <field name=\\"state_id\\" class=\\"o_address_state\\" placeholder=\\"State\\" options=\\"{'no_open': True, 'no_quick_create': True}\\" context=\\"{'country_id': country_id, 'default_country_id': country_id, 'zip': zip}\\"/>\\n                                                        <field name=\\"zip\\" placeholder=\\"ZIP\\" class=\\"o_address_zip\\"/>\\n                                                        <field name=\\"country_id\\" placeholder=\\"Country\\" class=\\"o_address_country\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\"/>\\n                                                    </div>\\n                                                </div>\\n                                            </group>\\n                                            <group>\\n                                                <field name=\\"email\\" widget=\\"email\\"/>\\n                                                <field name=\\"phone\\" widget=\\"phone\\"/>\\n                                                <field name=\\"mobile\\" widget=\\"phone\\"/>\\n                                                <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                            </group>\\n                                        </group>\\n                                        <group>\\n                                            <field name=\\"comment\\" placeholder=\\"Internal notes...\\" nolabel=\\"1\\" colspan=\\"2\\"/>\\n                                        </group>\\n                                        <field name=\\"lang\\" invisible=\\"True\\"/>\\n                                        <field name=\\"user_id\\" invisible=\\"True\\"/>\\n                                    </sheet>\\n                                </form>\\n                            </field>\\n                        </page>\\n                        <page name=\\"sales_purchases\\" string=\\"Sales &amp; Purchase\\">\\n                            <group name=\\"container_row_2\\">\\n                                <group string=\\"Sales\\" name=\\"sale\\" priority=\\"1\\">\\n                                    <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\" domain=\\"[('share', '=', False)]\\"/>\\n                                </group>\\n                                <group string=\\"Purchase\\" name=\\"purchase\\" priority=\\"2\\">\\n                                </group>\\n                                <group name=\\"misc\\" string=\\"Misc\\">\\n                                    <field name=\\"company_registry\\" invisible=\\"parent_id\\"/>\\n                                    <field name=\\"ref\\" string=\\"Reference\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" readonly=\\"parent_id\\" force_save=\\"1\\"/>\\n                                    <field name=\\"industry_id\\" invisible=\\"not is_company\\" options=\\"{'no_create': True}\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                        <page name=\\"internal_notes\\" string=\\"Internal Notes\\">\\n                            <field name=\\"comment\\" placeholder=\\"Internal notes...\\"/>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                </form>", "es_AR": "<form string=\\"Contactos\\">\\n                <div class=\\"alert alert-warning oe_edit_only\\" role=\\"alert\\" name=\\"warning_tax\\" invisible=\\"not same_vat_partner_id\\">\\n                  Ya existe un contacto con la misma <span><span class=\\"o_vat_label\\">identificación fiscal</span></span> (<field name=\\"same_vat_partner_id\\" context=\\"{'show_address': False, 'show_vat': False}\\"/>), ¿esta seguro de crear uno nuevo?\\n                </div>\\n                <div class=\\"alert alert-warning oe_edit_only\\" role=\\"alert\\" name=\\"warning_company\\" invisible=\\"not same_company_registry_partner_id\\">\\n                  Ya existe un contacto con el mismo <span><span class=\\"o_vat_label\\">registro de la empresa</span></span> (<field name=\\"same_company_registry_partner_id\\" context=\\"{'show_address': False, 'show_vat': False}\\"/>), ¿esta seguro de crear uno nuevo?\\n                </div>\\n                <sheet>\\n                    <div class=\\"oe_button_box\\" name=\\"button_box\\"/>\\n                    <widget name=\\"web_ribbon\\" title=\\"Archivado\\" bg_color=\\"text-bg-danger\\" invisible=\\"active\\"/>\\n                    <field name=\\"avatar_128\\" invisible=\\"1\\"/>\\n                    <field name=\\"image_1920\\" widget=\\"image\\" class=\\"oe_avatar\\" options=\\"{&quot;preview_image&quot;: &quot;avatar_128&quot;}\\"/>\\n                    <div class=\\"oe_title mb24\\">\\n                        <field name=\\"is_company\\" invisible=\\"1\\"/>\\n                        <field name=\\"commercial_partner_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"active\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"country_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_type\\" widget=\\"radio\\" options=\\"{'horizontal': true}\\"/>\\n                        <h1>\\n                            <field id=\\"company\\" options=\\"{'line_breaks': False}\\" widget=\\"text\\" class=\\"text-break\\" name=\\"name\\" default_focus=\\"1\\" placeholder=\\"Por ejemplo, Lumber Inc\\" invisible=\\"not is_company\\" required=\\"type == 'contact'\\"/>\\n                            <field id=\\"individual\\" options=\\"{'line_breaks': False}\\" widget=\\"text\\" class=\\"text-break\\" name=\\"name\\" default_focus=\\"1\\" placeholder=\\"Por ejemplo, Brandom Freeman\\" invisible=\\"is_company\\" required=\\"type == 'contact'\\"/>\\n                        </h1>\\n                        <div class=\\"o_row\\">\\n                            <field name=\\"parent_id\\" widget=\\"res_partner_many2one\\" placeholder=\\"Nombre de la empresa...\\" domain=\\"[('is_company', '=', True)]\\" context=\\"{'default_is_company': True, 'show_vat': True, 'default_user_id': user_id}\\" invisible=\\"((is_company and not parent_id) or company_name) and company_name != ''\\"/>\\n                                <field name=\\"company_name\\" invisible=\\"not company_name or company_name == '' or is_company\\"/>\\n                                <button name=\\"create_company\\" icon=\\"fa-plus-square\\" string=\\"Crear empresa\\" type=\\"object\\" class=\\"oe_edit_only btn-link\\" invisible=\\"is_company or company_name == '' or not company_name\\"/>\\n                        </div>\\n                    </div>\\n\\n                    <group>\\n                        <group>\\n                            <span class=\\"o_form_label o_td_label\\" name=\\"address_name\\">\\n                                <field name=\\"type\\" invisible=\\"is_company\\" readonly=\\"user_ids\\" required=\\"not is_company\\" class=\\"fw-bold\\"/>\\n                                <b invisible=\\"not is_company\\">Dirección</b>\\n                            </span>\\n                            <div class=\\"o_address_format\\">\\n                                <field name=\\"street\\" placeholder=\\"Calle...\\" class=\\"o_address_street\\" readonly=\\"type == 'contact' and parent_id\\"/>\\n                                <field name=\\"street2\\" placeholder=\\"Calle 2...\\" class=\\"o_address_street\\" readonly=\\"type == 'contact' and parent_id\\"/>\\n                                <field name=\\"city\\" placeholder=\\"Ciudad\\" class=\\"o_address_city\\" readonly=\\"type == 'contact' and parent_id\\"/>\\n                                <field name=\\"state_id\\" class=\\"o_address_state\\" placeholder=\\"Estado\\" options=\\"{'no_open': True, 'no_quick_create': True}\\" readonly=\\"type == 'contact' and parent_id\\" context=\\"{'country_id': country_id, 'default_country_id': country_id, 'zip': zip}\\"/>\\n                                <field name=\\"zip\\" placeholder=\\"C.P.\\" class=\\"o_address_zip\\" readonly=\\"type == 'contact' and parent_id\\"/>\\n                                <div name=\\"partner_address_country\\" class=\\"d-flex justify-content-between\\">\\n                                    <field name=\\"country_id\\" placeholder=\\"País\\" class=\\"o_address_country\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\" readonly=\\"type == 'contact' and parent_id\\"/>\\n                                </div>\\n                            </div>\\n                            <field name=\\"vat\\" placeholder=\\"Por ejemplo, BE0477472701\\" readonly=\\"parent_id\\"/>\\n                        </group>\\n                        <group>\\n                            <field name=\\"function\\" placeholder=\\"Por ejemplo, director de ventas\\" invisible=\\"is_company\\"/>\\n                            <field name=\\"phone\\" widget=\\"phone\\"/>\\n                            <field name=\\"mobile\\" widget=\\"phone\\"/>\\n                            <field name=\\"user_ids\\" invisible=\\"1\\"/>\\n                            <field name=\\"email\\" widget=\\"email\\" context=\\"{'gravatar_image': True}\\" required=\\"user_ids\\"/>\\n                            