name=\\"email\\" widget=\\"email\\"/></div>\\n                                                    <div t-if=\\"record.type.raw_value != 'contact'\\">\\n                                                        <div>\\n                                                            <field name=\\"zip\\"/><t t-if=\\"record.city\\"> </t>\\n                                                            <field name=\\"city\\"/>\\n                                                        </div>\\n                                                        <field t-if=\\"record.state_id.raw_value\\" name=\\"state_id\\"/><t t-if=\\"record.country_id\\"> </t>\\n                                                        <field name=\\"country_id\\"/>\\n                                                    </div>\\n                                                    <div t-if=\\"record.phone.raw_value\\">Teléfono: <t t-esc=\\"record.phone.value\\"/></div>\\n                                                    <div t-if=\\"record.mobile.raw_value\\">Móvil: <t t-esc=\\"record.mobile.value\\"/></div>\\n                                                </div>\\n                                            </div>\\n                                        </t>\\n                                    </templates>\\n                                </kanban>\\n                                <form string=\\"Contacto / dirección\\">\\n                                    <sheet>\\n                                        <field name=\\"type\\" required=\\"1\\" widget=\\"radio\\" options=\\"{'horizontal': true}\\"/>\\n                                        <field name=\\"parent_id\\" invisible=\\"1\\"/>\\n                                        <div class=\\"text-muted oe_edit_only\\">\\n                                            <p class=\\"mb-0\\" invisible=\\"type != 'contact'\\">\\n                                                <span>Use esto para organizar los detalles de contacto de los empleados de una empresa específica (por ejemplo, director ejecutivo, director financiero, etc.).</span>\\n                                            </p>\\n                                            <p class=\\"mb-0\\" invisible=\\"type != 'invoice'\\">\\n                                                <span>La dirección preferida para todas las facturas. Se selecciona de forma predeterminada cuando factura una orden que pertenece a esta empresa.</span>\\n                                            </p>\\n                                            <p class=\\"mb-0\\" invisible=\\"type != 'delivery'\\">\\n                                                <span>La dirección preferida para todas las entregas. Se selecciona de forma predeterminada al entregar una orden que pertenece a esta empresa.</span>\\n                                            </p>\\n                                            <p class=\\"mb-0\\" invisible=\\"type != 'other'\\">\\n                                                <span>Otras direcciones para la empresa (por ejemplo, subsidiaria...)</span>\\n                                            </p>\\n                                        </div>\\n                                        <hr/>\\n                                        <group>\\n                                            <group>\\n                                                <field name=\\"name\\" string=\\"Nombre del contacto\\" required=\\"type == 'contact'\\"/>\\n                                                <field name=\\"title\\" options=\\"{'no_open': True}\\" placeholder=\\"Por ejemplo, Sr.\\" invisible=\\"type != 'contact'\\"/>\\n                                                <field name=\\"function\\" placeholder=\\"Por ejemplo, director de ventas\\" invisible=\\"type != 'contact'\\"/>\\n                                                <label for=\\"street\\" string=\\"Dirección\\" invisible=\\"type == 'contact'\\"/>\\n                                                <div invisible=\\"type == 'contact'\\">\\n                                                    <div class=\\"o_address_format\\" name=\\"div_address\\">\\n                                                        <field name=\\"street\\" placeholder=\\"Calle...\\" class=\\"o_address_street\\"/>\\n                                                        <field name=\\"street2\\" placeholder=\\"Calle 2...\\" class=\\"o_address_street\\"/>\\n                                                        <field name=\\"city\\" placeholder=\\"Ciudad\\" class=\\"o_address_city\\"/>\\n                                                        <field name=\\"state_id\\" class=\\"o_address_state\\" placeholder=\\"Estado\\" options=\\"{'no_open': True, 'no_quick_create': True}\\" context=\\"{'country_id': country_id, 'default_country_id': country_id, 'zip': zip}\\"/>\\n                                                        <field name=\\"zip\\" placeholder=\\"C.P.\\" class=\\"o_address_zip\\"/>\\n                                                        <field name=\\"country_id\\" placeholder=\\"País\\" class=\\"o_address_country\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\"/>\\n                                                    </div>\\n                                                </div>\\n                                            </group>\\n                                            <group>\\n                                                <field name=\\"email\\" widget=\\"email\\"/>\\n                                                <field name=\\"phone\\" widget=\\"phone\\"/>\\n                                                <field name=\\"mobile\\" widget=\\"phone\\"/>\\n                                                <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                            </group>\\n                                        </group>\\n                                        <group>\\n                                         