214	16	162	1	1	user form: add totp status	res.users	\N	form	auth_totp/views/res_users_views.xml	extension	{"en_US": "<xpath expr=\\"//page[@name='preferences']\\" position=\\"after\\">\\n                <page string=\\"Account Security\\" name=\\"security\\" invisible=\\"not id\\">\\n                    <field name=\\"totp_enabled\\" invisible=\\"1\\"/>\\n                    <!-- For own user, allow to activate the two-factor Authentication -->\\n                    <div>\\n                        <div class=\\"o_horizontal_separator d-flex align-items-center mt-2 mb-4 text-uppercase fw-bolder small\\">Two-factor Authentication\\n                                <div invisible=\\"totp_enabled\\">\\n                                    <button invisible=\\"id == uid\\" name=\\"action_totp_enable_wizard\\" disabled=\\"1\\" type=\\"object\\" class=\\"fa fa-toggle-off o_auth_2fa_btn disabled\\" aria-label=\\"Enable 2FA\\"/>\\n                                            <button invisible=\\"id != uid\\" name=\\"action_totp_enable_wizard\\" type=\\"object\\" class=\\"fa fa-toggle-off o_auth_2fa_btn disabled pe-auto\\" aria-label=\\"Enable 2FA\\"/>\\n                                </div>\\n                                <button invisible=\\"not totp_enabled\\" name=\\"action_totp_disable\\" type=\\"object\\" class=\\"fa fa-toggle-on o_auth_2fa_btn text-primary enabled\\" aria-label=\\"Disable 2FA\\"/>\\n                            </div>\\n                            <span invisible=\\"totp_enabled\\" class=\\"text-muted\\">\\n                                Two-factor Authentication (\\"2FA\\") is a system of double authentication.\\n                                The first one is done with your password and the second one with a code you get from a dedicated mobile app.\\n                                Popular ones include Authy, Google Authenticator or the Microsoft Authenticator.\\n                                <a href=\\"https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html\\" title=\\"Learn More\\" target=\\"_blank\\">\\n                                    <i title=\\"Documentation\\" class=\\"fa fa-fw o_button_icon fa-info-circle\\"/>\\n                                    Learn More\\n                                </a>\\n                                </span>\\n                                <span invisible=\\"not totp_enabled\\" class=\\"text-muted\\">This account is protected!</span>\\n                            </div>\\n                        <group name=\\"auth_devices\\" string=\\"Trusted Devices\\" invisible=\\"not totp_trusted_device_ids\\">\\n                            <div colspan=\\"2\\">\\n                                <field name=\\"totp_trusted_device_ids\\" nolabel=\\"1\\" colspan=\\"4\\" readonly=\\"1\\">\\n                                    <tree create=\\"false\\" delete=\\"false\\">\\n                                        <field name=\\"name\\" string=\\"Device\\"/>\\n                                        <field name=\\"create_date\\" string=\\"Added On\\"/>\\n                                        <button type=\\"object\\" name=\\"remove\\" title=\\"Revoke\\" icon=\\"fa-trash\\"/>\\n                                    </tree>\\n                                </field>\\n                                <button name=\\"revoke_all_devices\\" string=\\"Revoke All\\" type=\\"object\\" class=\\"btn btn-secondary\\" confirm=\\"Are you sure? The user may be asked to enter two-factor codes again on those devices\\"/>\\n                            </div>\\n                        </group>\\n                </page>\\n            </xpath>", "es_AR": "<xpath expr=\\"//page[@name='preferences']\\" position=\\"after\\">\\n                <page string=\\"Seguridad de la cuenta\\" name=\\"security\\" invisible=\\"not id\\">\\n                    <field name=\\"totp_enabled\\" invisible=\\"1\\"/>\\n                    <!-- For own user, allow to activate the two-factor Authentication --