iewBox=\\"0 0 16 20\\" fill=\\"none\\">\\n                                <rect x=\\"1.5\\" y=\\"3.5\\" width=\\"13\\" height=\\"13\\" stroke=\\"#AAAAAD\\"/>\\n                                <path d=\\"M2 4H14V10C14 13.3137 11.3137 16 8 16H2V4Z\\" fill=\\"#8C8C92\\"/>\\n                                <path d=\\"M6 11C7.65685 11 9 9.65685 9 8C9 6.34315 7.65685 5 6 5C4.34315 5 3 6.34315 3 8C3 9.65685 4.34315 11 6 11Z\\" fill=\\"#74747B\\"/>\\n                                <path d=\\"M6 10C7.10457 10 8 9.10457 8 8C8 6.89543 7.10457 6 6 6C4.89543 6 4 6.89543 4 8C4 9.10457 4.89543 10 6 10Z\\" fill=\\"white\\"/>\\n                                <rect x=\\"15\\" y=\\"17\\" width=\\"7\\" height=\\"0.999999\\" transform=\\"rotate(-180 15 17)\\" fill=\\"white\\"/>\\n                                <rect x=\\"15\\" y=\\"10\\" width=\\"7\\" height=\\"1\\" transform=\\"rotate(90 15 10)\\" fill=\\"white\\"/>\\n                            </svg>\\n                        </we-button>\\n                    </span>\\n                </div>\\n                <div class=\\"mx-1 o_custom_gradient_scale\\">\\n                    <div class=\\"w-100\\"/>\\n                </div>\\n                <div class=\\"w-100 o_slider_multi\\" role=\\"group\\"/>\\n                <we-button class=\\"o_remove_color fa fa-fw fa-trash o_we_link o_we_hover_danger\\" title=\\"Eliminar color seleccionado\\" aria-label=\\"Eliminar color seleccionado\\"/>\\n            </div>\\n        </div>\\n    </colorpicker>\\n</t>"}	<?xml version="1.0"?>\n<t name="Color-Picker" t-name="web_editor.colorpicker">\n    <colorpicker>\n        <div class="o_colorpicker_section" data-name="theme">\n            <button data-color="o-color-1"/>\n            <button data-color="o-color-3"/>\n            <button data-color="o-color-2"/>\n            <button data-color="o-color-4" class="ms-2"/>\n            <button data-color="o-color-5"/>\n        </div>\n        <div class="o_colorpicker_section" data-name="common">\n            <button data-color="black"/>\n            <button data-color="900"/>\n            <button data-color="800"/>\n            <button data-color="700" class="d-none"/>\n            <button data-color="600"/>\n            <button data-color="500" class="d-none"/>\n            <button data-color="400"/>\n            <button data-color="300" class="d-none"/>\n            <button data-color="200"/>\n            <button data-color="100"/>\n            <button data-color="white"/>\n        </div>\n        <div class="o_colorpicker_section" data-name="transparent_grayscale">\n            <button data-color="black-15"/>\n            <button data-color="black-25"/>\n            <button data-color="black-50"/>\n            <button data-color="black-75"/>\n            <button data-color="white-25"/>\n            <button data-color="white-50"/>\n            <button data-color="white-75"/>\n            <button data-color="white-85"/>\n        </div>\n        <div class="o_colorpicker_section" data-name="predefined_gradients">\n            <t t-set="gradients" t-value="[                 'linear-gradient(135deg, rgb(255, 204, 51) 0%, rgb(226, 51, 255) 100%)',                 'linear-gradient(135deg, rgb(102, 153, 255) 0%, rgb(255, 51, 102) 100%)',                 'linear-gradient(135deg, rgb(47, 128, 237) 0%, rgb(178, 255, 218) 100%)',                 'linear-gradient(135deg, rgb(203, 94, 238) 0%, rgb(75, 225, 236) 100%)',                 'linear-gradient(135deg, rgb(214, 255, 127) 0%, rgb(0, 179, 204) 100%)',                 'linear-gradient(135deg, rgb(255, 222, 69) 0%, rgb(69, 33, 0) 100%)',                 'linear-gradient(135deg, rgb(222, 222, 222) 0%, rgb(69, 69, 69) 100%)',                 'linear-gradient(135deg, rgb(255, 222, 202) 0%, rgb(202, 115, 69) 100%)'             ]"/>\n            <t t-foreach="gradients" t-as="gradient">\n                <button class="w-50" t-attf-style="background-image: #{gradient};" t-att-data-color="gradient"/>\n            </t>\n     