lass=\\"d-inline-flex\\">\\n                            <field name=\\"sale_ok\\"/>\\n                            <label for=\\"sale_ok\\"/>\\n                        </span>\\n                        <span class=\\"d-inline-flex\\">\\n                            <field name=\\"purchase_ok\\"/>\\n                            <label for=\\"purchase_ok\\"/>\\n                        </span>\\n                    </div>\\n                    <notebook>\\n                        <page string=\\"Información general\\" name=\\"general_information\\">\\n                            <group>\\n                                <group name=\\"group_general\\">\\n                                    <field name=\\"active\\" invisible=\\"1\\"/>\\n                                    <field name=\\"detailed_type\\"/>\\n                                    <field name=\\"product_tooltip\\" string=\\"\\" class=\\"fst-italic text-muted\\" invisible=\\"type == 'service' and not sale_ok\\"/>\\n                                    <field name=\\"uom_id\\" groups=\\"uom.group_uom\\" options=\\"{'no_create': True}\\"/>\\n                                    <field name=\\"uom_po_id\\" groups=\\"uom.group_uom\\" options=\\"{'no_create': True}\\"/>\\n                                </group>\\n                                <group name=\\"group_standard_price\\">\\n                                    <label for=\\"list_price\\"/>\\n                                    <div name=\\"pricing\\" class=\\"o_row\\">\\n                                      <field name=\\"list_price\\" class=\\"oe_inline\\" widget=\\"monetary\\" options=\\"{'currency_field': 'currency_id', 'field_digits': True}\\"/>\\n                                    </div>\\n\\n                                    <!--\\n                                        `id` condition to prevent invisibility on new products\\n                                        when `product_variant_count` is 0.\\n                                        `product_variant_count != 1` to handle cases with dynamic\\n                                        / multiple variants since id will be set after saving.\\n                                        #TODO : revert this and create a compute field in master\\n                                        to ensure invisivility for dynamic variants only.\\n                                    -->\\n                                    <label for=\\"standard_price\\" invisible=\\"id and product_variant_count != 1 and not is_product_variant\\"/>\\n                                    <div name=\\"standard_price_uom\\" invisible=\\"id and product_variant_count != 1 and not is_product_variant\\">\\n                                        <field name=\\"standard_price\\" class=\\"oe_inline\\" widget=\\"monetary\\" options=\\"{'currency_field': 'cost_currency_id', 'field_digits': True}\\"/>\\n                                        <span groups=\\"uom.group_uom\\">por\\n                                            <field name=\\"uom_name\\" class=\\"oe_inline\\"/>\\n                                        </span>\\n                                    </div>\\n                                    <field name=\\"categ_id\\" string=\\"Categoría del producto\\"/>\\n                                    <field name=\\"product_tag_ids\\" widget=\\"many2many_tags\\" context=\\"{'product_template_id': id}\\"/>\\n                                    <button name=\\"161\\" icon=\\"oi-arrow-right\\" type=\\"action\\" class=\\"btn-link ps-0\\" colspan=\\"2\\" string=\\"Configurar etiquetas\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\"/>\\n                                    <field name=\\"currency_id\\" invisible=\\"1\\"/>\\n                                    <field name=\\"cost_currency_id\\" invisible=\\"1\\"/>\\n                                    <field name=\\"product_variant_id\\" invisible=\\"1\\"/>\\n                                </group>\\n                            </group>\\n                            <group string=\\"Notas internas\\">\\n                                <field colspan=\\"2\\" name=\\"description\\" nolabel=\\"1\\" placeholder=\\"Esta nota es solo para fines internos.\\"/>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Ventas\\" name=\\"sales\\" invisible=\\"1 or not sale_ok\\">\\n                            <group name=\\"sale\\">\\n                                <group string=\\"Ventas adicionales y ventas cruzadas\\" name=\\"upsell\\" invisible=\\"1\\"/>\\n                            </group>\\n                            <group>\\n                                <group string=\\"Descripción de ventas\\" name=\\"description\\">\\n                                    <field colspan=\\"2\\" name=\\"description_sale\\" nolabel=\\"1\\" placeholder=\\"Esta nota se agrega a las órdenes de ventas y facturas.\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Compras\\" name=\\"purchase\\" invisible=\\"1 or not purchase_ok\\">\\n                            <group name=\\"purchase\\">\\n                                <group string=\\"Facturas de proveedores\\" name=\\"bill\\"/>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Inventario\\" name=\\"inventory\\" groups=\\"product.group_stock_packaging\\" invisible=\\"type == 'service'\\">\\n                            <group name=\\"inventory\\">\\n                                <group name=\\"group_lots_and_weight\\" string=\\"Logística\\" invisible=\\"type not in ['product', 'consu']\\">\\n                                    <label for=\\"weight\\" invisible=\\"product_variant_count &gt; 1 and not is_product_variant\\"/>\\n                                    <div class=\\"o_row\\" name=\\"weight\\" invisible=\\"product_variant_count &gt; 1 and not is_product_variant\\">\\n                                        <field name=\\"weight\\" class=\\"oe_inline\\"/>\\n                                        <field name=\\"weight_uom_name\\"/>\\n                                    </div>\\n                                    <label for=\\"volume\\" invisible=\\"product_variant_count &gt; 1 and not is_product_variant\\"/>\\n                                    <div class=\\"o_row\\" name=\\"volume\\" invisible=\\"product_variant_count &gt; 1 and not is_product_variant\\">\\n                                        <field name=\\"volume\\" string=\\"Volumen\\" class=\\"oe_inline\\"/>\\n                                        <field name=\\"volume_uom_name\\"/>\\n                                    </div>\\n                                </group>\\n                            </group>\\n                            <group name=\\"packaging\\" string=\\"Embalaje\\" colspan=\\"4\\" invisible=\\"(type not in ['product', 'consu'] or product_variant_count &gt; 1) and not is_product_variant\\" groups=\\"product.group_stock_packaging\\">\\n                                <field colspan=\\"2\\" name=\\"packaging_ids\\" nolabel=\\"1\\" context=\\"{'tree_view_ref':'product.product_packaging_tree_view2', 'default_company_id': company_id}\\"/>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <div class=\\"oe_chatter\\">\\n                    <field name=\\"message_follower_ids\\"/>\\n                    <field name=\\"activity_ids\\"/>\\n                    <field name=\\"message_ids\\"/>\\n                </div>\\n            </form>"}	<?xml version="1.0"?>\n<form string="Product">\n                <header>\n                    <button string="Print Labels" type="object" name="action_open_label_layout" invisible="detailed_type not in ['consu', 'product', 'combo']"/>\n                </header>\n                <sheet name="product_form">\n                    <field name="product_variant_count" invisible="1"/>\n                    <field name="is_product_variant" invisible="1"/>\n                    <field name="attribute_line_ids" invisible="1"/>\n                    <field name="type" invisible="1"/>\n                    <field name="company_id" invisible="1"/>\n                    <div class="oe_button_box" name="button_box">\n                        <button class="oe_stat_button" name="open_pricelist_rules" icon="fa-list-ul" groups="product.group_product_pricelist" type="object">\n                               <div class="o_field_widget o_stat_info">\n                                    <span class="o_stat_value">\n                                        <field name="pricelist_item_count"/>\n                                    </span>\n                                    <span class="o_stat_text" invisible="pricelist_item_count == 1">\n                                        Extra Prices\n                                    </span>\n                                    <span class="o_stat_text" invisible="pricelist_item_count != 1">\n                                        Extra Price\n                                    </span>\n                               </div>\n                        </button>\n                        <button class="oe_stat_button" name="action_open_documents" type="object" icon="fa-file-text-o">\n                            <field string="Documents" name="product_document_count" widget="statinfo"/>\n                        </button>\n                    </div>\n                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>\n                    <field name="id" invisible="True"/>\n                    <field name="image_1920" widget="image" class="oe_avatar" options="{'preview_image': 'image_128'}"/>\n                    <div class="oe_title">\n                        <label for="name" string="Product Name"/>\n                        <h1>\n                            <div class="d-flex">\n                                <field name="priority" widget="priority" class="me-3"/>\n                                <field class="text-break" name="name" options="{'line_breaks': False}" widget="text" placeholder="e.g. Cheese Burger"/>\n                            </div>\n                        </h1>\n                    </div>\n                    <div name="options">\n                        <span class="d-inline-flex">\n                            <field name="sale_ok"/>\n                            <label for="sale_ok"/>\n                        </span>\n                        <span class="d-inline-flex">\n                            <field name="purchase_ok"/>\n                            <label for="purchase_ok"/>\n                        </span>\n                    </div>\n                    <notebook>\n                        <page string="General Information" name="general_information">\n                            <group>\n                                <group name="group_general">\n                                    <field name="active" invisible="1"/>\n                                    <field name="detailed_type"/>\n                                    <field name="product_tooltip" string="" class="fst-italic text-muted" invisible="type == 'service' and not sale_ok"/>\n                                    <field name="uom_id" groups="uom.group_uom" options="{'no_create': True}"/>\n                                    <field name="uom_po_id" groups="uom.group_uom" options="{'no_create': True}"/>\n                                </group>\n                                <group name="group_standard_price">\n                                    <label for="list_price"/>\n                                    <div name="pricing" class="o_row">\n                                      <field name="list_price" class="oe_inline" widget="monetary" options="{'currency_field': 'currency_id', 'field_digits': True}"/>\n                                    </div>\n\n                                    <!--\n                                        `id` condition to prevent invisibility on new products\n                                        when `product_variant_count` is 0.\n                                        `product_variant_count != 1` to handle cases with dynamic\n                                        / multiple variants since id will be set after saving.\n                                        #TODO : revert this and create a compute field in master\n                                        to ensure invisivility for dynamic variants only.\n                                    -->\n                                    <label for="standard_price" invisible="id and product_variant_count != 1 and not is_product_variant"/>\n                                    <div name="standard_price_uom" invisible="id and product_variant_count != 1 and not is_product_variant">\n                                        <field name="standard_price" class="oe_inline" widget="monetary" options="{'currency_field': 'cost_currency_id', 'field_digits': True}"/>\n                                        <span groups="uom.group_uom">per\n                                            <field name="uom_name" class="oe_inline"/>\n                                        </span>\n                                    </div>\n                                    <field name="categ_id" string="Product Category"/>\n                                    <field name="product_tag_ids" widget="many2many_tags" context="{'product_template_id': id}"/>\n                                    <button name="161" icon="oi-arrow-right" type="action" class="btn-link ps-0" colspan="2" string="Configure tags"/>\n                                    <field name="company_id" groups="base.group_multi_company" options="{'no_create': True}"/>\n                                    <field name="currency_id" invisible="1"/>\n                                    <field name="cost_currency_id" invisible="1"/>\n                                    <field name="product_variant_id" invisible="1"/>\n                                </group>\n                            </group>\n                            <group string="Internal Notes">\n                                <field colspan="2" name="description" nolabel="1" placeholder="This note is only for internal purposes."/>\n                            </group>\n                        </page>\n                        <page string="Sales" name="sales" invisible="1 or not sale_ok">\n                            <group name="sale">\n                                <group string="Upsell &amp; Cross-Sell" name="upsell" invisible="1"/>\n                            </group>\n                            <group>\n                                <group string="Sales Description" name="description">\n                                    <field colspan="2" name="description_sale" nolabel="1" placeholder="This note is added to sales orders and invoices."/>\n                                </group>\n                            </group>\n                        </page>\n                        <page string="Purchase" name="purchase" invisible="1 or not purchase_ok">\n                            <group name="purchase">\n                                <group string="Vendor Bills" name="bill"/>\n                            </group>\n                        </page>\n                        <page string="Inventory" name="inventory" groups="product.group_stock_packaging" invisible="type == 'service'">\n                            <group name="inventory">\n                                <group name="group_lots_and_weight" string="Logistics" invisible="type not in ['product', 'consu']">\n                                    <label for="weight" invisible="product_variant_count &gt; 1 and not is_product_variant"/>\n                                    <div class="o_row" name="weight" invisible="product_variant_count &gt; 1 and not is_product_variant">\n                                        <field name="weight" class="oe_inline"/>\n                                        <field name="weight_uom_name"/>\n                                    </div>\n                                    <label for="volume" invisible="product_variant_count &gt; 1 and not is_product_variant"/>\n                                    <div class="o_row" name="volume" invisible="product_variant_count &gt; 1 and not is_product_variant">\n                                        <field name="volume" string="Volume" class="oe_inline"/>\n                                        <field name="volume_uom_name"/>\n                                    </div>\n                                </group>\n                            </group>\n                            <group name="packaging" string="Packaging" colspan="4" invisible="(type not in ['product', 'consu'] or product_variant_count &gt; 1) and not is_product_variant" groups="product.group_stock_packaging">\n                                <field colspan="2" name="packaging_ids" nolabel="1" context="{'tree_view_ref':'product.product_packaging_tree_view2', 'default_company_id': company_id}"/>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n                <div class="oe_chatter">\n                    <field name="message_follower_ids"/>\n                    <field name="activity_ids"/>\n                    <field name="message_ids"/>\n                </div>\n            </form>\n        	f	t	2026-10-23 14:02:38.104334	2026-10-23 14:02:38.104334	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
