>\\n                    <block title=\\"Products\\" name=\\"matrix_setting_container\\">\\n                        <setting id=\\"variant_options\\" help=\\"Purchase variants of a product using attributes (size, color, etc.)\\" documentation=\\"/applications/sales/sales/products_prices/products/variants.html\\">\\n                            <field name=\\"group_product_variant\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not group_product_variant\\">\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"167\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Attributes\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"product_matrix\\" title=\\"If installed, the product variants will be added to purchase orders through a grid entry.\\" string=\\"Variant Grid Entry\\" help=\\"Add several variants to the purchase order from a grid\\">\\n                            <field name=\\"module_purchase_product_matrix\\"/>\\n                        </setting>\\n                        <setting id=\\"stock_packaging_purchase\\" help=\\"Purchase products by multiple of unit # per package\\" title=\\"Ability to select a package type in purchase orders and to force a quantity that is a multiple of the number of units per package.\\">\\n                            <field name=\\"group_stock_packaging\\"/>\\n                        </setting>\\n                        <setting id=\\"sell_purchase_uom\\" help=\\"Sell and purchase products in different units of measure\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/products/uom.html\\">\\n                            <field name=\\"group_uom\\"/>\\n                            <div class=\\"content-group\\">\\n                                <div class=\\"mt8\\" invisible=\\"not group_uom\\">\\n                                    <button name=\\"88\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Units Of Measure\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                    </block>\\n                </app>\\n            </xpath>", "es_AR": "<xpath expr=\\"//form\\" position=\\"inside\\">\\n                <app data-string=\\"Purchase\\" string=\\"Compras\\" name=\\"purchase\\" groups=\\"purchase.group_purchase_manager\\">\\n                    <field name=\\"po_double_validation\\" invisible=\\"1\\"/>\\n                    <field name=\\"company_currency_id\\" invisible=\\"1\\"/>\\n                    <field name=\\"po_lock\\" invisible=\\"1\\"/>\\n                    <block title=\\"Órdenes\\" name=\\"purchase_setting_container\\">\\n                        <setting id=\\"po_order_approval\\" company_dependent=\\"1\\" help=\\"Solicítele a los gerentes que aprueben ordenes que tengan un importe por arriba del mínimo\\">\\n                            <field name=\\"po_order_approval\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not po_order_approval\\">\\n                                <div class=\\"row mt16\\">\\n                                    <label for=\\"po_double_validation_amount\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                    <field name=\\"po_double_validation_amount\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"automatic_lock_confirmed_orders\\" help=\\"Bloquee de forma automática las órdenes confirmadas para evitar su edición\\">\\n                            <field name=\\"lock_confirmed_po\\"/>\\n                        </setting>\\n                        <setting id=\\"get_order_warnings\\" string=\\"Advertencias\\" help=\\"Reciba advertencias en las órdenes de productos o proveedores\\">\\n                            <field name=\\"group_warning_purchase\\"/>\\n                        </setting>\\n                        <setting id=\\"manage_purchase_agreements\\" title=\\"Las licitaciones son útiles cuando quiere enviar solicitudes de cotización a varios proveedores para ciertos productos y comparar las ofertas.\\" documentation=\\"/applications/inventory_and_mrp/purchase/manage_deals/agreements.html\\" help=\\"Gestione sus acuerdos de compra (licitaciones, órdenes abiertas)\\">\\n                            <field name=\\"module_purchase_requisition\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not module_purchase_requisition\\">\\n                                <div id=\\"use_purchase_requisition\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"auto_receipt_reminder\\" help=\\"Recuérdele la fecha de recepción a sus proveedores de forma automática\\">\\n                            <field name=\\"group_send_reminder\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Facturación\\" name=\\"invoicing_settings_container\\">\\n                        <setting id=\\"quantities_billed_vendor\\" title=\\"Este valor predeterminado se aplica a los productos nuevos que cree, pero puede cambiarlo en el formulario de detalles correspondiente.\\" documentation=\\"/applications/inventory_and_mrp/purchase/manage_deals/control_bills.html\\" help=\\"Cantidades facturadas por los proveedores\\">\\n                            <field name=\\"default_purchase_method\\" class=\\"o_light_label\\" widget=\\"radio\\"/>\\n                        </setting>\\n                        <setting id=\\"three_way_matching\\" title=\\"Si está habilitado, activa la conciliación de tres vías en las facturas del proveedor y deberá recibir los artículos para poder pagar la factura.\\" documentation=\\"/applications/inventory_and_mrp/purchase/manage_deals/control_bills.html\\" help=\\"Asegúrese de solo pagar las facturas de los bienes recibidos\\">\\n                            <field name=\\"module_account_3way_match\\" string=\\"Conciliación de tres vías\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Productos\\" name=\\"matrix_setting_container\\">\\n                        <setting id=\\"variant_options\\" help=\\"Compre variantes de un producto utilizando atributos (tamaño, color, etc.)\\" documentation=\\"/applications/sales/sales/products_prices/products/variants.html\\">\\n                            <field name=\\"group_product_variant\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not group_product_variant\\">\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"167\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Atributos\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"product_matrix\\" title=\\"Si está instalado, las variantes del producto se agregarán a las órdenes de compra a través de una tabla.\\" string=\\"Entrada de la tabla de variante\\" help=\\"Agregue distintas variantes a una orden de compra desde una tabla\\">\\n                            <field name=\\"module_purchase_product_matrix\\"/>\\n                        </setting>\\n                        <setting id=\\"stock_packaging_purchase\\" help=\\"Compre productos por múltiplos de unidad por paquete\\" title=\\"Permite seleccionar un tipo de paquete en las órdenes de venta y forzar una cantidad que sea un múltiplo del número de unidades por paquete.\\">\\n                            <field name=\\"group_stock_packaging\\"/>\\n                    