le_order.id\\"><t t-esc=\\"sale_order.name\\"/></a>.\\n            </t>\\n            Es posible que se necesiten acciones manuales.\\n        </p>\\n        <div class=\\"mt16\\">\\n            <p>Excepciones:</p>\\n            <ul t-foreach=\\"sale_lines\\" t-as=\\"sale_line\\">\\n                <li>\\n                    <t t-set=\\"new_qty\\" t-value=\\"sale_line.product_uom_qty\\"/>\\n                    <t t-set=\\"old_qty\\" t-value=\\"origin_values.get(sale_line.id, 0.0)\\"/>\\n\\n                    <a href=\\"#\\" data-oe-model=\\"sale.order\\" t-att-data-oe-id=\\"sale_line.order_id.id\\"><t t-esc=\\"sale_line.order_id.name\\"/></a>:\\n                    <t t-esc=\\"new_qty\\"/> <t t-esc=\\"sale_line.product_uom.name\\"/> de <t t-esc=\\"sale_line.product_id.name\\"/> ordenado en lugar de <t t-esc=\\"old_qty\\"/> <t t-esc=\\"sale_line.product_uom.name\\"/>\\n                  </li>\\n            </ul>\\n        </div>\\n    </div>\\n</t>"}	<?xml version="1.0"?>\n<t name="Message: Alert on purchase orders when ordered quantity decreased on Sales Orders" t-name="sale_purchase.exception_purchase_on_sale_quantity_decreased">\n    <div>\n        <p>\n            Exception(s) occurred on the sale order(s):\n            <t t-foreach="sale_orders" t-as="sale_order">\n                <a href="#" data-oe-model="sale.order" t-att-data-oe-id="sale_order.id"><t t-esc="sale_order.name"/></a>.\n            </t>\n            Manual actions may be needed.\n        </p>\n        <div class="mt16">\n            <p>Exception(s):</p>\n            <ul t-foreach="sale_lines" t-as="sale_line">\n                <li>\n                    <t t-set="new_qty" t-value="sale_line.product_uom_qty"/>\n                    <t t-set="old_qty" t-value="origin_values.get(sale_line.id, 0.0)"/>\n\n                    <a href="#" data-oe-model="sale.order" t-att-data-oe-id="sale_line.order_id.id"><t t-esc="sale_line.order_id.name"/></a>:\n                    <t t-esc="new_qty"/> <t t-esc="sale_l