iv class=\\"wrap\\">\\n                <div class=\\"container\\">\\n                    <!-- Portal breadcrumb -->\\n                    <t t-call=\\"payment.portal_breadcrumb\\"/>\\n                    <!-- Payment page -->\\n                    <div class=\\"row justify-content-center my-3\\">\\n                        <div class=\\"col-lg-7\\">\\n                            <div t-if=\\"not amount\\" class=\\"alert alert-info\\">\\n                                No hay nada que pagar.\\n                            </div>\\n                            <div t-elif=\\"not currency\\" class=\\"alert alert-warning\\">\\n                                <strong>Advertencia</strong> Falta la divisa o es incorrecta.\\n                            </div>\\n                            <div t-elif=\\"not partner_id\\" class=\\"alert alert-warning\\">\\n                                <strong>Advertencia</strong> Debe iniciar sesión para pagar.\\n                            </div>\\n                            <div t-elif=\\"company_mismatch\\">\\n                                <t t-call=\\"payment.company_mismatch_warning\\"/>\\n                            </div>\\n                            <div t-elif=\\"not payment_methods_sudo and not tokens_sudo\\" class=\\"alert alert-warning\\">\\n                                <strong>No se encontró un método de pago adecuado.</strong><br/>\\n                                Si cree que esto es un error, contacte al administrador del\\n                                sitio web.\\n                            </div>\\n                            <t t-else=\\"\\">\\n                                <div t-if=\\"partner_is_different\\" class=\\"alert alert-warning\\">\\n                                    <strong>Advertencia</strong> Asegúrese de que inició sesión como\\n                                    el contacto correcto antes de realizar este pago.\\n                                </div>\\n                                <div c