        <t t-set=\\"label\\">Reference</t>\\n                                <t t-set=\\"value\\" t-value=\\"tx.reference\\"/>\\n                                <t t-set=\\"include_separator\\" t-value=\\"True\\"/>\\n                            </t>\\n                            <t t-if=\\"tx.payment_method_code != 'unknown'\\">\\n                               <t t-call=\\"payment.summary_item\\">\\n                                    <t t-set=\\"name\\" t-value=\\"'method'\\"/>\\n                                    <t t-set=\\"label\\">Payment Method</t>\\n                                    <t t-set=\\"value\\" t-value=\\"tx.payment_method_id.name\\"/>\\n                                    <t t-set=\\"include_separator\\" t-value=\\"True\\"/>\\n                               </t>\\n                            </t>\\n                            <t t-call=\\"payment.summary_item\\">\\n                                <t t-set=\\"name\\" t-value=\\"'provider'\\"/>\\n                                <t t-set=\\"label\\">Processed by</t>\\n                                <t t-set=\\"value\\" t-value=\\"tx.provider_id.sudo().name\\"/>\\n                                <t t-set=\\"include_separator\\" t-value=\\"True\\"/>\\n                            </t>\\n                        </div>\\n\\n                        <div class=\\"row\\">\\n                            <div class=\\"col offset-md-3 ps-0\\">\\n                                <a role=\\"button\\" class=\\"btn btn-primary float-end\\" href=\\"/my/home\\">\\n                                    Go to my Account <i class=\\"oi oi-arrow-right ms-2\\"/>\\n                                </a>\\n                            </div>\\n                        </div>\\n                    </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </t>\\n    </t>", "es_AR": "<t t-name=\\"payment.confirm\\">\\n        <!-- Parameters description:\\n            - tx: The transaction to display.\\n        -->\\n        <t t-call=\\"portal.frontend_layout\\">\\n            <t t-set=\\"page_title\\" t-value=\\"'Payment Confirmation'\\"/>\\n            <t t-set=\\"additional_title\\"><t t-esc=\\"page_title\\"/></t>\\n            <t t-set=\\"show_pm\\" t-value=\\"tx.payment_method_code != 'unknown'\\"/>\\n            <div class=\\"wrap\\">\\n                <div class=\\"container\\">\\n                    <!-- Portal breadcrumb -->\\n                    <t t-call=\\"payment.portal_breadcrumb\\"/>\\n                    <div class=\\"row justify-content-center my-3\\">\\n                    <div class=\\"col-12 col-lg-7\\">\\n                        <!-- Confirmation page -->\\n                        <div class=\\"row\\">\\n                            <div class=\\"col\\">\\n                                <t t-call=\\"payment.transaction_status\\"/>\\n                            </div>\\n                        </div>\\n                        <div t-att-class=\\"'o_cc o_cc2 row row-cols-1 mx-0 mb-3 py-2 rounded'                                           + (' row-cols-md-4' if show_pm else ' row-cols-md-3')\\">\\n                            <t t-call=\\"payment.summary_item\\">\\n                                <t t-set=\\"name\\" t-value=\\"'amount'\\"/>\\n                                <t t-set=\\"label\\">Importe</t>\\n                                <t t-set=\\"value\\" t-value=\\"tx.amount\\"/>\\n                                <t t-set=\\"options\\" t-value=\\"{'widget': 'monetary', 'display_currency': tx.currency_id}\\"/>\\n                            </t>\\n                            <t t-call=\\"payment.summary_item\\">\\n                                <t t-set=\\"name\\" t-value=\\"'reference'\\"/>\\n                                <t t-set=\\"label\\">Referencia</t>\\n                                <t t-set=\\"value\\" t-value=\\"tx.reference\\"/>\\n                                <t t-set=\\"include_separator\\" t-value=\\"True\\"/>\\n                            </t>\\n                            <t t-if=\\"tx.payment_method_code != 'unknown'\\">\\n                               <t t-call=\\"payment.summary_item\\">\\n                                    <t t-set=\\"name\\" t-value=\\"'method'\\"/>\\n                                    <t t-set=\\"label\\">Método de pago</t>\\n                                    <t t-set=\\"value\\" t-value=\\"tx.payment_method_id.name\\"/>\\n                                    <t t-set=\\"include_separator\\" t-value=\\"True\\"/>\\n                               </t>\\n                            </t>\\n                            <t t-call=\\"payment.summary_item\\">\\n                                <t t-set=\\"name\\" t-value=\\"'provider'\\"/>\\n                                <t t-set=\\"label\\">Procesado por</t>\\n                                <t t-set=\\"value\\" t-value=\\"tx.provider_id.sudo().name\\"/>\\n                                <t t-set=\\"include_separator\\" t-value=\\"True\\"/>\\n                            </t>\\n                        </div>\\n\\n                        <div class=\\"row\\">\\n                            <div class=\\"col offset-md-3 ps-0\\">\\n                                <a role=\\"button\\" class=\\"btn btn-primary float-end\\" href=\\"/my/home\\">\\n                                    Ir a mi cuenta <i class=\\"oi oi-arrow-right ms-2\\"/>\\n                                </a>\\n                            </div>\\n                        </div>\\n                    </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="payment.confirm">\n        <!-- Parameters description:\n            - tx: The transaction to display.\n        -->\n        <t t-call="portal.frontend_layout">\n            <t t-set="page_title" t-value="'Payment Confirmation'"/>\n            <t t-set="additional_title"><t t-esc="page_title"/></t>\n            <t t-set="show_pm" t-value="tx.payment_method_code != 'unknown'"/>\n            <div class="wrap">\n                <div class="container">\n                    <!-- Portal breadcrumb -->\n                    <t t-call="payment.portal_breadcrumb"/>\n                    <div class="row justify-content-center my-3">\n                    <div class="col-12 col-lg-7">\n                        <!-- Confirmation page -->\n                        <div class="row">\n                            <div class="col">\n                                <t t-call="payment.transaction_status"/>\n                            </div>\n                        </div>\n                        <div t-att-class="'o_cc o_cc2 row row-cols-1 mx-0 mb-3 py-2 rounded'                                           + (' row-cols-md-4' if show_pm else ' row-cols-md-3')">\n                            <t t-call="payment.summary_item">\n                                <t t-set="name" t-value="'amount'"/>\n                                <t t-set="label">Amount</t>\n                                <t t-set="value" t-value="tx.amount"/>\n                                <t t-set="options" t-value="{'widget': 'monetary', 'display_currency': tx.currency_id}"/>\n                            </t>\n                            <t t-call="payment.summary_item">\n                                <t t-set="name" t-value="'reference'"/>\n                                <t t-set="label">Reference</t>\n                                <t t-set="value" t-value="tx.reference"/>\n                                <t t-set="include_separator" t-value="True"/>\n                            </t>\n                            <t t-if="tx.payment_method_code != 'unknown'">\n                               <t t-call="payment.summary_item">\n                                    <t t-set="name" t-value="'method'"/>\n                                    <t t-set="label">Payment Method</t>\n                                    <t t-set="value" t-value="tx.payment_method_id.name"/>\n                                    <t t-set="include_separator" t-value="True"/>\n                               </t>\n                            </t>\n                            <t t-call="payment.summary_item">\n                                <t t-set="name" t-value="'provider'"/>\n                                <t t-set="label">Processed by</t>\n                                <t t-set="value" t-value="tx.provider_id.sudo().name"/>\n                                <t t-set="include_separator" t-value="True"/>\n                            </t>\n                        </div>\n\n                        <div class="row">\n                            <div class="col offset-md-3 ps-0">\n                                <a role="button" class="btn btn-primary float-end" href="/my/home">\n                                    Go to my Account <i class="oi oi-arrow-right ms-2"/>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    </div>\n                </div>\n            </div>\n        </t>\n    </t>\n\n    	f	t	2026-10-23 14:02:44.872857	2026-10-23 14:02:44.872857	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
575	16	\N	1	1	Payment Form	\N	payment.form	qweb	payment/views/payment_form_templates.xml	primary	{"en_US": "<t name=\\"Payment Form\\" t-name=\\"payment.form\\">\\n        <!-- Form customization parameters:\\n            - mode: The operation mode of the form: `payment` or `validation`; default: `payment`.\\n            - allow_token_selection: Whether tokens can be selected for payment or assignation\\n                                     (through the `assign_token_route` parameter); default: `True`.\\n            - allow_token_deletion: Whether tokens can be deleted (archived); default: `False`.\\n            - default_token_id: The id of the token that should be pre-selected; default: `None`.\\n            - show_tokenize_input_mapping: For each provider, whether the tokenization checkbox is\\n                                           shown; used only in `payment` mode.\\n            - display_submit_button: Whether the submit button is displayed; default: `True`.\\n            - submit_button_label: The label of the submit button; default: 'Pay'/'Save'.\\n        -->\\n        <!-- Payment context:\\n            - reference_prefix: The custom prefix to compute the full transaction reference.\\n            - amount: The amount to pay.\\n            - currency: The currency of the payment, as a `res.currency` record.\\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\\n                                    recordset.\\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\\n            - transaction_route: The route to call to create the transaction.\\n            - assign_token_route: The route to call to assign a new or existing token to a record.\\n            - landing_route: The route the user is redirected to after payment.\\n            - access_token: The access token used to authenticate the partner.\\n        -->\\n        <t t-set=\\"mode\\" t-value=\\"mode or 'payment'\\"/>\\n        <t t-set=\\"allow_token_selection\\" t-value=\\"True if allow_token_selection is None else allow_token_selection\\"/>\\n        <t t-set=\\"allow_token_deletion\\" t-value=\\"allow_token_deletion or False\\"/>\\n        <t t-set=\\"selected_token_id\\" t-value=\\"allow_token_selection and (default_token_id or tokens_sudo[:1].id)\\"/>\\n        <t t-set=\\"selected_method_id\\" t-value=\\"not selected_token_id                     and len(payment_methods_sudo) == 1                     and payment_methods_sudo[:1].id\\"/>\\n        <t t-set=\\"collapse_payment_methods\\" t-value=\\"tokens_sudo and allow_token_selection and payment_methods_sudo\\"/>\\n        <t t-set=\\"display_submit_button\\" t-value=\\"True if display_submit_button is None else display_submit_button\\"/>\\n        <t t-set=\\"pay_label\\">Pay</t> <!-- Allow translating the label. -->\\n        <t t-set=\\"save_label\\">Save</t> <!-- Allow translating the label. -->\\n        <t t-set=\\"submit_button_label\\" t-value=\\"submit_button_label or (pay_label if mode == 'payment' else save_label)\\"/>\\n        <form id=\\"o_payment_form\\" class=\\"o_payment_form\\" t-att-data-mode=\\"mode\\" t-att-data-reference-prefix=\\"reference_prefix\\" t-att-data-amount=\\"amount\\" t-att-data-currency-id=\\"currency and currency.id\\" t-att-data-partner-id=\\"partner_id\\" t-att-data-transaction-route=\\"transaction_route\\" t-att-data-assign-token-route=\\"assign_token_route\\" t-att-data-landing-route=\\"landing_route\\" t-att-data-access-token=\\"access_token\\">\\n            <div id=\\"o_payment_form_options\\" class=\\"d-flex flex-column gap-3\\">\\n                <!-- === Payment tokens === -->\\n                <div t-if=\\"tokens_sudo\\">\\n                    <!-- === Header === -->\\n                    <h4 id=\\"o_payment_tokens_heading\\" class=\\"fs-6 small text-uppercase fw-bolder\\">\\n                        Your payment methods\\n                    </h4>\\n                    <!-- === Body === -->\\n                    <ul class=\\"list-group\\">\\n                        <t t-foreach=\\"tokens_sudo\\" t-as=\\"token_sudo\\">\\n                            <li name=\\"o_payment_option\\" t-att-class=\\"'list-group-item d-flex flex-column gap-2 py-3'                                              + (' o_outline' if allow_token_selection else '')\\">\\n                                <t t-call=\\"payment.token_form\\">\\n                                    <t t-set=\\"is_selected\\" t-value=\\"token_sudo.id == selected_token_id\\"/>\\n                                </t>\\n                            </li>\\n                        </t>\\n                    </ul>\\n                </div>\\n                <!-- === Payment methods === -->\\n                <div t-if=\\"payment_methods_sudo\\" id=\\"o_payment_methods\\" t-att-class=\\"'collapse' if collapse_payment_methods else ''\\">\\n                    <!-- === Header === -->\\n                    <h4 class=\\"fs-6 small text-uppercase fw-bolder\\">\\n                        <t t-if=\\"not collapse_payment_methods\\">Choose a payment method</t>\\n                        <t t-else=\\"\\">Other payment methods</t>\\n                    </h4>\\n                    <!-- === Body === -->\\n                    <ul class=\\"list-group\\">\\n                        <t t-foreach=\\"payment_methods_sudo\\" t-as=\\"pm_sudo\\">\\n                            <li name=\\"o_payment_option\\" class=\\"list-group-item d-flex flex-column gap-2 py-3 o_outline\\">\\n                                <t t-call=\\"payment.method_form\\">\\n                                    <t t-set=\\"is_selected\\" t-value=\\"pm_sudo.id == selected_method_id\\"/>\\n                                </t>\\n                            </li>\\n                        </t>\\n                    </ul>\\n                </div>\\n            </div>\\n            <div class=\\"d-flex justify-content-end flex-column flex-md-row gap-2 my-2\\">\\n                <!-- === Expand payment methods button === -->\\n                <button t-if=\\"collapse_payment_methods\\" name=\\"o_payment_expand_button\\" type=\\"button\\" href=\\"#o_payment_methods\\" class=\\"btn btn-link\\" data-bs-toggle=\\"collapse\\">\\n                    Choose another method <i class=\\"oi oi-arrow-down\\"/>\\n                </button>\\n                <!-- === Submit button === -->\\n                <t t-if=\\"display_submit_button\\" t-call=\\"payment.submit_button\\"/>\\n            </div>\\n        </form>\\n    </t>", "es_AR": "<t name=\\"Payment Form\\" t-name=\\"payment.form\\">\\n        <!-- Form customization parameters:\\n            - mode: The operation mode of the form: `payment` or `validation`; default: `payment`.\\n            - allow_token_selection: Whether tokens can be selected for payment or assignation\\n                                     (through the `assign_token_route` parameter); default: `True`.\\n            - allow_token_deletion: Whether tokens can be deleted (archived); default: `False`.\\n            - default_token_id: The id of the token that should be pre-selected; default: `None`.\\n            - show_tokenize_input_mapping: For each provider, whether the tokenization checkbox is\\n                                           shown; used only in `payment` mode.\\n            - display_submit_button: Whether the submit button is displayed; default: `True`.\\n            - submit_button_label: The label of the submit button; default: 'Pay'/'Save'.\\n        -->\\n        <!-- Payment context:\\n            - reference_prefix: The custom prefix to compute the full transaction reference.\\n            - amount: The amount to pay.\\n            - currency: The currency of the payment, as a `res.currency` record.\\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\\n                                    recordset.\\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\\n            - transaction_route: The route to call to create the transaction.\\n            - assign_token_route: The route to call to assign a new or existing token to a record.\\n            - landing_route: The route the user is redirected to after payment.\\n            - access_token: The access token used to authenticate the partner.\\n        -->\\n        <t t-set=\\"mode\\" t-value=\\"mode or 'payment'\\"/>\\n        <t t-set=\\"allow_token_selection\\" t-value=\\"True if allow_token_selection is None else allow_token_selection\\"/>\\n        <t t-set=\\"allow_token_deletion\\" t-value=\\"allow_token_deletion or False\\"/>\\n        <t t-set=\\"selected_token_id\\" t-value=\\"allow_token_selection and (default_token_id or tokens_sudo[:1].id)\\"/>\\n        <t t-set=\\"selected_method_id\\" t-value=\\"not selected_token_id                     and len(payment_methods_sudo) == 1                     and payment_methods_sudo[:1].id\\"/>\\n        <t t-set=\\"collapse_payment_methods\\" t-value=\\"tokens_sudo and allow_token_selection and payment_methods_sudo\\"/>\\n        <t t-set=\\"display_submit_button\\" t-value=\\"True if display_submit_button is None else display_submit_button\\"/>\\n        <t t-set=\\"pay_label\\">Pagar</t> <!-- Allow translating the label. -->\\n        <t t-set=\\"save_label\\">Guardar</t> <!-- Allow translating the label. -->\\n        <t t-set=\\"submit_button_label\\" t-value=\\"submit_button_label or (pay_label if mode == 'payment' else save_label)\\"/>\\n        <form id=\\"o_payment_form\\" class=\\"o_payment_form\\" t-att-data-mode=\\"mode\\" t-att-data-reference-prefix=\\"reference_prefix\\" t-att-data-amount=\\"amount\\" t-att-data-currency-id=\\"currency and currency.id\\" t-att-data-partner-id=\\"partner_id\\" t-att-data-transaction-route=\\"transaction_route\\" t-att-data-assign-token-route=\\"assign_token_route\\" t-att-data-landing-route=\\"landing_route\\" t-att-data-access-token=\\"access_token\\">\\n            <div id=\\"o_payment_form_options\\" class=\\"d-flex flex-column gap-3\\">\\n                <!-- === Payment tokens === -->\\n                <div t-if=\\"tokens_sudo\\">\\n                    <!-- === Header === -->\\n                    <h4 id=\\"o_payment_tokens_heading\\" class=\\"fs-6 small text-uppercase fw-bolder\\">\\n                        Sus métodos de pago\\n                    </h4>\\n                    <!-- === Body === -->\\n                    <ul class=\\"list-group\\">\\n                        <t t-foreach=\\"tokens_sudo\\" t-as=\\"token_sudo\\">\\n                            <li name=\\"o_payment_option\\" t-att-class=\\"'list-group-item d-flex flex-column gap-2 py-3'                                              + (' o_outline' if allow_token_selection else '')\\">\\n                                <t t-call=\\"payment.token_form\\">\\n                                    <t t-set=\\"is_selected\\" t-value=\\"token_sudo.id == selected_token_id\\"/>\\n                                </t>\\n                            </li>\\n                        </t>\\n                    </ul>\\n                </div>\\n                <!-- === Payment methods === -->\\n                <div t-if=\\"payment_methods_sudo\\" id=\\"o_payment_methods\\" t-att-class=\\"'collapse' if collapse_payment_methods else ''\\">\\n                    <!-- === Header === -->\\n                    <h4 class=\\"fs-6 small text-uppercase fw-bolder\\">\\n                        <t t-if=\\"not collapse_payment_methods\\">Elija un método de pago</t>\\n                        <t t-else=\\"\\">Otros métodos de pago </t>\\n                    </h4>\\n                    <!-- === Body === -->\\n                    <ul class=\\"list-group\\">\\n                        <t t-foreach=\\"payment_methods_sudo\\" t-as=\\"pm_sudo\\">\\n                            <li name=\\"o_payment_option\\" class=\\"list-group-item d-flex flex-column gap-2 py-3 o_outline\\">\\n                                <t t-call=\\"payment.method_form\\">\\n                                    <t t-set=\\"is_selected\\" t-value=\\"pm_sudo.id == selected_method_id\\"/>\\n                                </t>\\n                            </li>\\n                        </t>\\n                    </ul>\\n                </div>\\n            </div>\\n            <div class=\\"d-flex justify-content-end flex-column flex-md-row gap-2 my-2\\">\\n                <!-- === Expand payment methods button === -->\\n                <button t-if=\\"collapse_payment_methods\\" name=\\"o_payment_expand_button\\" type=\\"button\\" href=\\"#o_payment_methods\\" class=\\"btn btn-link\\" data-bs-toggle=\\"collapse\\">\\n                    Elija otro método <i class=\\"oi oi-arrow-down\\"/>\\n                </button>\\n                <!-- === Submit button === -->\\n                <t t-if=\\"display_submit_button\\" t-call=\\"payment.submit_button\\"/>\\n            </div>\\n        </form>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Payment Form" t-name="payment.form">\n        <!-- Form customization parameters:\n            - mode: The operation mode of the form: `payment` or `validation`; default: `payment`.\n            - allow_token_selection: Whether tokens can be selected for payment or assignation\n                                     (through the `assign_token_route` parameter); default: `True`.\n            - allow_token_deletion: Whether tokens can be deleted (archived); default: `False`.\n            - default_token_id: The id of the token that should be pre-selected; default: `None`.\n            - show_tokenize_input_mapping: For each provider, whether the tokenization checkbox is\n                                           shown; used only in `payment` mode.\n            - display_submit_button: Whether the submit button is displayed; default: `True`.\n            - submit_button_label: The label of the submit button; default: 'Pay'/'Save'.\n        -->\n        <!-- Payment context:\n            - reference_prefix: The custom prefix to compute the full transaction reference.\n            - amount: The amount to pay.\n            - currency: The currency of the payment, as a `res.currency` record.\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\n                                    recordset.\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\n            - transaction_route: The route to call to create the transaction.\n            - assign_token_route: The route to call to assign a new or existing token to a record.\n            - landing_route: The route the user is redirected to after payment.\n            - access_token: The access token used to authenticate the partner.\n        -->\n        <t t-set="mode" t-value="mode or 'payment'"/>\n        <t t-set="allow_token_selection" t-value="True if allow_token_selection is None else allow_token_selection"/>\n        <t t-set="allow_token_deletion" t-value="allow_token_deletion or False"/>\n        <t t-set="selected_token_id" t-value="allow_token_selection and (default_token_id or tokens_sudo[:1].id)"/>\n        <t t-set="selected_method_id" t-value="not selected_token_id                     and len(payment_methods_sudo) == 1                     and payment_methods_sudo[:1].id"/>\n        <t t-set="collapse_payment_methods" t-value="tokens_sudo and allow_token_selection and payment_methods_sudo"/>\n        <t t-set="display_submit_button" t-value="True if display_submit_button is None else display_submit_button"/>\n        <t t-set="pay_label">Pay</t> <!-- Allow translating the label. -->\n        <t t-set="save_label">Save</t> <!-- Allow translating the label. -->\n        <t t-set="submit_button_label" t-value="submit_button_label or (pay_label if mode == 'payment' else save_label)"/>\n        <form id="o_payment_form" class="o_payment_form" t-att-data-mode="mode" t-att-data-reference-prefix="reference_prefix" t-att-data-amount="amount" t-att-data-currency-id="currency and currency.id" t-att-data-partner-id="partner_id" t-att-data-transaction-route="transaction_route" t-att-data-assign-token-route="assign_token_route" t-att-data-landing-route="landing_route" t-att-data-access-token="access_token">\n            <div id="o_payment_form_options" class="d-flex flex-column gap-3">\n                <!-- === Payment tokens === -->\n                <div t-if="tokens_sudo">\n                    <!-- === Header === -->\n                    <h4 id="o_payment_tokens_heading" class="fs-6 small text-uppercase fw-bolder">\n                        Your payment methods\n                    </h4>\n                    <!-- === Body === -->\n                    <ul class="list-group">\n                        <t t-foreach="tokens_sudo" t-as="token_sudo">\n                            <li name="o_payment_option" t-att-class="'list-group-item d-flex flex-column gap-2 py-3'                                              + (' o_outline' if allow_token_selection else '')">\n                                <t t-call="payment.token_form">\n                                    <t t-set="is_selected" t-value="token_sudo.id == selected_token_id"/>\n                                </t>\n                            </li>\n                        </t>\n                    </ul>\n                </div>\n                <!-- === Payment methods === -->\n                <div t-if="payment_methods_sudo" id="o_payment_methods" t-att-class="'collapse' if collapse_payment_methods else ''">\n                    <!-- === Header === -->\n                    <h4 class="fs-6 small text-uppercase fw-bolder">\n                        <t t-if="not collapse_payment_methods">Choose a payment method</t>\n                        <t t-else="">Other payment methods</t>\n                    </h4>\n                    <!-- === Body === -->\n                    <ul class="list-group">\n                        <t t-foreach="payment_methods_sudo" t-as="pm_sudo">\n                            <li name="o_payment_option" class="list-group-item d-flex flex-column gap-2 py-3 o_outline">\n                                <t t-call="payment.method_form">\n                                    <t t-set="is_selected" t-value="pm_sudo.id == selected_method_id"/>\n                                </t>\n                            </li>\n                        </t>\n                    </ul>\n                </div>\n            </div>\n            <div class="d-flex justify-content-end flex-column flex-md-row gap-2 my-2">\n                <!-- === Expand payment methods button === -->\n                <button t-if="collapse_payment_methods" name="o_payment_expand_button" type="button" href="#o_payment_methods" class="btn btn-link" data-bs-toggle="collapse">\n                    Choose another method <i class="oi oi-arrow-down"/>\n                </button>\n                <!-- === Submit button === -->\n                <t t-if="display_submit_button" t-call="payment.submit_button"/>\n            </div>\n        </form>\n    </t>\n\n    	f	t	2026-10-23 14:02:44.872857	2026-10-23 14:02:44.872857	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
