l amount.\\"/>\\n                    </div>\\n                    <field name=\\"void_remaining_amount\\" readonly=\\"not has_remaining_amount\\"/>\\n                </group>\\n                <div id=\\"alert_amount_to_capture_above_authorized_amount\\" role=\\"alert\\" class=\\"alert alert-warning mb-2\\" invisible=\\"is_amount_to_capture_valid\\">\\n                    <strong>Warning!</strong> You can not capture a negative amount nor more\\n                    than <field name=\\"available_amount\\" class=\\"oe_inline\\" widget=\\"monetary\\"/>.\\n                </div>\\n                <footer>\\n                    <button string=\\"Capture\\" type=\\"object\\" name=\\"action_capture\\" class=\\"btn-primary\\"/>\\n                    <button string=\\"Close\\" special=\\"cancel\\" class=\\"btn-secondary\\"/>\\n                </footer>\\n            </form>", "es_AR": "<form string=\\"Capturar \\">\\n                <field name=\\"transaction_ids\\" invisible=\\"1\\"/>\\n                <field name=\\"is_amount_to_capture_valid\\" invisible=\\"1\\"/>\\n                <field name=\\"currency_id\\" invisible=\\"1\\"/>\\n                <field name=\\"support_partial_capture\\" invisible=\\"1\\"/>\\n                <field name=\\"has_draft_children\\" invisible=\\"1\\"/>\\n                <field name=\\"has_remaining_amount\\" invisible=\\"1\\"/>\\n                <div id=\\"alert_draft_capture_tx\\" role=\\"alert\\" class=\\"alert alert-warning\\" invisible=\\"not has_draft_children\\">\\n                    <strong>¡Advertencia!</strong> Hay una captura parcial pendiente. Espere\\n                    un momento para que se procese. Revise la configuración del pago de su proveedor si\\n                    la captura aún está pendiente después de unos minutos.\\n                </div>\\n                <group name=\\"readonly_fields\\">\\n                    <field name=\\"authorized_amount\\"/>\\n                    <field name=\\"captured_amount\\" invisible=\\"captured_amount &lt;= 0\\"/>\\n                    <field name=\\"voided_amount\\" invisible=\\"voided_amount &lt;= 0\\"/>\\n                </group>\\n                <hr/>\\n                <group name=\\"input_fields\\">\\n                    <label for=\\"amount_to_capture\\" class=\\"oe_inline\\"/>\\n                    <div class=\\"o_row\\">\\n                        <field name=\\"amount_to_capture\\" class=\\"oe_inline\\" readonly=\\"support_partial_capture == 'full_only'\\"/>\\n                        <i class=\\"fa fa-info-circle oe_inline\\" invisible=\\"support_partial_capture != 'full_only'\\" title=\\"Algunas de las transacciones que intenta capturar, solo se pueden capturar completas. Maneje las transacciones individualmente para capturar un importe parcial.\\"/>\\n                    </div>\\n                    <field name=\\"void_remaining_amount\\" readonly=\\"not has_remaining_amount\\"/>\\n                </group>\\n                <div id=\\"alert_amount_to_capture_above_authorized_amount\\" role=\\"alert\\" class=\\"alert alert-warning mb-2\\" invisible=\\"is_amount_to_capture_valid\\">\\n                    <strong>¡Advertencia!</strong> No puede capturar una cantidad negativa mayor\\n                    a <field name=\\"available_amount\\" class=\\"oe_inline\\" widget=\\"monetary\\"/>.\\n                </div>\\n                <footer>\\n                    <button string=\\"Capturar \\" type=\\"object\\" name=\\"action_capture\\" class=\\"btn-primary\\"/>\\n                    <button string=\\"Cerrar\\" special=\\"cancel\\" class=\\"btn-secondary\\"/>\\n                </footer>\\n            </form>"}	<?xml version="1.0"?>\n<form string="Capture">\n                <field name="transaction_ids" invisible="1"/>\n                <field name="is_amount_to_capture_valid" invisible="1"/>\n                <field name="currency_id" invisible="1"/>\n                <field name="support_partial_capture" invisible="1"/>\n                <field