\"pricelist_configuration\\" documentation=\\"/applications/sales/sales/products_prices/prices/pricing.html\\" help=\\"Set multiple prices per product, automated discounts, etc.\\">\\n                            <field name=\\"group_product_pricelist\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not group_product_pricelist\\">\\n                                <div class=\\"mt16\\">\\n                                    <field name=\\"group_sale_pricelist\\" invisible=\\"1\\"/>\\n                                    <field name=\\"product_pricelist_setting\\" widget=\\"radio\\" class=\\"o_light_label\\"/>\\n                                </div>\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"170\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Pricelists\\" groups=\\"product.group_product_pricelist\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"auth_signup_documents\\" title=\\" To send invitations in B2B mode, open a contact or select several ones in list view and click on 'Portal Access Management' option in the dropdown menu *Action*.\\" help=\\"Let your customers log in to see their documents\\">\\n                            <field name=\\"auth_signup_uninvited\\" class=\\"o_light_label\\" widget=\\"radio\\" options=\\"{'horizontal': true}\\" required=\\"True\\"/>\\n                        </setting>\\n                        <setting id=\\"show_margins\\" help=\\"Show margins on orders\\" title=\\"The margin is computed as the sum of product sales prices minus the cost set in their detail form.\\">\\n                            <field name=\\"module_sale_margin\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Quotations &amp; Orders\\" name=\\"quotation_order_setting_container\\">\\n                        <setting id=\\"order_default_values\\" string=\\"Default values\\" help=\\"Default values used when creating new quotations. Those can still be changed on each quotation.\\" company_dependent=\\"1\\">\\n                            <div class=\\"mt16\\" id=\\"order_default_values_div\\">\\n                                <div>\\n                                    <field name=\\"portal_confirmation_sign\\" class=\\"w-auto\\"/>\\n                                    <label for=\\"portal_confirmation_sign\\"/>\\n                                    <a href=\\"https://www.odoo.com/documentation/17.0/applications/sales/sales/send_quotations/get_signature_to_validate.html\\" title=\\"Documentation\\" class=\\"me-2 o_doc_link\\" target=\\"_blank\\"/>\\n                                </div>\\n                                <div class=\\"text-muted\\">\\n                                    Request an online signature to confirm orders\\n                                </div>\\n                                <div class=\\"mt16\\">\\n                                    <field name=\\"portal_confirmation_pay\\" class=\\"col-lg-4 oe_inline\\"/>\\n                                    <label for=\\"portal_confirmation_pay\\"/>\\n                                    <a href=\\"https://www.odoo.com/documentation/17.0/applications/sales/sales/send_quotations/get_paid_to_validate.html\\" title=\\"Documentation\\" class=\\"me-2 o_doc_link\\" target=\\"_blank\\"/>\\n                                </div>\\n                                <div class=\\"text-muted\\">\\n                                    Request an online prepayment from your customers to confirm orders. You can ask them to fully pay the order or partially with a downpayment\\n                                </div>\\n                                <div invisible=\\"not portal_confirmation_pay\\" class=\\"text-nowrap fw-bold\\">\\n                                    Prepayment amount\\n                                    <field name=\\"prepayment_percent\\" widget=\\"percentage\\" style=\\"width: 3rem\\"/>\\n                                </div>\\n                                <div class=\\"mt8\\" invisible=\\"not portal_confirmation_pay\\">\\n                                    <button name=\\"204\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Payment Providers\\" class=\\"btn-link\\"/>\\n                                </div>\\n                                <div class=\\"mt16\\" title=\\"Days between quotation proposal and expiration. 0 days means automatic expiration is disabled\\">\\n                                    <label for=\\"quotation_validity_days\\"/>\\n                                    <field name=\\"quotation_validity_days\\" class=\\"text-center\\" style=\\"width: 5rem;\\"/>\\n                                    <div class=\\"d-inline-block\\">days</div>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"order_warnings\\" string=\\"Sale Warnings\\" help=\\"Get warnings in orders for products or customers\\">\\n                            <field name=\\"group_warning_sale\\"/>\\n                        </setting>\\n                        <setting id=\\"sale_pdf_quote_builder\\" string=\\"PDF Quote builder\\" help=\\"Make your quote attractive by adding header pages, product descriptions and footer pages to your quote.\\">\\n                            <field name=\\"module_sale_pdf_quote_builder\\"/>\\n                        </setting>\\n                        <setting id=\\"no_edit_order\\" help=\\"No longer edit orders once confirmed\\">\\n                            <field name=\\"group_auto_done_setting\\"/>\\n                        </setting>\\n                        <setting id=\\"proforma_configuration\\" help=\\"Allows you to send Pro-Forma Invoice to your customers\\">\\n                            <field name=\\"group_proforma_sales\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Shipping\\" name=\\"sale_shipping_setting_container\\">\\n                        <setting id=\\"delivery\\" help=\\"Compute shipping costs on orders\\">\\n                            <field name=\\"module_delivery\\"/>\\n                        </setting>\\n                        <setting id=\\"ups\\">\\n                            <div class=\\"o_form_label\\">UPS Connector</div>\\n                                <a href=\\"https://www.odoo.com/documentation/17.0/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Documentation\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Compute shipping costs and ship with UPS<br/>\\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\\n                                </div>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_dhl\\">\\n                            <div class=\\"o_form_label\\">DHL Connector</div>\\n                                <a href=\\"https://www.odoo.com/documentation/17.0/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Documentation\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Compute shipping costs and ship with DHL<br/>\\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\\n                                </div>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_fedex\\">\\n                            <div class=\\"o_form_label\\">FedEx Connector</div>\\n                                <a href=\\"https://www.odoo.com/documentation/17.0/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Documentation\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Compute shipping costs and ship with FedEx<br/>\\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\\n                                </div>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_usps\\">\\n                            <div class=\\"o_form_label\\">USPS Connector</div>\\n                                <a href=\\"https://www.odoo.com/documentation/17.0/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Documentation\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Compute shipping costs and ship with USPS<br/>\\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\\n                                </div>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_bpost\\" help=\\"Compute shipping costs and ship with bpost\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_bpost\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_easypost\\" help=\\"Compute shipping costs and ship with Easypost\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_easypost\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_sendcloud\\" help=\\"Compute shipping costs and ship with Sendcloud\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_sendcloud\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                        <setting id=\\"shipping_costs_shiprocket\\" help=\\"Compute shipping costs and ship with Shiprocket\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                            <field name=\\"module_delivery_shiprocket\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Invoicing\\" name=\\"invoicing_setting_container\\">\\n                        <setting id=\\"sales_settings_invoicing_policy\\" title=\\"This default value is applied to any new product created. This can be changed in the product detail form.\\" documentation=\\"/applications/sales/sales/invoicing/invoicing_policy.html\\" help=\\"Quantities to invoice from sales orders\\">\\n                            <field name=\\"default_invoice_policy\\" class=\\"o_light_label\\" widget=\\"radio\\"/>\\n                        </setting>\\n                        <setting id=\\"automatic_invoicing\\" help=\\"Generate the invoice automatically when the online payment is confirmed\\" invisible=\\"default_invoice_policy != 'order' or not portal_confirmation_pay\\">\\n                            <field name=\\"automatic_invoice\\"/>\\n                            <div invisible=\\"not automatic_invoice\\" groups=\\"base.group_no_one\\">\\n                                <label for=\\"invoice_mail_template_id\\" class=\\"o_light_label me-2\\"/>\\n                                <field name=\\"invoice_mail_template_id\\" class=\\"oe_inline\\" options=\\"{'no_create': True}\\"/>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"down_payments\\" string=\\"Down Payments\\" help=\\"Product used for down payments\\" documentation=\\"/applications/sales/sales/invoicing/down_payment.html\\" company_dependent=\\"1\\">\\n                            <field name=\\"deposit_default_product_id\\" context=\\"{'default_detailed_type': 'service'}\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Connectors\\" id=\\"connectors_setting_container\\">\\n                        <setting id=\\"amazon_connector\\" documentation=\\"/applications/sales/sales/amazon_connector/setup.html\\" help=\\"Import Amazon orders and sync deliveries\\">\\n                            <field name=\\"module_sale_amazon\\" widget=\\"upgrade_boolean\\"/>\\n                            <div class=\\"content-group\\" name=\\"amazon_connector\\" invisible=\\"not module_sale_amazon\\"/>\\n                        </setting>\\n                    </block>\\n                    <div id=\\"sale_ebay\\"/>\\n                </app>\\n            </xpath>", "es_AR": "<xpath expr=\\"//form\\" position=\\"inside\\">\\n                <app notApp=\\"1\\" string=\\"Ventas\\" data-string=\\"Sales\\" name=\\"sale_management\\" groups=\\"sales_team.group_sale_manager\\">\\n                    <block title=\\"Catálogo de productos\\" name=\\"catalog_setting_container\\">\\n                        <setting id=\\"variant_options\\" help=\\"Venda variantes de sus productos con atributos (tamaño, color, entre otros)\\" documentation=\\"/applications/sales/sales/products_prices/products/variants.html\\">\\n                            <field name=\\"group_product_variant\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not group_product_variant\\">\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"167\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Atributos\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting string=\\"Entrada de la tabla de variante\\" help=\\"Agregar varias variantes a una orden desde una tabla\\" id=\\"product_matrix\\">\\n                            <field name=\\"module_sale_product_matrix\\"/>\\n                        </setting>\\n                        <setting id=\\"uom_settings\\" help=\\"Vender y comprar productos en diferentes unidades de medida\\">\\n                            <field name=\\"group_uom\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not group_uom\\">\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"88\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Unidades de medida\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"email_template\\" title=\\"Enviar un correo electrónico es útil si necesita compartir información específica o contenido acerca de un producto (instrucciones, reglas, enlaces, medios, etc.). Cree y configure la plantilla de correo electrónico desde el formulario de detalles del producto (en la pestaña de Contabilidad).\\" string=\\"Enviar contenido por correo electrónico\\" help=\\"Envíe un correo electrónico específico para el producto luego de validar la factura\\">\\n                            <field name=\\"module_product_email_template\\"/>\\n                        </setting>\\n                        <setting id=\\"stock_packaging\\" title=\\"Permite seleccionar un tipo de paquete en las órdenes de venta y forzar una cantidad que sea un múltiplo del número de unidades por paquete.\\" help=\\"Vender productos por múltiplo de número de unidad por paquete\\">\\n                            <field name=\\"group_stock_packaging\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Precios\\" id=\\"pricing_setting_container\\">\\n                      <setting id=\\"discount_sale_order_lines\\" title=\\"Aplique descuentos de forma manual en las líneas de las órdenes de venta o muestre los descuentos calculados desde la lista de precios (se activa la opción en la configuración de la lista de precios).\\" help=\\"Ofrezca descuentos en las líneas de las órdenes de venta\\">\\n                            <field name=\\"group_discount_per_so_line\\"/>\\n                       </setting>\\n                        <setting id=\\"coupon_settings\\" title=\\"Aumente sus ventas con varios tipos de programas: cupones, promociones, tarjetas de regalo y programas de lealtad. Puede establecer condiciones específicas (productos, clientes, importe de compra mínimo, periodo). Las recompensas pueden ser descuentos (un porcentaje o un importe) o productos gratis.\\" string=\\"Descuentos, programas de lealtad y tarjetas de regalo\\" help=\\"Gestiona promociones, cupones, tarjetas de lealtad, tarjetas de regalo y monederos electrónicos\\">\\n                            <field name=\\"module_loyalty\\"/>\\n                        </setting>\\n                        <setting id=\\"pricelist_configuration\\" documentation=\\"/applications/sales/sales/products_prices/prices/pricing.html\\" help=\\"Establezca varios precios por producto, descuentos automáticos, etc.\\">\\n                            <field name=\\"group_product_pricelist\\"/>\\n                            <div class=\\"content-group\\" invisible=\\"not group_product_pricelist\\">\\n                                <div class=\\"mt16\\">\\n                                    <field name=\\"group_sale_pricelist\\" invisible=\\"1\\"/>\\n                                    <field name=\\"product_pricelist_setting\\" widget=\\"radio\\" class=\\"o_light_label\\"/>\\n                                </div>\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"170\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Listas de precios\\" groups=\\"product.group_product_pricelist\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </div>\\n                        </setting>\\n                        <setting id=\\"auth_signup_documents\\" title=\\"Para enviar invitaciones en modo B2B, seleccione un contacto o varios en la vista de lista y haga clic en la opción &quot;Administración del acceso al portal&quot; en el menú desplegable *Acción*.\\" help=\\"Permita que sus clientes inicien sesión para ver sus documentos\\">\\n                            <field name=\\"auth_signup_uninvited\\" class=\\"o_light_label\\" widget=\\"radio\\" options=\\"{'horizontal': true}\\" required=\\"True\\"/>\\n                        </setting>\\n                        <setting id=\\"show_margins\\" help=\\"Mostrar márgenes en órdenes\\" title=\\"El margen se calcula como la suma de los precios de venta del producto menos el costo establecido en su forma detallada.\\">\\n                            <field name=\\"module_sale_margin\\"/>\\n                        </setting>\\n                    </block>\\n                    <block title=\\"Cotizaciones y órdenes\\" name=\\"quotation_order_setting_container\\">\\n                        <setting id=\\"order_default_values\\" string=\\"Valores predeterminados\\" help=\\"Los valores predeterminados que se utilizan cuando se crean nuevas cotizaciones, estos se pueden cambiar en cada cotización.\\" company_dependent=\\"1\\">\\n                            <div class=\\"mt16\\" id=\\"order_default_values_div\\">\\n                                <div>\\n                                    <field name=\\"portal_confirmation_sign\\" class=\\"w-auto\\"/>\\n                                    <label for=\\"portal_confirmation_sign\\"/>\\n                                    <a href=\\"https://www.odoo.com/documentation/17.0/applications/sales/sales/send_quotations/get_signature_to_validate.html\\" title=\\"Documentación\\" class=\\"me-2 o_doc_link\\" target=\\"_blank\\"/>\\n                                </div>\\n                                <div class=\\"text-muted\\">\\n                                    Solicitar firma en línea para confirmar órdenes\\n                                </div>\\n                                <div class=\\"mt16\\">\\n                                    <field name=\\"portal_confirmation_pay\\" class=\\"col-lg-4 oe_inline\\"/>\\n                                    <label for=\\"portal_confirmation_pay\\"/>\\n                                    <a href=\\"https://www.odoo.com/documentation/17.0/applications/sales/sales/send_quotations/get_paid_to_validate.html\\" title=\\"Documentación\\" class=\\"me-2 o_doc_link\\" target=\\"_blank\\"/>\\n                                </div>\\n                                <div class=\\"text-muted\\">\\n                                    Solicite a sus clientes que realicen el pago de un anticipo en línea para confirmar las órdenes. Puede pedirles que paguen la orden completa o solo una parte con un anticipo.\\n                                </div>\\n                                <div invisible=\\"not portal_confirmation_pay\\" class=\\"text-nowrap fw-bold\\">\\n                                    Importe de pago anticipado\\n                                    <field name=\\"prepayment_percent\\" widget=\\"percentage\\" style=\\"width: 3rem\\"/>\\n                                </div>\\n                                <div class=\\"mt8\\" invisible=\\"not portal_confirmation_pay\\">\\n                                    <button name=\\"204\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Proveedores de pago\\" class=\\"btn-link\\"/>\\n                                </div>\\n       