1053	16	\N	1	1	sale.order.form	sale.order	\N	form	sale/views/sale_order_views.xml	primary	{"en_US": "<form string=\\"Sales Order\\" class=\\"o_sale_order\\">\\n            <header>\\n                <field name=\\"locked\\" invisible=\\"1\\"/>\\n                <field name=\\"authorized_transaction_ids\\" invisible=\\"1\\"/>\\n                <button name=\\"payment_action_capture\\" type=\\"object\\" data-hotkey=\\"shift+g\\" string=\\"Capture Transaction\\" class=\\"oe_highlight\\" invisible=\\"not authorized_transaction_ids\\"/>\\n                <button name=\\"payment_action_void\\" type=\\"object\\" string=\\"Void Transaction\\" data-hotkey=\\"shift+v\\" confirm=\\"Are you sure you want to void the authorized transaction? This action can't be undone.\\" invisible=\\"not authorized_transaction_ids\\"/>\\n                <button id=\\"create_invoice\\" name=\\"362\\" string=\\"Create Invoice\\" type=\\"action\\" class=\\"btn-primary\\" data-hotkey=\\"q\\" invisible=\\"invoice_status != 'to invoice'\\"/>\\n                <button id=\\"create_invoice_percentage\\" name=\\"362\\" string=\\"Create Invoice\\" type=\\"action\\" context=\\"{'default_advance_payment_method': 'percentage'}\\" data-hotkey=\\"q\\" invisible=\\"invoice_status != 'no' or state != 'sale'\\"/>\\n                <button name=\\"action_quotation_send\\" id=\\"send_by_email_primary\\" string=\\"Send by Email\\" type=\\"object\\" data-hotkey=\\"g\\" invisible=\\"state != 'draft'\\" class=\\"btn-primary\\" context=\\"{'validate_analytic': True}\\"/>\\n                <button name=\\"action_quotation_send\\" id=\\"send_proforma_primary\\" type=\\"object\\" string=\\"Send PRO-FORMA Invoice\\" class=\\"btn-primary\\" groups=\\"sale.group_proforma_sales\\" invisible=\\"state != 'draft' or invoice_count &gt;= 1\\" context=\\"{'proforma': True, 'validate_analytic': True}\\"/>\\n                <button name=\\"action_confirm\\" id=\\"action_confirm\\" data-hotkey=\\"q\\" string=\\"Confirm\\" class=\\"btn-primary\\" type=\\"object\\" context=\\"{'validate_analytic': True}\\" invisible=\\"state != 'sent'\\"/>\\n                <button name=\\"action_confirm\\" data-hotkey=\\"q\\" string=\\"Confirm\\" type=\\"object\\" context=\\"{'validate_analytic': True}\\" invisible=\\"state != 'draft'\\"/>\\n                <button name=\\"action_quotation_send\\" id=\\"send_proforma\\" type=\\"object\\" string=\\"Send PRO-FORMA Invoice\\" groups=\\"sale.group_proforma_sales\\" invisible=\\"state == 'draft' or invoice_count &gt;= 1\\" context=\\"{'proforma': True, 'validate_analytic': True}\\"/>\\n                <button name=\\"action_quotation_send\\" id=\\"send_by_email\\" string=\\"Send by Email\\" type=\\"object\\" invisible=\\"state not in ('sent', 'sale')\\" data-hotkey=\\"g\\" context=\\"{'validate_analytic': True}\\"/>\\n\\n                <!-- allow to unlock locked orders even if setting is not enabled (e.g. orders synchronized from connectors) -->\\n                <button name=\\"action_unlock\\" type=\\"object\\" string=\\"Unlock\\" invisible=\\"not locked\\" groups=\\"sales_team.group_sale_manager\\"/>\\n                <button name=\\"action_preview_sale_order\\" string=\\"Preview\\" type=\\"object\\" class=\\"btn-secondary\\"/>\\n                <button name=\\"action_cancel\\" type=\\"object\\" string=\\"Cancel\\" invisible=\\"state not in ['draft', 'sent', 'sale'] or not id or locked\\" data-hotkey=\\"x\\"/>\\n                <button name=\\"action_draft\\" invisible=\\"state != 'cancel'\\" type=\\"object\\" string=\\"Set to Quotation\\" data-hotkey=\\"w\\"/>\\n                <t groups=\\"sale.group_auto_done_setting\\">\\n                    <button name=\\"action_lock\\" type=\\"object\\" string=\\"Lock\\" help=\\"If the sale is locked, you can not modify it anymore. However, you will still be able to invoice or deliver.\\" invisible=\\"locked or state != 'sale'\\" groups=\\"sales_team.group_sale_manager\\"/>\\n                </t>\\n                <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,sent,sale\\"/>\\n            </header>\\n            <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"partner_credit_warning == ''\\">\\n                <field name=\\"partner_credit_warning\\"/>\\n            </div>\\n            <sheet>\\n                <div class=\\"oe_button_box\\" name=\\"button_box\\">\\n                    <button name=\\"action_view_invoice\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-pencil-square-o\\" invisible=\\"invoice_count == 0\\">\\n                        <field name=\\"invoice_count\\" widget=\\"statinfo\\" string=\\"Invoices\\"/>\\n                    </button>\\n                </div>\\n                <div class=\\"badge rounded-pill text-bg-secondary float-end fs-6 border-0\\" invisible=\\"not locked\\">\\n                    <i class=\\"fa fa-lock\\"/>\\n                    Locked\\n                </div>\\n                <div class=\\"oe_title\\">\\n                    <h1>\\n                        <field name=\\"name\\" readonly=\\"1\\"/>\\n                    </h1>\\n                </div>\\n                <group name=\\"sale_header\\">\\n                    <group name=\\"partner_details\\">\\n                        <field name=\\"partner_id\\" widget=\\"res_partner_many2one\\" context=\\"{'res_partner_search_mode': 'customer', 'show_address': 1, 'show_vat': True}\\" placeholder=\\"Type to find a customer...\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <field name=\\"partner_invoice_id\\" groups=\\"account.group_delivery_invoice_address\\" context=\\"{'default_type':'invoice', 'show_address': False, 'show_vat': False}\\" readonly=\\"state == 'cancel' or locked\\"/>\\n                        <field name=\\"partner_shipping_id\\" groups=\\"account.group_delivery_invoice_address\\" context=\\"{'default_type':'delivery', 'show_address': False, 'show_vat': False}\\" readonly=\\"state == 'cancel' or locked\\"/>\\n                    </group>\\n                    <group name=\\"order_details\\">\\n                        <field name=\\"validity_date\\" invisible=\\"state == 'sale'\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <div class=\\"o_td_label\\" groups=\\"base.group_no_one\\" invisible=\\"state in ['sale', 'cancel']\\">\\n                            <label for=\\"date_order\\" string=\\"Quotation Date\\"/>\\n                        </div>\\n                        <field name=\\"date_order\\" nolabel=\\"1\\" groups=\\"base.group_no_one\\" invisible=\\"state in ['sale', 'cancel']\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <div class=\\"o_td_label\\" invisible=\\"state in ['draft', 'sent']\\">\\n                            <label for=\\"date_order\\" string=\\"Order Date\\"/>\\n                        </div>\\n                        <field name=\\"date_order\\" invisible=\\"state in ['draft', 'sent']\\" readonly=\\"state in ['cancel', 'sale']\\" nolabel=\\"1\\"/>\\n                        <field name=\\"has_active_pricelist\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_update_pricelist\\" invisible=\\"1\\"/>\\n                        <label for=\\"pricelist_id\\" groups=\\"product.group_product_pricelist\\" invisible=\\"not has_active_pricelist\\"/>\\n                        <div groups=\\"product.group_product_pricelist\\" class=\\"o_row\\" invisible=\\"not has_active_pricelist\\">\\n                            <field name=\\"pricelist_id\\" options=\\"{'no_open':True,'no_create': True}\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                            <button name=\\"action_update_prices\\" type=\\"object\\" string=\\" Update Prices\\" help=\\"Recompute all prices based on this pricelist\\" class=\\"btn-link mb-1 px-0\\" icon=\\"fa-refresh\\" confirm=\\"This will update the unit price of all products based on the new pricelist.\\" invisible=\\"not show_update_pricelist or state in ['sale', 'cancel']\\"/>\\n                        </div>\\n                        <field name=\\"country_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"currency_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"pricelist_id\\" invisible=\\"1\\" readonly=\\"state in ['cancel', 'sale']\\" groups=\\"!product.group_product_pricelist\\"/>\\n                        <field name=\\"tax_country_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                        <field name=\\"payment_term_id\\" options=\\"{'no_open': True, 'no_create': True}\\"/>\\n                    </group>\\n                </group>\\n                <notebook>\\n                    <page string=\\"Order Lines\\" name=\\"order_lines\\">\\n                        <field name=\\"order_line\\" widget=\\"section_and_note_one2many\\" mode=\\"tree,kanban\\" readonly=\\"state == 'cancel' or locked\\">\\n                            <form>\\n                                <field name=\\"display_type\\" invisible=\\"1\\"/>\\n                                <!--\\n                                    We need the sequence field to be here for new lines to be added at the correct position.\\n                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.\\n                                -->\\n                                <field name=\\"sequence\\" invisible=\\"1\\"/>\\n                                <field name=\\"product_uom_category_id\\" invisible=\\"1\\"/>\\n                                <group>\\n                                    <group invisible=\\"display_type\\">\\n                                        <field name=\\"product_updatable\\" invisible=\\"1\\"/>\\n                                        <field name=\\"product_id\\" domain=\\"[('sale_ok', '=', True)]\\" context=\\"{'partner_id':parent.partner_id, 'quantity':product_uom_qty, 'pricelist':parent.pricelist_id, 'uom':product_uom, 'company_id': parent.company_id}\\" readonly=\\"not product_updatable\\" required=\\"not display_type\\" force_save=\\"1\\" widget=\\"many2one_barcode\\"/>\\n                                        <field name=\\"product_type\\" invisible=\\"1\\"/>\\n                                        <field name=\\"invoice_status\\" invisible=\\"1\\"/>\\n                                        <field name=\\"qty_to_invoice\\" invisible=\\"1\\"/>\\n                                        <field name=\\"qty_delivered_method\\" invisible=\\"1\\"/>\\n                                        <field name=\\"price_total\\" invisible=\\"1\\"/>\\n                                        <field name=\\"price_tax\\" invisible=\\"1\\"/>\\n                                        <field name=\\"price_subtotal\\" invisible=\\"1\\"/>\\n                                        <field name=\\"product_uom_readonly\\" invisible=\\"1\\"/>\\n                                        <label for=\\"product_uom_qty\\"/>\\n                                        <div class=\\"o_row\\" name=\\"ordered_qty\\">\\n                                            <field context=\\"{'partner_id':parent.partner_id, 'quantity':product_uom_qty, 'pricelist':parent.pricelist_id, 'uom':product_uom, 'uom_qty_change':True, 'company_id': parent.company_id}\\" name=\\"product_uom_qty\\"/>\\n                                            <field name=\\"product_uom\\" invisible=\\"1\\" groups=\\"!uom.group_uom\\"/>\\n                                            <field name=\\"product_uom\\" force_save=\\"1\\" groups=\\"uom.group_uom\\" class=\\"oe_no_button\\" readonly=\\"product_uom_readonly\\" required=\\"not display_type\\"/>\\n                                        </div>\\n                                        <label for=\\"qty_delivered\\" string=\\"Delivered\\" invisible=\\"parent.state != 'sale'\\"/>\\n                                        <div name=\\"delivered_qty\\" invisible=\\"parent.state != 'sale'\\">\\n                                            <field name=\\"qty_delivered\\" readonly=\\"qty_delivered_method != 'manual'\\"/>\\n                                        </div>\\n                                        <label for=\\"qty_invoiced\\" string=\\"Invoiced\\" invisible=\\"parent.state != 'sale'\\"/>\\n                                        <div name=\\"invoiced_qty\\" invisible=\\"parent.state != 'sale'\\">\\n                                            <field name=\\"qty_invoiced\\"/>\\n                                        </div>\\n                                        <field name=\\"product_packaging_qty\\" invisible=\\"not product_id or not product_packaging_id\\" groups=\\"product.group_stock_packaging\\"/>\\n                                        <field name=\\"product_packaging_id\\" invisible=\\"not product_id\\" context=\\"{'default_product_id': product_id, 'tree_view_ref':'product.product_packaging_tree_view', 'form_view_ref':'product.product_packaging_form_view'}\\" groups=\\"product.group_stock_packaging\\"/>\\n                                        <field name=\\"price_unit\\"/>\\n                                        <field name=\\"tax_id\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\" context=\\"{'search_view_ref': 'account.account_tax_view_search'}\\" domain=\\"[('type_tax_use', '=', 'sale'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]\\" readonly=\\"qty_invoiced &gt; 0\\"/>\\n                                        <t groups=\\"product.group_discount_per_so_line\\">\\n                                            <label for=\\"discount\\"/>\\n                                            <div name=\\"discount\\">\\n                                                <field name=\\"discount\\" class=\\"oe_inline\\"/> %\\n                                            </div>\\n                                        </t>\\n                                        <!--\\n                                            We need the sequence field to be here\\n                                            because we want to be able to overwrite the default sequence value in the JS\\n                                            in order for new lines to be added at the correct position.\\n                                            NOTE: at some point we want to fix this in the framework so that an invisible field is not required.\\n                                        -->\\n                                        <field name=\\"sequence\\" invisible=\\"1\\"/>\\n                                    </group>\\n                                    <group invisible=\\"display_type\\">\\n                                        <label for=\\"customer_lead\\"/>\\n                                        <div name=\\"lead\\">\\n                                            <field name=\\"customer_lead\\" class=\\"oe_inline\\"/> days\\n                                        </div>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" options=\\"{'product_field': 'product_id', 'business_domain': 'sale_order'}\\"/>\\n                                    </group>\\n                                </group>\\n                                <label for=\\"name\\" string=\\"Description\\" invisible=\\"display_type\\"/>\\n                                <label for=\\"name\\" string=\\"Section Name (eg. Products, Services)\\" invisible=\\"display_type != 'line_section'\\"/>\\n                                <label for=\\"name\\" string=\\"Note\\" invisible=\\"display_type != 'line_note'\\"/>\\n                                <field name=\\"name\\"/>\\n                                <div name=\\"invoice_lines\\" groups=\\"base.group_no_one\\" invisible=\\"display_type\\">\\n                                    <label for=\\"invoice_lines\\"/>\\n                                    <field name=\\"invoice_lines\\"/>\\n                                </div>\\n                                <field name=\\"state\\" invisible=\\"1\\"/>\\n                                <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                            </form>\\n                            <tree string=\\"Sales Order Lines\\" editable=\\"bottom\\" limit=\\"200\\">\\n                                <control>\\n                                    <create name=\\"add_product_control\\" string=\\"Add a product\\"/>\\n                                    <create name=\\"add_section_control\\" string=\\"Add a section\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                    <create name=\\"add_note_control\\" string=\\"Add a note\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                    <button name=\\"action_add_from_catalog\\" string=\\"Catalog\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                </control>\\n\\n                                <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                <!-- We do not display the type because we don't want the user to be bothered with that information if he has no section or note. -->\\n                                <field name=\\"display_type\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_uom_category_id\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_type\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_updatable\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"is_downpayment\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_id\\" readonly=\\"not product_updatable\\" required=\\"not display_type\\" force_save=\\"1\\" context=\\"{                                         'partner_id': parent.partner_id,                                         'quantity': product_uom_qty,                                         'pricelist': parent.pricelist_id,                                         'uom':product_uom,                                         'company_id': parent.company_id,                                         'default_lst_price': price_unit,                                         'default_description_sale': name                                     }\\" options=\\"{                                         'no_open': True,                                     }\\" domain=\\"[('sale_ok', '=', True)]\\" widget=\\"sol_product_many2one\\"/>\\n                                <field name=\\"product_template_id\\" string=\\"Product\\" column_invisible=\\"True\\" readonly=\\"not product_updatable\\" required=\\"not display_type\\" context=\\"{                                         'partner_id': parent.partner_id,                                         'quantity': product_uom_qty,                                         'pricelist': parent.pricelist_id,                                         'uom':product_uom,                                         'company_id': parent.company_id,                                         'default_list_price': price_unit,                                         'default_description_sale': name                                     }\\" options=\\"{                                         'no_open': True,                                     }\\" domain=\\"[('sale_ok', '=', True)]\\" widget=\\"sol_product_many2one\\" placeholder=\\"Type to find a product...\\"/>\\n                                <field name=\\"name\\" widget=\\"section_and_note_text\\" optional=\\"show\\"/>\\n                                <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" optional=\\"hide\\" groups=\\"analytic.group_analytic_accounting\\" options=\\"{'product_field': 'product_id', 'business_domain': 'sale_order', 'amount_field': 'price_subtotal'}\\"/>\\n                                <field name=\\"product_uom_qty\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" context=\\"{                                         'partner_id': parent.partner_id,                                         'quantity': product_uom_qty,                                         'pricelist': parent.pricelist_id,                                         'uom': product_uom,                                         'company_id': parent.company_id                                     }\\" readonly=\\"is_downpayment\\"/>\\n                                <field name=\\"qty_delivered\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" string=\\"Delivered\\" column_invisible=\\"parent.state != 'sale'\\" readonly=\\"qty_delivered_method != 'manual' or is_downpayment\\" optional=\\"show\\"/>\\n                                <field name=\\"qty_delivered_method\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"qty_invoiced\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" string=\\"Invoiced\\" column_invisible=\\"parent.state != 'sale'\\" optional=\\"show\\"/>\\n                                <field name=\\"qty_to_invoice\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_uom_readonly\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_uom\\" column_invisible=\\"True\\" groups=\\"!uom.group_uom\\"/>\\n                                <field name=\\"product_uom\\" force_save=\\"1\\" string=\\"UoM\\" readonly=\\"product_uom_readonly\\" required=\\"not display_type\\" context=\\"{'company_id': parent.company_id}\\" groups=\\"uom.group_uom\\" options=\\"{&quot;no_open&quot;: True}\\" optional=\\"show\\"/>\\n                                <field name=\\"customer_lead\\" optional=\\"hide\\" readonly=\\"parent.state not in ['draft', 'sent', 'sale'] or is_downpayment\\"/>\\n                                <field name=\\"product_packaging_qty\\" invisible=\\"not product_id or not product_packaging_id\\" groups=\\"product.group_stock_packaging\\" optional=\\"show\\"/>\\n                                <field name=\\"product_packaging_id\\" invisible=\\"not product_id\\" context=\\"{'default_product_id': product_id, 'tree_view_ref':'product.product_packaging_tree_view', 'form_view_ref':'product.product_packaging_form_view'}\\" groups=\\"product.group_stock_packaging\\" optional=\\"show\\"/>\\n                                <field name=\\"price_unit\\" readonly=\\"qty_invoiced &gt; 0\\"/>\\n                                <field name=\\"tax_id\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\" domain=\\"[('type_tax_use', '=', 'sale'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]\\" context=\\"{'active_test': True}\\" readonly=\\"qty_invoiced &gt; 0 or is_downpayment\\" optional=\\"show\\"/>\\n                                <field name=\\"discount\\" string=\\"Disc.%\\" groups=\\"product.group_discount_per_so_line\\" optional=\\"show\\"/>\\n                                <field name=\\"is_downpayment\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"price_subtotal\\" string=\\"Tax excl.\\" invisible=\\"is_downpayment\\"/>\\n                                <field name=\\"price_total\\" string=\\"Tax incl.\\" column_invisible=\\"parent.tax_calculation_rounding_method == 'round_globally'\\" invisible=\\"is_downpayment\\" optional=\\"hide\\"/>\\n                                <!-- Others fields -->\\n                                <field name=\\"tax_calculation_rounding_method\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"state\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"invoice_status\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"currency_id\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"price_tax\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                            </tree>\\n                            <kanban class=\\"o_kanban_mobile\\">\\n                                <field name=\\"name\\"/>\\n                                <field name=\\"product_id\\"/>\\n                                <field name=\\"product_uom_qty\\"/>\\n                                <field name=\\"product_uom\\"/>\\n                                <field name=\\"price_subtotal\\"/>\\n                                <field name=\\"price_total\\"/>\\n                                <field name=\\"price_tax\\"/>\\n                                <field name=\\"price_total\\"/>\\n                                <field name=\\"price_unit\\"/>\\n                                <field name=\\"display_type\\"/>\\n                                <field name=\\"tax_id\\"/>\\n                                <field name=\\"company_id\\"/>\\n                                <field name=\\"tax_calculation_rounding_method\\"/>\\n                                <control>\\n                                    <create name=\\"add_product_control\\" string=\\"Add a product\\"/>\\n                                    <create name=\\"add_section_control\\" string=\\"Add a section\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                    <create name=\\"add_note_control\\" string=\\"Add a note\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                    <button name=\\"action_add_from_catalog\\" context=\\"{'order_id': parent.id}\\" string=\\"Catalog\\" type=\\"object\\" class=\\"btn-secondary\\"/>\\n                                </control>\\n                                <templates>\\n                                    <t t-name=\\"kanban-box\\">\\n                                        <div t-attf-class=\\"oe_kanban_card oe_kanban_global_click ps-0 pe-0 {{ record.display_type.raw_value ? 'o_is_' + record.display_type.raw_value : '' }}\\">\\n                                            <t t-if=\\"!record.display_type.raw_value\\">\\n                                                <div class=\\"row g-0\\">\\n                                                    <div class=\\"col-2 pe-3\\">\\n                                                        <img t-att-src=\\"kanban_image('product.product', 'image_128', record.product_id.raw_value)\\" t-att-title=\\"record.product_id.value\\" t-att-alt=\\"record.product_id.value\\" style=\\"max-width: 100%;\\"/>\\n                                                    </div>\\n                                                    <div class=\\"col-10\\">\\n                                                        <div class=\\"row\\">\\n                                                            <div class=\\"col\\">\\n                                                                <strong t-out=\\"record.product_id.value\\"/>\\n                                                            </div>\\n                                                            <div class=\\"col-auto\\">\\n                                                                <strong>Tax excl.: </strong>\\n                                                                <t t-set=\\"line_price\\" t-value=\\"record.price_subtotal.value\\"/>\\n                                                                <strong class=\\"float-end text-end\\" t-out=\\"line_price\\"/>\\n                                                            </div>\\n                                                        </div>\\n                                                        <div class=\\"row\\">\\n                                                            <div class=\\"col-12 text-muted\\">\\n                                                                Quantity:\\n                                                                <t t-out=\\"record.product_uom_qty.value\\"/> <t t-out=\\"record.product_uom.value\\"/>\\n                                                            </div>\\n                                                        </div>\\n                                                        <div class=\\"row\\">\\n                                                            <div class=\\"col text-muted\\">\\n                                                                Unit Price:\\n                                                                <t t-out=\\"record.price_unit.value\\"/>\\n                                                            </div>\\n                                                            <div class=\\"col-auto\\" t-if=\\"record.tax_calculation_rounding_method.raw_value === 'round_per_line'\\">\\n                                                                <strong>Tax incl.: </strong>\\n                                                                <t t-set=\\"line_price\\" t-value=\\"record.price_total.value\\"/>\\n                                                                <strong class=\\"float-end text-end\\" t-out=\\"line_price\\"/>\\n                                                            </div>\\n                                                        </div>\\n                                                        <t t-if=\\"record.discount?.raw_value\\">\\n                                                            <div class=\\"row\\">\\n                                                                <div class=\\"col-12 text-muted\\">\\n                                                                    Discount:\\n                                                                    <t t-out=\\"record.discount.value\\"/>%\\n                                                                </div>\\n                                                            </div>\\n                                                        </t>\\n                                                    </div>\\n                                                </div>\\n                                            </t>\\n                                            <t t-if=\\"record.display_type.raw_value === 'line_section' || record.display_type.raw_value === 'line_note'\\">\\n                                                <div class=\\"row\\">\\n                                                    <div class=\\"col-12\\">\\n                                                        <t t-out=\\"record.name.value\\"/>\\n                                                    </div>\\n                                                </div>\\n                                            </t>\\n                                        </div>\\n                                    </t>\\n                                </templates>\\n                            </kanban>\\n                        </field>\\n                        <div class=\\"float-end d-flex gap-1 mb-2 ms-1\\" name=\\"so_button_below_order_lines\\">\\n                            <button string=\\"Discount\\" name=\\"action_open_discount_wizard\\" type=\\"object\\" class=\\"btn btn-secondary\\" groups=\\"product.group_discount_per_so_line\\"/>\\n                        </div>\\n                        <group name=\\"note_group\\" col=\\"6\\" class=\\"mt-2 mt-md-0\\">\\n                            <group colspan=\\"4\\">\\n                                <field colspan=\\"2\\" name=\\"note\\" nolabel=\\"1\\" placeholder=\\"Terms and conditions...\\"/>\\n                            </group>\\n                            <group class=\\"oe_subtotal_footer\\" colspan=\\"2\\" name=\\"sale_total\\">\\n                                <field name=\\"tax_totals\\" widget=\\"account-tax-totals-field\\" nolabel=\\"1\\" colspan=\\"2\\" readonly=\\"1\\"/>\\n                            </group>\\n                            <div class=\\"clearfix\\"/>\\n                        </group>\\n                    </page>\\n                    <page string=\\"Other Info\\" name=\\"other_information\\">\\n                        <group>\\n                            <group name=\\"sales_person\\" string=\\"Sales\\">\\n                                <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\"/>\\n                                <field name=\\"team_id\\" context=\\"{'kanban_view_ref': 'sales_team.crm_team_view_kanban'}\\" options=\\"{'no_create': True}\\"/>\\n                                <field name=\\"company_id\\" options=\\"{'no_create': True}\\" groups=\\"base.group_multi_company\\"/>\\n                                <field name=\\"require_signature\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                                <label for=\\"require_payment\\"/>\\n                                <div id=\\"require_payment\\">\\n                                    <field name=\\"require_payment\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                                    <span class=\\"mx-3\\" invisible=\\"not require_payment\\">of</span>\\n                                    <field name=\\"prepayment_percent\\" readonly=\\"state in ['cancel', 'sale']\\" invisible=\\"not require_payment\\" widget=\\"percentage\\" style=\\"width: 3rem\\"/>\\n                                </div>\\n                                <field name=\\"reference\\" readonly=\\"1\\" invisible=\\"not reference\\"/>\\n                                <field name=\\"client_order_ref\\"/>\\n                                <field name=\\"tag_ids\\" widget=\\"many2many_tags\\" options=\\"{'color_field': 'color', 'no_create_edit': True}\\"/>\\n                            </group>\\n                            <group name=\\"sale_info\\" string=\\"Invoicing\\">\\n                                <field name=\\"show_update_fpos\\" invisible=\\"1\\"/>\\n                                <label for=\\"fiscal_position_id\\"/>\\n                                <div class=\\"o_row\\">\\n                                    <field name=\\"fiscal_position_id\\" options=\\"{'no_create': True}\\"/>\\n                                    <button name=\\"action_update_taxes\\" type=\\"object\\" string=\\" Update Taxes\\" help=\\"Recompute all taxes based on this fiscal position\\" class=\\"btn-link mb-1 px-0\\" icon=\\"fa-refresh\\" confirm=\\"This will update all taxes based on the currently selected fiscal position.\\" invisible=\\"not show_update_fpos or state in ['sale', 'cancel']\\"/>\\n                                </div>\\n                                <field name=\\"partner_invoice_id\\" groups=\\"!account.group_delivery_invoice_address\\" invisible=\\"1\\"/>\\n                                <field name=\\"analytic_account_id\\" context=\\"{'default_partner_id':partner_invoice_id, 'default_name':name}\\" readonly=\\"invoice_count != 0 and state == 'sale'\\" groups=\\"analytic.group_analytic_accounting\\" force_save=\\"1\\"/>\\n                                <field name=\\"journal_id\\" groups=\\"base.group_no_one\\" readonly=\\"invoice_count != 0 and state == 'sale'\\"/>\\n                                <field name=\\"invoice_status\\" invisible=\\"state != 'sale'\\" groups=\\"base.group_no_one\\"/>\\n                                <!-- test_event_configurator -->\\n                                <field name=\\"invoice_status\\" invisible=\\"1\\" groups=\\"!base.group_no_one\\"/>\\n                            </group>\\n                            <group name=\\"sale_shipping\\" string=\\"Shipping\\">\\n                                <label for=\\"commitment_date\\" string=\\"Delivery Date\\"/>\\n                                <div name=\\"commitment_date_div\\" class=\\"o_row\\">\\n                                    <field name=\\"commitment_date\\" readonly=\\"state == 'cancel' or locked\\"/>\\n                                    <span name=\\"expected_date_span\\" class=\\"text-muted\\">Expected: <field name=\\"expected_date\\" class=\\"oe_inline\\" widget=\\"date\\"/></span>\\n                                </div>\\n                            </group>\\n                            <group string=\\"Tracking\\" name=\\"sale_reporting\\">\\n                                <field name=\\"origin\\"/>\\n                                <field name=\\"campaign_id\\" options=\\"{'create_name_field': 'title'}\\"/>\\n                                <field name=\\"medium_id\\"/>\\n                                <field name=\\"source_id\\"/>\\n                            </group>\\n                        </group>\\n                    </page>\\n                    <page groups=\\"base.group_no_one\\" string=\\"Customer Signature\\" name=\\"customer_signature\\" invisible=\\"1\\">\\n                        <group>\\n                            <field name=\\"signed_by\\" readonly=\\"signature\\"/>\\n                            <field name=\\"signed_on\\" readonly=\\"signature\\"/>\\n                            <field name=\\"signature\\" widget=\\"image\\"/>\\n                        </group>\\n                    </page>\\n                </notebook>\\n            </sheet>\\n            <div class=\\"oe_chatter\\">\\n                <field name=\\"message_follower_ids\\"/>\\n                <field name=\\"activity_ids\\"/>\\n                <field name=\\"message_ids\\"/>\\n            </div>\\n            </form>", "es_AR": "<form string=\\"Orden de venta\\" class=\\"o_sale_order\\">\\n            <header>\\n                <field name=\\"locked\\" invisible=\\"1\\"/>\\n                <field name=\\"authorized_transaction_ids\\" invisible=\\"1\\"/>\\n                <button name=\\"payment_action_capture\\" type=\\"object\\" data-hotkey=\\"shift+g\\" string=\\"Capturar transacción\\" class=\\"oe_highlight\\" invisible=\\"not authorized_transaction_ids\\"/>\\n                <button name=\\"payment_action_void\\" type=\\"object\\" string=\\"Transacción nula\\" data-hotkey=\\"shift+v\\" confirm=\\"¿Está seguro de que desea anular la transacción autorizada? Esta acción no se puede deshacer.\\" invisible=\\"not authorized_transaction_ids\\"/>\\n                <button id=\\"create_invoice\\" name=\\"362\\" string=\\"Crear factura\\" type=\\"action\\" class=\\"btn-primary\\" data-hotkey=\\"q\\" invisible=\\"invoice_status != 'to invoice'\\"/>\\n                <button id=\\"create_invoice_percentage\\" name=\\"362\\" string=\\"Crear factura\\" type=\\"action\\" context=\\"{'default_advance_payment_method': 'percentage'}\\" data-hotkey=\\"q\\" invisible=\\"invoice_status != 'no' or state != 'sale'\\"/>\\n                <button name=\\"action_quotation_send\\" id=\\"send_by_email_primary\\" string=\\"Enviar por correo electrónico\\" type=\\"object\\" data-hotkey=\\"g\\" invisible=\\"state != 'draft'\\" class=\\"btn-primary\\" context=\\"{'validate_analytic': True}\\"/>\\n                <button name=\\"action_quotation_send\\" id=\\"send_proforma_primary\\" type=\\"object\\" string=\\"Enviar factura PROFORMA\\" class=\\"btn-primary\\" groups=\\"sale.group_proforma_sales\\" invisible=\\"state != 'draft' or invoice_count &gt;= 1\\" context=\\"{'proforma': True, 'validate_analytic': True}\\"/>\\n                <button name=\\"action_confirm\\" id=\\"action_confirm\\" data-hotkey=\\"q\\" string=\\"Confirmar\\" class=\\"btn-primary\\" type=\\"object\\" context=\\"{'validate_analytic': True}\\" invisible=\\"state != 'sent'\\"/>\\n                <button name=\\"action_confirm\\" data-hotkey=\\"q\\" string=\\"Confirmar\\" type=\\"object\\" context=\\"{'validate_analytic': True}\\" invisible=\\"state != 'draft'\\"/>\\n                <button name=\\"action_quotation_send\\" id=\\"send_proforma\\" type=\\"object\\" string=\\"Enviar factura PROFORMA\\" groups=\\"sale.group_proforma_sales\\" invisible=\\"state == 'draft' or invoice_count &gt;= 1\\" context=\\"{'proforma': True, 'validate_analytic': True}\\"/>\\n                <button name=\\"action_quotation_send\\" id=\\"send_by_email\\" string=\\"Enviar por correo electrónico\\" type=\\"object\\" invisible=\\"state not in ('sent', 'sale')\\" data-hotkey=\\"g\\" context=\\"{'validate_analytic': True}\\"/>\\n\\n                <!-- allow to unlock locked orders even if setting is not enabled (e.g. orders synchronized from connectors) -->\\n                <button name=\\"action_unlock\\" type=\\"object\\" string=\\"Desbloquear\\" invisible=\\"not locked\\" groups=\\"sales_team.group_sale_manager\\"/>\\n                <button name=\\"action_preview_sale_order\\" string=\\"Vista previa\\" type=\\"object\\" class=\\"btn-secondary\\"/>\\n                <button name=\\"action_cancel\\" type=\\"object\\" string=\\"Cancelar\\" invisible=\\"state not in ['draft', 'sent', 'sale'] or not id or locked\\" data-hotkey=\\"x\\"/>\\n                <button name=\\"action_draft\\" invisible=\\"state != 'cancel'\\" type=\\"object\\" string=\\"Establecer como cotización\\" data-hotkey=\\"w\\"/>\\n                <t groups=\\"sale.group_auto_done_setting\\">\\n                    <button name=\\"action_lock\\" type=\\"object\\" string=\\"Bloquear\\" help=\\"No podrás modificar la venta si está bloqueada, pero todavía la podrás facturar o entregar.\\" invisible=\\"locked or state != 'sale'\\" groups=\\"sales_team.group_sale_manager\\"/>\\n                </t>\\n                <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,sent,sale\\"/>\\n            </header>\\n            <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"partner_credit_warning == ''\\">\\n                <field name=\\"partner_credit_warning\\"/>\\n            </div>\\n            <sheet>\\n                <div class=\\"oe_button_box\\" name=\\"button_box\\">\\n                    <button name=\\"action_view_invoice\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-pencil-square-o\\" invisible=\\"invoice_count == 0\\">\\n                        <field name=\\"invoice_count\\" widget=\\"statinfo\\" string=\\"Facturas\\"/>\\n                    </button>\\n                </div>\\n                <div class=\\"badge rounded-pill text-bg-secondary float-end fs-6 border-0\\" invisible=\\"not locked\\">\\n                    <i class=\\"fa fa-lock\\"/>\\n                    Bloqueada\\n                </div>\\n                <div class=\\"oe_title\\">\\n                    <h1>\\n                        <field name=\\"name\\" readonly=\\"1\\"/>\\n                    </h1>\\n                </div>\\n                <group name=\\"sale_header\\">\\n                    <group name=\\"partner_details\\">\\n                        <field name=\\"partner_id\\" widget=\\"res_partner_many2one\\" context=\\"{'res_partner_search_mode': 'customer', 'show_address': 1, 'show_vat': True}\\" placeholder=\\"Comience a escribir para encontrar a un cliente...\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <field name=\\"partner_invoice_id\\" groups=\\"account.group_delivery_invoice_address\\" context=\\"{'default_type':'invoice', 'show_address': False, 'show_vat': False}\\" readonly=\\"state == 'cancel' or locked\\"/>\\n                        <field name=\\"partner_shipping_id\\" groups=\\"account.group_delivery_invoice_address\\" context=\\"{'default_type':'delivery', 'show_address': False, 'show_vat': False}\\" readonly=\\"state == 'cancel' or locked\\"/>\\n                    </group>\\n                    <group name=\\"order_details\\">\\n                        <field name=\\"validity_date\\" invisible=\\"state == 'sale'\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <div class=\\"o_td_label\\" groups=\\"base.group_no_one\\" invisible=\\"state in ['sale', 'cancel']\\">\\n                            <label for=\\"date_order\\" string=\\"Fecha de cotización\\"/>\\n                        </div>\\n                        <field name=\\"date_order\\" nolabel=\\"1\\" groups=\\"base.group_no_one\\" invisible=\\"state in ['sale', 'cancel']\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                        <div class=\\"o_td_label\\" invisible=\\"state in ['draft', 'sent']\\">\\n                            <label for=\\"date_order\\" string=\\"Fecha de la orden\\"/>\\n                        </div>\\n                        <field name=\\"date_order\\" invisible=\\"state in ['draft', 'sent']\\" readonly=\\"state in ['cancel', 'sale']\\" nolabel=\\"1\\"/>\\n                        <field name=\\"has_active_pricelist\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_update_pricelist\\" invisible=\\"1\\"/>\\n                        <label for=\\"pricelist_id\\" groups=\\"product.group_product_pricelist\\" invisible=\\"not has_active_pricelist\\"/>\\n                        <div groups=\\"product.group_product_pricelist\\" class=\\"o_row\\" invisible=\\"not has_active_pricelist\\">\\n                            <field name=\\"pricelist_id\\" options=\\"{'no_open':True,'no_create': True}\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                            <button name=\\"action_update_prices\\" type=\\"object\\" string=\\"Actualizar precios\\" help=\\"Volver a calcular todos los precios según esta lista de precios\\" class=\\"btn-link mb-1 px-0\\" icon=\\"fa-refresh\\" confirm=\\"Esto usará como referencia la nueva lista de precios para actualizar el precio unitario de todos los productos.\\" invisible=\\"not show_update_pricelist or state in ['sale', 'cancel']\\"/>\\n                        </div>\\n                        <field name=\\"country_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"currency_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"pricelist_id\\" invisible=\\"1\\" readonly=\\"state in ['cancel', 'sale']\\" groups=\\"!product.group_product_pricelist\\"/>\\n                        <field name=\\"tax_country_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                        <field name=\\"payment_term_id\\" options=\\"{'no_open': True, 'no_create': True}\\"/>\\n                    </group>\\n                </group>\\n                <notebook>\\n                    <page string=\\"Líneas de la orden\\" name=\\"order_lines\\">\\n                        <field name=\\"order_line\\" widget=\\"section_and_note_one2many\\" mode=\\"tree,kanban\\" readonly=\\"state == 'cancel' or locked\\">\\n                            <form>\\n                                <field name=\\"display_type\\" invisible=\\"1\\"/>\\n                                <!--\\n                                    We need the sequence field to be here for new lines to be added at the correct position.\\n                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.\\n                                -->\\n                                <field name=\\"sequence\\" invisible=\\"1\\"/>\\n                                <field name=\\"product_uom_category_id\\" invisible=\\"1\\"/>\\n                                <group>\\n                                    <group invisible=\\"display_type\\">\\n                                        <field name=\\"product_updatable\\" invisible=\\"1\\"/>\\n                                        <field name=\\"product_id\\" domain=\\"[('sale_ok', '=', True)]\\" context=\\"{'partner_id':parent.partner_id, 'quantity':product_uom_qty, 'pricelist':parent.pricelist_id, 'uom':product_uom, 'company_id': parent.company_id}\\" readonly=\\"not product_updatable\\" required=\\"not display_type\\" force_save=\\"1\\" widget=\\"many2one_barcode\\"/>\\n                                        <field name=\\"product_type\\" invisible=\\"1\\"/>\\n                                        <field name=\\"invoice_status\\" invisible=\\"1\\"/>\\n                                        <field name=\\"qty_to_invoice\\" invisible=\\"1\\"/>\\n                                        <field name=\\"qty_delivered_method\\" invisible=\\"1\\"/>\\n                                        <field name=\\"price_total\\" invisible=\\"1\\"/>\\n                                        <field name=\\"price_tax\\" invisible=\\"1\\"/>\\n                                        <field name=\\"price_subtotal\\" invisible=\\"1\\"/>\\n                                        <field name=\\"product_uom_readonly\\" invisible=\\"1\\"/>\\n                                        <label for=\\"product_uom_qty\\"/>\\n                                        <div class=\\"o_row\\" name=\\"ordered_qty\\">\\n                                            <field context=\\"{'partner_id':parent.partner_id, 'quantity':product_uom_qty, 'pricelist':parent.pricelist_id, 'uom':product_uom, 'uom_qty_change':True, 'company_id': parent.company_id}\\" name=\\"product_uom_qty\\"/>\\n                                            <field name=\\"product_uom\\" invisible=\\"1\\" groups=\\"!uom.group_uom\\"/>\\n                                            <field name=\\"product_uom\\" force_save=\\"1\\" groups=\\"uom.group_uom\\" class=\\"oe_no_button\\" readonly=\\"product_uom_readonly\\" required=\\"not display_type\\"/>\\n                                        </div>\\n                                        <label for=\\"qty_delivered\\" string=\\"Entregado\\" invisible=\\"parent.state != 'sale'\\"/>\\n                                        <div name=\\"delivered_qty\\" invisible=\\"parent.state != 'sale'\\">\\n                                            <field name=\\"qty_delivered\\" readonly=\\"qty_delivered_method != 'manual'\\"/>\\n                                        </div>\\n                                        <label for=\\"qty_invoiced\\" string=\\"Facturado\\" invisible=\\"parent.state != 'sale'\\"/>\\n                                        <div name=\\"invoiced_qty\\" invisible=\\"parent.state != 'sale'\\">\\n                                            <field name=\\"qty_invoiced\\"/>\\n                                        </div>\\n                                        <field name=\\"product_packaging_qty\\" invisible=\\"not product_id or not product_packaging_id\\" groups=\\"product.group_stock_packaging\\"/>\\n                                        <field name=\\"product_packaging_id\\" invisible=\\"not product_id\\" context=\\"{'default_product_id': product_id, 'tree_view_ref':'product.product_packaging_tree_view', 'form_view_ref':'product.product_packaging_form_view'}\\" groups=\\"product.group_stock_packaging\\"/>\\n                                        <field name=\\"price_unit\\"/>\\n                                        <field name=\\"tax_id\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\" context=\\"{'search_view_ref': 'account.account_tax_view_search'}\\" domain=\\"[('type_tax_use', '=', 'sale'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]\\" readonly=\\"qty_invoiced &gt; 0\\"/>\\n                                        <t groups=\\"product.group_discount_per_so_line\\">\\n                                            <label for=\\"discount\\"/>\\n                                            <div name=\\"discount\\">\\n                                                <field name=\\"discount\\" class=\\"oe_inline\\"/> %\\n                                            </div>\\n                                        </t>\\n                                        <!--\\n                                            We need the sequence field to be here\\n                                            because we want to be able to overwrite the default sequence value in the JS\\n                                            in order for new lines to be added at the correct position.\\n                                            NOTE: at some point we want to fix this in the framework so that an invisible field is not required.\\n                                        -->\\n                                        <field name=\\"sequence\\" invisible=\\"1\\"/>\\n                                    </group>\\n                                    <group invisible=\\"display_type\\">\\n                                        <label for=\\"customer_lead\\"/>\\n                                        <div name=\\"lead\\">\\n                                            <field name=\\"customer_lead\\" class=\\"oe_inline\\"/> días\\n                                        </div>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" options=\\"{'product_field': 'product_id', 'business_domain': 'sale_order'}\\"/>\\n                                    </group>\\n                                </group>\\n                                <label for=\\"name\\" string=\\"Descripción\\" invisible=\\"display_type\\"/>\\n                                <label for=\\"name\\" string=\\"Nombre de la sección (por ejemplo, productos, servicios)\\" invisible=\\"display_type != 'line_section'\\"/>\\n                                <label for=\\"name\\" string=\\"Nota\\" invisible=\\"display_type != 'line_note'\\"/>\\n                                <field name=\\"name\\"/>\\n                                <div name=\\"invoice_lines\\" groups=\\"base.group_no_one\\" invisible=\\"display_type\\">\\n                                    <label for=\\"invoice_lines\\"/>\\n                                    <field name=\\"invoice_lines\\"/>\\n                                </div>\\n                                <field name=\\"state\\" invisible=\\"1\\"/>\\n                                <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                            </form>\\n                            <tree string=\\"Líneas de la orden de venta\\" editable=\\"bottom\\" limit=\\"200\\">\\n                                <control>\\n                                    <create name=\\"add_product_control\\" string=\\"Agregar un producto\\"/>\\n                                    <create name=\\"add_section_control\\" string=\\"Agregar una sección\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                    <create name=\\"add_note_control\\" string=\\"Agregar una nota\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                    <button name=\\"action_add_from_catalog\\" string=\\"Catálogo\\" type=\\"object\\" class=\\"px-4 btn-link\\" context=\\"{'order_id': parent.id}\\"/>\\n                                </control>\\n\\n                                <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                <!-- We do not display the type because we don't want the user to be bothered with that information if he has no section or note. -->\\n                                <field name=\\"display_type\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_uom_category_id\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_type\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_updatable\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"is_downpayment\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_id\\" readonly=\\"not product_updatable\\" required=\\"not display_type\\" force_save=\\"1\\" context=\\"{                                         'partner_id': parent.partner_id,                                         'quantity': product_uom_qty,                                         'pricelist': parent.pricelist_id,                                         'uom':product_uom,                                         'company_id': parent.company_id,                                         'default_lst_price': price_unit,                                         'default_description_sale': name                                     }\\" options=\\"{                                         'no_open': True,                                     }\\" domain=\\"[('sale_ok', '=', True)]\\" widget=\\"sol_product_many2one\\"/>\\n                                <field name=\\"product_template_id\\" string=\\"Producto\\" column_invisible=\\"True\\" readonly=\\"not product_updatable\\" required=\\"not display_type\\" context=\\"{                                         'partner_id': parent.partner_id,                                         'quantity': product_uom_qty,                                         'pricelist': parent.pricelist_id,                                         'uom':product_uom,                                         'company_id': parent.company_id,                                         'default_list_price': price_unit,                                         'default_description_sale': name                                     }\\" options=\\"{                                         'no_open': True,                                     }\\" domain=\\"[('sale_ok', '=', True)]\\" widget=\\"sol_product_many2one\\" placeholder=\\"Comience a escribir para encontrar un producto...\\"/>\\n                                <field name=\\"name\\" widget=\\"section_and_note_text\\" optional=\\"show\\"/>\\n                                <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" optional=\\"hide\\" groups=\\"analytic.group_analytic_accounting\\" options=\\"{'product_field': 'product_id', 'business_domain': 'sale_order', 'amount_field': 'price_subtotal'}\\"/>\\n                                <field name=\\"product_uom_qty\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" context=\\"{                                         'partner_id': parent.partner_id,                                         'quantity': product_uom_qty,                                         'pricelist': parent.pricelist_id,                                         'uom': product_uom,                                         'company_id': parent.company_id                                     }\\" readonly=\\"is_downpayment\\"/>\\n                                <field name=\\"qty_delivered\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" string=\\"Entregado\\" column_invisible=\\"parent.state != 'sale'\\" readonly=\\"qty_delivered_method != 'manual' or is_downpayment\\" optional=\\"show\\"/>\\n                                <field name=\\"qty_delivered_method\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"qty_invoiced\\" decoration-info=\\"(not display_type and invoice_status == 'to invoice')\\" decoration-bf=\\"(not display_type and invoice_status == 'to invoice')\\" string=\\"Facturado\\" column_invisible=\\"parent.state != 'sale'\\" optional=\\"show\\"/>\\n                                <field name=\\"qty_to_invoice\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_uom_readonly\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"product_uom\\" column_invisible=\\"True\\" groups=\\"!uom.group_uom\\"/>\\n                                <field name=\\"product_uom\\" force_save=\\"1\\" string=\\"UdM\\" readonly=\\"product_uom_readonly\\" required=\\"not display_type\\" context=\\"{'company_id': parent.company_id}\\" groups=\\"uom.group_uom\\" options=\\"{&quot;no_open&quot;: True}\\" optional=\\"show\\"/>\\n                                <field name=\\"customer_lead\\" optional=\\"hide\\" readonly=\\"parent.state not in ['draft', 'sent', 'sale'] or is_downpayment\\"/>\\n                                <field name=\\"product_packaging_qty\\" invisible=\\"not product_id or not product_packaging_id\\" groups=\\"product.group_stock_packaging\\" optional=\\"show\\"/>\\n                                <field name=\\"product_packaging_id\\" invisible=\\"not product_id\\" context=\\"{'default_product_id': product_id, 'tree_view_ref':'product.product_packaging_tree_view', 'form_view_ref':'product.product_packaging_form_view'}\\" groups=\\"product.group_stock_packaging\\" optional=\\"show\\"/>\\n                                <field name=\\"price_unit\\" readonly=\\"qty_invoiced &gt; 0\\"/>\\n                                <field name=\\"tax_id\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\" domain=\\"[('type_tax_use', '=', 'sale'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]\\" context=\\"{'active_test': True}\\" readonly=\\"qty_invoiced &gt; 0 or is_downpayment\\" optional=\\"show\\"/>\\n                                <field name=\\"discount\\" string=\\"% de desc.\\" groups=\\"product.group_discount_per_so_line\\" optional=\\"show\\"/>\\n                                <field name=\\"is_downpayment\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"price_subtotal\\" string=\\"Impuestos excl.\\" invisible=\\"is_downpayment\\"/>\\n                                <field name=\\"price_total\\" string=\\"Impuestos incl.\\" column_invisible=\\"parent.tax_calculation_rounding_method == 'round_globally'\\" invisible=\\"is_downpayment\\" optional=\\"hide\\"/>\\n                                <!-- Others fields -->\\n                                <field name=\\"tax_calculation_rounding_method\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"state\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"invoice_status\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"currency_id\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"price_tax\\" column_invisible=\\"True\\"/>\\n                                <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                            </tree>\\n                            <kanban class=\\"o_kanban_mobile\\">\\n                                <field name=\\"name\\"/>\\n                                <field name=\\"product_id\\"/>\\n                                <field name=\\"product_uom_qty\\"/>\\n                                <field name=\\"product_uom\\"/>\\n                                <field name=\\"price_subtotal\\"/>\\n                                <field name=\\"price_total\\"/>\\n                                <field name=\\"price_tax\\"/>\\n                                <field name=\\"price_total\\"/>\\n                                <field name=\\"price_unit\\"/>\\n                                <field name=\\"display_type\\"/>\\n                                <field name=\\"tax_id\\"/>\\n                                <field name=\\"company_id\\"/>\\n                                <field name=\\"tax_calculation_rounding_method\\"/>\\n                                <control>\\n                                    <create name=\\"add_product_control\\" string=\\"Agregar un producto\\"/>\\n                                    <create name=\\"add_section_control\\" string=\\"Agregar una sección\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                    <create name=\\"add_note_control\\" string=\\"Agregar una nota\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                    <button name=\\"action_add_from_catalog\\" context=\\"{'order_id': parent.id}\\" string=\\"Catálogo\\" type=\\"object\\" class=\\"btn-secondary\\"/>\\n                                </control>\\n                                <templates>\\n                                    <t t-name=\\"kanban-box\\">\\n                                        <div t-attf-class=\\"oe_kanban_card oe_kanban_global_click ps-0 pe-0 {{ record.display_type.raw_value ? 'o_is_' + record.display_type.raw_value : '' }}\\">\\n                                            <t t-if=\\"!record.display_type.raw_value\\">\\n                                                <div class=\\"row g-0\\">\\n                                                    <div class=\\"col-2 pe-3\\">\\n                                                        <img t-att-src=\\"kanban_image('product.product', 'image_128', record.product_id.raw_value)\\" t-att-title=\\"record.product_id.value\\" t-att-alt=\\"record.product_id.value\\" style=\\"max-width: 100%;\\"/>\\n                                                    </div>\\n                                                    <div class=\\"col-10\\">\\n                                                        <div class=\\"row\\">\\n                                                            <div class=\\"col\\">\\n                                                                <strong t-out=\\"record.product_id.value\\"/>\\n                                                            </div>\\n                                                            <div class=\\"col-auto\\">\\n                                                                <strong>Impuestos excl.: </strong>\\n                                                                <t t-set=\\"line_price\\" t-value=\\"record.price_subtotal.value\\"/>\\n                                                                <strong class=\\"float-end text-end\\" t-out=\\"line_price\\"/>\\n                                                            </div>\\n                                                        </div>\\n                                                        <div class=\\"row\\">\\n                                                            <div class=\\"col-12 text-muted\\">\\n                                                                Cantidad:\\n                                                                <t t-out=\\"record.product_uom_qty.value\\"/> <t t-out=\\"record.product_uom.value\\"/>\\n                                                            </div>\\n                                                        </div>\\n                                                        <div class=\\"row\\">\\n                                                            <div class=\\"col text-muted\\">\\n                                                                Precio unitario:\\n                                                                <t t-out=\\"record.price_unit.value\\"/>\\n                                                            </div>\\n                                                            <div class=\\"col-auto\\" t-if=\\"record.tax_calculation_rounding_method.raw_value === 'round_per_line'\\">\\n                                                                <strong>Impuestos incl.: </strong>\\n                                                                <t t-set=\\"line_price\\" t-value=\\"record.price_total.value\\"/>\\n                                                                <strong class=\\"float-end text-end\\" t-out=\\"line_price\\"/>\\n                                                            </div>\\n                                                        </div>\\n                                                        <t t-if=\\"record.discount?.raw_value\\">\\n                                                            <div class=\\"row\\">\\n                                                                <div class=\\"col-12 text-muted\\">\\n                                                                    Descuento:\\n                                                                    <t t-out=\\"record.discount.value\\"/>%\\n                                                                </div>\\n                                                            </div>\\n                                                        </t>\\n                                                    </div>\\n                                                </div>\\n                                            </t>\\n                                            <t t-if=\\"record.display_type.raw_value === 'line_section' || record.display_type.raw_value === 'line_note'\\">\\n                                                <div class=\\"row\\">\\n                                                    <div class=\\"col-12\\">\\n                                                        <t t-out=\\"record.name.value\\"/>\\n                                                    </div>\\n                                                </div>\\n                                            </t>\\n                                        </div>\\n                                    </t>\\n                                </templates>\\n                            </kanban>\\n                        </field>\\n                        <div class=\\"float-end d-flex gap-1 mb-2 ms-1\\" name=\\"so_button_below_order_lines\\">\\n                            <button string=\\"Descuento \\" name=\\"action_open_discount_wizard\\" type=\\"object\\" class=\\"btn btn-secondary\\" groups=\\"product.group_discount_per_so_line\\"/>\\n                        </div>\\n                        <group name=\\"note_group\\" col=\\"6\\" class=\\"mt-2 mt-md-0\\">\\n                            <group colspan=\\"4\\">\\n                                <field colspan=\\"2\\" name=\\"note\\" nolabel=\\"1\\" placeholder=\\"Términos y condiciones...\\"/>\\n                            </group>\\n                            <group class=\\"oe_subtotal_footer\\" colspan=\\"2\\" name=\\"sale_total\\">\\n                                <field name=\\"tax_totals\\" widget=\\"account-tax-totals-field\\" nolabel=\\"1\\" colspan=\\"2\\" readonly=\\"1\\"/>\\n                            </group>\\n                            <div class=\\"clearfix\\"/>\\n                        </group>\\n                    </page>\\n                    <page string=\\"Otra información\\" name=\\"other_information\\">\\n                        <group>\\n                            <group name=\\"sales_person\\" string=\\"Ventas\\">\\n                                <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\"/>\\n                                <field name=\\"team_id\\" context=\\"{'kanban_view_ref': 'sales_team.crm_team_view_kanban'}\\" options=\\"{'no_create': True}\\"/>\\n                                <field name=\\"company_id\\" options=\\"{'no_create': True}\\" groups=\\"base.group_multi_company\\"/>\\n                                <field name=\\"require_signature\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                                <label for=\\"require_payment\\"/>\\n                                <div id=\\"require_payment\\">\\n                                    <field name=\\"require_payment\\" readonly=\\"state in ['cancel', 'sale']\\"/>\\n                                    <span class=\\"mx-3\\" invisible=\\"not require_payment\\">de</span>\\n                                    <field name=\\"prepayment_percent\\" readonly=\\"state in ['cancel', 'sale']\\" invisible=\\"not require_payment\\" widget=\\"percentage\\" style=\\"width: 3rem\\"/>\\n                                </div>\\n                                <field name=\\"reference\\" readonly=\\"1\\" invisible=\\"not reference\\"/>\\n                                <field name=\\"client_order_ref\\"/>\\n                                <field name=\\"tag_ids\\" widget=\\"many2many_tags\\" options=\\"{'color_field': 'color', 'no_create_edit': True}\\"/>\\n                            </group>\\n                            <group name=\\"sale_info\\" string=\\"Facturación\\">\\n                                <field name=\\"show_update_fpos\\" invisible=\\"1\\"/>\\n                                <label for=\\"fiscal_position_id\\"/>\\n                                <div class=\\"o_row\\">\\n                                    <field name=\\"fiscal_position_id\\" options=\\"{'no_create': True}\\"/>\\n                                    <button name=\\"action_update_taxes\\" type=\\"object\\" string=\\"Actualizar impuestos\\" help=\\"Volver a calcular todos los impuestos según esta posición fiscal\\" class=\\"btn-link mb-1 px-0\\" icon=\\"fa-refresh\\" confirm=\\"Esto actualizará todos los impuestos según la posición fiscal actualmente establecida.\\" invisible=\\"not show_update_fpos or state in ['sale', 'cancel']\\"/>\\n                                </div>\\n                                <field name=\\"partner_invoice_id\\" groups=\\"!account.group_delivery_invoice_address\\" invisible=\\"1\\"/>\\n                                <field name=\\"analytic_account_id\\" context=\\"{'default_partner_id':partner_invoice_id, 'default_name':name}\\" readonly=\\"invoice_count != 0 and state == 'sale'\\" groups=\\"analytic.group_analytic_accounting\\" force_save=\\"1\\"/>\\n                                <field name=\\"journal_id\\" groups=\\"base.group_no_one\\" readonly=\\"invoice_count != 0 and state == 'sale'\\"/>\\n                                <field name=\\"invoice_status\\" invisible=\\"state != 'sale'\\" groups=\\"base.group_no_one\\"/>\\n                                <!-- test_event_configurator -->\\n                                <field name=\\"invoice_status\\" invisible=\\"1\\" groups=\\"!base.group_no_one\\"/>\\n                            </group>\\n                            <group name=\\"sale_shipping\\" string=\\"Envío\\">\\n                                <label for=\\"commitment_date\\" string=\\"Fecha de entrega\\"/>\\n                                <div name=\\"commitment_date_div\\" class=\\"o_row\\">\\n                                    <field name=\\"commitment_date\\" readonly=\\"state == 'cancel' or locked\\"/>\\n                                    <span name=\\"expected_date_span\\" class=\\"text-muted\\">Esperado: <field name=\\"expected_date\\" class=\\"oe_inline\\" widget=\\"date\\"/></span>\\n                                </div>\\n                            </group>\\n                            <group string=\\"Seguimiento\\" name=\\"sale_reporting\\">\\n                                <field name=\\"origin\\"/>\\n                                <field name=\\"campaign_id\\" options=\\"{'create_name_field': 'title'}\\"/>\\n                                <field name=\\"medium_id\\"/>\\n                                <field name=\\"source_id\\"/>\\n                            </group>\\n                        </group>\\n                    </page>\\n                    <page groups=\\"base.group_no_one\\" string=\\"Firma del cliente\\" name=\\"customer_signature\\" invisible=\\"1\\">\\n                        <group>\\n                            <field name=\\"signed_by\\" readonly=\\"signature\\"/>\\n                            <field name=\\"signed_on\\" readonly=\\"signature\\"/>\\n                            <field name=\\"signature\\" widget=\\"image\\"/>\\n                        </group>\\n                    </page>\\n                </notebook>\\n            </sheet>\\n            <div class=\\"oe_chatter\\">\\n                <field name=\\"message_follower_ids\\"/>\\n                <field name=\\"activity_ids\\"/>\\n                <field name=\\"message_ids\\"/>\\n            </div>\\n            </form>"}	<?xml version="1.0"?>\n<form string="Sales Order" class="o_sale_order">\n            <header>\n                <field name="locked" invisible="1"/>\n                <field name="authorized_transaction_ids" invisible="1"/>\n                <button name="payment_action_capture" type="object" data-hotkey="shift+g" string="Capture Transaction" class="oe_highlight" invisible="not authorized_transaction_ids"/>\n                <button name="payment_action_void" type="object" string="Void Transaction" data-hotkey="shift+v" confirm="Are you sure you want to void the authorized transaction? This action can't be undone." invisible="not authorized_transaction_ids"/>\n                <button id="create_invoice" name="362" string="Create Invoice" type="action" class="btn-primary" data-hotkey="q" invisible="invoice_status != 'to invoice'"/>\n                <button id="create_invoice_percentage" name="362" string="Create Invoice" type="action" context="{'default_advance_payment_method': 'percentage'}" data-hotkey="q" invisible="invoice_status != 'no' or state != 'sale'"/>\n                <button name="action_quotation_send" id="send_by_email_primary" string="Send by Email" type="object" data-hotkey="g" invisible="state != 'draft'" class="btn-primary" context="{'validate_analytic': True}"/>\n                <button name="action_quotation_send" id="send_proforma_primary" type="object" string="Send PRO-FORMA Invoice" class="btn-primary" groups="sale.group_proforma_sales" invisible="state != 'draft' or invoice_count &gt;= 1" context="{'proforma': True, 'validate_analytic': True}"/>\n                <button name="action_confirm" id="action_confirm" data-hotkey="q" string="Confirm" class="btn-primary" type="object" context="{'validate_analytic': True}" invisible="state != 'sent'"/>\n                <button name="action_confirm" data-hotkey="q" string="Confirm" type="object" context="{'validate_analytic': True}" invisible="state != 'draft'"/>\n                <button name="action_quotation_send" id="send_proforma" type="object" string="Send PRO-FORMA Invoice" groups="sale.group_proforma_sales" invisible="state == 'draft' or invoice_count &gt;= 1" context="{'proforma': True, 'validate_analytic': True}"/>\n                <button name="action_quotation_send" id="send_by_email" string="Send by Email" type="object" invisible="state not in ('sent', 'sale')" data-hotkey="g" context="{'validate_analytic': True}"/>\n\n                <!-- allow to unlock locked orders even if setting is not enabled (e.g. orders synchronized from connectors) -->\n                <button name="action_unlock" type="object" string="Unlock" invisible="not locked" groups="sales_team.group_sale_manager"/>\n                <button name="action_preview_sale_order" string="Preview" type="object" class="btn-secondary"/>\n                <button name="action_cancel" type="object" string="Cancel" invisible="state not in ['draft', 'sent', 'sale'] or not id or locked" data-hotkey="x"/>\n                <button name="action_draft" invisible="state != 'cancel'" type="object" string="Set to Quotation" data-hotkey="w"/>\n                <t groups="sale.group_auto_done_setting">\n                    <button name="action_lock" type="object" string="Lock" help="If the sale is locked, you can not modify it anymore. However, you will still be able to invoice or deliver." invisible="locked or state != 'sale'" groups="sales_team.group_sale_manager"/>\n                </t>\n                <field name="state" widget="statusbar" statusbar_visible="draft,sent,sale"/>\n            </header>\n            <div class="alert alert-warning" role="alert" invisible="partner_credit_warning == ''">\n                <field name="partner_credit_warning"/>\n            </div>\n            <sheet>\n                <div class="oe_button_box" name="button_box">\n                    <button name="action_view_invoice" type="object" class="oe_stat_button" icon="fa-pencil-square-o" invisible="invoice_count == 0">\n                        <field name="invoice_count" widget="statinfo" string="Invoices"/>\n                    </button>\n                </div>\n                <div class="badge rounded-pill text-bg-secondary float-end fs-6 border-0" invisible="not locked">\n                    <i class="fa fa-lock"/>\n                    Locked\n                </div>\n                <div class="oe_title">\n                    <h1>\n                        <field name="name" readonly="1"/>\n                    </h1>\n                </div>\n                <group name="sale_header">\n                    <group name="partner_details">\n                        <field name="partner_id" widget="res_partner_many2one" context="{'res_partner_search_mode': 'customer', 'show_address': 1, 'show_vat': True}" placeholder="Type to find a customer..." readonly="state in ['cancel', 'sale']"/>\n                        <field name="partner_invoice_id" groups="account.group_delivery_invoice_address" context="{'default_type':'invoice', 'show_address': False, 'show_vat': False}" readonly="state == 'cancel' or locked"/>\n                        <field name="partner_shipping_id" groups="account.group_delivery_invoice_address" context="{'default_type':'delivery', 'show_address': False, 'show_vat': False}" readonly="state == 'cancel' or locked"/>\n                    </group>\n                    <group name="order_details">\n                        <field name="validity_date" invisible="state == 'sale'" readonly="state in ['cancel', 'sale']"/>\n                        <div class="o_td_label" groups="base.group_no_one" invisible="state in ['sale', 'cancel']">\n                            <label for="date_order" string="Quotation Date"/>\n                        </div>\n                        <field name="date_order" nolabel="1" groups="base.group_no_one" invisible="state in ['sale', 'cancel']" readonly="state in ['cancel', 'sale']"/>\n                        <div class="o_td_label" invisible="state in ['draft', 'sent']">\n                            <label for="date_order" string="Order Date"/>\n                        </div>\n                        <field name="date_order" invisible="state in ['draft', 'sent']" readonly="state in ['cancel', 'sale']" nolabel="1"/>\n                        <field name="has_active_pricelist" invisible="1"/>\n                        <field name="show_update_pricelist" invisible="1"/>\n                        <label for="pricelist_id" groups="product.group_product_pricelist" invisible="not has_active_pricelist"/>\n                        <div groups="product.group_product_pricelist" class="o_row" invisible="not has_active_pricelist">\n                            <field name="pricelist_id" options="{'no_open':True,'no_create': True}" readonly="state in ['cancel', 'sale']"/>\n                            <button name="action_update_prices" type="object" string=" Update Prices" help="Recompute all prices based on this pricelist" class="btn-link mb-1 px-0" icon="fa-refresh" confirm="This will update the unit price of all products based on the new pricelist." invisible="not show_update_pricelist or state in ['sale', 'cancel']"/>\n                        </div>\n                        <field name="country_code" invisible="1"/>\n                        <field name="company_id" invisible="1"/>\n                        <field name="currency_id" invisible="1"/>\n                        <field name="pricelist_id" invisible="1" readonly="state in ['cancel', 'sale']" groups="!product.group_product_pricelist"/>\n                        <field name="tax_country_id" invisible="1"/>\n                        <field name="tax_calculation_rounding_method" invisible="1"/>\n                        <field name="payment_term_id" options="{'no_open': True, 'no_create': True}"/>\n                    </group>\n                </group>\n                <notebook>\n                    <page string="Order Lines" name="order_lines">\n                        <field name="order_line" widget="section_and_note_one2many" mode="tree,kanban" readonly="state == 'cancel' or locked">\n                            <form>\n                                <field name="display_type" invisible="1"/>\n                                <!--\n                                    We need the sequence field to be here for new lines to be added at the correct position.\n                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.\n                                -->\n                                <field name="sequence" invisible="1"/>\n                                <field name="product_uom_category_id" invisible="1"/>\n                                <group>\n                                    <group invisible="display_type">\n                                        <field name="product_updatable" invisible="1"/>\n                                        <field name="product_id" domain="[('sale_ok', '=', True)]" context="{'partner_id':parent.partner_id, 'quantity':product_uom_qty, 'pricelist':parent.pricelist_id, 'uom':product_uom, 'company_id': parent.company_id}" readonly="not product_updatable" required="not display_type" force_save="1" widget="many2one_barcode"/>\n                                        <field name="product_type" invisible="1"/>\n                                        <field name="invoice_status" invisible="1"/>\n                                        <field name="qty_to_invoice" invisible="1"/>\n                                        <field name="qty_delivered_method" invisible="1"/>\n                                        <field name="price_total" invisible="1"/>\n                                        <field name="price_tax" invisible="1"/>\n                                        <field name="price_subtotal" invisible="1"/>\n                                        <field name="product_uom_readonly" invisible="1"/>\n                                        <label for="product_uom_qty"/>\n                                        <div class="o_row" name="ordered_qty">\n                                            <field context="{'partner_id':parent.partner_id, 'quantity':product_uom_qty, 'pricelist':parent.pricelist_id, 'uom':product_uom, 'uom_qty_change':True, 'company_id': parent.company_id}" name="product_uom_qty"/>\n                                            <field name="product_uom" invisible="1" groups="!uom.group_uom"/>\n                                            <field name="product_uom" force_save="1" groups="uom.group_uom" class="oe_no_button" readonly="product_uom_readonly" required="not display_type"/>\n                                        </div>\n                                        <label for="qty_delivered" string="Delivered" invisible="parent.state != 'sale'"/>\n                                        <div name="delivered_qty" invisible="parent.state != 'sale'">\n                                            <field name="qty_delivered" readonly="qty_delivered_method != 'manual'"/>\n                                        </div>\n                                        <label for="qty_invoiced" string="Invoiced" invisible="parent.state != 'sale'"/>\n                                        <div name="invoiced_qty" invisible="parent.state != 'sale'">\n                                            <field name="qty_invoiced"/>\n                                        </div>\n                                        <field name="product_packaging_qty" invisible="not product_id or not product_packaging_id" groups="product.group_stock_packaging"/>\n                                        <field name="product_packaging_id" invisible="not product_id" context="{'default_product_id': product_id, 'tree_view_ref':'product.product_packaging_tree_view', 'form_view_ref':'product.product_packaging_form_view'}" groups="product.group_stock_packaging"/>\n                                        <field name="price_unit"/>\n                                        <field name="tax_id" widget="many2many_tags" options="{'no_create': True}" context="{'search_view_ref': 'account.account_tax_view_search'}" domain="[('type_tax_use', '=', 'sale'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]" readonly="qty_invoiced &gt; 0"/>\n                                        <t groups="product.group_discount_per_so_line">\n                                            <label for="discount"/>\n                                            <div name="discount">\n                                                <field name="discount" class="oe_inline"/> %\n                                            </div>\n                                        </t>\n                                        <!--\n                                            We need the sequence field to be here\n                                            because we want to be able to overwrite the default sequence value in the JS\n                                            in order for new lines to be added at the correct position.\n                                            NOTE: at some point we want to fix this in the framework so that an invisible field is not required.\n                                        -->\n                                        <field name="sequence" invisible="1"/>\n                                    </group>\n                                    <group invisible="display_type">\n                                        <label for="customer_lead"/>\n                                        <div name="lead">\n                                            <field name="customer_lead" class="oe_inline"/> days\n                                        </div>\n                                        <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" options="{'product_field': 'product_id', 'business_domain': 'sale_order'}"/>\n                                    </group>\n                                </group>\n                                <label for="name" string="Description" invisible="display_type"/>\n                                <label for="name" string="Section Name (eg. Products, Services)" invisible="display_type != 'line_section'"/>\n                                <label for="name" string="Note" invisible="display_type != 'line_note'"/>\n                                <field name="name"/>\n                                <div name="invoice_lines" groups="base.group_no_one" invisible="display_type">\n                                    <label for="invoice_lines"/>\n                                    <field name="invoice_lines"/>\n                                </div>\n                                <field name="state" invisible="1"/>\n                                <field name="company_id" invisible="1"/>\n                            </form>\n                            <tree string="Sales Order Lines" editable="bottom" limit="200">\n                                <control>\n                                    <create name="add_product_control" string="Add a product"/>\n                                    <create name="add_section_control" string="Add a section" context="{'default_display_type': 'line_section'}"/>\n                                    <create name="add_note_control" string="Add a note" context="{'default_display_type': 'line_note'}"/>\n                                    <button name="action_add_from_catalog" string="Catalog" type="object" class="px-4 btn-link" context="{'order_id': parent.id}"/>\n                                </control>\n\n                                <field name="sequence" widget="handle"/>\n                                <!-- We do not display the type because we don't want the user to be bothered with that information if he has no section or note. -->\n                                <field name="display_type" column_invisible="True"/>\n                                <field name="product_uom_category_id" column_invisible="True"/>\n                                <field name="product_type" column_invisible="True"/>\n                                <field name="product_updatable" column_invisible="True"/>\n                                <field name="is_downpayment" column_invisible="True"/>\n                                <field name="product_id" readonly="not product_updatable" required="not display_type" force_save="1" context="{                                         'partner_id': parent.partner_id,                                         'quantity': product_uom_qty,                                         'pricelist': parent.pricelist_id,                                         'uom':product_uom,                                         'company_id': parent.company_id,                                         'default_lst_price': price_unit,                                         'default_description_sale': name                                     }" options="{                                         'no_open': True,                                     }" domain="[('sale_ok', '=', True)]" widget="sol_product_many2one"/>\n                                <field name="product_template_id" string="Product" column_invisible="True" readonly="not product_updatable" required="not display_type" context="{                                         'partner_id': parent.partner_id,                                         'quantity': product_uom_qty,                                         'pricelist': parent.pricelist_id,                                         'uom':product_uom,                                         'company_id': parent.company_id,                                         'default_list_price': price_unit,                                         'default_description_sale': name                                     }" options="{                                         'no_open': True,                                     }" domain="[('sale_ok', '=', True)]" widget="sol_product_many2one" placeholder="Type to find a product..."/>\n                                <field name="name" widget="section_and_note_text" optional="show"/>\n                                <field name="analytic_distribution" widget="analytic_distribution" optional="hide" groups="analytic.group_analytic_accounting" options="{'product_field': 'product_id', 'business_domain': 'sale_order', 'amount_field': 'price_subtotal'}"/>\n                                <field name="product_uom_qty" decoration-info="(not display_type and invoice_status == 'to invoice')" decoration-bf="(not display_type and invoice_status == 'to invoice')" context="{                                         'partner_id': parent.partner_id,                                         'quantity': product_uom_qty,                                         'pricelist': parent.pricelist_id,                                         'uom': product_uom,                                         'company_id': parent.company_id                                     }" readonly="is_downpayment"/>\n                                <field name="qty_delivered" decoration-info="(not display_type and invoice_status == 'to invoice')" decoration-bf="(not display_type and invoice_status == 'to invoice')" string="Delivered" column_invisible="parent.state != 'sale'" readonly="qty_delivered_method != 'manual' or is_downpayment" optional="show"/>\n                                <field name="qty_delivered_method" column_invisible="True"/>\n                                <field name="qty_invoiced" decoration-info="(not display_type and invoice_status == 'to invoice')" decoration-bf="(not display_type and invoice_status == 'to invoice')" string="Invoiced" column_invisible="parent.state != 'sale'" optional="show"/>\n                                <field name="qty_to_invoice" column_invisible="True"/>\n                                <field name="product_uom_readonly" column_invisible="True"/>\n                                <field name="product_uom" column_invisible="True" groups="!uom.group_uom"/>\n                                <field name="product_uom" force_save="1" string="UoM" readonly="product_uom_readonly" required="not display_type" context="{'company_id': parent.company_id}" groups="uom.group_uom" options="{&quot;no_open&quot;: True}" optional="show"/>\n                                <field name="customer_lead" optional="hide" readonly="parent.state not in ['draft', 'sent', 'sale'] or is_downpayment"/>\n                                <field name="product_packaging_qty" invisible="not product_id or not product_packaging_id" groups="product.group_stock_packaging" optional="show"/>\n                                <field name="product_packaging_id" invisible="not product_id" context="{'default_product_id': product_id, 'tree_view_ref':'product.product_packaging_tree_view', 'form_view_ref':'product.product_packaging_form_view'}" groups="product.group_stock_packaging" optional="show"/>\n                                <field name="price_unit" readonly="qty_invoiced &gt; 0"/>\n                                <field name="tax_id" widget="many2many_tags" options="{'no_create': True}" domain="[('type_tax_use', '=', 'sale'), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]" context="{'active_test': True}" readonly="qty_invoiced &gt; 0 or is_downpayment" optional="show"/>\n                                <field name="discount" string="Disc.%" groups="product.group_discount_per_so_line" optional="show"/>\n                                <field name="is_downpayment" column_invisible="True"/>\n                                <field name="price_subtotal" string="Tax excl." invisible="is_downpayment"/>\n                                <field name="price_total" string="Tax incl." column_invisible="parent.tax_calculation_rounding_method == 'round_globally'" invisible="is_downpayment" optional="hide"/>\n                                <!-- Others fields -->\n                                <field name="tax_calculation_rounding_method" column_invisible="True"/>\n                                <field name="state" column_invisible="True"/>\n                                <field name="invoice_status" column_invisible="True"/>\n                                <field name="currency_id" column_invisible="True"/>\n                                <field name="price_tax" column_invisible="True"/>\n                                <field name="company_id" column_invisible="True"/>\n                            </tree>\n                            <kanban class="o_kanban_mobile">\n                                <field name="name"/>\n                                <field name="product_id"/>\n                                <field name="product_uom_qty"/>\n                                <field name="product_uom"/>\n                                <field name="price_subtotal"/>\n                                <field name="price_total"/>\n                                <field name="price_tax"/>\n                                <field name="price_total"/>\n                                <field name="price_unit"/>\n                                <field name="display_type"/>\n                                <field name="tax_id"/>\n                                <field name="company_id"/>\n                                <field name="tax_calculation_rounding_method"/>\n                                <control>\n                                    <create name="add_product_control" string="Add a product"/>\n                                    <create name="add_section_control" string="Add a section" context="{'default_display_type': 'line_section'}"/>\n                                    <create name="add_note_control" string="Add a note" context="{'default_display_type': 'line_note'}"/>\n                                    <button name="action_add_from_catalog" context="{'order_id': parent.id}" string="Catalog" type="object" class="btn-secondary"/>\n                                </control>\n                                <templates>\n                                    <t t-name="kanban-box">\n                                        <div t-attf-class="oe_kanban_card oe_kanban_global_click ps-0 pe-0 {{ record.display_type.raw_value ? 'o_is_' + record.display_type.raw_value : '' }}">\n                                            <t t-if="!record.display_type.raw_value">\n                                                <div class="row g-0">\n                                                    <div class="col-2 pe-3">\n                                                        <img t-att-src="kanban_image('product.product', 'image_128', record.product_id.raw_value)" t-att-title="record.product_id.value" t-att-alt="record.product_id.value" style="max-width: 100%;"/>\n                                                    </div>\n                                                    <div class="col-10">\n                                                        <div class="row">\n                                                            <div class="col">\n                                                                <strong t-out="record.product_id.value"/>\n                                                            </div>\n                                                            <div class="col-auto">\n                                                                <strong>Tax excl.: </strong>\n                                                                <t t-set="line_price" t-value="rec