                    <block title=\\"Bank &amp; Cash\\" id=\\"bank_cash\\">\\n                                <setting id=\\"import_bank_statements_csv\\" title=\\"Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.\\" string=\\"CSV, XLS, and XLSX Import\\" help=\\"Import your bank statements in CSV, XLS, and XLSX\\">\\n                                    <field name=\\"module_account_bank_statement_import_csv\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                                <setting title=\\"Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.\\" string=\\"QIF Import\\" help=\\"Import your bank statements in QIF\\">\\n                                    <field name=\\"module_account_bank_statement_import_qif\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                                <setting title=\\"Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.\\" string=\\"OFX Import\\" help=\\"Import your bank statements in OFX\\">\\n                                    <field name=\\"module_account_bank_statement_import_ofx\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                                <setting id=\\"import_bank_statement_camt\\" title=\\"Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.\\" string=\\"CAMT Import\\" help=\\"Import your bank statements in CAMT.053\\">\\n                                    <field name=\\"module_account_bank_statement_import_camt\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                            </block>\\n                        </t>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <block title=\\"Fiscal Periods\\" id=\\"accounting_reports\\">\\n                                <setting id=\\"fiscalyear\\" invisible=\\"1\\" groups=\\"account.group_account_user\\"/>\\n                                <setting id=\\"dynamic_report\\" groups=\\"account.group_account_user\\" help=\\"Navigate easily through reports and see what is behind the numbers\\">\\n                                    <field name=\\"module_account_reports\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                            </block>\\n                        </t>\\n                        <block title=\\"Analytics\\" id=\\"analytic\\">\\n                            <setting id=\\"track_costs_revenues\\" title=\\"Allows you to use the analytic accounting.\\" groups=\\"account.group_account_user\\" help=\\"Track costs &amp; revenues by project, department, etc\\" documentation=\\"/applications/finance/accounting/others/analytic_accounting.html\\">\\n                                <field name=\\"group_analytic_accounting\\"/>\\n                            </setting>\\n                            <setting id=\\"account_budget\\" title=\\"This allows accountants to manage analytic and crossovered budgets. Once the master budgets and the budgets are defined, the project managers can set the planned amount on each analytic account.\\" groups=\\"account.group_account_user\\" help=\\"Use budgets to compare actual with expected revenues and costs\\" documentation=\\"/applications/finance/accounting/others/adviser/budget.html\\">\\n                                <field name=\\"module_account_budget\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"monitor_product_margins\\" string=\\"Margin Analysis\\" help=\\"Monitor your product margins from invoices\\">\\n                                <field name=\\"module_product_margin\\"/>\\n                            </setting>\\n                        </block>\\n                        <field name=\\"is_account_peppol_eligible\\" invisible=\\"1\\"/>\\n                        <block title=\\"PEPPOL Electronic Document Invoicing\\" id=\\"peppol\\" invisible=\\"not is_account_peppol_eligible\\">\\n                            <div id=\\"account_peppol_install\\" class=\\"col-12 col-lg-12 o_setting_box\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"module_account_peppol\\" readonly=\\"False\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\">\\n                                    <label for=\\"module_account_peppol\\" string=\\"Enable PEPPOL\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Allow sending and receiving invoices through the PEPPOL network\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </block>\\n                        <block title=\\"Storno Accounting\\" id=\\"storno\\">\\n                            <setting id=\\"enable_storno_accounting\\" company_dependent=\\"1\\" help=\\"Use Storno accounting\\" title=\\"Allows you to use Storno accounting.\\">\\n                                <field name=\\"account_storno\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Accounting Firms mode\\" id=\\"quick_edit_mode\\">\\n                            <div class=\\"text-muted\\">\\n                                <p style=\\"margin-bottom: 0\\">Accounting firm mode will change invoice/bill encoding:</p>\\n                                <p style=\\"margin-bottom: 0\\"> - The document's sequence becomes editable on all documents.</p>\\n                                <p style=\\"margin-bottom: 0\\"> - A new field « Total (tax inc.) » to speed up and control the encoding by automating line creation with the right account &amp; tax.</p>\\n                                <p style=\\"margin-bottom: 0\\"> - A default Customer Invoice / Vendor Bill date will be suggested.</p>\\n                            </div>\\n                            <setting company_dependent=\\"1\\">\\n                                <field name=\\"quick_edit_mode\\" placeholder=\\"Disabled\\"/>\\n                            </setting>\\n                        </block>\\n                    </app>\\n                </xpath>", "es_AR": "<xpath expr=\\"//form\\" position=\\"inside\\">\\n                    <field name=\\"country_code\\" invisible=\\"1\\" groups=\\"account.group_account_manager\\"/>\\n                    <app data-string=\\"Invoicing\\" string=\\"Facturación\\" name=\\"account\\" groups=\\"account.group_account_manager\\">\\n                        <field name=\\"has_chart_of_accounts\\" invisible=\\"1\\"/>\\n                        <field name=\\"has_accounting_entries\\" invisible=\\"1\\"/>\\n                        <block title=\\"Localización fiscal\\" name=\\"fiscal_localization_setting_container\\" invisible=\\"not is_root_company\\">\\n                            <setting string=\\"Localización fiscal\\" company_dependent=\\"1\\" help=\\"Impuestos, posiciones fiscales, planes de cuentas y declaraciones legales de su país.  \\" documentation=\\"/applications/finance/fiscal_localizations.html\\">\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt16\\">\\n                                        <div>\\n                                            <label for=\\"chart_template\\" string=\\"Paquete\\" class=\\"col-2 o_light_label\\"/>\\n                                            <field name=\\"chart_template\\" readonly=\\"has_accounting_entries\\" required=\\"chart_template\\"/>\\n                                        </div>\\n                                        <div class=\\"mt16\\">\\n                                            <button name=\\"reload_template\\" type=\\"object\\" string=\\"Volver a cargar\\" class=\\"btn-secondary ps-2 w-100\\" icon=\\"fa-refresh\\" title=\\"Volver a cargar datos contables (impuestos, cuentas,...) si hay inconsistencias. Esta acción es irreversible. \\" invisible=\\"not has_accounting_entries or not chart_template\\"/>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Impuestos\\" name=\\"default_taxes_setting_container\\">\\n                            <setting id=\\"default_taxes\\" string=\\"Impuestos predeterminados\\" company_dependent=\\"1\\" help=\\"Impuestos predeterminados aplicados a transacciones locales\\" title=\\"Estos impuestos se establecen en cualquier producto nuevo creado.\\" documentation=\\"/applications/finance/accounting/taxation/taxes/default_taxes.html\\">\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"row mt16\\">\\n                                        <label string=\\"Impuesto de venta\\" for=\\"sale_tax_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"sale_tax_id\\" domain=\\"[('type_tax_use', 'in', ('sale', 'all'))]\\"/>\\n                                    </div>\\n                                    <div class=\\"row\\">\\n                                        <label string=\\"Impuesto de compra\\" for=\\"purchase_tax_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"purchase_tax_id\\" domain=\\"[('type_tax_use', 'in', ('purchase', 'all'))]\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"rounding_method\\" company_dependent=\\"1\\" string=\\"Método de redondeo\\" help=\\"Cómo se calcula la cantidad total de impuestos en pedidos y facturas\\" title=\\"Si los precios tienen los impuestos incluidos, se aconseja redondearlos por línea. De este modo, la suma de los subtotales de las líneas es igual al total con impuestos.\\">\\n                                <field name=\\"tax_calculation_rounding_method\\" class=\\"o_light_label mt16\\" widget=\\"radio\\"/>\\n                            </setting>\\n                            <setting id=\\"taxcloud_settings\\" string=\\"TaxCloud\\" help=\\"Calcule las tasas de impuestos según los códigos postales de EE.UU.\\" documentation=\\"/applications/finance/accounting/taxation/taxes/taxcloud.html\\">\\n                                <field name=\\"module_account_taxcloud\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"avatax_settings\\" string=\\"AvaTax\\" help=\\"Calcular tasas de impuestos automáticamente\\" documentation=\\"/applications/finance/accounting/taxation/taxes/avatax.html\\" company_dependent=\\"1\\">\\n                                <field name=\\"module_account_avatax\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"eu_service\\" title=\\"Si vendes bienes y servicios a clientes en un país que no sea miembro de la UE, debes cobrar el IVA según la dirección de entrega. Esta regla aplica sin importar en dónde te encuentras tú.\\" documentation=\\"/applications/finance/accounting/taxation/taxes/eu_distance_selling.html\\" help=\\"Aplicar el número de identificación fiscal del país de la Unión Europea al que se entregan productos y servicios.\\">\\n                                <field name=\\"module_l10n_eu_oss\\"/>\\n                            </setting>\\n                            <setting id=\\"tax_exigibility\\" company_dependent=\\"1\\" help=\\"Permitir configurar impuestos al momento del pago\\" title=\\"Seleccione esto si los impuestos deben usar la base de efectivo, que creará un asiento para dichos impuestos en una cuenta determinada durante la conciliación.\\" documentation=\\"/applications/finance/accounting/taxation/taxes/cash_basis_taxes.html\\">\\n                                <field name=\\"tax_exigibility\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not tax_exigibility\\" groups=\\"account.group_account_user\\">\\n                                    <div class=\\"row mt16\\">\\n                                        <label for=\\"tax_cash_basis_journal_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"tax_cash_basis_journal_id\\"/>\\n                                    </div>\\n                                    <div class=\\"row mt16\\">\\n                                        <label for=\\"account_cash_basis_base_account_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"account_cash_basis_base_account_id\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"tax_fiscal_country_234\\" string=\\"País fiscal\\" company_dependent=\\"1\\" help=\\"País de origen de su contabilidad\\">\\n                                <field name=\\"account_fiscal_country_id\\" options=\\"{'no_create': True, 'no_open': True}\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Monedas\\" name=\\"main_currency_setting_container\\">\\n                            <setting id=\\"main_currency\\" string=\\"Divisa principal\\