coinage_currency\\" help=\\"Define la moneda más pequeña utilizada para pagar en efectivo\\" documentation=\\"/applications/finance/accounting/receivables/customer_invoices/cash_rounding.html\\">\\n                                <field name=\\"group_cash_rounding\\"/>\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"271\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Redondeos de efectivo\\" class=\\"btn-link\\" invisible=\\"not group_cash_rounding\\"/>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"intrastat_statistics\\" help=\\"Recolecta información y produce estadísticas de la negociación de bienes en Europa con Intrastat.\\" documentation=\\"/applications/finance/accounting/reporting/declarations/intrastat.html\\">\\n                                <field name=\\"module_account_intrastat\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"default_incoterm\\" string=\\"Incoterm predeterminado\\" help=\\"Incoterm determinado de su empresa\\">\\n                                <field name=\\"incoterm_id\\"/>\\n                            </setting>\\n                            <setting id=\\"show_sale_receipts\\" help=\\"Activar para crear un recibo de venta\\">\\n                                <field name=\\"group_show_sale_receipts\\"/>\\n                            </setting>\\n                            <setting id=\\"use_invoice_terms\\" company_dependent=\\"1\\" help=\\"Agregue sus términos y condiciones al final de sus facturas, órdenes o cotizaciones\\">\\n                                <field name=\\"use_invoice_terms\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not use_invoice_terms\\">\\n                                    <div class=\\"mt16\\">\\n                                        <field name=\\"terms_type\\" class=\\"o_light_label\\" widget=\\"radio\\"/>\\n                                        <div>\\n                                            <field name=\\"invoice_terms\\" invisible=\\"terms_type == 'html'\\" class=\\"oe_account_terms mt-5 w-100\\" placeholder=\\"Inserta tus términos y condiciones aquí...\\"/>\\n                                        </div>\\n                                        <div class=\\"mt8\\" invisible=\\"terms_type != 'html'\\">\\n                                            <button name=\\"action_update_terms\\" icon=\\"oi-arrow-right\\" type=\\"object\\" string=\\"Actualizar términos\\" class=\\"btn-link\\"/>\\n                                        </div>\\n                                        <field name=\\"preview_ready\\" invisible=\\"1\\"/>\\n                                        <div class=\\"mt4 ms-1\\" invisible=\\"not preview_ready\\">\\n                                            <a class=\\"btn-link\\" href=\\"/terms\\" role=\\"button\\">\\n                                                <i class=\\"oi oi-arrow-right\\"/>\\n                                                Vista previa\\n                                            </a>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting company_dependent=\\"1\\" help=\\"Active alertas al crear facturas y órdenes de venta para los contactos que tengan un importe total por cobrar que exceda un límite.                                      Defina un valor superior a 0.0 para activar la verificación del límite de crédito.\\">\\n                                <field name=\\"account_use_credit_limit\\"/>\\n                                <div class=\\"content-group mt-2\\" invisible=\\"not account_use_credit_limit\\">\\n                                    <div class=\\"row\\">\\n                                        <label for=\\"account_default_credit_limit\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                        <field name=\\"account_default_credit_limit\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"total_amount_words\\" help=\\"Mostrar el importe total de una factura con letra\\">\\n                                <field name=\\"display_invoice_amount_total_words\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Pagos del cliente\\" id=\\"pay_invoice_online_setting_container\\">\\n                            <setting help=\\"Permite que tus clientes paguen sus facturas en línea\\" documentation=\\"/applications/finance/accounting/receivables/customer_payments/online_payment.html\\">\\n                                <field name=\\"module_account_payment\\"/>\\n                            </setting>\\n                            <setting id=\\"account_batch_payment\\" string=\\"Pagos por lotes\\" help=\\"Agrupa pagos en un solo lote para facilitar el proceso de conciliación\\" documentation=\\"/applications/finance/accounting/receivables/customer_payments/batch.html\\">\\n                                <field name=\\"module_account_batch_payment\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"collect_customer_payment\\" title=\\"Si seleccionas esta casilla, podrás cobrar utilizando los mandatos de domiciliación bancaria SEPA.\\" string=\\"Domiciliación bancaria SEPA (SDD)\\" company_dependent=\\"1\\" help=\\"Recolecta los pagos de los clientes con un solo clic utilizando el Servicio Euro SEPA.\\" documentation=\\"/applications/finance/accounting/receivables/customer_payments/batch_sdd.html\\">\\n                                <field name=\\"module_account_sepa_direct_debit\\" class=\\"oe_inline\\" widget=\\"upgrade_boolean\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not module_account_sepa_direct_debit\\">\\n                                    <div class=\\"text-warning mt16 mb4\\">\\n                                        Guarde esta página y luego regrese para configurar la función.\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"qr_code_invoices\\" title=\\"Agrega un código QR a tus facturas para que tus clientes puedan pagar al instante con su aplicación móvil bancaria.\\" string=\\"Códigos QR\\" company_dependent=\\"1\\" help=\\"Agregue un código QR de pago a sus facturas\\" documentation=\\"/applications/finance/accounting/receivables/customer_invoices/epc_qr_code.html\\">\\n                                <field name=\\"qr_code\\" class=\\"oe_inline\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Facturas de proveedores\\" id=\\"account_vendor_bills\\">\\n                            <setting id=\\"show_purchase_receipts\\" help=\\"Active para crear recibo de compra\\">\\n                                <field name=\\"group_show_purchase_receipts\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Pagos de proveedor\\" id=\\"print_vendor_checks_setting_container\\">\\n                            <setting id=\\"print_checks\\" groups=\\"account.group_account_user\\" string=\\"Cheques\\" company_dependent=\\"1\\" help=\\"Imprima cheques para pagar a sus proveedores\\" documentation=\\"/applications/finance/accounting/payables/pay/check.html\\">\\n                                <field name=\\"module_account_check_printing\\"/>\\n                            </setting>\\n                            <setting id=\\"sepa_payments\\" title=\\"Si seleccionas esta casilla, podrás registrar tu pago utilizando SEPA.\\" company_dependent=\\"1\\" help=\\"Pague sus facturas con solo un clic al utilizar el servicio Euro SEPA\\" documentation=\\"/applications/finance/accounting/payables/pay/sepa.html\\">\\n                                <field name=\\"module_account_sepa\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                        </block>\\n\\n                        <block title=\\"Digitalización\\" id=\\"account_digitalization\\">\\n                            <setting id=\\"account_ocr_settings\\" help=\\"Usa el OCR y la inteligencia artificial para digitalizar tus PDF o documentos escaneados\\" documentation=\\"/applications/finance/accounting/payables/supplier_bills/invoice_digitization.html\\">\\n                                <field name=\\"module_account_invoice_extract\\" widget=\\"upgrade_boolean\\"/>\\n                                <div id=\\"msg_invoice_extract\\" class=\\"content-group\\" invisible=\\"not module_account_invoice_extract\\">\\n                                    <div class=\\"text-warning mt16 mb4\\">\\n                                        Guarde esta página y luego regrese para configurar la función.\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <block title=\\"Cuentas predeterminadas\\" id=\\"default_accounts\\">\\n                                <setting invisible=\\"not group_multi_currency\\" string=\\"Publicar los asientos de diferencia de cambio en:\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"currency_exchange_journal_id\\" class=\\"col-lg-4 o_light_label\\" string=\\"Diario\\"/>\\n                                            <field name=\\"currency_exchange_journal_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"income_currency_exchange_account_id\\" string=\\"Ganancia\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"income_currency_exchange_account_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"expense_currency_exchange_account_id\\" string=\\"Pérdida\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                            <field name=\\"expense_currency_exchange_account_id\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"post_bank_transactions_and_payments_setting\\" string=\\"Publicar transacciones bancarias y pagos en:\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_journal_suspense_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"account_journal_suspense_account_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_journal_payment_debit_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"account_journal_payment_debit_account_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_journal_payment_credit_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"account_journal_payment_credit_account_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"transfer_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"transfer_account_id\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Cuentas de descuento separadas en las facturas\\" title=\\"Si está vacío, el descuento se realizará directamente sobre la cuenta de ingresos/gastos. Si está establecido, los descuentos sobre las facturas se realizarán en cuentas separadas.\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_discount_expense_allocation_id\\" class=\\"col-lg-5 o_light_label\\" string=\\"Facturas de cliente\\"/>\\n                                            <field name=\\"account_discount_expense_allocation_id\\" placeholder=\\"Misma cuenta\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_discount_income_allocation_id\\" class=\\"col-lg-5 o_light_label\\" string=\\"Facturas de proveedores\\"/>\\n                                            <field name=\\"account_discount_income_allocation_id\\" placeholder=\\"Misma cuenta\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Publicar descuentos en:\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_journal_early_pay_discount_gain_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"account_journal_early_pay_discount_gain_account_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_journal_early_pay_discount_loss_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"account_journal_early_pay_discount_loss_account_id\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n                        </t>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <block title=\\"Banco y efectivo\\" id=\\"bank_cash\\">\\n                                <setting id=\\"import_bank_statements_csv\\" title=\\"Una vez instalado, configure &quot;conexiones bancarias&quot; como &quot;importar archivo&quot; en la configuración de la cuenta bancaria. Esto agrega un botón para importar desde el tablero de Contabilidad.\\" string=\\"Importación de formatos CSV, XLS y XLSX\\" help=\\"Importe sus estados de cuenta bancarios en formato CSV, XLS y XLSX\\">\\n                                    <field name=\\"module_account_bank_statement_import_csv\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                                <setting title=\\"Una vez instalado, configure &quot;conexiones bancarias&quot; como &quot;importar archivo&quot; en la configuración de la cuenta bancaria. Esto agrega un botón para importar desde el tablero de Contabilidad.\\" string=\\"Importar QIF\\" help=\\"Importar sus estados de cuenta bancarios en QIF\\">\\n                                    <field name=\\"module_account_bank_statement_import_qif\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                                <setting title=\\"Una vez instalado, configure &quot;conexiones bancarias&quot; como &quot;importar archivo&quot; en la configuración de la cuenta bancaria. Esto agrega un botón para importar desde el tablero de Contabilidad.\\" string=\\"Importar OFX\\" help=\\"Importar sus estados de cuenta bancarios en OFX\\">\\n                                    <field name=\\"module_account_bank_statement_import_ofx\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                                <setting id=\\"import_bank_statement_camt\\" title=\\"Una vez instalado, configure &quot;conexiones bancarias&quot; como &quot;importar archivo&quot; en la configuración de la cuenta bancaria. Esto agrega un botón para importar desde el tablero de Contabilidad.\\" string=\\"Importar CAMT\\" help=\\"Importar sus estados de cuenta bancarios en CAMT.053\\">\\n                                    <field name=\\"module_account_bank_statement_import_camt\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                            </block>\\n                        </t>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <block title=\\"Periodos fiscales\\" id=\\"accounting_reports\\">\\n                                <setting id=\\"fiscalyear\\" invisible=\\"1\\" groups=\\"account.group_account_user\\"/>\\n                                <setting id=\\"dynamic_report\\" groups=\\"account.group_account_user\\" help=\\"Navegue con facilidad por los reportes y observe qué hay detrás de los números\\">\\n                                    <field name=\\"module_account_reports\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                            </block>\\n                        </t>\\n                        <block title=\\"Analítica\\" id=\\"analytic\\">\\n                            <setting id=\\"track_costs_revenues\\" title=\\"Te permite usar la contabilidad analítica.\\" groups=\\"account.group_account_user\\" help=\\"Lleve el seguimiento de costos e ingresos por proyecto, departamento, etc.\\" documentation=\\"/applications/finance/accounting/others/analytic_accounting.html\\">\\n                                <field name=\\"group_analytic_accounting\\"/>\\n                            </setting>\\n                            <setting id=\\"account_budget\\" title=\\"Esto permite que los contadores gestionen presupuestos analíticos y cruzados. Una vez que se definen los presupuestos maestros y los presupuestos, los administradores del proyecto pueden establecer la cantidad planeada en cada cuenta analítica.\\" groups=\\"account.group_account_user\\" help=\\"Utilice los presupuestos para comparar los ingresos y costos reales con los esperados.\\" documentation=\\"/applications/finance/accounting/others/adviser/budget.html\\">\\n                                <field name=\\"module_account_budget\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"monitor_product_margins\\" string=\\"Análisis de margen\\" help=\\"Controle sus márgenes de productos de las facturas\\">\\n                                <field name=\\"module_product_margin\\"/>\\n                            </setting>\\n                        </block>\\n                        <field name=\\"is_account_peppol_eligible\\" invisible=\\"1\\"/>\\n                        <block title=\\"Facturación de documentos electrónicos PEPPOL\\" id=\\"peppol\\" invisible=\\"not is_account_peppol_eligible\\">\\n                            <div id=\\"account_peppol_install\\" class=\\"col-12 col-lg-12 o_setting_box\\">\\n                                <div class=\\"o_setting_left_pane\\">\\n                                    <field name=\\"module_account_peppol\\" readonly=\\"False\\"/>\\n                                </div>\\n                                <div class=\\"o_setting_right_pane\\">\\n                                    <label for=\\"module_account_peppol\\" string=\\"Habilitar PEPPOL\\"/>\\n                                    <div class=\\"text-muted\\">\\n                                        Permitir que se envíen y reciban facturas a través de la red de PEPPOL\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </block>\\n                        <block title=\\"Contabilidad Storno\\" id=\\"storno\\">\\n                            <setting id=\\"enable_storno_accounting\\" company_dependent=\\"1\\" help=\\"Utiliza la contabilidad Storno\\" title=\\"Permite usar la contabilidad Storno.\\">\\n                                <field name=\\"account_storno\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Modo de empresas de contabilidad\\" id=\\"quick_edit_mode\\">\\n                            <div class=\\"text-muted\\">\\n                                <p style=\\"margin-bottom: 0\\">El modo de empresas de contabilidad cambiará la codificación de la factura:</p>\\n                                <p style=\\"margin-bottom: 0\\"> - Se habilita la edición de la secuencia de documentos en todos los documentos.</p>\\n                                <p style=\\"margin-bottom: 0\\"> - Con el campo nuevo \\"Total (impuestos incluidos)\\" podrás  acelerar y controlar la codificación, ya que las líneas se crearán de inmediato con la cuenta y el impuesto correctos.</p>\\n                                <p style=\\"margin-bottom: 0\\"> - Se sugerirá una fecha predeterminada para la factura del cliente o del proveedor.</p>\\n                            </div>\\n                            <setting company_dependent=\\"1\\">\\n                                <field name=\\"quick_edit_mode\\" placeholder=\\"Deshabilitado\\"/>\\n                            </setting>\\n                        </block>\\n                    </app>\\n                </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                    <field name="country_code" invisible="1" groups="account.group_account_manager"/>\n                    <app data-string="Invoicing" string="Invoicing" name="account" groups="account.group_account_manager">\n                        <field name="has_chart_of_accounts" invisible="1"/>\n                        <field name="has_accounting_entries" invisible="1"/>\n                        <block title="Fiscal Localization" name="fiscal_localization_setting_container" invisible="not is_root_company">\n                            <setting string="Fiscal Localization" company_dependent="1" help="Taxes, fiscal positions, chart of accounts &amp; legal statements for your country" documentation="/applications/finance/fiscal_localizations.html">\n                                <div class="content-group">\n                                    <div class="mt16">\n                                        <div>\n                                            <label for="chart_template" string="Package" class="col-2 o_light_label"/>\n                                            <field name="chart_template" readonly="has_accounting_entries" required="chart_template"/>\n                                        </div>\n                                        <div class="mt16">\n                                            <button name="reload_template" type="object" string="Reload" class="btn-secondary ps-2 w-100" icon="fa-refresh" title="Reload accounting data (taxes, accounts, ...) if you notice inconsistencies. This action is irreversible." invisible="not has_accounting_entries or not chart_template"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </setting>\n                        </block>\n                        <block title="Taxes" name="default_taxes_setting_container">\n                            <setting id="default_taxes" string="Default Taxes" company_dependent="1" help="Default taxes applied to local transactions" title="These taxes are set in any new product created." documentation="/applications/finance/accounting/taxation/taxes/default_taxes.html">\n                                <div class="content-group">\n                                    <div class="row mt16">\n                                        <label string="Sales Tax" for="sale_tax_id" class="col-lg-3 o_light_label"/>\n                                        <field name="sale_tax_id" domain="[('type_tax_use', 'in', ('sale', 'all'))]"/>\n                                    </div>\n                                    <div class="row">\n                                        <label string="Purchase Tax" for="purchase_tax_id" class="col-lg-3 o_light_label"/>\n                                        <field name="purchase_tax_id" domain="[('type_tax_use', 'in', ('purchase', 'all'))]"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="rounding_method" company_dependent="1" string="Rounding Method" help="How total tax amount is computed in orders and invoices" title="A rounding per line is advised if your prices are tax-included. That way, the sum of line subtotals equals the total with taxes.">\n                                <field name="tax_calculation_rounding_method" class="o_light_label mt16" widget="radio"/>\n                            </setting>\n                            <setting id="taxcloud_settings" string="TaxCloud" help="Compute tax rates based on U.S. ZIP codes" documentation="/applications/finance/accounting/taxation/taxes/taxcloud.html">\n                                <field name="module_account_taxcloud" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="avatax_settings" string="AvaTax" help="Automatically compute tax rates" documentation="/applications/finance/accounting/taxation/taxes/avatax.html" company_dependent="1">\n                                <field name="module_account_avatax" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="eu_service" title="If you sell goods and services to customers in a foreign EU country, you must charge VAT based on the delivery address. This rule applies regardless of where you are located." documentation="/applications/finance/accounting/taxation/taxes/eu_distance_selling.html" help="Apply VAT of the EU country to which goods and services are delivered.">\n                                <field name="module_l10n_eu_oss"/>\n                            </setting>\n                            <setting id="tax_exigibility" company_dependent="1" help="Allow to configure taxes using cash basis" title="Select this if the taxes should use cash basis, which will create an entry for such taxes on a given account during reconciliation." documentation="/applications/finance/accounting/taxation/taxes/cash_basis_taxes.html">\n                                <field name="tax_exigibility"/>\n                                <div class="content-group" invisible="not tax_exigibility" groups="account.group_account_user">\n                                    <div class="row mt16">\n                                        <label for="tax_cash_basis_journal_id" class="col-lg-3 o_light_label"/>\n                                        <field name="tax_cash_basis_journal_id"/>\n                                    </div>\n                                    <div class="row mt16">\n                                        <label for="account_cash_basis_base_account_id" class="col-lg-3 o_light_label"/>\n                                        <field name="account_cash_basis_base_account_id"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="tax_fiscal_country_234" string="Fiscal Country" company_dependent="1" help="Domestic country of your accounting">\n                                <field name="account_fiscal_country_id" options="{'no_create': True, 'no_open': True}"/>\n                            </setting>\n                        </block>\n                        <block title="Currencies" name="main_currency_setting_container">\n                            <setting id="main_currency" string="Main Currency" company_dependent="1" help="Main currency of your company" documentation="/applications/finance/accounting/others/multi_currency.html">\n                                <div class="content-group">\n                                    <div class="row mt16">\n                                        <label for="currency_id" class="col-lg-3 o_light_label"/>\n                                        <field name="currency_id" options="{'no_create_edit': True, 'no_open': True}" context="{'active_test': False}"/>\n                                        <field name="group_multi_currency" invisible="1"/>\n                                    </div>\n                                    <div class="mt8">\n                                        <button type="action" name="66" string="Currencies" class="btn-link" icon="oi-arrow-right"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="update_exchange_rates" invisible="not group_multi_currency" help="Update exchange rates automatically" documentation="/applications/finance/accounting/others/multi_currency.html">\n                                <field name="module_currency_rate_live" widget="upgrade_boolean"/>\n                            </setting>\n                        </block>\n                        <block title="Customer Invoices" id="invoicing_settings">\n                            <setting id="default_setting_options" string="Default Sending Options" help="Those options will be selected by default when clicking &quot;Send &amp; Print&quot; on invoices">\n                                <div class="mt16">\n                                    <div class="content-group" id="send_default">\n                                        <div>\n                                            <field name="invoice_is_download"/>\n                                            <label for="invoice_is_download"/>\n                                            <span class="fa fa-lg fa-building-o" title="Values set here are company-specific."/>\n                                        </div>\n                                        <div>\n                                            <field name="invoice_is_email"/>\n                                            <label for="invoice_is_email"/>\n                                            <span class="fa fa-lg fa-building-o" title="Values set here are company-specific."/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="send_invoices_followups" help="Send invoices and payment follow-ups by post" documentation="/applications/finance/accounting/receivables/customer_invoices/snailmail.html">\n                                <field name="module_snailmail_account"/>\n                            </setting>\n                            <setting id="invoice_delivery_addresses" documentation="/applications/sales/sales/send_quotations/different_addresses.html" help="Select specific invoice and delivery addresses">\n                                <field name="group_sale_delivery_address"/>\n                            </setting>\n                            <setting id="get_invoice_warnings" string="Warnings" help="Get warnings when invoicing specific customers">\n                                <field name="group_warning_account"/>\n                            </setting>\n                            <setting id="smallest_coinage_currency" help="Define the smallest coinage of the currency used to pay by cash" documentation="/applications/finance/accounting/receivables/customer_invoices/cash_rounding.html">\n                                <field name="group_cash_rounding"/>\n                                <div class="mt8">\n                                    <button name="271" icon="oi-arrow-right" type="action" string="Cash Roundings" class="btn-link" invisible="not group_cash_rounding"/>\n                                </div>\n                            </setting>\n                            <setting id="intrastat_statistics" help="Collect information and produce statistics on the trade in goods in Europe with intrastat" documentation="/applications/finance/accounting/reporting/declarations/intrastat.html">\n                                <field name="module_account_intrastat" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="default_incoterm" string="Default Incoterm" help="Default Incoterm of your company">\n                                <field name="incoterm_id"/>\n                            </setting>\n                            <setting id="show_sale_receipts" help="Activate to create sale receipt">\n                                <field name="group_show_sale_receipts"/>\n                            </setting>\n                            <setting id="use_invoice_terms" company_dependent="1" help="Add your terms &amp; conditions at the bottom of invoices/orders/quotations">\n                                <field name="use_invoice_terms"/>\n                                <div class="content-group" invisible="not use_invoice_terms">\n                                    <div class="mt16">\n                                        <field name="terms_type" class="o_light_label" widget="radio"/>\n                                        <div>\n                                            <field name="invoice_terms" invisible="terms_type == 'html'" class="oe_account_terms mt-5 w-100" placeholder="Insert your terms &amp; conditions here..."/>\n                                        </div>\n                                        <div class="mt8" invisible="terms_type != 'html'">\n                                            <button name="action_update_terms" icon="oi-arrow-right" type="object" string="Update Terms" class="btn-link"/>\n                                        </div>\n                                        <field name="preview_ready" invisible="1"/>\n                                        <div class="mt4 ms-1" invisible="not preview_ready">\n                                            <a class="btn-link" href="/terms" role="button">\n                                                <i class="oi oi-arrow-right"/>\n                                                Preview\n                                            </a>\n                                        </div>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting company_dependent="1" help="Trigger alerts when creating Invoices and Sales Orders for Partners with a Total Receivable amount exceeding a limit.                                      Set a value greater than 0.0 to activate a credit limit check">\n                                <field name="account_use_credit_limit"/>\n                                <div class="content-group mt-2" invisible="not account_use_credit_limit">\n                                    <div class="row">\n                                        <label for="account_default_credit_limit" class="col-lg-4 o_light_label"/>\n                                        <field name="account_default_credit_limit"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="total_amount_words" help="Display the total amount of an invoice in letters">\n                                <field name="display_invoice_amount_total_words"/>\n                            </setting>\n                        </block>\n                        <block title="Customer Payments" id="pay_invoice_online_setting_container">\n                            <setting help="Let your customers pay their invoices online" documentation="/applications/finance/accounting/receivables/customer_payments/online_payment.html">\n                                <field name="module_account_payment"/>\n                            </setting>\n                            <setting id="account_batch_payment" string="Batch Payments" help="Group payments into a single batch to ease the reconciliation process" documentation="/applications/finance/accounting/receivables/customer_payments/batch.html">\n                                <field name="module_account_batch_payment" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="collect_customer_payment" title="If you check this box, you will be able to collect payments using SEPA Direct Debit mandates." string="SEPA Direct Debit (SDD)" company_dependent="1" help="Collect customer payments in one-click using Euro SEPA Service" documentation="/applications/finance/accounting/receivables/customer_payments/batch_sdd.html">\n                                <field name="module_account_sepa_direct_debit" class="oe_inline" widget="upgrade_boolean"/>\n                                <div class="content-group" invisible="not module_account_sepa_direct_debit">\n                                    <div class="text-warning mt16 mb4">\n                                        Save this page and come back here to set up the feature.\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="qr_code_invoices" title="Add a QR-code to your invoices so that your customers can pay instantly with their mobile banking application." string="QR Codes" company_dependent="1" help="Add a payment QR-code to your invoices" documentation="/applications/finance/accounting/receivables/customer_invoices/epc_qr_code.html">\n                                <field name="qr_code" class="oe_inline"/>\n                            </setting>\n                        </block>\n                        <block title="Vendor Bills" id="account_vendor_bills">\n                            <setting id="show_purchase_receipts" help="Activate to create purchase receipt">\n                                <field name="group_show_purchase_receipts"/>\n                            </setting>\n                        </block>\n                        <block title="Vendor Payments" id="print_vendor_checks_setting_container">\n                            <setting id="print_checks" groups="account.group_account_user" string="Checks" company_dependent="1" help="Print checks to pay your vendors" documentation="/applications/finance/accounting/payables/pay/check.html">\n                                <field name="module_account_check_printing"/>\n                            </se