"{'no_open': True, 'no_create': True}"/>\n                            <field name="state_ids" widget="many2many_tags" domain="[('country_id', '=', country_id)]" invisible="(not auto_apply and not foreign_vat) or not country_id or states_count == 0"/>\n                            <label for="zip_from" string="Zip Range" invisible="not auto_apply or not country_id"/>\n                            <div invisible="not auto_apply or not country_id">\n                                <span> From </span>\n                                <field name="zip_from" class="oe_inline"/>\n                                <div class="oe_edit_only"/>\n                                <span> To </span>\n                                <field name="zip_to" class="oe_inline"/>\n                            </div>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page name="tax_mapping" string="Tax Mapping">\n                            <field name="tax_ids" widget="one2many" nolabel="1" context="{'append_type_to_tax_name': True}">\n                                <tree name="tax_map_tree" string="Tax Mapping" editable="bottom" no_open="1" decoration-muted="tax_dest_id and not tax_dest_active">\n                                    <field name="tax_dest_active" column_invisible="1"/>\n                                    <field name="tax_src_id" domain="[                                             ('type_tax_use', '!=', 'none'),                                             ('country_id', '=', parent.company_country_id),                                             '|', ('company_id', '=', False), ('company_id', 'parent_of', parent.company_id)                                         ]" context="{'append_type_to_tax_name': True}"/>\n\n                                    <field name="tax_dest_id" domain="[                                             ('type_tax_use', '!=', 'none'),                                             ('country_id', '=', parent.country_id if parent.foreign_vat else parent.company_country_id),                                             '|', ('company_id', '=', False), ('company_id', 'parent_of', parent.company_id)]" context="{'append_type_to_tax_name': True}"/>\n                                </tree>\n                                <form name="tax_map_form" string="Tax Mapping">\n                                    <group>\n                                        <field name="tax_src_id" domain="[('type_tax_use', '!=', 'none')]" context="{'append_type_to_tax_name': True}"/>\n                                        <field name="tax_dest_id" domain="[('type_tax_use', '!=', 'none')]" context="{'append_type_to_tax_name': True}"/>\n                                    </group>\n                                </form>\n                            </field>\n                        </page>\n                        <page name="account_mapping" string="Account Mapping" groups="account.group_account_readonly">\n                            <field name="account_ids" widget="one2many" nolabel="1">\n                                <tree string="Account Mapping" editable="bottom">\n                                    <field name="account_src_id" domain="['|', '|', ('company_id', '=', False), ('company_id', '=', parent.company_id), ('account_type', '!=', 'off_balance')]"/>\n                                    <field name="account_dest_id" domain="['|', '|', ('company_id', '=', False), ('company_id', '=', parent.company_id), ('account_type', '!=', 'off_balance')]"/>\n                                </tree>\n                                <form string="Account Mapping">\n                                    <field name="account_src_id" domain="['|', '|', ('company_id', '=', False), ('company_id', '=', parent.company_id), ('account_type', '!=', 'off_balance')]"/>\n                                    <field name="account_dest_id" domain="['|', '|', ('company_id', '=', False), ('company_id', '=', parent.company_id), ('account_type', '!=', 'off_balance')]"/>\n                                </form>\n                            </field>\n                        </page>\n                    </notebook>\n                    <field name="note" class="oe-bordered-editor" placeholder="Legal Notes..."/>\n                    </sheet>\n                </form>\n            	f	t	2026-10-23 14:02:50.18711	2026-10-23 14:02:50.18711	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
