1070	16	439	1	1	product.template.form.view.inherit.sale	product.template	\N	form	sale/views/product_views.xml	extension	{"en_US": "<data><page name=\\"sales\\" position=\\"attributes\\">\\n                <attribute name=\\"invisible\\" remove=\\"1\\" separator=\\" or \\"/>\\n            </page>\\n            <field name=\\"product_variant_count\\" position=\\"after\\">\\n                <field name=\\"service_type\\" widget=\\"radio\\" invisible=\\"True\\"/>\\n                <field name=\\"visible_expense_policy\\" invisible=\\"1\\"/>\\n            </field>\\n            <field name=\\"detailed_type\\" position=\\"after\\">\\n                <field name=\\"invoice_policy\\" required=\\"1\\"/>\\n                <field name=\\"expense_policy\\" widget=\\"radio\\" invisible=\\"not visible_expense_policy\\"/>\\n            </field>\\n            <field name=\\"product_tooltip\\" position=\\"after\\">\\n                <label for=\\"product_tooltip\\" string=\\"\\" invisible=\\"type not in ('product', 'consu') or invoice_policy != 'order'\\"/>\\n                <div invisible=\\"type not in ('product', 'consu') or invoice_policy != 'order'\\" class=\\"fst-italic text-muted\\">\\n                    You can invoice them before they are delivered.\\n                </div>\\n                <label for=\\"product_tooltip\\" string=\\"\\" invisible=\\"type not in ('product', 'consu') or invoice_policy != 'delivery'\\"/>\\n                <div invisible=\\"type not in ('product', 'consu') or invoice_policy != 'delivery'\\" class=\\"fst-italic text-muted\\">\\n                    Invoice after delivery, based on quantities delivered, not ordered.\\n                </div>\\n            </field>\\n        </data>", "es_AR": "<data><page name=\\"sales\\" position=\\"attributes\\">\\n                <attribute name=\\"invisible\\" remove=\\"1\\" separator=\\" or \\"/>\\n            </page>\\n            <field name=\\"product_variant_count\\" position=\\"after\\">\\n                <field name=\\"service_type\\" widget=\\"radio\\" invisible=\\"True\\"/>\\n                <field name=\\"visible_expense_policy\\" invisible=\\"1\\"/>\\n            </field>\\n            <field name=\\"detailed_type\\" position=\\"after\\">\\n                <field name=\\"invoice_policy\\" required=\\"1\\"/>\\n                <field name=\\"expense_policy\\" widget=\\"radio\\" invisible=\\"not visible_expense_policy\\"/>\\n            </field>\\n            <field name=\\"product_tooltip\\" position=\\"after\\">\\n                <label for=\\"product_tooltip\\" string=\\"\\" invisible=\\"type not in ('product', 'consu') or invoice_policy != 'order'\\"/>\\n                <div invisible=\\"type not in ('product', 'consu') or invoice_policy != 'order'\\" class=\\"fst-italic text-muted\\">\\n                    Puede facturarlas antes de que se entreguen.\\n                </div>\\n                <label for=\\"product_tooltip\\" string=\\"\\" invisible=\\"type not in ('product', 'consu') or invoice_policy != 'delivery'\\"/>\\n                <div invisible=\\"type not in ('product', 'consu') or invoice_policy != 'delivery'\\" class=\\"fst-italic text-muted\\">\\n                    Factura después de la entrega, según las cantidades entregadas, no en las órdenes.\\n                </div>\\n            </field>\\n        </data>"}	<?xml version="1.0"?>\n<data><page name="sales" position="attributes">\n                <attribute name="invisible" remove="1" separator=" or "/>\n            </page>\n            <field name="product_variant_count" position="after">\n                <field name="service_type" widget="radio" invisible="True"/>\n                <field name="visible_expense_policy" invisible="1"/>\n            </field>\n            <field name="detailed_type" position="after">\n                <field name="invoice_policy" required="1"/>\n                <field name="expense_policy" widget="radio" invisible="not visible_expense_policy"/>\n            </field>\n            <field name="product_tooltip" position="after">\n                <label for="product_tooltip" string="" invisible="type not in ('product', 'consu') or invoice_policy != 'order'"/>\n                <div invisible="type not in ('product', 'consu') or invoice_policy != 'order'" class="fst-italic text-muted">\n                    You can invoice them before they are delivered.\n                </div>\n                <label for="product_tooltip" string="" invisible="type not in ('product', 'consu') or invoice_policy != 'delivery'"/>\n                <div invisible="type not in ('product', 'consu') or invoice_policy != 'delivery'" class="fst-italic text-muted">\n                    Invoice after delivery, based on quantities delivered, not ordered.\n                </div>\n            </field>\n        </data>	f	t	2026-10-30 14:24:31.464076	2026-10-30 14:24:31.464076	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
