                <span class=\\"o_stat_value d-flex gap-1\\">\\n                            <field name=\\"sales_count\\" widget=\\"statinfo\\" nolabel=\\"1\\" class=\\"oe_inline\\"/>\\n                            <field name=\\"uom_name\\" class=\\"oe_inline\\"/>\\n                        </span>\\n                        <span class=\\"o_stat_text\\">Vendido</span>\\n                    </div>\\n                </button>\\n            </div>\\n            <group name=\\"description\\" position=\\"after\\">\\n                <t groups=\\"sales_team.group_sale_salesman\\">\\n                    <group string=\\"Advertencia cuando se venda este producto\\" groups=\\"sale.group_warning_sale\\">\\n                        <field name=\\"sale_line_warn\\" string=\\"Advertencia\\"/>\\n                        <field name=\\"sale_line_warn_msg\\" string=\\"Mensaje\\" placeholder=\\"Escribe un mensaje...\\" invisible=\\"sale_line_warn == 'no-message'\\" readonly=\\"sale_line_warn == 'no-message'\\" required=\\"sale_line_warn != 'no-message'\\"/>\\n                    </group>\\n                </t>\\n            </group>\\n        </data>"}	<?xml version="1.0"?>\n<data><div name="button_box" position="inside">\n                <button class="oe_stat_button" name="action_view_sales" type="object" icon="fa-signal" help="Sold in the last 365 days" groups="sales_team.group_sale_salesman" invisible="not sale_ok">\n                    <div class="o_field_widget o_stat_info">\n                        <span class="o_stat_value d-flex gap-1">\n                            <field name="sales_count" widget="statinfo" nolabel="1" class="oe_inline"/>\n                            <field name="uom_name" class="oe_inline"/>\n                        </span>\n                        <span class="o_stat_text">Sold</span>\n                    </div>\n                </button>\n            </div>\n            <group name="description" position="after">\n                <t groups="sales_team.group_