\\" position=\\"inside\\">\\n                        <separator/>\\n                        <filter name=\\"account_id\\" context=\\"{'group_by': 'account_id'}\\"/>\\n                        <separator/>\\n                        <filter string=\\"Cuenta financiera\\" name=\\"group_by_financial_account\\" context=\\"{'group_by':'general_account_id'}\\"/>\\n                        <filter string=\\"Categoría\\" name=\\"category\\" context=\\"{'group_by': 'category'}\\"/>\\n                        <filter string=\\"Producto\\" name=\\"product\\" context=\\"{'group_by':'product_id'}\\"/>\\n                        <filter string=\\"Contacto\\" name=\\"partner\\" context=\\"{'group_by':'partner_id'}\\"/>\\n                    </xpath>\\n                </data>"}	<?xml version="1.0"?>\n<data>\n                    <xpath expr="//field[@name='date']" position="after">\n                        <field name="auto_account_id"/>\n                        <field name="account_id"/>\n                        <field name="product_id"/>\n                        <field name="general_account_id"/>\n                        <field name="partner_id" filter_domain="[('partner_id','child_of',self)]"/>\n                    </xpath>\n                    <xpath expr="//group[@name='groupby']" position="inside">\n                        <separator/>\n                        <filter name="account_id" context="{'group_by': 'account_id'}"/>\n                        <separator/>\n                        <filter string="Financial Account" name="group_by_financial_account" context="{'group_by':'general_account_id'}"/>\n                        <filter string="Category" name="category" context="{'group_by': 'category'}"/>\n                        <filter string="Product" name="product" context="{'group_by':'product_id'}"/>\n                        <filter string="Partner" name="partner" context="{'group_by':'partner_id'}"/>\n                    </xpath>\n                </data>\n            	f	t	2026-10