ces, SO and PO.\\n\\n                ARGUMENTS:\\n                - tax_totals: dict in the form generated by account.move's _get_tax_totals.\\n            -->\\n            <t t-foreach=\\"tax_totals.get('subtotals')\\" t-as=\\"subtotal\\">\\n                <tr class=\\"border-black o_subtotal\\">\\n                    <td><strong t-out=\\"subtotal['name']\\">Subtotal</strong></td>\\n\\n                    <td class=\\"text-end\\">\\n                        <span t-att-class=\\"oe_subtotal_footer_separator\\" t-out=\\"subtotal['formatted_amount']\\">27.00</span>\\n                    </td>\\n                </tr>\\n\\n                <t t-set=\\"subtotal_to_show\\" t-value=\\"subtotal['name']\\"/>\\n                <t t-call=\\"account.tax_groups_totals\\"/>\\n            </t>\\n\\n            <tr t-if=\\"'formatted_rounding_amount' in tax_totals and tax_totals.get('rounding_amount') != 0\\">\\n                <td>Redondeo</td>\\n                <td class=\\"text-end\\">\\n                    <span t-out=\\"tax_totals.get('formatted_rounding_amount')\\">0</span>\\n                </td>\\n            </tr>\\n            \\n            <!--Total amount with all taxes-->\\n            <tr class=\\"border-black o_total\\">\\n                <td><strong>Total</strong></td>\\n                <td class=\\"text-end\\">\\n                    <span t-out=\\"tax_totals.get('formatted_amount_total')\\">31.05</span>\\n                </td>\\n            </tr>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="account.document_tax_totals_template">\n            <!--\n                Generic template to display tax totals in pdf reports.\n                Used by invoices, SO and PO.\n\n                ARGUMENTS:\n                - tax_totals: dict in the form generated by account.move's _get_tax_totals.\n            -->\n            <t t-foreach="tax_totals.get('subtotals')" t-as="subtotal">\n                <tr class="border-black o_subtotal">\n                    <td><strong t-out="subtotal['name']">Untaxed Amount</strong></td>\n\n                    <td class="text-end">\n                        <span t-att-class="oe_subtotal_footer_separator" t-out="subtotal['formatted_amount']">27.00</span>\n                    </td>\n                </tr>\n\n                <t t-set="subtotal_to_show" t-value="subtotal['name']"/>\n                <t t-call="account.tax_groups_totals"/>\n            </t>\n\n            <tr t-if="'formatted_rounding_amount' in tax_totals and tax_totals.get('rounding_amount') != 0">\n                <td>Rounding</td>\n                <td class="text-end">\n                    <span t-out="tax_totals.get('formatted_rounding_amount')">0</span>\n                </td>\n            </tr>\n            \n            <!--Total amount with all taxes-->\n            <tr class="border-black o_total">\n                <td><strong>Total</strong></td>\n                <td class="text-end">\n                    <span t-out="tax_totals.get('formatted_amount_total')">31.05</span>\n                </td>\n            </tr>\n        </t>\n\n         	f	t	2026-10-23 14:02:50.18711	2026-10-23 14:02:50.18711	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
