       <t t-if=\\"invoice.state == 'posted'\\" name=\\"invoice_status_posted\\">\\n                                <span t-if=\\"invoice.payment_state in ('paid', 'in_payment')\\" class=\\"badge rounded-pill text-bg-success\\">\\n                                    <i class=\\"fa fa-fw fa-check\\" aria-label=\\"Pagado\\" title=\\"Pagado\\" role=\\"img\\"/>\\n                                    <span class=\\"d-none d-md-inline\\"> Pagado</span>\\n                                </span>\\n                                <span t-elif=\\"invoice.payment_state == 'reversed'\\" class=\\"badge rounded-pill text-bg-success\\">\\n                                    <i class=\\"fa fa-fw fa-check\\" aria-label=\\"Revertido\\" title=\\"Revertido\\" role=\\"img\\"/>\\n                                    <span class=\\"d-none d-md-inline\\"> Revertido</span>\\n                                </span>\\n                                <span t-else=\\"\\" class=\\"badge rounded-pill text-bg-info\\" name=\\"invoice_status_waiting_for_payment\\">\\n                                    <i class=\\"fa fa-fw fa-clock-o\\" aria-label=\\"Abierto\\" title=\\"Abierto\\" role=\\"img\\"/>\\n                                    <span class=\\"d-none d-md-inline\\"> En espera del pago</span>\\n                                </span>\\n                            </t>\\n                            <t t-elif=\\"invoice.state == 'cancel'\\">\\n                                <span class=\\"badge rounded-pill text-bg-warning\\">\\n                                    <i class=\\"fa fa-fw fa-remove\\" aria-label=\\"Cancelado\\" title=\\"Cancelado\\" role=\\"img\\"/>\\n                                    <span class=\\"d-none d-md-inline\\"> Cancelado</span>\\n                                </span>\\n                            </t>\\n                        </td>\\n                        <td class=\\"text-end\\"><span t-out=\\"-invoice.amount_residual if invoice.move_type == 'out_refund' else invoice