 t-out=\\"ExchangedDocument_vals.get('included_note')\\"/>\\n                    </ram:IncludedNote>\\n                    <ram:IncludedNote t-foreach=\\"ExchangedDocument_vals.get('included_note_list')\\" t-as=\\"included_note\\">\\n                        <ram:Content t-out=\\"included_note.get('content')\\"/>\\n                        <ram:SubjectCode t-out=\\"included_note.get('subject_code')\\"/>\\n                    </ram:IncludedNote>\\n                </rsm:ExchangedDocument>\\n\\n                <rsm:SupplyChainTradeTransaction>\\n                    <!-- Invoice lines. -->\\n                    <t t-foreach=\\"invoice_line_vals_list\\" t-as=\\"line_vals\\">\\n                        <t t-call=\\"account_edi_ubl_cii.account_invoice_line_facturx_export_22\\"/>\\n                    </t>\\n\\n                    <!-- Partners. -->\\n                    <ram:ApplicableHeaderTradeAgreement>\\n                        <!-- \\"Service Exécutant\\" (Used by Chorus Pro) -->\\n                        <ram:BuyerReference t-out=\\"buyer_reference\\"/>\\n                        <!-- Seller. -->\\n                        <ram:SellerTradeParty>\\n                            <!-- Address. -->\\n                            <t t-call=\\"account_edi_ubl_cii.account_invoice_partner_facturx_export_22\\">\\n                                <t t-set=\\"partner\\" t-value=\\"record.company_id.partner_id\\"/>\\n                                <t t-set=\\"specified_legal_organization_val\\" t-value=\\"seller_specified_legal_organization\\"/>\\n                            </t>\\n\\n                            <ram:URIUniversalCommunication t-if=\\"record.company_id.partner_id.peppol_eas and record.company_id.partner_id.peppol_endpoint\\">\\n                                <ram:URIID t-att-schemeID=\\"record.company_id.partner_id.peppol_eas\\" t-out=\\"record.company_id.partner_id.peppol_endpoint\\"/>\\n                            </ram:URIUniversalCommunication>\\n\\n                            <!-- VAT. -->\\n                            <ram:SpecifiedTaxRegistration t-if=\\"record.fiscal_position_id.foreign_vat\\">\\n                                <ram:ID schemeID=\\"VA\\" t-out=\\"record.fiscal_position_id.foreign_vat\\"/>\\n                            </ram:SpecifiedTaxRegistration>\\n\\n                            <ram:SpecifiedTaxRegistration t-elif=\\"record.company_id.vat\\">\\n                                <ram:ID schemeID=\\"VA\\" t-out=\\"record.company_id.vat\\"/>\\n                            </ram:SpecifiedTaxRegistration>\\n                        </ram:SellerTradeParty>\\n\\n                        <!-- Customer. -->\\n                        <ram:BuyerTradeParty>\\n                            <!-- Address. -->\\n                            <t t-call=\\"account_edi_ubl_cii.account_invoice_partner_facturx_export_22\\">\\n                                <t t-set=\\"partner\\" t-value=\\"record.partner_id\\"/>\\n                                <t t-set=\\"specified_legal_organization_val\\" t-value=\\"buyer_specified_legal_organization\\"/>\\n                            </t>\\n\\n                            <ram:URIUniversalCommunication t-if=\\"record.partner_id.peppol_eas and record.partner_id.peppol_endpoint\\">\\n                                <ram:URIID t-att-schemeID=\\"record.partner_id.peppol_eas\\" t-out=\\"record.partner_id.peppol_endpoint\\"/>\\n                            </ram:URIUniversalCommunication>\\n\\n                            <!-- VAT. -->\\n                            <ram:SpecifiedTaxRegistration t-if=\\"record.commercial_partner_id.vat\\">\\n                                <ram:ID schemeID=\\"VA\\" t-out=\\"record.commercial_partner_id.vat\\"/>\\n                            </ram:SpecifiedTaxRegistration>\\n                        </ram:BuyerTradeParty>\\n\\n                        <!-- Reference. -->\\n                        <ram:BuyerOrderReferencedDocument>\\n                            <!-- \\"Engagement Juridique\\" (used by Chorus Pro) -->\\n                            <ram:IssuerAssignedID t-out=\\"purchase_order_reference\\"/>\\n                        </ram:BuyerOrderReferencedDocument>\\n                        <ram:ContractReferencedDocument>\\n                            <!-- \\"Numéro de Marché\\" (Used by Chorus Pro) -->\\n                            <ram:IssuerAssignedID t-out=\\"contract_reference\\"/>\\n                        </ram:ContractReferencedDocument>\\n                    </ram:ApplicableHeaderTradeAgreement>\\n\\n                    <!-- Delivery -->\\n                    <ram:ApplicableHeaderTradeDelivery>\\n                        <ram:ShipToTradeParty>\\n                            <t t-call=\\"account_edi_ubl_cii.account_invoice_partner_facturx_export_22\\">\\n                                <t t-set=\\"partner\\" t-value=\\"ship_to_trade_party\\"/>\\n                                <t t-set=\\"hide_dtc\\" t-value=\\"document_context_id == 'urn:cen.eu:en16931:2017#compliant#urn:xoev-de:kosit:standard:xrechnung_2.2'\\"/>\\n                            </t>\\n                        </ram:ShipToTradeParty>\\n\\n                        <ram:ActualDeliverySupplyChainEvent t-if=\\"scheduled_delivery_time\\">\\n                            <ram:OccurrenceDateTime>\\n                                <udt:DateTimeString t-att-format=\\"102\\" t-out=\\"format_date(scheduled_delivery_time)\\"/>\\n                            </ram:OccurrenceDateTime>\\n                        </ram:ActualDeliverySupplyChainEvent>\\n                    </ram:ApplicableHeaderTradeDelivery>\\n\\n                    <!-- Taxes. -->\\n                    <ram:ApplicableHeaderTradeSettlement>\\n\\n                        <ram:PaymentReference t-out=\\"record.payment_reference\\"/>\\n                        <ram:InvoiceCurrencyCode t-out=\\"currency.name\\"/>\\n\\n                        <!-- Bank account. -->\\n                        <ram:SpecifiedTradeSettlementPaymentMeans t-if=\\"record.partner_bank_id.sanitized_acc_number\\">\\n                            <ram:TypeCode t-out=\\"payment_means_code\\"/>\\n                            <ram:PayeePartyCreditorFinancialAccount>\\n                                <ram:IBANID t-if=\\"record.partner_bank_id.acc_type == 'iban'\\" t-out=\\"record.partner_bank_id.sanitized_acc_number\\"/>\\n                                <ram:ProprietaryID t-if=\\"record.partner_bank_id.acc_type != 'iban'\\" t-out=\\"record.partner_bank_id.sanitized_acc_number\\"/>\\n                            </ram:PayeePartyCreditorFinancialAccount>\\n                        </ram:SpecifiedTradeSettlementPaymentMeans>\\n\\n                        <!-- Tax Summary. -->\\n                        <t t-foreach=\\"tax_details.get('tax_details', {}).values()\\" t-as=\\"tax_detail_vals\\">\\n                            <ram:ApplicableTradeTax>\\n                                <ram:CalculatedAmount t-out=\\"format_monetary(tax_detail_vals.get('calculated_amount'), 2)\\"/>\\n                                <ram:TypeCode t-translation=\\"off\\">VAT</ram:TypeCode>\\n                                <ram:ExemptionReason t-out=\\"tax_detail_vals.get('tax_exemption_reason')\\"/>\\n                                <ram:BasisAmount t-out=\\"format_monetary(tax_detail_vals['base_amount_currency'], 2)\\"/>\\n                                <ram:CategoryCode t-out=\\"tax_detail_vals['tax_category_code']\\"/>\\n                                <ram:ExemptionReasonCode t-out=\\"tax_detail_vals['tax_exemption_reason_code']\\"/>\\n                                <!-- 5 = Tax is exigible on the date on the invoice -->\\n                                <ram:DueDateTypeCode>5</ram:DueDateTypeCode>\\n                                <ram:RateApplicablePercent t-if=\\"tax_detail_vals['amount_type'] == 'percent'\\" t-out=\\"tax_detail_vals['amount']\\"/>\\n                            </ram:ApplicableTradeTax>\\n                        </t>\\n\\n   