draft_refund_tx\\" role=\\"alert\\" invisible=\\"not has_pending_refund\\">\\n                    <p>\\n                        <strong>¡Advertencia!</strong> Hay un reembolso pendiente para este pago.\\n                        Espere un momento a que se procese. Si el reembolso sigue pendiente en\\n                        unos minutos, verifique la configuración de su proveedor de pago.\\n                    </p>\\n                </div>\\n                <group>\\n                    <group>\\n                        <field name=\\"payment_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"transaction_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"currency_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"support_refund\\" invisible=\\"1\\"/>\\n                        <field name=\\"payment_amount\\"/>\\n                        <field name=\\"refunded_amount\\" invisible=\\"refunded_amount &lt;= 0\\"/>\\n                        <field name=\\"amount_available_for_refund\\"/>\\n                        <field name=\\"amount_to_refund\\" readonly=\\"support_refund == 'full_only'\\"/>\\n                    </group>\\n                </group>\\n                <footer>\\n                    <button string=\\"Reembolso\\" type=\\"object\\" name=\\"action_refund\\" class=\\"btn-primary\\"/>\\n                    <button string=\\"Cerrar\\" special=\\"cancel\\" class=\\"btn-secondary\\"/>\\n                </footer>\\n            </form>"}	<?xml version="1.0"?>\n<form string="Refund">\n                <field name="has_pending_refund" invisible="1"/>\n                <div class="alert alert-warning" id="alert_draft_refund_tx" role="alert" invisible="not has_pending_refund">\n                    <p>\n                        <strong>Warning!</strong> There is a refund pending for this payment.\n                        Wait a moment for it to be processed. If the refund is still pending in a\n                        few minutes, please check your payment provider configuration.\n                    </p>\n                </div>\n                <group>\n                    <group>\n                        <field name="payment_id" invisible="1"/>\n                        <field name="transaction_id" invisible="1"/>\n                        <field name="currency_id" invisible="1"/>\n                        <field name="support_refund" invisible="1"/>\n                        <field name="payment_amount"/>\n                        <field name="refunded_amount" invisible="refunded_amount &lt;= 0"/>\n                        <field name="amount_available_for_refund"/>\n                        <field name="amount_to_refund" readonly="support_refund == 'full_only'"/>\n                    </group>\n                </group>\n                <footer>\n                    <button string="Refund" type="object" name="action_refund" class="btn-primary"/>\n                    <button string="Close" special="cancel" class="btn-secondary"/>\n                </footer>\n            </form>\n        	f	t	2026-10-23 14:03:02.870137	2026-10-23 14:03:02.870137	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
813	16	748	1	1	Invoice error display: payment errors	\N	account_payment.portal_invoice_error	qweb	account_payment/views/account_portal_templates.xml	extension	{"en_US": "<data name=\\"Invoice error display: payment errors\\" inherit_id=\\"account.portal_invoice_error\\">\\n        <xpath expr=\\"//t[@name='generic']\\" position=\\"after\\">\\n            <t t-if=\\"error == 'pay_invoice_invalid_doc'\\">\\n                There was an error processing your payment: invalid invoice.\\n            </t>\\n            <t t-elif=\\"error == 'pay_invoice_invalid_token'\\">\\n                There was en error processing your payment: invalid credit card ID.\\n            </t>\\n            <t t-elif=\\"error == 'pay_invoice_tx_fail'\\">\\n                There was an error processing your payment: transaction failed.<br/>\\n                <t t-set=\\"tx_sudo\\" t-value=\\"invoice.get_portal_last_transaction()\\"/>\\n                <t t-if=\\"tx_sudo and tx_sudo.state_message\\">\\n                    <t t-out=\\"tx_sudo.state_message\\"/>\\n                </t>\\n            </t>\\n            <t t-elif=\\"error == 'pay_invoice_tx_token'\\">\\n                There was an error processing your payment: issue with credit card ID validation.\\n            </t>\\n        </xpath>\\n    </data>", "es_AR": "<data name=\\"Invoice error display: payment errors\\" inherit_id=\\"account.portal_invoice_error\\">\\n        <xpath expr=\\"//t[@name='generic']\\" position=\\"after\\">\\n            <t t-if=\\"error == 'pay_invoice_invalid_doc'\\">\\n                Se produjo un error al procesar su pago: factura no válida.\\n            </t>\\n            <t t-elif=\\"error == 'pay_invoice_invalid_token'\\">\\n                Se produjo un error al procesar su pago: identificación de la tarjeta de crédito no válida.\\n            </t>\\n            <t t-elif=\\"error == 'pay_invoice_tx_fail'\\">\\n                Ocurrió un error al procesar su pago: la transacción falló. <br/>\\n  