king\\">Descripción en el traslado</span>\\n                                        </td>\\n                                        <td>\\n                                            <span t-field=\\"ml.quantity\\">3.00</span>\\n                                            <span t-field=\\"ml.product_uom_id\\" groups=\\"uom.group_uom\\">unidades</span>\\n                                            <span t-if=\\"ml.move_id.product_packaging_id\\">\\n                                                <span t-if=\\"o.state != 'done'\\">\\n                                                    (<span t-field=\\"ml.product_packaging_qty\\" t-options=\\"{&quot;widget&quot;: &quot;integer&quot;}\\"/> <span t-field=\\"ml.move_id.product_packaging_id.name\\"/>)\\n                                                </span>\\n                                                <span t-if=\\"o.state == 'done'\\">\\n                                                    (<span t-field=\\"ml.product_packaging_qty\\" t-options=\\"{&quot;widget&quot;: &quot;integer&quot;}\\"/> <span t-field=\\"ml.move_id.product_packaging_id.name\\"/>)\\n                                                </span>\\n                                            </span>\\n                                        </td>\\n                                        <td t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <span t-esc=\\"ml.location_id.display_name\\">WH/Existencias</span>\\n                                                <t t-if=\\"ml.package_id\\">\\n                                                    <span t-field=\\"ml.package_id\\">Paquete A</span>\\n                                                </t>\\n                                        </td>\\n                                        <td t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <div>\\n                                                <span t-field=\\"ml.location_dest_id\\">WH/Saliente</span>\\n                                                <t t-if=\\"ml.result_package_id\\">\\n                                                    <span t-field=\\"ml.result_package_id\\">Paquete B</span>\\n                                                </t>\\n                                            </div>\\n                                        </td>\\n                                        <td class=\\" text-center h6\\" t-if=\\"has_serial_number\\">\\n                                            <span t-if=\\"has_serial_number and (ml.lot_id or ml.lot_name)\\" t-esc=\\"ml.lot_id.name or ml.lot_name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 400, 'height': 100, 'img_style': 'width:100%;height:35px;'}\\">\\n                                                <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\\">\\n                                                    (código de barras en serie)\\n                                                </div>\\n                                            </span>\\n                                        </td>\\n                                        <td class=\\"text-center\\" t-if=\\"has_barcode\\">\\n                                            <t t-if=\\"product_barcode != ml.product_id.barcode\\">\\n                                                <span t-if=\\"ml.product_id and ml.product_id.barcode\\">\\n                                                    <div t-field=\\"ml.product_id.barcode\\" t-options=\\"{'widget': 'barcode', 'symbology': 'auto', 'width': 400, 'height': 100, 'quiet': 0, 'img_style': 'height:35px;'}\\">\\n                                                        <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\\">\\n                                                            (código de barras del producto)\\n                                                        </div>\\n                                                    </div>\\n                                                </span>\\n                                                <t t-set=\\"product_barcode\\" t-value=\\"ml.product_id.barcode\\"/>\\n                                            </t>\\n                                        </td>\\n                                    </tr>\\n                                  </tbody>\\n                            </table>\\n                            <div t-if=\\"not (o.package_level_ids and o.picking_type_entire_packs and o.state in ['assigned', 'done'])\\" class=\\"oe_structure\\"/>\\n                            <table t-else=\\"\\" class=\\"table table-sm\\">\\n                                <thead>\\n                                    <tr>\\n                                        <th name=\\"th_package\\">Paquete</th>\\n                                        <th name=\\"th_pko_from\\" t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">Desde</th>\\n                                        <th name=\\"th_pki_from\\" t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">A</th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <tr t-foreach=\\"o.package_level_ids.sorted(key=lambda p: p.package_id.name)\\" t-as=\\"package\\">\\n                                        <td name=\\"td_pk_barcode\\">\\n                                            <t t-set=\\"package\\" t-value=\\"package.with_context(picking_id=o.id)\\"/>\\n                                            <div t-field=\\"package.package_id.name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}\\">\\n                                                <div class=\\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center\\">\\n                                                    (código de barras del paquete)\\n                                                </div>\\n                                            </div>\\n                                                <br/>\\n                                        </td>\\n                                        <td t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <span t-field=\\"package.location_id\\"/>\\n                                        </td>\\n                                        <td t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <span t-field=\\"package.location_dest_id\\"/>\\n                                        </td>\\n                                    </tr>\\n                                </tbody>\\n                            </table>\\n\\n                            <t t-set=\\"no_reserved_product\\" t-value=\\"o.move_ids.filtered(lambda x: x.product_uom_qty != x.quantity and x.move_line_ids and x.state!='done')\\"/>\\n                            <p t-if=\\"o.state in ['draft', 'waiting', 'confirmed'] or no_reserved_product\\"><i class=\\"fa fa-exclamation-triangle\\"/>\\n                                No se pudieron reservar todos los productos. Haga clic en el botón \\"comprobar disponibilidad\\" para intentar reservar productos.\\n                            </p>\\n                            <p t-else=\\"\\"/>\\n                            <div class=\\"oe_structure\\"/>\\n                            <p t-field=\\"o.note\\"/>\\n                            <div class=\\"oe_structure\\"/>\\n                        </div>\\n                    </t>\\n                </t>\\n            </t>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="stock.report_picking">\n            <t t-call="web.html_container">\n                <t t-foreach="docs" t-as="o">\n                    <t t-call="web.external_layout">\n                        <t t-set="address" t-value="None"/>\n                        <div class="page">\n                            <div class="row justify-content-end mb16">\n                                <div class="col-4" name="right_box">\n                                    <div t-field="o.name" t-options="{'widget': 'barcode', 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;'}">\n                                        <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center p-3 opacity-75 text-muted text-center">\n                                            (document barcode)\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="row">\n                                <div class="col-6" name="div_outgoing_address">\n                                    <div t-if="o.should_print_delivery_address()">\n                                        <span><strong>Delivery Address:</strong></span>\n                                        <div t-out="o.move_ids[0].partner_id or o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}">\n                                                <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center">\n                                                    <strong>Delivery address</strong>\n                                                    <div>Presence depends on the type of operation.</div>\n                                                </div>\n                                        </div>\n                                    </div>\n                                    <div t-elif="o.picking_type_id.code != 'internal' and o.picking_type_id.warehouse_id.partner_id">\n                                        <span><strong>Warehouse Address:</strong></span>\n                                        <div t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}">\n                                                <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center">\n                                                    <strong>Warehouse address</strong>\n                                                    <div>Presence depends on the type of operation.</div>\n                                                </div>\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class="col-5 offset-1" name="div_incoming_address">\n                                    <t t-set="show_partner" t-value="False"/>\n                                    <div t-if="o.picking_type_id.code=='incoming' and o.partner_id">\n                                        <span><strong>Vendor Address:</strong></span>\n                                        <t t-set="show_partner" t-value="True"/>\n                                    </div>\n                                    <div t-elif="o.picking_type_id.code=='internal' and o.partner_id">\n                                        <span><strong>Warehouse Address:</strong></span>\n                                        <t t-set="show_partner" t-value="True"/>\n                                    </div>\n                                    <div t-elif="o.picking_type_id.code=='outgoing' and o.partner_id and o.partner_id != o.partner_id.commercial_partner_id">\n                                        <span><strong>Customer Address:</strong></span>\n                                        <t t-set="show_partner" t-value="True"/>\n                                    </div>\n                                    <div t-if="show_partner" name="partner_header">\n                                        <div t-field="o.partner_id.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}">\n                                             <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center">\n                                                <strong>Recipient address</strong>\n                                                <div>Presence depends on the type of operation.</div>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                                <!-- This node is incompatible (in wkhtmltopdf) with its siblings which together take all space. We can't remove it in stable for stability reasons -->\n                                <div class="oe_structure" style="display: none;"/>\n                            </div>\n                            <div class="oe_structure"/>\n                            <h1 t-field="o.name" class="mt0">WH/OUT/00001</h1>\n                            <div class="oe_structure"/>\n                            <div class="row mt32 mb32">\n                                <div t-if="o.origin" class="col-auto" name="div_origin">\n                                    <strong>Order:</strong>\n                                    <p t-field="o.origin">S0001</p>\n                                </div>\n                                <div class="col-auto" name="div_state">\n                                    <strong>Status:</strong>\n                                    <p t-field="o.state">Draft</p>\n                                </div>\n                                <div t-if="o.scheduled_date" class="col-auto" name="div_sched_date">\n                                    <strong>Scheduled Date:</strong>\n                                    <p t-field="o.scheduled_date">2023-09-24</p>\n                                </div>\n                            </div>\n                            <table class="table table-sm" t-if="o.move_line_ids and o.move_ids_without_package">\n                                <t t-set="has_barcode" t-value="any(move_line.product_id and move_line.product_id.sudo().barcode or move_line.package_id for move_line in o.move_line_ids)"/>\n                                <t t-set="has_serial_number" t-value="any(move_line.lot_id or move_line.lot_name for move_line in o.move_line_ids)" groups="stock.group_production_lot"/>\n                                <thead>\n                                    <tr>\n                                        <th name="th_product">\n                                            <strong>Product</strong>\n                                        </th>\n                                        <th>\n                                            <strong>Quantity</strong>\n                                        </th>\n                                        <th name="th_from" t-if="o.picking_type_id.code != 'incoming'" align="left" groups="stock.group_stock_multi_locations">\n                                            <strong>From</strong>\n                                        </th>\n                                        <th name="th_to" t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">\n                                            <strong>To</strong>\n                                        </th>\n                                        <th name="th_serial_number" class="text-center" t-if="has_serial_number">\n                                           <strong>Lot/Serial Number</strong>\n                                        </th>\n                                        <th name="th_barcode" class="text-center" t-if="has_barcode">\n                                            <strong>Product Barcode</strong>\n                                        </th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <!-- In case you come across duplicated lines, ask NIM or LAP -->\n                                    <tr t-foreach="o.move_line_ids_without_package.sorted(lambda ml: (ml.location_id.complete_name, ml.location_dest_id.complete_name))" t-as="ml">\n                                        <td>\n                                            <span t-field="ml.product_id.display_name">Customizable Desk</span><br/>\n                                            <span t-if="ml.product_id.description_picking" t-field="ml.product_id.description_picking">Description on transfer</span>\n                                        </td>\n                                        <td>\n                                            <span t-field="ml.quantity">3.00</span>\n                                            <span t-field="ml.product_uom_id" groups="uom.group_uom">units</span>\n                                            <span t-if="ml.move_id.product_packaging_id">\n                                                <span t-if="o.state != 'done'">\n                                                    (<span t-field="ml.product_packaging_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="ml.move_id.product_packaging_id.name"/>)\n                                                </span>\n                                                <span t-if="o.state == 'done'">\n                                                    (<span t-field="ml.product_packaging_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="ml.move_id.product_packaging_id.name"/>)\n                                                </span>\n                                            </span>\n                                        </td>\n                                        <td t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">\n                                            <span t-esc="ml.location_id.display_name">WH/Stock</span>\n                                                <t t-if="ml.package_id">\n                                                    <span t-field="ml.package_id">Package A</span>\n                                                </t>\n                                        </td>\n                                        <td t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">\n                                            <div>\n                                                <span t-field="ml.location_dest_id">WH/Outgoing</span>\n                                                <t t-if="ml.result_package_id">\n                                                    <span t-field="ml.result_package_id">Package B</span>\n                                                </t>\n                                            </div>\n                                        </td>\n                                        <td class=" text-center h6" t-if="has_serial_number">\n                                            <span t-if="has_serial_number and (ml.lot_id or ml.lot_name)" t-esc="ml.lot_id.name or ml.lot_name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 400, 'height': 100, 'img_style': 'width:100%;height:35px;'}">\n                                                <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center">\n                                                    (serial barcode)\n                                                </div>\n                                            </span>\n                                        </td>\n                                        <td class="text-center" t-if="has_barcode">\n                                            <t t-if="product_barcode != ml.product_id.barcode">\n                                                <span t-if="ml.product_id and ml.product_id.barcode">\n                                                    <div t-field="ml.product_id.barcode" t-options="{'widget': 'barcode', 'symbology': 'auto', 'width': 400, 'height': 100, 'quiet': 0, 'img_style': 'height:35px;'}">\n                                                        <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center">\n                                                            (product barcode)\n                                                        </div>\n                                                    </div>\n                                                </span>\n                                                <t t-set="product_barcode" t-value="ml.product_id.barcode"/>\n                                            </t>\n                                        </td>\n                                    </tr>\n                                  </tbody>\n                            </table>\n                            <div t-if="not (o.package_level_ids and o.picking_type_entire_packs and o.state in ['assigned', 'done'])" class="oe_structure"/>\n                            <table t-else="" class="table table-sm">\n                                <thead>\n                                    <tr>\n                                        <th name="th_package">Package</th>\n                                        <th name="th_pko_from" t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">From</th>\n                                        <th name="th_pki_from" t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">To</th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <tr t-foreach="o.package_level_ids.sorted(key=lambda p: p.package_id.name)" t-as="package">\n                                        <td name="td_pk_barcode">\n                                            <t t-set="package" t-value="package.with_context(picking_id=o.id)"/>\n                                            <div t-field="package.package_id.name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}">\n                                                <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center">\n                                                    (package barcode)\n                                                </div>\n                                            </div>\n                                                <br/>\n                                        </td>\n                                        <td t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations"