ment/use_locations.html\\" title=\\"Store products in specific locations of your warehouse (e.g. bins, racks) and to track inventory accordingly.\\">\\n                                <field name=\\"group_stock_multi_locations\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_stock_multi_locations\\">\\n                                        <button name=\\"456\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Locations\\" class=\\"btn-link\\"/><br/>\\n                                        <button name=\\"stock.action_putaway_tree\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Putaway Rules\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"use_own_routes\\" help=\\"Use your own routes\\" documentation=\\"/applications/inventory_and_mrp/inventory/routes/concepts/use_routes.html\\" title=\\"Add and customize route operations to process product moves in your warehouse(s): e.g. unload &gt; quality control &gt; stock for incoming products, pick &gt; pack &gt; ship for outgoing products. You can also set putaway strategies on warehouse locations in order to send incoming products into specific child locations straight away (e.g. specific bins, racks).\\">\\n                                <field name=\\"group_stock_adv_location\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_stock_adv_location\\">\\n                                        <button name=\\"427\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Set Warehouse Routes\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"categorize_locations\\" help=\\"Categorize your locations for smarter putaway rules\\" invisible=\\"not group_stock_multi_locations\\">\\n                                <field name=\\"group_stock_storage_categories\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not group_stock_storage_categories\\">\\n                                    <div class=\\"mt8\\">\\n                                        <button name=\\"462\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Storage Categories\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                    <div class=\\"mt4\\" groups=\\"base.group_no_one\\">\\n                                        <button name=\\"463\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Storage Category Capacity\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Advanced Scheduling\\" id=\\"schedule_info\\" invisible=\\"1\\">\\n                            <div id=\\"sale_security_lead\\"/>\\n                            <div id=\\"purchase_po_lead\\"/>\\n                        </block>\\n                        <block title=\\"Logistics\\" name=\\"request_vendor_setting_container\\">\\n                            <setting title=\\"This adds a dropshipping route to apply on products in order to request your vendors to deliver to your customers. A product to dropship will generate a purchase request for quotation once the sales order confirmed. This is a on-demand flow. The requested delivery address will be the customer delivery address and not your warehouse.\\" help=\\"Request your vendors to deliver to your customers\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/delivery/dropshipping.html\\">\\n                      