lass=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"sell_purchase_uom\\" help=\\"Vender y comprar productos en diferentes unidades de medida\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/products/uom.html\\">\\n                                <field name=\\"group_uom\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_uom\\">\\n                                        <button name=\\"88\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Unidades de medida\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"manage_product_packaging\\" title=\\"Gestione paquetes de productos (por ejemplo, paquete de 6 botellas, caja de 10 unidades)\\" help=\\"Gestione paquetes de productos (por ejemplo, paquete de 6 botellas, caja de 10 unidades)\\" documentation=\\"/applications/inventory_and_mrp/inventory/product_management/product_tracking/packaging.html\\">\\n                                <field name=\\"group_stock_packaging\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_stock_packaging\\">\\n                                        <button name=\\"169\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Embalajes del producto\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Trazabilidad\\" id=\\"production_lot_info\\">\\n                            <setting id=\\"full_traceability