\">\\n                            <p class=\\"o_view_nocontent_empty_folder\\">No se seleccionó ningún punto de venta</p>\\n                            <p>Cree o seleccione un punto de venta para mostrar las opciones de configuración.</p>\\n                        </div>\\n                    </div>\\n                    <div class=\\"o_notification_alert alert alert-warning mt-1 mb-0\\" invisible=\\"not pos_has_active_session\\" role=\\"alert\\">\\n                        Hay una sesión abierta para este PdV. Antes de cambiar algunos ajustes debe cerrar la sesión.\\n                        <button class=\\"btn-link\\" style=\\"padding:0\\" name=\\"pos_open_ui\\" type=\\"object\\" context=\\"{'pos_config_id': pos_config_id}\\">Haga clic aquí para cerrar la sesión</button>\\n                    </div>\\n                    <div class=\\"o_notification_alert alert alert-warning\\" invisible=\\"pos_company_has_template\\" role=\\"alert\\">\\n                        No hay un plan de cuentas configurado en la empresa. Vaya a la configuración de facturación para instalar un plan de cuentas.\\n                    </div>\\n                    <div invisible=\\"not pos_config_id\\">\\n                        <block title=\\"Modo de restaurante\\" id=\\"restaurant_section\\">\\n                            <!-- Wrap the warnings in an o_setting_box so that it doesn't show in the search. -->\\n                            <setting>\\n                                <field name=\\"pos_module_pos_restaurant\\" readonly=\\"pos_has_active_session\\"/>\\n                                <div class=\\"content-group\\" id=\\"warning_text_pos_restaurant\\" invisible=\\"not pos_module_pos_restaurant\\">\\n                                    <div class=\\"text-warning mt16 mb4\\">\\n                                        Guarde esta página y regrese para configurar la función.\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Pago\\" id=\\"pos_payment_section\\">\\n                            <setting id=\\"payment_methods_new\\" string=\\"Métodos de pago\\" help=\\"Métodos de pago disponibles\\">\\n                                <field name=\\"pos_payment_method_ids\\" colspan=\\"4\\" widget=\\"many2many_tags\\" readonly=\\"pos_has_active_session\\" required=\\"pos_company_has_template\\" options=\\"{'no_create': True}\\"/>\\n                                <div>\\n                                    <button name=\\"489\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Métodos de pago\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </setting>\\n                            <setting string=\\"Validar órdenes de forma automática\\" help=\\"Valide las órdenes pagadas con una terminal de pago en automático\\">\\n                                <field name=\\"pos_auto_validate_terminal_payment\\"/>\\n                            </setting>\\n                            <setting string=\\"Redondeo de efectivo\\" invisible=\\"is_kiosk_mode\\" documentation=\\"/applications/sales/point_of_sale/pricing/cash_rounding.html\\" help=\\"Define la moneda más pequeña utilizada para pagar en efectivo\\">\\n                                <field name=\\"pos_cash_rounding\\" readonly=\\"pos_has_active_session\\"/>\\n                                <div class=\\"content-group mt16\\" invisible=\\"not pos_cash_rounding\\">\\n                                    <div class=\\"row mt16\\">\\n                                        <label string=\\"Método de redondeo\\" for=\\"pos_rounding_method\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"pos_rounding_method\\" required=\\"pos_cash_rounding\\" domain=\\"[('company_id', '=', company_id)]\\" readonly=\\"pos_has_active_session\\"/>\\n                                 