ble=\\"not pos_iface_tipproduct\\">\\n                                    <div class=\\"mt16\\" id=\\"tip_product\\">\\n                                        <label string=\\"Producto de propina\\" for=\\"pos_tip_product_id\\" class=\\"o_light_label\\"/>\\n                                        <field name=\\"pos_tip_product_id\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Interfaz de PdV\\" id=\\"pos_interface_section\\">\\n                            <div class=\\"o_notification_alert alert alert-warning\\" invisible=\\"pos_company_has_template\\" role=\\"alert\\">\\n                                No hay un plan de cuentas configurado en la empresa. Vaya a la configuración de facturación para instalar un plan de cuentas.\\n                            </div>\\n                            <setting help=\\"Empiece a vender desde una categoría de producto predeterminada\\">\\n                                <field name=\\"pos_start_category\\"/>\\n                                <div class=\\"content-group mt16\\" invisible=\\"not pos_start_category\\">\\n                                    <field name=\\"pos_iface_start_categ_id\\" domain=\\"[('id', 'in', pos_selectable_categ_ids)]\\"/>\\n                                </div>\\n                            </setting>\\n\\n                            <setting id=\\"multiple_employee_session\\" title=\\"Los empleados pueden escanear su credencial o ingresar un PIN para iniciar sesión en una sesión de PdV. Puede configurar estos permisos en la pestaña *Ajustes de RR. HH.* en el formulario del empleado.\\" string=\\"Múltiples empleados por sesión\\" help=\\"Permitir registrar y cambiar entre empleados seleccionados\\">\\n                                <field name=\\"pos_module_pos_hr\\" readonly=\\"pos_has_active_session\\"/>\\n                            