s de los demás\\" id=\\"is_order_shared\\" invisible=\\"pos_module_pos_restaurant or is_kiosk_mode\\">\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"row mt16\\">\\n                                        <label string=\\"PdV de confianza\\" for=\\"pos_trusted_config_ids\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"pos_trusted_config_ids\\" widget=\\"many2many_tags\\" options=\\"{'no_create':'true'}\\" placeholder=\\"Seleccione el PdV para empezar a compartir órdenes\\"/>\\n                                    </div>\\n                                    <div>\\n                                        <button name=\\"492\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Punto de venta\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Contabilidad\\" id=\\"pos_accounting_section\\">\\n                            <setting id=\\"default_sales_tax_setting\\" title=\\"Este impuesto se aplica a todos los productos nuevos creados en el catálogo.\\">\\n                                <label string=\\"Impuesto de ventas predeterminado\\" for=\\"sale_tax_id\\"/>\\n                                <i class=\\"fa fa-info-circle me-1\\" title=\\"Este ajuste es normal en todos los PdV.\\" pos-data-toggle=\\"tooltip\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Impuesto de venta de productos predeterminado\\n                                </div>\\n                                <div class=\\"content-group mt16\\">\\n                                    <field name=\\"sale_tax_id\\" colspan=\\"4\\" nolabel=\\"1\\" domain=\\"[('type_tax_use', 'in', ('sale', 'all'))]\\"/>\\n                                </div>\\n                                <div class=\\"mt8\\">\\n                                    <button name=\\"260\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Impuestos\\" class=\\"btn-link\\"/>\\n                                </div>\\n                            </setting>\\n                            <setting groups=\\"account.group_account_readonly\\">\\n                                <label string=\\"Cuenta temporal predeterminada\\" for=\\"account_default_pos_receivable_account_id\\"/>\\n                                <i class=\\"fa fa-info-circle me-1\\" title=\\"Este ajuste es normal en todos los PdV.\\" pos-data-toggle=\\"tooltip\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Cuenta intermediaria que se utiliza para clientes sin identificar.\\n                                </div>\\n                                <field name=\\"account_default_pos_receivable_account_id\\" colspan=\\"4\\" nolabel=\\"1\\" domain=\\"[('reconcile', '=', True), ('account_type', '=', 'asset_receivable')]\\"/>\\n                            </setting>\\n                            <setting id=\\"flexible_taxes\\" title=\\"Elija una posición fiscal específica en la orden en función del tipo de cliente (exento de impuestos, &quot;en el lugar&quot; vs. &quot;para llevar&quot;, etc.).\\" string=\\"Impuestos flexibles\\" help=\\"Utilice las posiciones fiscales para usar impuestos distintos por orden\\">\\n                                <field name=\\"pos_tax_regime_selection\\"/>\\n                                <div class=\\"content-group mt16\\" invisible=\\"not pos_tax_regime_selection\\">\\n                                    <div class=\\"row\\">\\n                                        <label string=\\"Predeterminado\\" for=\\"pos_default_fiscal_position_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"pos_default_fiscal_position_id\\"/>\\n                                    </div>\\n                                    <div class=\\"row\\">\\n                                        <label string=\\"Permitido\\" for=\\"pos_fiscal_position_ids\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"pos_fiscal_position_ids\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\"/>\\n                                    </div>\\n                                    <div>\\n                                        <button name=\\"275\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Posiciones fiscales\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting string=\\"Diarios predeterminados\\" id=\\"pos_default_journals\\" help=\\"Diarios predeterminados para órdenes y facturas\\">\\n                                <div class=\\"content-group mt16\\">\\n                                    <div class=\\"row\\" title=\\"Cada vez que cierra una sesión se genera un asiento en el siguiente registro contable para todas las órdenes no facturadas. Las facturas se registran en la contabilidad por separado.\\">\\n                                        <label string=\\"Órdenes\\" for=\\"pos_journal_id\\" class=\\"col-lg-3 o_light_label\\" options=\\"{'no_open': True, 'no_create': True}\\"/>\\n                                        <field name=\\"pos_journal_id\\" domain=\\"[('company_id', '=', company_id), ('type', 'in', ('general', 'sale'))]\\" context=\\"{'default_company_id': company_id, 'default_type': 'general'}\\" required=\\"pos_company_has_template\\"/>\\n                                    </div>\\n                                    <div class=\\"row\\">\\n                                        <label string=\\"Facturas\\" for=\\"pos_invoice_journal_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"pos_invoice_journal_id\\" domain=\\"[('company_id', '=', company_id), ('type', '=', 'sale')]\\" required=\\"pos_company_has_template\\" context=\\"{'default_company_id': company_id, 'default_type': 'sale'}\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n\\n                        <block title=\\"Precios\\" id=\\"pos_pricing_section\\">\\n                            <setting id=\\"multiple_prices_setting\\" string=\\"Listas de precios flexibles\\" help=\\"Establezca varios precios por producto, descuentos automáticos, etc.\\">\\n                                <field name=\\"pos_use_pricelist\\" readonly=\\"pos_has_active_session\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not pos_use_pricelist\\">\\n                                    <div class=\\"mt16\\">\\n                                        <field name=\\"group_sale_pricelist\\" invisible=\\"1\\"/>\\n                                        <field name=\\"product_pricelist_setting\\" widget=\\"radio\\" class=\\"o_light_label\\"/>\\n                                    </div>\\n                                    <div class=\\"row mt16\\">\\n                                        <label string=\\"Disponible\\" for=\\"pos_available_pricelist_ids\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"pos_available_pricelist_ids\\" widget=\\"many2many_tags\\" domain=\\"['|',('company_id', '=', company_id),('company_id', '=', False)]\\" readonly=\\"pos_has_active_session\\"/>\\n                                    </div>\\n                                    <div class=\\"row mt16\\">\\n                                        <label string=\\"Predeterminado\\" for=\\"pos_pricelist_id\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                        <field name=\\"pos_pricelist_id\\" domain=\\"[('id', 'in', pos_allowed_pricelist_ids)]\\" options=\\"{'no_create': True}\\"/>\\n                                    </div>\\n                                    <div class=\\"mt8\\">\\n                                        <button name=\\"170\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Listas de precios\\" groups=\\"product.group_product_pricelist\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"price_control\\" class=\\"price_control\\" title=\\"Solo los usuarios con permisos de acceso de gerente en la aplicación Punto de Venta pueden modificar los precios de los productos en las órdenes.\\" string=\\"Control de precios\\" help=\\"Restringir la modificación de los precios a los responsables\\">\\n                                <field name=\\"pos_restrict_price_control\\"/>\\n                            </setting>\\n                            <setting id=\\"product_prices\\" string=\\"Precios del producto\\" help=\\"Precios del producto en los recibos\\">\\n                                <field name=\\"pos_iface_tax_included\\" class=\\"o_light_label\\" widget=\\"radio\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <a invisible=\\"pos_iface_tax_included != 'total'\\" href=\\"https://www.odoo.com/documentation/17.0/applications/finance/accounting/taxation/taxes/B2B_B2C.html\\" target=\\"_blank\\" class=\\"oe-link\\"><i class=\\"oi oi-fw oi-arrow-right\\"/>Cómo gestionar precios con impuestos incluidos</a>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"manual_discount\\" help=\\"Permitir a los cajeros configurar un descuento por línea\\">\\n                                <field name=\\"pos_manual_discount\\"/>\\n                            </setting>\\n                            <setting help=\\"Agregar un botón para configurar un descuento global\\">\\n                                <field name=\\"pos_module_pos_discount\\" readonly=\\"pos_has_active_session\\"/>\\n                                <div class=\\"content-group mt16\\" invisible=\\"not pos_module_pos_discount\\">\\n                                    <div class=\\"text-warning mb4\\" id=\\"warning_text_pos_discount\\">\\n                                        Guarde esta página y regrese para configurar la función.\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"pos-loyalty\\" title=\\"Aumente sus ventas con varios tipos de programas: cupones, promociones, tarjetas de regalo y programas de lealtad. Puede establecer condiciones específicas (productos, clientes, importe de compra mínimo, periodo). Las recompensas pueden ser descuentos (un porcentaje o un importe) o productos gratis.\\" string=\\"Promociones, cupones, tarjetas de regalo y programas de lealtad\\" help=\\"Gestione las promociones que le otorgarán descuentos o regalos a los clientes\\">\\n                                <field name=\\"module_loyalty\\"/>\\n                            </setting>\\n                        </block>\\n\\n                        <block title=\\"Facturas y recibos\\" id=\\"pos_bills_and_receipts_section\\">\\n                            <setting help=\\"Agregar un mensaje personalizado en el encabezado y pie de página\\">\\n                                <field name=\\"pos_is_header_or_footer\\"/>\\n                                <div class=\\"content-group mt16\\" invisible=\\"not pos_is_header_or_footer\\">\\n                                    <div>\\n                                        <label string=\\"Encabezado\\" for=\\"pos_receipt_header\\" class=\\"col-lg-2 o_light_label\\"/>\\n                                        <field name=\\"pos_receipt_header\\" placeholder=\\"por ejemplo, dirección de la empresa, sitio web\\"/>\\n                                    </div>\\n                                    <div>\\n                                        <label string=\\"Pie de página\\" for=\\"pos_receipt_footer\\" class=\\"col-lg-2 o_light_label\\"/>\\n                                        <field name=\\"pos_receipt_footer\\" placeholder=\\"por ejemplo, política de devoluciones, ¡gracias por comprar con nosotros!\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"auto_printing\\" help=\\"Imprimir recibos automáticamente una vez registrado el pago\\">\\n                                <field name=\\"pos_iface_print_auto\\"/>\\n                                <div class=\\"content-group mt16\\" invisible=\\"not pos_iface_print_auto or not pos_is_posbox and not pos_other_devices\\">\\n                                    <div>\\n                                        <field name=\\"pos_iface_print_skip_screen\\" class=\\"oe_inline\\"/><span class=\\"oe_inline\\"><b>Omitir la pantalla de vista previa</b></span>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting help=\\"Imprimir un código QR en el recibo para permitir que el usuario solicite la factura de una orden con facilidad.\\">\\n                                <field name=\\"point_of_sale_use_ticket_qr_code\\"/>\\n                            </setting>\\n                            <setting help=\\"Agregar un código de 5 dígitos en el recibo con el que el usuario pueda solicitar una factura desde el portal.\\">\\n                                <field name=\\"point_of_sale_ticket_unique_code\\"/>\\n                            </setting>\\n                            <setting id=\\"order_reference\\" groups=\\"base.group_no_one\\" string=\\"Referencia de la orden\\" help=\\"Creación de las referencias de su orden\\">\\n                                <field name=\\"pos_sequence_id\\" readonly=\\"1\\"/>\\n                            </setting>\\n                        </block>\\n\\n                        <block title=\\"Terminales de pago\\" help=\\"Estos ajustes son comunes en todos los PdV. \\" id=\\"pos_payment_terminals_section\\">\\n                            <setting id=\\"adyen_payment_terminal_setting\\" title=\\"Adyen procesa las transacciones. Establezca sus credenciales de Adyen en el método de pago relacionado.\\" string=\\"Adyen\\" help=\\"Aceptar pagos con una terminal de pago Adyen\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/adyen.html\\">\\n                                <field name=\\"module_pos_adyen\\"/>\\n                            </setting>\\n                            <setting id=\\"stripe_payment_terminal_setting\\" title=\\"Stripe procesa las transacciones. Establezca sus credenciales de Stripe en el método de pago relacionado.\\" string=\\"Stripe\\" help=\\"Aceptar pagos con una terminal de pago Stripe\\">\\n                                <field name=\\"module_pos_stripe\\"/>\\n                            </setting>\\n                            <setting id=\\"vantiv_payment_terminal_setting\\" title=\\"Vantiv procesa las transacciones. Establezca sus credenciales de Vantiv en el método de pago relacionado.\\" string=\\"Vantiv (EE. UU. y Canadá)\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/vantiv.html\\" help=\\"Aceptar pagos con un terminal de pago Vantiv\\">\\n                                <field name=\\"module_pos_mercury\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not module_pos_mercury\\">\\n                                    <div class=\\"mt16\\" id=\\"btn_use_pos_mercury\\">\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting title=\\"Six procesa las transacciones. Establezca la dirección IP de la terminal en el método de pago relacionado.\\" string=\\"Six\\" documentation=\\"/applications/sales/point_of_sale/payment_methods/terminals/six.html\\" help=\\"Aceptar pagos con una terminal de pago SIX\\">\\n                                <field name=\\"module_pos_six\\"/>\\n                            </setting>\\n                            <setting title=\\"Paytm procesa las transacciones. Establezca sus credenciales de Paytm en el método de pago relacionado.\\" string=\\"Paytm\\" help=\\"Aceptar pagos con una terminal de pago Paytm\\">\\n                                <field name=\\"module_pos_paytm\\"/>\\n                            </setting>\\n                        </block>\\n\\n                        <block title=\\"Dispositivos conectados\\" id=\\"pos_connected_devices_section\\">\\n                            <setting id=\\"pos_other_devices\\" string=\\"Impresora ePos\\" help=\\"Conectar un dispositivo a su PdV sin una caja IoT\\">\\n                                <field name=\\"pos_other_devices\\"/>\\n                            </setting>\\n                            <setting id=\\"customer_display\\" string=\\"Pantalla del cliente\\" help=\\"Mostrar el proceso pago a los clientes a en una segunda pantalla\\">\\n                                <field name=\\"pos_iface_customer_facing_display_local\\"/>\\n                                <div invisible=\\"not pos_iface_customer_facing_display_local\\">\\n                                    <label for=\\"pos_iface_customer_facing_display_background_image_1920\\"/>\\n                                    <field name=\\"pos_iface_customer_facing_display_background_image_1920\\" widget=\\"image\\" style=\\"width: max(min(min(30vw, 30vh), 100%), 10rem); display: block; margin-top: .3rem;\\"/>\\n                                </div>\\n                            </setting>\\n                            <setting string=\\"Caja IoT\\" help=\\"Conectar dispositivos con una caja IoT\\">\\n                                <field name=\\"pos_is_posbox\\"/>\\n                                <div class=\\"content-group pos_iot_config\\" invisible=\\"not pos_is_posbox\\">\\n                                    <div class=\\"row\\">\\n                                        <label string=\\"Dirección IP de la Caja IoT\\" for=\\"pos_proxy_ip\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                        <field name=\\"pos_proxy_ip\\"/>\\n                                    </div>\\n                                    <div class=\\"row iot_barcode_scanner\\">\\n                                        <label string=\\"Lector de código de barras/lector de tarjetas\\" for=\\"pos_iface_scan_via_proxy\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                        <field name=\\"pos_iface_scan_via_proxy\\"/>\\n                                    </div>\\n                                    <div class=\\"row\\">\\n                                        <label string=\\"Báscula electrónica\\" for=\\"pos_iface_electronic_scale\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                        <field name=\\"pos_iface_electronic_scale\\"/>\\n                                    </div>\\n                                    <div class=\\"row\\">\\n                                        <label string=\\"Impresora de recibos\\" for=\\"pos_iface_print_via_proxy\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                        <field name=\\"pos_iface_print_via_proxy\\"/>\\n                                    </div>\\n                                    <div class=\\"row\\" invisible=\\"not pos_iface_print_via_proxy\\">\\n                                        <label string=\\"Caja registradora\\" for=\\"pos_iface_cashdrawer\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                        <field name=\\"pos_iface_cashdrawer\\"/>\\n                                    </div>\\n                                    <div class=\\"row\\">\\n                                        <label string=\\"Pantalla del cliente\\" for=\\"pos_iface_customer_facing_display_via_proxy\\" class=\\"col-lg-4 o_light_label\\"/>\\n                                        <field name=\\"pos_iface_customer_facing_display_via_proxy\\"/>\\n                                        <div invisible=\\"not pos_iface_customer_facing_display_via_proxy\\">\\n                                            <label for=\\"pos_iface_customer_facing_display_background_image_1920\\"/>\\n                                            <field name=\\"pos_iface_customer_facing_display_background_image_1920\\" widget=\\"image\\" style=\\"width: max(min(min(30vw, 30vh), 100%), 10rem); display: block; margin-top: .3rem;\\"/>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting string=\\"Impresoras de preparación\\" help=\\"Imprimir las comandas en la cocina, en el bar, etc.\\" id=\\"is_order_printer\\">\\n                                <field name=\\"pos_is_order_printer\\"/>\\n                                <div class=\\"content-group\\" invisible=\\"not pos_is_order_printer\\">\\n                                    <div class=\\"mt16\\">\\n                                        <label string=\\"Impresoras\\" for=\\"pos_printer_ids\\" class=\\"o_light_label\\"/>\\n                                        <field name=\\"pos_printer_ids\\" widget=\\"many2many_tags\\"/>\\n                                    </div>\\n                                    <div>\\n                                        <button name=\\"502\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Impresoras\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting string=\\"Pantalla de preparación\\" help=\\"Mostrar órdenes en la pantalla de preparación\\" id=\\"preparation_display\\">\\n                                <field name=\\"module_pos_preparation_display\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                        </block>\\n\\n                        <block title=\\"Inventario\\" id=\\"pos_inventory_section\\">\\n                            <setting title=\\"Los tipos de operación aparecen en el tablero de Inventario.\\" string=\\"Tipo de operación\\" help=\\"Se utiliza para registrar la recolección de productos. Los productos se consumen de su ubicación de origen predeterminada.\\">\\n                                <field name=\\"pos_picking_type_id\\" domain=\\"[('company_id', '=', company_id)]\\" required=\\"pos_config_id\\"/>\\n                            </setting>\\n                            <setting string=\\"Permitir enviar después\\" help=\\"Vende productos y entrégalos después.\\">\\n                                <field name=\\"pos_ship_later\\"/>\\n                                <div class=\\"mt16\\" invisible=\\"not pos_ship_later\\">\\n                                    <div>\\n                                        <label for=\\"pos_warehouse_id\\" string=\\"Almacén\\" class=\\"fw-normal\\"/>\\n                                        <field name=\\"pos_warehouse_id\\" required=\\"pos_ship_later\\"/>\\n                                    </div>\\n                                    <div groups=\\"stock.group_adv_location\\">\\n                                        <label for=\\"pos_route_id\\" string=\\"Ruta específica\\" class=\\"fw-normal\\"/>\\n                                        <field name=\\"pos_route_id\\"/>\\n                                    </div>\\n                                    <div>\\n                                        <label for=\\"pos_picking_policy\\" class=\\"fw-normal\\"/>\\n                                        <field name=\\"pos_picking_policy\\" required=\\"pos_ship_later\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"barcode_scanner\\">\\n                                <span class=\\"o_form_label\\">Códigos de barras</span>\\n                                <i class=\\"fa fa-info-circle me-1\\" title=\\"Esta configuración es común para todos los PdV.\\" pos-data-toggle=\\"tooltip\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Utilice códigos de barras para escanear productos, tarjetas de clientes, etc.\\n                                </div>\\n                                <div class=\\"content-group mt16 row\\">\\n                                    <label for=\\"barcode_nomenclature_id\\" string=\\"Nomenclatura del código de barras\\" class=\\"col-lg-3 o_light_label\\"/>\\n                                    <field name=\\"barcode_nomenclature_id\\"/>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"update_quantities_stock_setting\\" groups=\\"base.group_no_one\\" string=\\"Gestión de inventario\\" company_dependent=\\"1\\" help=\\"Actualizar cantidades en existencias.\\">\\n                                <field name=\\"update_stock_quantities\\" colspan=\\"4\\" widget=\\"radio\\"/>\\n                            </setting>\\n                        </block>\\n                    </div>\\n                </app>\\n            </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                <t groups="point_of_sale.group_pos_manager">\n                    <field name="is_kiosk_mode" invisible="1"/>\n                    <field name="pos_selectable_categ_ids" invisible="1"/>\n                    <field name="pos_has_active_session" invisible="1"/>\n                    <field name="pos_allowed_pricelist_ids" invisible="1"/>\n                    <field name="pos_cash_control" invisible="1"/>\n                    <field name="pos_iface_print_via_proxy" invisible="1"/>\n                    <field name="pos_company_has_template" invisible="1"/>\n                    <field name="group_cash_rounding" invisible="1"/>\n                </t>\n\n                <app data-string="Point of sale" string="Point of Sale" name="point_of_sale" groups="point_of_sale.group_pos_manager">\n                    <setting type="header" string="Point of Sale">\n                        <field name="pos_config_id" options="{'no_open': True, 'no_create': True}" title="Settings on this page will apply to this point of sale."/>\n                        <button name="action_pos_config_create_new" type="object" string="+ New Shop" class="btn btn-link"/>\n                    </setting>\n\n                    <div class="o_view_nocontent" invisible="pos_config_id">\n                        <div class="o_nocontent_help">\n                            <p class="o_view_nocontent_empty_folder">No Point of Sale selected</p>\n                            <p>Please create/select a Point of Sale above to show the configuration options.</p>\n                        </div>\n                    </div>\n                    <div class="o_notification_alert alert alert-warning mt-1 mb-0" invisible="not pos_has_active_session" role="alert">\n                        A session is currently opened for this PoS. Some settings can only be changed after the session is closed.\n                        <button class="btn-link" style="padding:0" name="pos_open_ui" type="object" context="{'pos_config_id': pos_config_id}">Click here to close the session</button>\n                    </div>\n                    <div class="o_notification_alert alert alert-warning" invisible="pos_company_has_template" role="alert">\n                        There is no Chart of Accounts configured on the company. Please go to the invoicing settings to install a Chart of Accounts.\n                    </div>\n                    <div invisible="not pos_config_id">\n                        <block title="Restaurant Mode" id="restaurant_section">\n                            <!-- Wrap the warnings in an o_setting_box so that it doesn't show in the search. -->\n                            <setting>\n                                <field name="pos_module_pos_restaurant" readonly="pos_has_active_session"/>\n                                <div class="content-group" id="warning_text_pos_restaurant" invisible="not pos_module_pos_restaurant">\n                                    <div class="text-warning mt16 mb4">\n                                        Save this page and come back here to set up the feature.\n                                    </div>\n                                </div>\n                            </setting>\n                        </block>\n                        <block title="Payment" id="pos_payment_section">\n                            <setting id="payment_methods_new" string="Payment Methods" help="Payment methods available">\n                                <field name="pos_payment_method_ids" colspan="4" widget="many2many_tags" readonly="pos_has_active_session" required="pos_company_has_template" options="{'no_create': True}"/>\n                                <div>\n                                    <button name="489" icon="oi-arrow-right" type="action" string="Payment Methods" class="btn-link"/>\n                                </div>\n                            </setting>\n                            <setting string="Automatically validate order" help="Automatically validates orders paid with a payment terminal.">\n                                <field name="pos_auto_validate_terminal_payment"/>\n                            </setting>\n                            <setting string="Cash Rounding" invisible="is_kiosk_mode" documentation="/applications/sales/point_of_sale/pricing/cash_rounding.html" help="Define the smallest coinage of the currency used to pay by cash">\n                                <field name="pos_cash_rounding" readonly="pos_has_active_session"/>\n                                <div class="content-group mt16" invisible="not pos_cash_rounding">\n                                    <div class="row mt16">\n                                        <label string="Rounding Method" for="pos_rounding_method" class="col-lg-3 o_light_label"/>\n                                        <field name="pos_rounding_method" required="pos_cash_rounding" domain="[('company_id', '=', company_id)]" readonly="pos_has_active_session"/>\n                                    </div>\n                                    <div class="row mt16">\n                                        <div class="col">\n                                            <field name="pos_only_round_cash_method" readonly="pos_has_active_session"/>\n                                            <label string="Only on cash methods" for="pos_only_round_cash_method" class="o_light_label"/>\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class="mt8">\n                                    <button name="271" icon="oi-arrow-right" type="action" string="Cash Roundings" class="btn-link" invisible="not group_cash_rounding"/>\n                                </div>\n                            </setting>\n                            <setting help="Set a maximum difference allowed between the expected and counted money during the closing of the session">\n                                <field name="pos_set_maximum_difference"/>\n                                <div class="content-group mt16" invisible="not pos_set_maximum_difference">\n                                    <label for="pos_amount_authorized_diff" string="Authorized Difference" class="fw-normal"/>\n                                    <field name="pos_amount_authorized_diff"/>\n                                </div>\n                            </setting>\n                            <setting id="iface_tipproduct" title="This product is used as reference on customer receipts." string="Tips" help="Accept customer tips or convert their change to a tip">\n                                <field name="pos_iface_tipproduct" readonly="pos_has_active_session"/>\n                                <div class="content-group" invisible="not pos_iface_tipproduct">\n                                    <div class="mt16" id="tip_product">\n                                        <label string="Tip Product" for="pos_tip_product_id" class="o_light_label"/>\n                                        <field name="pos_tip_product_id"/>\n                                    </div>\n                                </div>\n                            </setting>\n                        </block>\n                        <block title="PoS Interface" id="pos_interface_section">\n                            <div class="o_notification_alert alert alert-warning" invisible="pos_company_has_template" role="alert">\n                                There is no Chart of Accounts configured on the company. Please go to the invoicing settings to install a Chart of Accounts.\n                            </div>\n                            <setting help="Start selling from a default product category">\n                                <field name="pos_start_category"/>\n                                <div class="content-group mt16" invisible="not pos_start_category">\n                                    <field name="pos_iface_start_categ_id" domain="[('id', 'in', pos_selectable_categ_ids)]"/>\n                                </div>\n                            </setting>\n\n                            <setting id="multiple_employee_session" title="Employees can scan their badge or enter a PIN to log in to a PoS session. These credentials are configurable in the *HR Settings* tab of the employee form." string="Multi Employees per Session" help="Allow to log and switch between selected Employees">\n                                <field name="pos_module_pos_hr" readonly="pos_has_active_session"/>\n                                <div class="content-group mt16" invisible="not pos_module_pos_hr">\n                                    <div class="text-warning" id="warning_text_employees">\n                                        Save this page and come back here to set up the feature.\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting help="Pick which product categories are available">\n                                <field name="pos_limit_categories" readonly="pos_has_active_session"/>\n                                <div class="content-group mt16" invisible="not pos_limit_categories">\n                                    <field name="pos_iface_available_categ_ids" widget="many2many_tags" readonly="pos_has_active_session"/>\n                                </div>\n                                <div class="content-group mt16" invisible="not pos_limit_categories">\n                                    <button name="483" icon="oi-arrow-right" type="action" string="PoS Product Categories" class="btn-link"/>\n                                </div>\n                            </setting>\n                            <setting invisible="is_kiosk_mode" help="Improve navigation for imprecise industrial touchscreens">\n                                <field name="pos_iface_big_scrollbars"/>\n                            </setting>\n                            <setting id="margin_and_cost" string="Margins &amp; Costs" help="Show margins &amp; costs on product information">\n                                <field name="pos_is_margins_costs_accessible_to_every_user"/>\n                            </setting>\n                            <setting string="Share Open Orders" help="Allow to access each other's active orders" id="is_order_shared" invisible="pos_module_pos_restaurant or is_kiosk_mode">\n                                <div class="content-group">\n                                    <div class="row mt16">\n                                        <label string="Trusted POS" for="pos_trusted_config_ids" class="col-lg-3 o_light_label"/>\n                                        <field name="pos_trusted_config_ids" widget="many2many_tags" options="{'no_create':'true'}" placeholder="Select PoS to start sharing orders"/>\n                                    </div>\n                                    <div>\n                                        <button name="492" icon="oi-arrow-right" type="action" string="Point of Sales" class="btn-link"/>\n                                    </div>\n                                </div>\n                            </setting>\n                        </block>\n                        <block title="Accounting" id="pos_accounting_section">\n                            <setting id="default_sales_tax_setting" title="This tax is applied to any new product created in the catalog.">\n                                <label string="Default Sales Tax" for="sale_tax_id"/>\n                                <i class="fa fa-info-circle me-1" title="This setting is common to all PoS." pos-data-toggle="tooltip"/>\n                                <div class="text-muted">\n                                    Default sales tax for products\n                                </div>\n                                <div class="content-group mt16">\n                                    <field name="sale_tax_id" colspan="4" nolabel="1" domain="[('type_tax_use', 'in', ('sale', 'all'))]"/>\n                                </div>\n                                <div class="mt8">\n                                    <button name="260" icon="oi-arrow-right" type="action" string="Taxes" class="btn-link"/>\n                                </div>\n                            </setting>\n                            <setting groups="account.group_account_readonly">\n                                <label string="Default Temporary Account" for="account_default_pos_receivable_account_id"/>\n                                <i class="fa fa-info-circle me-1" title="This setting is common to all PoS." pos-data-toggle="tooltip"/>\n                                <div class="text-muted">\n                                    Intermediary account used for unidentified customers.\n                                </div>\n                                <field name="account_default_pos_receivable_account_id" colspan="4" nolabel="1" domain="[('reconcile', '=', True), ('account_type', '=', 'asset_receivable')]"/>\n                            </setting>\n                            <setting id="flexible_taxes" title="Choose a specific fiscal position at the order depending on the kind of customer (tax exempt, onsite vs. takeaway, etc.)." string="Flexible Taxes" help="Use fiscal positions to get different taxes by order">\n                                <field name="pos_tax_regime_selection"/>\n                                <div class="content-group mt16" invisible="not pos_tax_regime_selection">\n                                    <div class="row">\n                                        <label string="Default" for="pos_default_fiscal_position_id" class="col-lg-3 o_light_label"/>\n                                        <field name="pos_default_fiscal_position_id"/>\n                                    </div>\n                                    <div class="row">\n                                        <label string="Allowed" for="pos_fiscal_position_ids" class="col-lg-3 o_light_label"/>\n                                        <field name="pos_fiscal_position_ids" widget="many2many_tags" options="{'no_create': True}"/>\n                                    </div>\n                                    <div>\n                                        <button name="275" icon="oi-arrow-right" type="action" string="Fiscal Positions" class="btn-link"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting string="Default Journals" id="pos_default_journals" help="Default journals for orders and invoices">\n                                <div class="content-group mt16">\n                                    <div class="row" title="Whenever you close a session, one entry is generated in the following accounting journal for all the orders not invoiced. Invoices are recorded in accounting separately.">\n                                        <label string="Orders" for="pos_journal_id" class="col-lg-3 o_light_label" options="{'no_open': True, 'no_create': True}"/>\n                                        <field name="pos_journal_id" domain="[('company_id', '=', company_id), ('type', 'in', ('general', 'sale'))]" context="{'default_company_id': company_id, 'default_type': 'general'}" required="pos_company_has_template"/>\n                                    </div>\n                                    <div class="row">\n                                        <label string="Invoices" for="pos_invoice_journal_id" class="col-lg-3 o_light_label"/>\n                                        <field name="pos_invoice_journal_id" domain="[('company_id', '=', company_id), ('type', '=', 'sale')]" required="pos_company_has_template" context="{'default_company_id': company_id, 'default_type': 'sale'}"/>\n                                    </div>\n                                </div>\n                            </setting>\n                        </block>\n\n                        <block title="Pricing" id="pos_pricing_section">\n                            <setting id="multiple_prices_setting" string="Flexible Pricelists" help="Set multiple prices per product, automated discounts, etc.">\n                                <field name="pos_use_pricelist" readonly="pos_has_active_session"/>\n                                <div class="content-group" invisible="not pos_use_pricelist">\n                                    <div class="mt16">\n                                        <field name="group_sale_pricelist" invisible="1"/>\n                                        <field name="product_pricelist_setting" widget="radio" class="o_light_label"/>\n                                    </div>\n                                    <div class="row mt16">\n                                        <label string="Available" for="pos_available_pricelist_ids" class="col-lg-3 o_light_label"/>\n                                        <field name="pos_available_pricelist_ids" widget="many2many_tags" domain="['|',('company_id', '=', company_id),('company_id', '=', False)]" readonly="pos_has_active_session"/>\n                                    </div>\n                                    <div class="row mt16">\n                                        <label string="Default" for="pos_pricelist_id" class="col-lg-3 o_light_label"/>\n                                        <field name="pos_pricelist_id" domain="[('id', 'in', pos_allowed_pricelist_ids)]" options="{'no_create': True}"/>\n                                    </div>\n                                    <div class="mt8">\n                                        <button name="170" icon="oi-arrow-right" type="action" string="Pricelists" groups="product.group_product_pricelist" class="btn-link"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="price_control" class="price_control" title="Only users with Manager access rights for PoS app can modify the product prices on orders." string="Price Control" help="Restrict price modification to managers">\n                                <field name="pos_restrict_price_control"/>\n                            </setting>\n                            <setting id="product_prices" string="Product Prices" help="Product prices on receipts">\n                                <field name="pos_iface_tax_included" class="o_light_label" widget="radio"/>\n                                <div class="content-group">\n                                    <a invisible="pos_iface_tax_included != 'total'" href="https://www.odoo.com/documentation/17.0/applications/finance/accounting/taxation/taxes/B2B_B2C.html" target="_blank" class="oe-link"><i class="oi oi-fw oi-arrow-right"/>How to manage tax-included prices</a>\n                                </div>\n                            </setting>\n                            <setting id="manual_discount" help="Allow cashiers to set a discount per line">\n                                <field name="pos_manual_discount"/>\n                            </setting>\n                            <setting help="Adds a button to set a global discount">\n                                <field name="pos_module_pos_discount" readonly="pos_has_active_session"/>\n                                <div class="content-group mt16" invisible="not pos_module_pos_discount">\n                                    <div class="text-warning mb4" id="warning_text_pos_discount">\n                                        Save this page and come back here to set up the feature.\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="pos-loyalty" title="Boost your sales with multiple kinds of programs: Coupons, Promotions, Gift Card, Loyalty. Specific conditions can be set (products, customers, minimum purchase amount, period). Rewards can be discounts (% or amount) or free products." string="Promotions, Coupons, Gift Card &amp; Loyalty Program" help="Manage promotion that will grant customers discounts or gifts">\n                                <field name="module_loyalty"/>\n                            </setting>\n                        </block>\n\n                        <block title="Bills &amp; Receipts" id="pos_bills_and_receipts_section">\n                            <setting help="Add a custom message to header and footer">\n                                <field name="pos_is_header_or_footer"/>\n                                <div class="content-group mt16" invisible="not pos_is_header_or_footer">\n                                    <div>\n                                        <label string="Header" for="pos_receipt_header" class="col-lg-2 o_light_label"/>\n                                        <field name="pos_receipt_header" placeholder="e.g. Company Address, Website"/>\n                                    </div>\n                                    <div>\n                                        <label string="Footer" for="pos_receipt_footer" class="col-lg-2 o_light_label"/>\n                                        <field name="pos_receipt_footer" placeholder="e.g. Return Policy, Thanks for shopping with us!"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="auto_printing" help="Print receipts automatically once the payment is registered">\n                                <field name="pos_iface_print_auto"/>\n                                <div class="content-group mt16" invisible="not pos_iface_print_auto or not pos_is_posbox and not pos_other_devices">\n                                    <div>\n                                        <field name="pos_iface_print_skip_screen" class="oe_inline"/><span class="oe_inline"><b>Skip Preview Screen</b></span>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting help="Print a QR code on the receipt to allow the user to easily request the invoice for an order.">\n                                <field name="point_of_sale_use_ticket_qr_code"/>\n                            </setting>\n                            <setting help="Add a 5-digit code on the receipt to allow the user to request the invoice for an order on the portal.">\n                                <field name="point_of_sale_ticket_unique_code"/>\n                            </setting>\n                            <setting id="order_reference" groups="base.group_no_one" string="Order Reference" help="Generation of your order references">\n                                <field name="pos_sequence_id" readonly="1"/>\n                            </setting>\n                        </block>\n\n                        <block title="Payment Terminals" help="Those settings are common to all PoS." id="pos_payment_terminals_section">\n                            <setting id="adyen_payment_terminal_setting" title="The transactions are processed by Adyen. Set your Adyen credentials on the related payment method." string="Adyen" help="Accept payments with an Adyen payment terminal" documentation="/applications/sales/point_of_sale/payment_methods/terminals/adyen.html">\n                                <field name="module_pos_adyen"/>\n                            </setting>\n                            <setting id="stripe_payment_terminal_setting" title="The transactions are processed by Stripe. Set your Stripe credentials on the related payment method." string="Stripe" help="Accept payments with a Stripe payment terminal">\n                                <field name="module_pos_stripe"/>\n                            </setting>\n                            <setting id="vantiv_payment_terminal_setting" title="The transactions are processed by Vantiv. Set your Vantiv credentials on the related payment method." string="Vantiv (US &amp; Canada)" documentation="/applications/sales/point_of_sale/payment_methods/terminals/vantiv.html" help="Accept payments with a Vantiv payment terminal">\n                                <field name="module_pos_mercury"/>\n                                <div class="content-group" invisible="not module_pos_mercury">\n                                    <div class="mt16" id="btn_use_pos_mercury">\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting title="The transactions are processed by Six. Set the IP address of the terminal on the related payment method." string="Six" documentation="/applications/sales/point_of_sale/payment_methods/terminals/six.html" help="Accept payments with a Six payment terminal">\n                                <field name="module_pos_six"/>\n                            </setting>\n                            <setting title="The transactions are processed by PayTM. Set your PayTM credentials on the related payment method." string="PayTM" help="Accept payments with a PayTM payment terminal">\n                                <field name="module_pos_paytm"/>\n                            </setting>\n                        </block>\n\n                        <block title="Connected Devices" id="pos_connected_devices_section">\n                            <setting id="pos_other_devices" string="ePos Printer" help="Connect device to your PoS without an IoT Box">\n                                <field name="pos_other_devices"/>\n                            </setting>\n                            <setting id="customer_display" string="Customer Display" help="Show checkout to customers through a second display">\n                                <field name="pos_iface_customer_facing_display_local"/>\n                                <div invisible="not pos_iface_customer_facing_display_local">\n                                    <label for="pos_iface_customer_facing_display_background_image_1920"/>\n                                    <field name="pos_iface_customer_facing_display_background_image_1920" widget="image" style="width: max(min(min(30vw, 30vh), 100%), 10rem); display: block; margin-top: .3rem;"/>\n                                </div>\n                            </setting>\n                            <setting string="IoT Box" help="Connect devices using an IoT Box">\n                                <field name="pos_is_posbox"/>\n                                <div class="content-group pos_iot_config" invisible="not pos_is_posbox">\n                                    <div class="row">\n                                        <label string="IoT Box IP Address" for="pos_proxy_ip" class="col-lg-4 o_light_label"/>\n                                        <field name="pos_proxy_ip"/>\n                                    </div>\n                                    <div class="row iot_barcode_scanner">\n                                        <label string="Barcode Scanner/Card Reader" for="pos_iface_scan_via_proxy" class="col-lg-4 o_light_label"/>\n                                        <field name="pos_iface_scan_via_proxy"/>\n                                    </div>\n                                    <div class="row">\n                                        <label string="Electronic Scale" for="pos_iface_electronic_scale" class="col-lg-4 o_light_label"/>\n                                        <field name="pos_iface_electronic_scale"/>\n                                    </div>\n                                    <div class="row">\n                                        <label string="Receipt Printer" for="pos_iface_print_via_proxy" class="col-lg-4 o_light_label"/>\n                                        <field name="pos_iface_print_via_proxy"/>\n                                    </div>\n                                    <div class="row" invisible="not pos_iface_print_via_proxy">\n                                        <label string="Cashdrawer" for="pos_iface_cashdrawer" class="col-lg-4 o_light_label"/>\n                                        <field name="pos_iface_cashdrawer"/>\n                                    </div>\n                                    <div class="row">\n                                        <label string="Customer Display" for="pos_iface_customer_facing_display_via_proxy" class="col-lg-4 o_light_label"/>\n                                        <field name="pos_iface_customer_facing_display_via_proxy"/>\n                                        <div invisible="not pos_iface_customer_facing_display_via_proxy">\n                                            <label for="pos_iface_customer_facing_display_background_image_1920"/>\n                                            <field name="pos_iface_customer_facing_display_background_image_1920" widget="image" style="width: max(min(min(30vw, 30vh), 100%), 10rem); display: block; margin-top: .3rem;"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting string="Preparation Printers" help="Print orders at the kitchen, at the bar, etc." id="is_order_printer">\n                                <field name="pos_is_order_printer"/>\n                                <div class="content-group" invisible="not pos_is_order_printer">\n                                    <div class="mt16">\n                                        <label string="Printers" for="pos_printer_ids" class="o_light_label"/>\n                                        <field name="pos_printer_ids" widget="many2many_tags"/>\n                                    </div>\n                                    <div>\n                                        <button name="502" icon="oi-arrow-right" type="action" string="Printers" class="btn-link"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting string="Preparation Display" help="Display orders on the preparation display" id="preparation_display">\n                                <field name="module_pos_preparation_display" widget="upgrade_boolean"/>\n                            </setting>\n                        </block>\n\n                        <block title="Inventory" id="pos_inventory_section">\n                            <setting title="Operation types show up in the Inventory dashboard." string="Operation Type" help="Used to record product pickings. Products are consumed from its default source location.">\n                                <field name="pos_picking_type_id" domain="[('company_id', '=', company_id)]" required="pos_config_id"/>\n                            </setting>\n                            <setting string="Allow Ship Later" help="Sell products and deliver them later.">\n                                <field name="pos_ship_later"/>\n                                <div class="mt16" invisible="not pos_ship_later">\n                                    <div>\n                                        <label for="pos_warehouse_id" string="Warehouse" class="fw-normal"/>\n                                        <field name="pos_warehouse_id" required="pos_ship_later"/>\n                                    </div>\n                                    <div groups="stock.group_adv_location">\n                                        <label for="pos_route_id" string="Specific route" class="fw-normal"/>\n                                        <field name="pos_route_id"/>\n                                    </div>\n                                    <div>\n                                        <label for="pos_picking_policy" class="fw-normal"/>\n                                        <field name="pos_picking_policy" required="pos_ship_later"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="barcode_scanner">\n                                <span class="o_form_label">Barcodes</span>\n                                <i class="fa fa-info-circle me-1" title="This setting is common to all PoS." pos-data-toggle="tooltip"/>\n                                <div class="text-muted">\n                                    Use barcodes to scan products, customer cards, etc.\n                                </div>\n                                <div class="content-group mt16 row">\n                                    <label for="barcode_nomenclature_id" string="Barcode Nomenclature" class="col-lg-3 o_light_label"/>\n                                    <field name="barcode_nomenclature_id"/>\n                                </div>\n                            </setting>\n                            <setting id="update_quantities_stock_setting" groups="base.group_no_one" string="Inventory Management" company_dependent="1" help="Update quantities in stock">\n                                <field name="update_stock_quantities" colspan="4" widget="radio"/>\n                            </setting>\n                        </block>\n                    </div>\n                </app>\n            </xpath>\n        	f	t	2026-10-30 14:36:16.80785	2026-10-30 14:36:16.80785	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	\N
1367	16	\N	1	1	ticket_validation_screen	\N	point_of_sale.ticket_validation_screen	qweb	point_of_sale/views/pos_ticket_view.xml	primary	{"en_US": "<t t-name=\\"point_of_sale.ticket_validation_screen\\">\\n        <t t-call=\\"portal.portal_layout\\">\\n            <t t-set=\\"no_breadcrumbs\\" t-value=\\"True\\"/>\\n            <div class=\\"row justify-content-md-center\\">\\n                <form method=\\"post\\" target=\\"_self\\" t-att-action=\\"'/pos/ticket/validate'\\" onsubmit=\\"$('button:submit').attr('disabled', 'disabled')\\">\\n                    <input type=\\"hidden\\" name=\\"csrf_token\\" t-att-value=\\"request.csrf_token()\\"/>\\n                    <input type=\\"hidden\\" name=\\"access_token\\" t-att-value=\\"access_token\\"/>\\n                    <div class=\\"col-12 col-md-6 mt-4 offset-md-3\\">\\n                        <div class=\\"row\\">\\n                            <h2>Invoicing confirmation</h2>\\n                            <hr class=\\"mt-1 mb-0\\"/>\\n                        </div>\\n                        <div class=\\"row\\">\\n                            <h4 class=\\"mt-2\\"><t t-out=\\"pos_order.pos_reference\\"/></h4>\\n                        </div>\\n                        <div class=\\"row\\">\\n                            <div class=\\"col-12 fw-bold\\">\\n                                Products:\\n                            </div>\\n                        </div>\\n                        <div class=\\"row\\">\\n                            <div class=\\"col-12\\">\\n                                <ul>\\n                                    <t t-foreach=\\"pos_order.lines\\" t-as=\\"order_line\\">\\n                                        <li><t t-out=\\"int(order_line.qty)\\"/> <t t-out=\\"order_line.full_product_name\\"/> for <t t-out=\\"format_amount(env, order_line.price_subtotal_incl, order_line.currency_id)\\"/></li>\\n                                    </t>\\n                                </ul>\\n            