1541	16	1540	1	1	Show Odoo Information	\N	website.show_website_info	qweb	website/views/website_templates.xml	extension	{"en_US": "<data inherit_id=\\"website.website_info\\" name=\\"Show Odoo Information\\">\\n    <xpath expr=\\"//div[@id='wrap']\\" position=\\"inside\\">\\n        <div class=\\"oe_structure\\">\\n            <section class=\\"container\\">\\n                <h1><t t-esc=\\"res_company.name\\"/>\\n                    <small groups=\\"base.group_no_one\\">Odoo Version <t t-out=\\"version.get('server_version')\\"/></small>\\n                </h1>\\n                <p>\\n                    Information about the <t t-esc=\\"res_company.name\\"/> instance of Odoo, the <a target=\\"_blank\\" href=\\"https://www.odoo.com\\">Open Source ERP</a>.\\n                </p>\\n\\n                <div class=\\"alert alert-warning alert-dismissable mt16\\" groups=\\"website.group_website_restricted_editor\\" role=\\"status\\">\\n                   <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"Close\\"/>\\n                   <p>\\n                     Note: To hide this page, uncheck it from the Customize tab in edit mode.\\n                   </p>\\n                </div>\\n                <h2>Installed Applications</h2>\\n                <dl class=\\"dl-horizontal\\" t-foreach=\\"apps\\" t-as=\\"app\\">\\n                    <dt>\\n                        <a t-att-href=\\"app.website\\" t-if=\\"app.website\\">\\n                            <t t-out=\\"app.shortdesc\\"/>\\n                        </a>\\n                        <span t-out=\\"app.shortdesc\\" t-if=\\"not app.website\\"/>\\n                    </dt>\\n                    <dd>\\n                        <span t-out=\\"app.summary\\"/>\\n                    </dd><dd class=\\"text-muted\\" groups=\\"base.group_no_one\\">\\n                        Technical name: <span t-field=\\"app.name\\"/>, author: <span t-field=\\"app.author\\"/>\\n                    </dd>\\n                </dl>\\n\\n                <div t-if=\\"l10n\\">\\n                    <h2 class=\\"mt32\\">Installed Localizations / Account Charts</h2>\\n                    <dl class=\\"dl-horizontal\\" t-foreach=\\"l10n\\" t-as=\\"app\\">\\n                        <dt>\\n                            <a t-att-href=\\"app.website or 'https://www.odoo.com/app/accounting/' + app.name\\">\\n                                <t t-out=\\"app.shortdesc\\"/>\\n                            </a>\\n                        </dt>\\n                        <dd>\\n                            <span t-out=\\"app.summary\\"/>\\n                        </dd><dd class=\\"text-muted\\" groups=\\"base.group_no_one\\">\\n                            Technical name: <span t-field=\\"app.name\\"/>, author: <span t-field=\\"app.author\\"/>\\n                        </dd>\\n                    </dl>\\n                </div>\\n            </section>\\n        </div>\\n    </xpath>\\n</data>", "es_AR": "<data inherit_id=\\"website.website_info\\" name=\\"Show Odoo Information\\">\\n    <xpath expr=\\"//div[@id='wrap']\\" position=\\"inside\\">\\n        <div class=\\"oe_structure\\">\\n            <section class=\\"container\\">\\n                <h1><t t-esc=\\"res_company.name\\"/>\\n                    <small groups=\\"base.group_no_one\\">Versión de Odoo <t t-out=\\"version.get('server_version')\\"/></small>\\n                </h1>\\n                <p>\\n                    Información sobre <t t-esc=\\"res_company.name\\"/> instancia de Odoo, el <a target=\\"_blank\\" href=\\"https://www.odoo.com\\">ERP de código abierto</a>.\\n                </p>\\n\\n                <div class=\\"alert alert-warning alert-dismissable mt16\\" groups=\\"website.group_website_restricted_editor\\" role=\\"status\\">\\n                   <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"Cerrar\\"/>\\n                   <p>\\n                     Nota: para ocultar esta página, desmárquela en la pestaña \\"personalizar\\" en el modo de edición.\\n                   </p>\\n                </div>\\n                <h2>Aplicaciones instaladas</h2>\\n                <dl class=\\"dl-horizontal\\" t-foreach=\\"apps\\" t-as=\\"app\\">\\n                    <dt>\\n                        <a t-att-href=\\"app.website\\" t-if=\\"app.website\\">\\n                            <t t-out=\\"app.shortdesc\\"/>\\n                        </a>\\n                        <span t-out=\\"app.shortdesc\\" t-if=\\"not app.website\\"/>\\n                    </dt>\\n                    <dd>\\n                        <span t-out=\\"app.summary\\"/>\\n                    </dd><dd class=\\"text-muted\\" groups=\\"base.group_no_one\\">\\n                        Nombre técnico: <span t-field=\\"app.name\\"/>, autor: <span t-field=\\"app.author\\"/>\\n                    </dd>\\n                </dl>\\n\\n                <div t-if=\\"l10n\\">\\n                    <h2 class=\\"mt32\\">Localizaciones/planes de cuentas instalados</h2>\\n                    <dl class=\\"dl-horizontal\\" t-foreach=\\"l10n\\" t-as=\\"app\\">\\n                        <dt>\\n                            <a t-att-href=\\"app.website or 'https://www.odoo.com/app/accounting/' + app.name\\">\\n                                <t t-out=\\"app.shortdesc\\"/>\\n                            </a>\\n                        </dt>\\n                        <dd>\\n                            <span t-out=\\"app.summary\\"/>\\n                        </dd><dd class=\\"text-muted\\" groups=\\"base.group_no_one\\">\\n                            Nombre técnico: <span t-field=\\"app.name\\"/>, autor: <span t-field=\\"app.author\\"/>\\n                        </dd>\\n                    </dl>\\n                </div>\\n            </section>\\n        </div>\\n    </xpath>\\n</data>"}	<?xml version="1.0"?>\n<data inherit_id="website.website_info" name="Show Odoo Information">\n    <xpath expr="//div[@id='wrap']" position="inside">\n        <div class="oe_structure">\n            <section class="container">\n                <h1><t t-esc="res_company.name"/>\n                    <small groups="base.group_no_one">Odoo Version <t t-out="version.get('server_version')"/></small>\n                </h1>\n                <p>\n                    Information about the <t t-esc="res_company.name"/> instance of Odoo, the <a target="_blank" href="https://www.odoo.com">Open Source ERP</a>.\n                </p>\n\n                <div class="alert alert-warning alert-dismissable mt16" groups="website.group_website_restricted_editor" role="status">\n                   <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"/>\n                   <p>\n                     Note: To hide this page, uncheck it from the Customize tab in edit mode.\n                   </p>\n                </div>\n                <h2>Installed Applications</h2>\n                <dl class="dl-horizontal" t-foreach="apps" t-as="app">\n                    <dt>\n                        <a t-att-href="app.website" t-if="app.website">\n                            <t t-out="app.shortdesc"/>\n                        </a>\n                        <span t-out="app.shortdesc" t-if="not app.website"/>\n                    </dt>\n                    <dd>\n                        <span t-out="app.summary"/>\n                    </dd><dd class="text-muted" groups="base.group_no_one">\n                        Technical name: <span t-field="app.name"/>, author: <span t-field="app.author"/>\n                    </dd>\n                </dl>\n\n                <div t-if="l10n">\n                    <h2 class="mt32">Installed Localizations / Account Charts</h2>\n                    <dl class="dl-horizontal" t-foreach="l10n" t-as="app">\n                        <dt>\n                            <a t-att-href="app.website or 'https://www.odoo.com/app/accounting/' + app.name">\n                        