st_hybrid\\">\\n    <t t-call=\\"website.layout\\">\\n        <div id=\\"wrap\\">\\n            <div class=\\"container pt24 pb24\\">\\n                <t t-call=\\"website.website_search_box_input\\">\\n                    <t t-set=\\"_classes\\" t-valuef=\\"mt8\\"/>\\n                    <t t-set=\\"search_type\\" t-valuef=\\"all\\"/>\\n                    <t t-set=\\"action\\" t-valuef=\\"/website/search\\"/>\\n                </t>\\n                <div class=\\"mt24 h3\\">Resultados de la búsqueda</div>\\n                <t t-if=\\"not results\\">\\n                    <div class=\\"alert alert-warning mt8\\" role=\\"alert\\">\\n                        <t t-if=\\"search\\">\\n                            Su búsqueda \\"<t t-esc=\\"search\\"/>\\" no coincide con nada.\\n                        </t>\\n                        <t t-else=\\"\\">\\n                            Especifique un término de búsqueda.\\n                        </t>\\n                    </div>\\n                </t>\\n                <t t-elif=\\"fuzzy_search\\">\\n                    <div class=\\"alert alert-warning mt8\\" role=\\"alert\\">\\n                        Su búsqueda \\"<t t-esc=\\"search\\"/>\\" no coincidió con nada.\\n                        Se muestran los resultados para \\"<t t-esc=\\"fuzzy_search\\"/>'.\\n                    </div>\\n                </t>\\n                <div t-if=\\"results\\" class=\\"table-responsive\\">\\n                    <t t-call=\\"website.one_hybrid\\" t-foreach=\\"results\\" t-as=\\"result\\"/>\\n                </div>\\n                <div t-if=\\"pager\\" class=\\"o_portal_pager d-flex justify-content-center\\">\\n                    <t t-call=\\"website.pager\\"/>\\n                </div>\\n            </div>\\n        </div>\\n    </t>\\n</t>"}	<?xml version="1.0"?>\n<t name="Any Search Results" t-name="website.list_hybrid">\n    <t t-call="website.layout">\n        <div id="wrap">\n            <div class="container pt24 pb24">\n        