lass=\\"o_we_sublevel_2\\" data-select-data-attribute=\\"\\" data-attribute-name=\\"hoverEffectIntensity\\" data-dependencies=\\"hover_effect_zoom_in_opt, hover_effect_zoom_out_opt, hover_effect_mirror_blur_opt, hover_effect_dolly_zoom_opt\\" data-min=\\"1\\" data-max=\\"100\\" data-step=\\"1\\" data-display-range-value=\\"true\\" data-no-preview=\\"true\\"/>\\n            <we-colorpicker string=\\"Color\\" class=\\"o_we_sublevel_2\\" data-set-hover-effect-color=\\"true\\" data-excluded=\\"theme, common\\" data-dependencies=\\"hover_effect_dolly_zoom_opt, hover_effect_overlay_opt, hover_effect_zoom_in_opt, hover_effect_zoom_out_opt, hover_effect_outline_opt\\" data-no-preview=\\"true\\" data-name=\\"hover_effect_color_opt\\"/>\\n            <we-input string=\\"Stroke Width\\" class=\\"o_we_sublevel_2\\" data-select-data-attribute=\\"\\" data-attribute-name=\\"hoverEffectStrokeWidth\\" data-step=\\"1\\" data-min=\\"1\\" data-unit=\\"px\\" data-dependencies=\\"hover_effect_outline_opt\\" data-no-preview=\\"true\\"/>\\n        </div>\\n    </xpath>\\n\\n    <!-- =================================================================== -->\\n    <!-- Adding website specific snippet options                             -->\\n    <!-- =================================================================== -->\\n\\n    <xpath expr=\\".\\" position=\\"inside\\">\\n\\n    <!-- COLOR, BORDER, SHADOW | .s_three_columns | .s_comparisons -->\\n    <div data-js=\\"Box\\" data-selector=\\".s_three_columns .row &gt; div, .s_comparisons .row &gt; div\\" data-target=\\".card\\">\\n        <we-colorpicker string=\\"Colors\\" data-select-style=\\"true\\" data-css-property=\\"background-color\\" data-color-prefix=\\"bg-\\"/>\\n        <t t-call=\\"website.snippet_options_border_widgets\\">\\n            <t t-set=\\"so_rounded_no_dependencies\\" t-value=\\"True\\"/>\\n        </t>\\n        <t t-call=\\"website.snippet_options_shadow_widgets\\"/>\\n    </div>\\n\\n    <!-- COLOR | .s_cards -->\\n    <div data-selector=\\".s_card, .accordion .card\\">\\n        <we-colorpicker string=\\"Color\\" data-select-style=\\"true\\" data-css-property=\\"background-color\\" data-color-prefix=\\"bg-\\"/>\\n    </div>\\n\\n    <!-- H-ALIGN -->\\n    <div id=\\"so_text_align\\" data-selector=\\".s_share, .s_text_highlight, .s_social_media\\">\\n        <we-button-group string=\\"Alignment\\">\\n            <we-button class=\\"fa fa-fw fa-align-left\\" title=\\"Left\\" data-select-class=\\"text-start\\"/>\\n            <we-button class=\\"fa fa-fw fa-align-center\\" title=\\"Center\\" data-select-class=\\"text-center\\"/>\\n            <we-button class=\\"fa fa-fw fa-align-right\\" title=\\"Right\\" data-select-class=\\"text-end\\"/>\\n        </we-button-group>\\n    </div>\\n\\n    <div data-selector=\\".s_share, .s_social_media\\">\\n        <we-select string=\\"Title Position\\" data-apply-to=\\".s_share_title, .s_social_media_title\\">\\n            <we-button data-select-class=\\"d-block\\">Top</we-button>\\n            <we-button data-select-class=\\"\\">Left</we-button>\\n            <we-button data-select-class=\\"d-none\\">None</we-button>\\n        </we-select>\\n        <we-select string=\\"Layout\\" data-apply-to=\\".fa\\">\\n            <we-button data-select-class=\\"rounded shadow-sm\\">Square</we-button>\\n            <we-button data-select-class=\\"rounded-empty-circle shadow-sm\\">Circle</we-button>\\n            <we-button data-select-class=\\"rounded-circle shadow-sm\\">Disk</we-button>\\n            <we-button data-select-class=\\"fa-stack\\">None</we-button>\\n        </we-select>\\n        <we-select string=\\"Size\\" data-apply-to=\\".fa\\">\\n            <we-button data-select-class=\\"\\">Small</we-button>\\n            <we-button data-select-class=\\"fa-2x\\">Medium</we-button>\\n            <we-button data-select-class=\\"fa-3x\\">Big</we-button>\\n        </we-select>\\n        <!-- Compatibility, keep reverse logical, don't use `icon_color` -->\\n        <we-checkbox string=\\"Color\\" data-select-class=\\"no_icon_color|\\"/>\\n    </div>\\n\\n    <div id=\\"so_width\\" data-selector=\\".s_alert, .s_card, .s_blockquote, .s_text_highlight\\">\\n        <we-select string=\\"Width\\">\\n            <we-button data-select-class=\\"w-25\\">25%</we-button>\\n            <we-button data-select-class=\\"w-50\\">50%</we-button>\\n            <we-button data-select-class=\\"w-75\\">75%</we-button>\\n            <we-button data-select-class=\\"w-100\\" data-name=\\"so_width_100\\">100%</we-button>\\n        </we-select>\\n    </div>\\n\\n    <div id=\\"so_block_align\\" data-selector=\\".s_alert, .s_card, .s_blockquote, .s_text_highlight\\">\\n        <we-button-group string=\\"Alignment\\" data-dependencies=\\"!so_width_100\\">\\n            <we-button class=\\"fa fa-fw fa-align-left\\" title=\\"Left\\" data-select-class=\\"me-auto\\"/>\\n            <we-button class=\\"fa fa-fw fa-align-center\\" title=\\"Center\\" data-select-class=\\"mx-auto\\"/>\\n            <we-button class=\\"fa fa-fw fa-align-right\\" title=\\"Right\\" data-select-class=\\"ms-auto\\"/>\\n        </we-button-group>\\n    </div>\\n\\n    <!-- Carousel | .s_carousel | .s_quotes_carousel -->\\n    <!-- Dedicated colorpicker so that there is not 3 level of\\n         o_colored_level. Use inline-style color for the same reason. -->\\n    <t t-call=\\"website.snippet_options_background_options\\">\\n        <t t-set=\\"selector\\" t-value=\\"'section'\\"/>\\n        <t t-set=\\"target\\" t-value=\\"'&gt; .carousel'\\"/>\\n        <t t-set=\\"with_colors\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_images\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_videos\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_shapes\\" t-value=\\"True\\"/>\\n        <t t-set=\\"css_compatible\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_gradients\\" t-value=\\"True\\"/>\\n    </t>\\n    <div data-js=\\"Carousel\\" data-selector=\\"section\\" data-target=\\"&gt; .carousel\\">\\n        <we-row string=\\"Slide\\">\\n            <we-button data-add-slide=\\"true\\" data-no-preview=\\"true\\" class=\\"o_we_bg_brand_primary\\">Add Slide</we-button>\\n        </we-row>\\n        <we-select string=\\"Style\\">\\n            <we-button data-select-class=\\"s_carousel_default\\">Default</we-button>\\n            <we-button data-select-class=\\"s_carousel_bordered\\">Bordered</we-button>\\n            <we-button data-select-class=\\"s_carousel_boxed\\">Boxed</we-button>\\n            <we-button data-select-class=\\"s_carousel_rounded\\">Rounded</we-button>\\n        </we-select>\\n        <we-select string=\\"Transition\\">\\n            <we-button data-select-class=\\"slide\\">Slide</we-button>\\n            <we-button data-select-class=\\"carousel-fade slide\\">Fade</we-button>\\n            <we-divider/>\\n            <we-button data-select-class=\\"\\">None</we-button>\\n        </we-select>\\n        <we-input string=\\"Speed\\" data-select-data-attribute=\\"0s\\" data-attribute-name=\\"bsInterval\\" data-unit=\\"s\\" data-save-unit=\\"ms\\" data-step=\\"0.1\\"/>\\n    </div>\\n\\n    <div data-js=\\"CarouselItem\\" data-selector=\\".s_carousel .carousel-item, .s_quotes_carousel .carousel-item\\">\\n        <we-button class=\\"fa fa-fw fa-angle-left\\" data-switch-to-slide=\\"left\\" data-no-preview=\\"true\\" title=\\"Move Backward\\"/>\\n        <we-button class=\\"fa fa-fw fa-angle-right me-2\\" data-switch-to-slide=\\"right\\" data-no-preview=\\"true\\" title=\\"Move Forward\\"/>\\n        <we-button class=\\"fa fa-fw fa-plus o_we_bg_success\\" data-add-slide-item=\\"true\\" data-no-preview=\\"true\\" title=\\"Add Slide\\"/>\\n        <we-button class=\\"fa fa-fw fa-minus o_we_bg_danger\\" data-remove-slide=\\"true\\" data-no-preview=\\"true\\" title=\\"Remove Slide\\"/>\\n    </div>\\n\\n    <div data-js=\\"GalleryElement\\" data-selector=\\".s_image_gallery img, .s_carousel .carousel-item\\">\\n        <we-row string=\\"Re-order\\" data-no-preview=\\"true\\">\\n            <we-button class=\\"fa fa-fw fa-angle-double-left\\" title=\\"Move to first\\" data-position=\\"first\\"/>\\n            <we-button class=\\"fa fa-fw fa-angle-left\\" title=\\"Move to previous\\" data-position=\\"prev\\"/>\\n            <we-button class=\\"fa fa-fw fa-angle-right\\" title=\\"Move to next\\" data-position=\\"next\\"/>\\n            <we-button class=\\"fa fa-fw fa-angle-double-right\\" title=\\"Move to last\\" data-position=\\"last\\"/>\\n        </we-row>\\n    </div>\\n    <!-- Accordion -->\\n    <div data-js=\\"collapse\\" data-selector=\\".accordion &gt; .card\\" data-drop-in=\\".accordion:has(&gt; .card)\\"/>\\n\\n    <div data-js=\\"MultipleItems\\" data-selector=\\".s_faq_collapse\\">\\n        <we-row string=\\"Item\\">\\n            <we-button data-add-item=\\"\\" data-item=\\".accordion &gt; .card:last\\" data-select-item=\\"\\" data-no-preview=\\"true\\" class=\\"o_we_bg_brand_primary\\">\\n                Add Item\\n            </we-button>\\n        </we-row>\\n    </div>\\n\\n    <t t-set=\\"so_submit_button_selector\\" t-translation=\\"off\\">\\n        .s_donation_donate_btn, .s_website_form_send\\n    </t>\\n\\n    <!-- Button -->\\n    <div data-js=\\"Button\\" data-selector=\\"a.btn\\" t-att-data-exclude=\\"so_submit_button_selector\\"/>\\n\\n    <!-- Columns only -->\\n    <div data-js=\\"layout_column\\" data-selector=\\"section.s_features_grid, section.s_process_steps\\" data-target=\\"&gt; *:has(&gt; .row), &gt; .s_allow_columns\\">\\n        <t t-call=\\"website.column_count_option\\"/>\\n    </div>\\n\\n    <!-- Grid only -->\\n    <div data-js=\\"layout_column\\" data-selector=\\"section.s_masonry_block\\" data-target=\\"&gt; *:has(&gt; .row)\\">\\n        <t t-call=\\"website.grid_layout_options\\"/>\\n    </div>\\n\\n    <!-- Grid and columns -->\\n    <div data-js=\\"layout_column\\" data-selector=\\"section, section.s_carousel_wrapper .carousel-item\\" data-target=\\"&gt; *:has(&gt; .row), &gt; .s_allow_columns\\" data-exclude=\\".s_masonry_block, .s_features_grid, .s_media_list, .s_showcase, .s_table_of_content, .s_process_steps, .s_image_gallery\\">\\n        <we-row>\\n            <we-button-group string=\\"Layout\\" data-no-preview=\\"true\\">\\n                <we-button data-select-layout=\\"grid\\" data-name=\\"grid_mode\\">Grid</we-button>\\n                <we-button data-select-layout=\\"normal\\" data-name=\\"normal_mode\\">Cols</we-button>\\n            </we-button-group>\\n            <t t-call=\\"website.column_count_option\\">\\n                <t t-set=\\"with_grid\\" t-value=\\"True\\"/>\\n            </t>\\n        </we-row>\\n        <t t-call=\\"website.grid_layout_options\\">\\n            <t t-set=\\"indent\\" t-value=\\"True\\"/>\\n        </t>\\n    </div>\\n\\n    <!--  Vertical Alignment -->\\n    <div id=\\"row_valign_snippet_option\\" data-selector=\\".s_text_image, .s_image_text, .s_three_columns\\" data-target=\\".row\\">\\n        <we-button-group class=\\"o_we_sublevel_1\\" string=\\"Vert. Alignment\\" title=\\"Vertical Alignment\\" data-dependencies=\\"normal_mode\\">\\n            <we-button title=\\"Align Top\\" data-select-class=\\"align-items-start\\" data-img=\\"/website/static/src/img/snippets_options/align_top.svg\\"/>\\n            <we-button title=\\"Align Middle\\" data-select-class=\\"align-items-center\\" data-img=\\"/website/static/src/img/snippets_options/align_middle.svg\\"/>\\n            <we-button title=\\"Align Bottom\\" data-select-class=\\"align-items-end\\" data-img=\\"/website/static/src/img/snippets_options/align_bottom.svg\\"/>\\n            <we-button title=\\"Stretch to Equal Height\\" data-select-class=\\"align-items-stretch\\" data-img=\\"/website/static/src/img/snippets_options/align_stretch.svg\\"/>\\n        </we-button-group>\\n    </div>\\n\\n    <!-- Move snippets around -->\\n    <div data-js=\\"SnippetMove\\" data-selector=\\"section, .accordion &gt; .card, .s_showcase .row:not(.s_col_no_resize) &gt; div\\" data-no-scroll=\\".accordion &gt; .card\\">\\n        <we-button class=\\"fa fa-fw fa-angle-up\\" data-move-snippet=\\"prev\\" data-no-preview=\\"true\\" data-name=\\"move_up_opt\\"/>\\n        <we-button class=\\"fa fa-fw fa-angle-down\\" data-move-snippet=\\"next\\" data-no-preview=\\"true\\" data-name=\\"move_down_opt\\"/>\\n    </div>\\n    <div data-js=\\"SnippetMove\\" data-selector=\\".row:not(.s_col_no_resize) &gt; div, .nav-item\\" data-exclude=\\".s_showcase .row &gt; div\\" data-name=\\"move_horizontally_opt\\">\\n        <we-button class=\\"fa fa-fw fa-angle-left\\" data-move-snippet=\\"prev\\" data-no-preview=\\"true\\" data-name=\\"move_left_opt\\"/>\\n        <we-button class=\\"fa fa-fw fa-angle-right\\" data-move-snippet=\\"next\\" data-no-preview=\\"true\\" data-name=\\"move_right_opt\\"/>\\n    </div>\\n\\n    <!-- Background -->\\n    <t t-set=\\"only_bg_color_selector\\" t-value=\\"'section .row &gt; div, .s_text_highlight, .s_mega_menu_thumbnails_footer'\\"/>\\n    <t t-set=\\"only_bg_color_exclude\\" t-value=\\"'.s_col_no_bgcolor, .s_col_no_bgcolor.row &gt; div, .s_masonry_block .row &gt; div, .s_color_blocks_2 .row &gt; div, .s_image_gallery .row &gt; div, .s_text_cover .row &gt; .o_not_editable'\\"/>\\n\\n    <t t-set=\\"base_only_bg_image_selector\\" t-value=\\"'.s_tabs .oe_structure &gt; *, footer .oe_structure &gt; *'\\"/>\\n    <t t-set=\\"only_bg_image_selector\\" t-value=\\"base_only_bg_image_selector\\"/>\\n    <t t-set=\\"only_bg_image_exclude\\" t-value=\\"''\\"/>\\n\\n    <t t-set=\\"both_bg_color_image_selector\\" t-value=\\"'section, .carousel-item, .s_masonry_block .row &gt; div, .s_color_blocks_2 .row &gt; div, .parallax, .s_text_cover .row &gt; .o_not_editable'\\"/>\\n    <t t-set=\\"both_bg_color_image_exclude\\" t-value=\\"base_only_bg_image_selector + ', .s_carousel_wrapper, .s_image_gallery .carousel-item, .s_google_map, .s_map, [data-snippet] :not(.oe_structure) &gt; [data-snippet], .s_masonry_block .s_col_no_resize'\\"/>\\n\\n    <t t-call=\\"website.snippet_options_background_options\\">\\n        <t t-set=\\"selector\\" t-value=\\"both_bg_color_image_selector\\"/>\\n        <t t-set=\\"exclude\\" t-value=\\"both_bg_color_image_exclude\\"/>\\n        <t t-set=\\"with_colors\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_images\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_videos\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_shapes\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_color_combinations\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_gradients\\" t-value=\\"True\\"/>\\n    </t>\\n\\n    <t t-call=\\"website.snippet_options_background_options\\">\\n        <t t-set=\\"selector\\" t-value=\\"only_bg_color_selector\\"/>\\n        <t t-set=\\"exclude\\" t-value=\\"only_bg_color_exclude\\"/>\\n        <t t-set=\\"with_colors\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_images\\" t-value=\\"False\\"/>\\n        <t t-set=\\"with_color_combinations\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_gradients\\" t-value=\\"True\\"/>\\n    </t>\\n\\n    <t t-call=\\"website.snippet_options_background_options\\">\\n        <t t-set=\\"selector\\" t-value=\\"only_bg_image_selector\\"/>\\n        <t t-set=\\"exclude\\" t-value=\\"only_bg_image_exclude\\"/>\\n        <t t-set=\\"with_colors\\" t-value=\\"False\\"/>\\n        <t t-set=\\"with_images\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_videos\\" t-value=\\"True\\"/>\\n        <t t-set=\\"with_shapes\\" t-value=\\"True\\"/>\\n    </t>\\n\\n    <!-- Grid mode columns -->\\n    <div data-js=\\"GridColumns\\" data-selector=\\".row:not(.s_col_no_resize) &gt; div\\">\\n        <we-row string=\\"Padding (Y, X)\\">\\n            <we-input data-select-style=\\"\\" data-css-property=\\"--grid-item-padding-y\\" data-unit=\\"px\\" data-name=\\"grid_padding_y_opt\\"/>\\n            <we-input data-select-style=\\"\\" data-css-property=\\"--grid-item-padding-x\\" data-unit=\\"px\\" data-name=\\"grid_padding_x_opt\\"/>\\n        </we-row>\\n    </div>\\n\\n    <!-- Border | Columns -->\\n    <div data-js=\\"Box\\" data-selector=\\"section .row &gt; div\\" data-exclude=\\".s_col_no_bgcolor, .s_col_no_bgcolor.row &gt; div, .s_image_gallery .row &gt; div, .s_masonry_block .s_col_no_resize, .s_text_cover .row &gt; .o_not_editable\\">\\n        <t t-call=\\"website.snippet_options_border_widgets\\"/>\\n        <t t-call=\\"website.snippet_options_shadow_widgets\\"/>\\n    </div>\\n\\n    <div data-js=\\"sizing_y\\" data-selector=\\"section, .row &gt; div, .parallax, .s_hr, .carousel-item, .s_rating\\" data-exclude=\\"section:has(&gt; .carousel), .s_image_gallery .carousel-item, .s_col_no_resize.row &gt; div, .s_col_no_resize\\"/>\\n\\n    <div data-js=\\"sizing_x\\" data-selector=\\".row &gt; div\\" data-drop-near=\\".row:not(.s_col_no_resize) &gt; div\\" data-exclude=\\".s_col_no_resize.row &gt; div, .s_col_no_resize\\"/>\\n\\n    <div data-js=\\"sizing_grid\\" data-selector=\\".row &gt; div\\" data-drop-near=\\".row.o_grid_mode &gt; div\\" data-exclude=\\".s_col_no_resize.row &gt; div, .s_col_no_resize\\"/>\\n\\n    <t t-set=\\"so_snippet_addition_selector\\" t-translation=\\"off\\">section, .parallax</t>\\n    <div id=\\"so_snippet_addition\\" t-att-data-selector=\\"so_snippet_addition_selector\\" data-drop-in=\\":not(p).oe_structure:not(.oe_structure_solo), :not(.o_mega_menu):not(p)[data-oe-type=html], :not(p).oe_structure.oe_structure_solo:not(:has(&gt; section, &gt; div))\\"/>\\n        <!-- /!\\\\ drop-in here is partly duplicated for s_popup (see dedicated options) -->\\n        <!-- TODO should be improved -->\\n\\n    <t t-set=\\"so_content_addition_selector\\" t-translation=\\"off\\">\\n        blockquote, .s_card:not(.s_timeline_card), .s_alert, .o_facebook_page, .s_share, .s_social_media, .s_rating,\\n        .s_hr, .s_google_map, .s_map, .s_countdown, .s_chart, .s_text_highlight, .s_progress_bar, .s_badge,\\n        .s_embed_code, .s_donation, .s_add_to_cart, .s_online_appointment, .o_snippet_drop_in_only\\n    </t>\\n\\n    <div id=\\"so_content_addition\\" t-att-data-selector=\\"so_content_addition_selector\\" t-attf-data-drop-near=\\"p, h1, h2, h3, ul, ol, div:not(.o_grid_item_image) &gt; img, .btn, #{so_content_addition_selector}\\" data-drop-in=\\"nav\\"/>\\n\\n    <div data-js=\\"SnippetSave\\" data-selector=\\"[data-snippet], a.btn\\" t-attf-data-exclude=\\".o_no_save, #{so_submit_button_selector}\\">\\n        <we-button class=\\"fa fa-fw fa-save o_we_link o_we_hover_warning\\" title=\\"Save the block to use it elsewhere\\" data-save-snippet=\\"\\" data-no-preview=\\"true\\"/>\\n    </div>\\n\\n    <!-- TODO adapt in master to use the top_menu class -->\\n    <div data-js=\\"menu_data\\" data-selector=\\"#top_menu li &gt; a, [data-content_menu_id] li &gt; a\\" data-exclude=\\".dropdown-toggle, li.o_header_menu_button a, [data-toggle], .o_offcanvas_logo\\" data-no-check=\\"true\\"/>\\n\\n    <div data-js=\\"HeaderLayout\\" data-selector=\\"#wrapwrap &gt; header\\" data-no-check=\\"true\\" groups=\\"website.group_website_designer\\">\\n        <we-select string=\\"Template\\" data-variable=\\"header-template\\" data-default-variables=\\"header-links-style: default\\" data-reload=\\"/\\" data-no-preview=\\"true\\">\\n            <we-button title=\\"Default\\" data-name=\\"header_default_opt\\" data-trigger=\\"regular_header_visibility_opt\\" data-customize-website-views=\\"website.template_header_default\\" data-customize-website-variable=\\"'default'\\" data-img=\\"/website/static/src/img/snippets_options/header_template_default.svg\\"/>\\n            <we-button title=\\"Hamburger menu\\" data-name=\\"header_hamburger_opt\\" data-trigger=\\"regular_header_visibility_opt\\" data-customize-website-views=\\"website.template_header_hamburger, website.no_autohide_menu\\" data-customize-website-variable=\\"'hamburger'\\" data-img=\\"/website/static/src/img/snippets_options/header_template_hamburger.svg\\"/>\\n            <we-button title=\\"Rounded box menu\\" data-name=\\"header_boxed_opt\\" data-trigger=\\"over_content_header_visibility_opt\\" data-customize-website-views=\\"website.header_navbar_pills_style,website.template_header_boxed\\" data-customize-website-variable=\\"'boxed'\\" data-customize-website-variables=\\"header-links-style: pills\\" data-img=\\"/website/static/src/img/snippets_options/header_template_boxed.svg\\"/>\\n            <we-button title=\\"Stretch menu\\" data-name=\\"header_stretch_opt\\" data-trigger=\\"regular_header_visibility_opt\\" data-customize-website-views=\\"website.template_header_stretch\\" data-customize-website-variable=\\"'stretch'\\" data-img=\\"/website/static/src/img/snippets_options/header_template_stretch.svg\\"/>\\n            <we-button title=\\"Vertical\\" data-name=\\"header_vertical_opt\\" data-trigger=\\"regular_header_visibility_opt\\" data-customize-website-views=\\"website.template_header_vertical\\" data-customize-website-variable=\\"'vertical'\\" data-img=\\"/website/static/src/img/snippets_options/header_template_vertical.svg\\"/>\\n            <we-button title=\\"Menu with Search bar\\" data-name=\\"header_search_opt\\" data-trigger=\\"regular_header_visibility_opt\\" data-customize-website-views=\\"website.template_header_search\\" data-customize-website-variable=\\"'search'\\" data-img=\\"/website/static/src/img/snippets_options/header_template_search.svg\\"/>\\n            <we-button title=\\"Menu - Sales 1\\" data-name=\\"header_sales_one_opt\\" data-trigger=\\"regular_header_visibility_opt\\" data-customize-website-views=\\"website.template_header_sales_one\\" data-customize-website-variable=\\"'sales_one'\\" data-img=\\"/website/static/src/img/snippets_options/header_template_sales_one.svg\\"/>\\n            <we-button title=\\"Menu - Sales 2\\" data-name=\\"header_sales_two_opt\\" data-trigger=\\"regular_header_visibility_opt\\" data-customize-website-views=\\"website.template_header_sales_two\\" data-customize-website-variable=\\"'sales_two'\\" data-img=\\"/website/static/src/img/snippets_options/header_template_sales_two.svg\\"/>\\n            <we-button title=\\"Menu - Sales 3\\" data-name=\\"header_sales_three_opt\\" data-trigger=\\"regular_header_visibility_opt\\" data-customize-website-views=\\"website.template_header_sales_three\\" data-customize-website-variable=\\"'sales_three'\\" data-img=\\"/website/static/src/img/snippets_options/header_template_sales_three.svg\\"/>\\n            <we-button title=\\"Menu - Sales 4\\" data-name=\\"header_sales_four_opt\\" data-trigger=\\"regular_header_visibility_opt\\" data-customize-website-views=\\"website.template_header_sales_four\\" data-customize-website-variable=\\"'sales_four'\\" data-img=\\"/website/static/src/img/snippets_options/header_template_sales_four.svg\\"/>\\n            <we-button title=\\"Sidebar\\" data-name=\\"header_sidebar_opt\\" data-trigger=\\"regular_header_visibility_opt\\" data-customize-website-views=\\"website.template_header_sidebar, website.no_autohide_menu\\" data-customize-website-variable=\\"'sidebar'\\" data-img=\\"/website/static/src/img/snippets_options/header_template_sidebar.svg\\"/>\\n        </we-select>\\n\\n        <!-- Header Sidebar Template - Options -->\\n        <we-input string=\\"Width\\" class=\\"o_we_sublevel_1\\" data-dependencies=\\"header_sidebar_opt\\" data-customize-website-variable=\\"null\\" data-variable=\\"sidebar-width\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n\\n        <we-row string=\\"Background\\">\\n            <we-colorpicker data-customize-website-color=\\"\\" data-color=\\"menu\\" data-customize-website-layer2-color=\\"\\" data-layer-color=\\"menu-custom\\" data-layer-gradient=\\"menu-gradient\\" data-no-bundle-reload=\\"true\\" data-null-value=\\"'NULL'\\" data-with-combinations=\\"customizeWebsiteColor\\" data-with-gradients=\\"true\\"/>\\n            <we-colorpicker data-dependencies=\\"header_sales_one_opt\\" data-customize-website-color=\\"\\" data-color=\\"header-sales_one\\" data-customize-website-layer2-color=\\"\\" data-layer-color=\\"header-sales_one-custom\\" data-layer-gradient=\\"menu-secondary-gradient\\" data-no-bundle-reload=\\"true\\" data-null-value=\\"'NULL'\\" data-with-combinations=\\"customizeWebsiteColor\\" data-with-gradients=\\"true\\"/>\\n            <we-colorpicker data-dependencies=\\"header_sales_two_opt\\" data-customize-website-color=\\"\\" data-color=\\"header-sales_two\\" data-customize-website-layer2-color=\\"\\" data-layer-color=\\"header-sales_two-custom\\" data-layer-gradient=\\"menu-secondary-gradient\\" data-no-bundle-reload=\\"true\\" data-null-value=\\"'NULL'\\" data-with-combinations=\\"customizeWebsiteColor\\" data-with-gradients=\\"true\\"/>\\n            <we-colorpicker data-dependencies=\\"header_sales_three_opt\\" data-customize-website-color=\\"\\" data-color=\\"header-sales_three\\" data-customize-website-layer2-color=\\"\\" data-layer-color=\\"header-sales_three-custom\\" data-layer-gradient=\\"menu-secondary-gradient\\" data-no-bundle-reload=\\"true\\" data-null-value=\\"'NULL'\\" data-with-combinations=\\"customizeWebsiteColor\\" data-with-gradients=\\"true\\"/>\\n            <we-colorpicker data-dependencies=\\"header_sales_four_opt\\" data-customize-website-color=\\"\\" data-color=\\"header-sales_four\\" data-customize-website-layer2-color=\\"\\" data-layer-color=\\"header-sales_four-custom\\" data-layer-gradient=\\"menu-secondary-gradient\\" data-no-bundle-reload=\\"true\\" data-null-value=\\"'NULL'\\" data-with-combinations=\\"customizeWebsiteColor\\" data-with-gradients=\\"true\\"/>\\n        </we-row>\\n    </div>\\n\\n    <!-- Header - Borders & Shadows -->\\n    <div data-js=\\"HeaderBox\\" id=\\"option_header_shadow\\" data-selector=\\"#wrapwrap &gt; header:not(:has(.o_header_force_no_radius))\\" data-target=\\"nav\\" data-no-check=\\"true\\" groups=\\"website.group_website_designer\\">\\n     