-class=\\"o_anim_zoom_out\\" data-trigger=\\"animation_direction_in_place_opt\\">Zoom Out</we-button>\\n            <we-button data-select-class=\\"o_anim_zoom_in\\" data-trigger=\\"animation_direction_in_place_opt\\">Zoom In</we-button>\\n            <we-button data-select-class=\\"o_anim_flash\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Flash</we-button>\\n            <we-button data-select-class=\\"o_anim_pulse\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Pulse</we-button>\\n            <we-button data-select-class=\\"o_anim_shake\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Shake</we-button>\\n            <we-button data-select-class=\\"o_anim_tada\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Tada</we-button>\\n            <we-button data-select-class=\\"o_anim_flip_in_x\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Flip-In-X</we-button>\\n            <we-button data-select-class=\\"o_anim_flip_in_y\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Flip-In-Y</we-button>\\n        </we-select>\\n        <!-- Direction -->\\n        <we-select string=\\"Direction\\" class=\\"o_we_sublevel_1\\" data-name=\\"animation_direction_opt\\" data-force-animation=\\"true\\">\\n            <we-button data-select-class=\\"\\" data-name=\\"animation_direction_in_place_opt\\" data-dependencies=\\"!o_anim_slide_in_opt\\">In Place</we-button>\\n            <we-button data-select-class=\\"o_anim_from_right\\" data-name=\\"animation_direction_from_right_opt\\" data-dependencies=\\"!o_anim_rotate_opt\\">From Right</we-button>\\n            <we-button data-select-class=\\"o_anim_from_left\\" data-dependencies=\\"!o_anim_rotate_opt\\">From Left</we-button>\\n            <we-button data-select-class=\\"o_anim_from_bottom\\" data-dependencies=\\"!o_anim_rotate_opt\\">From Bottom</we-button>\\n            <we-button data-select-class=\\"o_anim_from_top\\" data-dependencies=\\"!o_anim_rotate_opt\\">From Top</we-button>\\n            <we-button data-select-class=\\"o_anim_from_top_right\\" data-dependencies=\\"o_anim_rotate_opt\\">From Top Right</we-button>\\n            <we-button data-select-class=\\"o_anim_from_top_left\\" data-dependencies=\\"o_anim_rotate_opt\\">From Top Left</we-button>\\n            <we-button data-select-class=\\"o_anim_from_bottom_right\\" data-dependencies=\\"o_anim_rotate_opt\\">From Bottom Right</we-button>\\n            <we-button data-select-class=\\"o_anim_from_bottom_left\\" data-dependencies=\\"o_anim_rotate_opt\\">From Bottom Left</we-button>\\n        </we-select>\\n        <!-- Trigger -->\\n        <we-select string=\\"Trigger\\" class=\\"o_we_sublevel_1\\" data-dependencies=\\"animation_on_appearance_opt\\" data-name=\\"animation_trigger_opt\\">\\n            <we-button data-select-class=\\"\\">First Time Only</we-button>\\n            <we-button data-select-class=\\"o_animate_both_scroll\\">Every Time</we-button>\\n        </we-select>\\n        <!-- Intensity -->\\n        <we-range string=\\"Intensity\\" class=\\"o_we_sublevel_1\\" data-name=\\"animation_intensity_opt\\" data-animation-intensity=\\"\\" data-min=\\"1\\" data-max=\\"100\\" data-step=\\"1\\" data-display-range-value=\\"true\\" data-no-preview=\\"true\\"/>\\n        <!-- Scroll Zone -->\\n        <we-row string=\\"Scroll Zone\\" class=\\"o_we_sublevel_1\\">\\n            <we-input data-unit=\\"%\\" data-step=\\"1\\" data-dependencies=\\"animation_on_scroll_opt\\" data-no-preview=\\"true\\" data-select-data-attribute=\\"\\" data-attribute-name=\\"scrollZoneStart\\" data-force-animation=\\"true\\"/>\\n            <span class=\\"mx-2\\">to</span>\\n            <we-input data-unit=\\"%\\" data-step=\\"1\\" data-dependencies=\\"animation_on_scroll_opt\\" data-no-preview=\\"true\\" data-select-data-attribute=\\"\\" data-attribute-name=\\"scrollZoneEnd\\" data-force-animation=\\"true\\"/>\\n        </we-row>\\n        <!-- Start After -->\\n        <we-input string=\\"Start After\\" class=\\"o_we_sublevel_1 o_we_small_input\\" data-dependencies=\\"animation_on_appearance_opt\\" data-name=\\"animation_delay_opt\\" data-select-style=\\"0s\\" data-css-property=\\"animation-delay\\" data-unit=\\"s\\"/>\\n        <!-- Duration -->\\n        <we-input string=\\"Duration\\" class=\\"o_we_sublevel_1 o_we_small_input\\" data-dependencies=\\"animation_on_appearance_opt\\" data-select-style=\\"0.4s\\" data-css-property=\\"animation-duration\\" data-unit=\\"s\\"/>\\n    </div>\\n\\n    <!-- Text highlight effects -->\\n    <div data-js=\\"TextHighlight\\" data-selector=\\".o_text_highlight\\">\\n        <!-- Text highlight style -->\\n        <we-select string=\\"Highlight\\" data-name=\\"text_highlight_opt\\" class=\\"o_we_select_grid\\">\\n            <div class=\\"grid gap-0\\">\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_underline\\" data-set-text-highlight=\\"underline\\" data-select-label=\\"Underline\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_freehand_1\\" data-set-text-highlight=\\"freehand_1\\" data-select-label=\\"Freehand 1\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_freehand_2 o_text_highlight_fill\\" data-set-text-highlight=\\"freehand_2\\" data-select-label=\\"Freehand 2\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_freehand_3 o_text_highlight_fill\\" data-set-text-highlight=\\"freehand_3\\" data-select-label=\\"Freehand 3\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_double\\" data-set-text-highlight=\\"double\\" data-selec