string=\\"Language\\">\\n            <we-button data-add-language=\\"\\" data-no-preview=\\"true\\" class=\\"o_we_bg_brand_primary\\">Add a Language</we-button>\\n        </we-row>\\n        <we-select string=\\"Page Layout\\" data-variable=\\"layout\\">\\n            <we-button data-customize-website-variable=\\"'full'\\" data-name=\\"layout_full_opt\\">Full</we-button>\\n            <we-button data-customize-website-variable=\\"'boxed'\\">Boxed</we-button>\\n            <we-button data-customize-website-variable=\\"'framed'\\">Framed</we-button>\\n            <we-button data-customize-website-variable=\\"'postcard'\\">Postcard</we-button>\\n        </we-select>\\n        <we-row string=\\"Background\\" class=\\"o_we_sublevel_1\\" data-no-preview=\\"true\\">\\n            <we-colorpicker data-dependencies=\\"!layout_full_opt\\" data-customize-website-color=\\"\\" data-color=\\"body\\"/>\\n            <we-button-group data-imagepicker=\\"body_bg_image_opt\\">\\n                <we-button title=\\"Image\\" class=\\"fa fa-fw fa-camera\\" data-customize-body-bg-type=\\"'image'\\"/>\\n                <we-button title=\\"Pattern\\" class=\\"fa fa-fw fa-th\\" data-customize-body-bg-type=\\"'pattern'\\"/>\\n                <we-button title=\\"None\\" class=\\"fa fa-fw fa-ban\\" data-customize-body-bg-type=\\"NONE\\"/>\\n            </we-button-group>\\n            <!-- Hidden imagepicker enabled by above button-group -->\\n            <we-imagepicker data-name=\\"body_bg_image_opt\\" data-customize-body-bg=\\"\\"/>\\n        </we-row>\\n    </div>\\n    <div data-js=\\"OptionsTab\\" data-selector=\\"theme-paragraph\\" data-no-check=\\"true\\">\\n        <we-collapse>\\n            <we-input string=\\"Font size\\" data-customize-website-variable=\\"null\\" data-variable=\\"font-size-base\\" data-unit=\\"px\\" data-save-unit=\\"rem\\"/>\\n            <we-input string=\\"Small\\" class=\\"o_we_sublevel_1\\" data-customize-website-variable=\\"null\\" data-variable=\\"small-fon