able=\\"'outline'\\">Contorno</we-button>\\n            <we-button data-name=\\"option_header_navbar_links_pills\\" data-customize-website-views=\\"website.header_navbar_pills_style\\" data-customize-website-variable=\\"'pills'\\">Píldoras</we-button>\\n            <we-button data-name=\\"option_header_navbar_block\\" data-customize-website-views=\\"website.header_navbar_pills_style\\" data-customize-website-variable=\\"'block'\\">Bloque</we-button>\\n            <we-button data-name=\\"option_header_navbar_border_bottom\\" data-customize-website-views=\\"\\" data-customize-website-variable=\\"'border-bottom'\\">Borde inferior</we-button>\\n        </we-select>\\n\\n        <we-select id=\\"option_header_dropdown\\" string=\\"Submenús\\" data-dependencies=\\"!header_hamburger_opt\\" data-no-preview=\\"true\\">\\n            <we-button data-select-class=\\"o_hoverable_dropdown\\" data-customize-website-views=\\"website.header_hoverable_dropdown\\">Al pasar el cursor por encima</we-button>\\n            <we-button data-select-class=\\"\\" data-name=\\"header_dropdown_on_click_opt\\">Al hacer clic</we-button>\\n        </we-select>\\n    </div>\\n\\n    <div data-selector=\\"#wrapwrap &gt; header nav.navbar .o_header_language_selector\\" data-no-check=\\"true\\" groups=\\"website.group_website_designer\\">\\n        <we-select string=\\"Estilo\\" data-reload=\\"/\\">\\n            <we-button data-name=\\"header_language_selector_none_opt\\" data-customize-website-views=\\"\\">Ninguno</we-button>\\n            <we-button data-customize-website-views=\\"website.header_language_selector\\">Desplegable</we-button>\\n            <we-button data-customize-website-views=\\"website.header_language_selector, website.header_language_selector_inline\\">En línea</we-button>\\n        </we-select>\\n        <we-select string=\\"Etiqueta\\" class=\\"o_we_sublevel_1\\" data-dependencies=\\"!header_language_selector_none_opt\\" data-reload=\\"/\\" data-no-preview=\\"true\\">\\n       