   <div data-js=\\"WebsiteLevelColor\\" data-selector=\\"#wrapwrap &gt; footer\\" data-no-check=\\"true\\" groups=\\"website.group_website_designer\\">\\n\\n        <!-- Layouts -->\\n        <we-select string=\\"Plantilla\\" data-variable=\\"footer-template\\" data-reload=\\"/\\">\\n            <we-button title=\\"Predeterminado\\" data-customize-website-views=\\"website.footer_custom\\" data-customize-website-variable=\\"'default'\\" data-img=\\"/website/static/src/img/snippets_options/footer_template_default.svg\\"/>\\n            <we-button title=\\"Descriptivo\\" data-customize-website-views=\\"website.template_footer_descriptive\\" data-customize-website-variable=\\"'descriptive'\\" data-img=\\"/website/static/src/img/snippets_options/footer_template_descriptive.svg\\"/>\\n            <we-button title=\\"Centrado\\" data-customize-website-views=\\"website.template_footer_centered\\" data-customize-website-variable=\\"'centered'\\" data-img=\\"/website/static/src/img/snippets_options/footer_template_centered.svg\\"/>\\n            <we-button title=\\"Enlaces\\" data-customize-website-views=\\"website.template_footer_links\\" data-customize-website-variable=\\"'links'\\" data-img=\\"/website/static/src/img/snippets_options/footer_template_links.svg\\"/>\\n            <we-button title=\\"Minimalista\\" data-customize-website-views=\\"website.template_footer_minimalist\\" data-customize-website-variable=\\"'minimalist'\\" data-img=\\"/website/static/src/img/snippets_options/footer_template_minimalist.svg\\"/>\\n            <we-button title=\\"Contacto\\" data-customize-website-views=\\"website.template_footer_contact\\" data-customize-website-variable=\\"'contact'\\" data-img=\\"/website/static/src/img/snippets_options/footer_template_contact.svg\\"/>\\n            <we-button title=\\"Llamada a la acción\\" data-customize-website-views=\\"website.template_footer_call_to_action\\" data-customize-website-variable=\\"'call_to_action'\\" data-img=\\"/website/static/src/img/snippets_options/footer_template_call_to_action.svg\\"/>\\n            <we-button title=\\"Titular\\" data-customize-website-views=\\"website.template_footer_headline\\" data-customize-website-variable=\\"'headline'\\" data-img=\\"/website/static/src/img/snippets_options/footer_template_headline.svg\\"/>\\n        </we-select>\\n        <!-- Colors -->\\n        <we-colorpicker string=\\"Colores\\" data-customize-website-color=\\"\\" data-color=\\"footer\\" data-customize-website-layer2-color=\\"\\" data-layer-color=\\"footer-custom\\" data-layer-gradient=\\"footer-gradient\\" data-no-bundle-reload=\\"true\\" data-null-value=\\"'NULL'\\" data-with-combinations=\\"customizeWebsiteColor\\" data-with-gradients=\\"true\\"/>\\n        <we-select string=\\"Efecto de desplazamiento de salida\\" data-variable=\\"footer-effect\\" data-reload=\\"/\\">\\n            <we-button string=\\"Regular\\" data-customize-website-views=\\"\\" data-customize-website-variable=\\"\\"/>\\n            <we-button string=\\"Deslizamiento al pasar el cursor por encima\\" data-customize-website-views=\\"website.template_footer_slideout\\" data-customize-website-variable=\\"'slideout_slide_hover'\\"/>\\n            <we-button string=\\"Sombra\\" data-customize-website-views=\\"website.template_footer_slideout\\" data-customize-website-variable=\\"'slideout_shadow'\\"/>\\n        </we-select>\\n        <we-checkbox string=\\"Derechos de autor\\" data-name=\\"footer_copyright_opt\\" data-customize-website-views=\\"website.footer_no_copyright|\\" data-no-preview=\\"true\\" data-reload=\\"/\\"/>\\n        <we-checkbox string=\\"Selector de idioma\\" data-dependencies=\\"!footer_copyright_opt\\" data-customize-website-views=\\"website.footer_no_copyright|portal.footer_language_selector\\" data-no-preview=\\"true\\" data-reload=\\"/\\"/>\\n    </div>\\n\\n    <!-- Footer - Borders & Shadows -->\\n    <div data-js=\\"Box\\" data-selector=\\"#wrapwrap &gt; footer\\" data-target=\\"#footer\\" data-no-check=\\"true\\" groups=\\"website.group_website_designer\\">\\n        <t t-call=\\"website.snippet_options_border_widgets\\"/>\\n        <t t-call=\\"website.snippet_options_shadow_widgets\\"/>\\n    </div>\\n\\n    <!-- Scroll to Top -->\\n    <div data-selector=\\"#wrapwrap &gt; footer\\" data-no-check=\\"true\\" groups=\\"website.group_website_designer\\">\\n        <we-row string=\\"Botón para regresar a la parte superior\\">\\n            <we-checkbox data-name=\\"footer_scrolltop_opt\\" data-customize-website-views=\\"website.option_footer_scrolltop\\" data-customize-website-variable=\\"false|true\\" data-variable=\\"footer-scrolltop\\" data-reload=\\"/\\"/>\\n            <we-select data-dependencies=\\"footer_scrolltop_opt\\" data-apply-to=\\"#o_footer_scrolltop_wrapper\\">\\n                <we-button string=\\"Izquierda\\" data-select-class=\\"justify-content-start\\"/>\\n                <we-button string=\\"Centro\\" data-select-class=\\"justify-content-center\\"/>\\n                <we-button string=\\"Derecha\\" data-select-class=\\"justify-content-end\\"/>\\n            </we-select>\\n        </we-row>\\n    </div>\\n\\n    <div data-js=\\"HideFooter\\" data-selector=\\"[data-main-object^='website.page('] #wrapwrap &gt; footer\\" data-no-check=\\"true\\" groups=\\"website.group_website_designer\\">\\n        <we-checkbox string=\\"Visibilidad de la página\\" data-name=\\"hide_footer_page_opt\\" data-visibility=\\"hidden|shown\\" data-no-preview=\\"true\\"/>\\n    </div>\\n\\n    <!-- Copyright -->\\n    <div data-js=\\"WebsiteLevelColor\\" data-selector=\\".o_footer_copyright\\" data-no-check=\\"true\\" groups=\\"website.group_website_designer\\">\\n        <we-colorpicker string=\\"Colores\\" data-customize-website-color=\\"\\" data-color=\\"copyright\\" data-customize-website-layer2-color=\\"\\" data-layer-color=\\"copyright-custom\\" data-layer-gradient=\\"copyright-gradient\\" data-no-bundle-reload=\\"true\\" data-null-value=\\"'NULL'\\" data-with-combinations=\\"customizeWebsiteColor\\" data-with-gradients=\\"true\\"/>\\n        <we-select data-name=\\"footer_language_selector_opt\\" string=\\"Selector de idioma\\" data-reload=\\"/\\" data-no-preview=\\"true\\">\\n            <we-button data-name=\\"language_selector_none_opt\\" data-customize-website-views=\\"\\">Ninguno</we-button>\\n            <we-button data-customize-website-views=\\"portal.footer_language_selector\\">Desplegable</we-button>\\n            <we-button data-customize-website-views=\\"portal.footer_language_selector, website.footer_language_selector_inline\\">En línea</we-button>\\n        </we-select>\\n        <we-select data-name=\\"footer_language_selector_label_opt\\" string=\\"Etiqueta\\" class=\\"o_we_sublevel_1\\" data-dependencies=\\"!language_selector_none_opt\\" data-reload=\\"/\\" data-no-preview=\\"true\\">\\n            <we-button data-customize-website-views=\\"\\">Texto</we-button>\\n            <we-button data-customize-website-views=\\"website.footer_language_selector_flag, website.footer_language_selector_no_text\\">Bandera</we-button>\\n            <we-button data-customize-website-views=\\"website.footer_language_selector_flag\\">Marcar y texto</we-button>\\n            <we-button data-customize-website-views=\\"website.footer_language_selector_code, website.footer_language_selector_no_text\\">Código</we-button>\\n            <we-button data-customize-website-views=\\"website.footer_language_selector_flag, website.footer_language_selector_code, website.footer_language_selector_no_text\\">Marca y código</we-button>\\n        </we-select>\\n    </div>\\n\\n    <!-- Anchor Name -->\\n    <div data-js=\\"anchor\\" data-selector=\\":not(p).oe_structure &gt; *, :not(p)[data-oe-type=html] &gt; *\\" data-exclude=\\".modal *, .oe_structure .oe_structure *, [data-oe-type=html] .oe_structure *, .s_popup\\">\\n        <we-button class=\\"fa fa-fw fa-link o_we_link\\" title=\\"Crear enlace para redirigir a esta sección\\" data-no-preview=\\"true\\"/>\\n    </div>\\n\\n    <div data-js=\\"anchor\\" data-selector=\\".s_popup\\" data-target=\\".modal\\">\\n    </div>\\n\\n    <!-- Mega Menu settings -->\\n    <div data-js=\\"MegaMenuLayout\\" data-selector=\\".o_mega_menu\\">\\n        <we-select string=\\"Plantilla\\" data-name=\\"mega_menu_template_opt\\">\\n            <t t-set=\\"_label\\">Multimenús</t>\\n            <we-button t-att-data-select-label=\\"_label\\" data-select-template=\\"website.s_mega_menu_multi_menus\\" data-img=\\"/website/static/src/img/snippets_thumbs/s_mega_menu_multi_menus.svg\\" t-out=\\"_label\\"/>\\n            <t t-set=\\"_label\\">Menú de imagen</t>\\n            <we-button t-att-data-select-label=\\"_label\\" data-select-template=\\"website.s_mega_menu_menu_image_menu\\" data-img=\\"/website/static/src/img/snippets_thumbs/s_mega_menu_menu_image_menu.svg\\" t-out=\\"_label\\"/>\\n            <t t-set=\\"_label\\">Menú de Odoo</t>\\n            <we-button t-att-data-select-label=\\"_label\\" data-select-template=\\"website.s_mega_menu_odoo_menu\\" data-img=\\"/website/static/src/img/snippets_thumbs/s_mega_menu_odoo_menu.svg\\" t-out=\\"_label\\"/>\\n            <t t-set=\\"_label\\">Iconos pequeños</t>\\n            <we-button t-att-data-select-label=\\"_label\\" data-select-template=\\"website.s_mega_menu_little_icons\\" data-img=\\"/website/static/src/img/snippets_thumbs/s_mega_menu_little_icons.svg\\" t-out=\\"_label\\"/>\\n            <t t-set=\\"_label\\">Subtítulos de iconos grandes</t>\\n            <we-button t-att-data-select-label=\\"_label\\" data-select-template=\\"website.s_mega_menu_big_icons_subtitles\\" data-img=\\"/website/static/src/img/snippets_thumbs/s_mega_menu_big_icons_subtitles.svg\\" t-out=\\"_label\\"/>\\n            <t t-set=\\"_label\\">Subtítulos de las imágenes</t>\\n            <we-button t-att-data-select-label=\\"_label\\" data-select-template=\\"website.s_mega_menu_images_subtitles\\" data-img=\\"/website/static/src/img/snippets_thumbs/s_mega_menu_images_subtitles.svg\\" t-out=\\"_label\\"/>\\n            <t t-set=\\"_label\\">Logos</t>\\n            <we-button t-att-data-select-label=\\"_label\\" data-select-template=\\"website.s_mega_menu_menus_logos\\" data-img=\\"/website/static/src/img/snippets_thumbs/s_mega_menu_menus_logos.svg\\" t-out=\\"_label\\"/>\\n            <t t-set=\\"_label\\">Miniaturas</t>\\n            <we-button t-att-data-select-label=\\"_label\\" data-select-template=\\"website.s_mega_menu_thumbnails\\" data-img=\\"/website/static/src/img/snippets_thumbs/s_mega_menu_thumbnails.svg\\" t-out=\\"_label\\"/>\\n            <t t-set=\\"_label\\">Tarjetas</t>\\n            <we-button t-att-data-select-label=\\"_label\\" data-select-template=\\"website.s_mega_menu_cards\\" data-img=\\"/website/static/src/img/snippets_thumbs/s_mega_menu_cards.svg\\" t-out=\\"_label\\"/>\\n        </we-select>\\n        <we-select string=\\"Tamaño\\">\\n            <we-button data-select-class=\\"\\">Ancho completo</we-button>\\n            <we-button data-select-class=\\"o_mega_menu_container_size\\">Estrecho</we-button>\\n        </we-select>\\n    </div>\\n\\n    <div data-js=\\"MegaMenuNoDelete\\" data-selector=\\".o_mega_menu &gt; section\\"/>\\n\\n    <div data-selector=\\".o_mega_menu .nav &gt; .nav-link\\" data-drop-in=\\".o_mega_menu nav\\" data-drop-near=\\".o_mega_menu .nav-link\\"/>\\n\\n    <div data-js=\\"CoverProperties\\" data-selector=\\".o_record_cover_container\\" data-no-check=\\"true\\">\\n        <we-row string=\\"Fondo\\" class=\\"o_we_full_row\\">\\n            <t t-call=\\"web_editor.snippet_options_background_color_widget\\">\\n                <t t-set=\\"with_color_combinations\\" t-value=\\"True\\"/>\\n                <t t-set=\\"with_gradients\\" t-value=\\"True\\"/>\\n            </t>\\n            <we-button-group class=\\"ms-auto\\">\\n                <we-imagepicker title=\\"Imagen\\" data-background=\\"\\" data-button-style=\\"true\\"/>\\n                <we-button class=\\"fa fa-fw fa-ban\\" title=\\"Ninguno\\" data-background=\\"\\">\\n                </we-button>\\n            </we-button-group>\\n        </we-row>\\n        <we-select string=\\"Tamaño\\" data-name=\\"size_opt\\" data-cover-opt-name=\\"size\\">\\n            <we-button data-select-class=\\"o_full_screen_height\\">Pantalla completa</we-button>\\n            <we-button class=\\"o_record_cover_opt_size_default\\" data-select-class=\\"o_half_screen_height\\">Media pantalla</we-button>\\n            <we-button data-select-class=\\"cover_auto\\">Ajustar texto</we-button>\\n        </we-select>\\n        <we-select string=\\"Intensidad del filtro\\" data-name=\\"filters_opt\\" data-cover-opt-name=\\"filters\\">\\n            <we-button data-filter-value=\\"0.0\\">Ninguno</we-button>\\n            <we-button data-filter-value=\\"0.2\\">Baja</we-button>\\n            <we-button data-filter-value=\\"0.4\\">Medio</we-button>\\n            <we-button data-filter-value=\\"0.6\\">Alta</we-button>\\n        </we-select>\\n        <we-select string=\\"Alineación del texto\\" data-name=\\"text_align_opt\\" data-cover-opt-name=\\"text_align\\">\\n            <we-button data-select-class=\\"\\">Izquierda</we-button>\\n            <we-button data-select-class=\\"text-center\\">Centrado</we-button>\\n            <we-button data-select-class=\\"text-end\\">Derecha</we-button>\\n        </we-select>\\n    </div>\\n\\n    <!-- Stretch section -->\\n    <div data-js=\\"ContainerWidth\\" data-selector=\\"section, .s_carousel .carousel-item, s_quotes_carousel .carousel-item\\" data-exclude=\\"[data-snippet] :not(.oe_structure) &gt; [data-snippet]\\" data-target=\\"&gt; .container, &gt; .container-fluid, &gt; .o_container_small\\">\\n        <we-button-group string=\\"Ancho del contenido\\">\\n            <we-button data-select-class=\\"o_container_small\\" data-img=\\"/website/static/src/img/snippets_options/content_width_small.svg\\" title=\\"Pequeño\\"/>\\n            <we-button data-select-class=\\"container\\" data-img=\\"/website/static/src/img/snippets_options/content_width_normal.svg\\" title=\\"Regular\\"/>\\n            <we-button data-select-class=\\"container-fluid\\" data-img=\\"/website/static/src/img/snippets_options/content_width_full.svg\\" title=\\"Completo\\"/>\\n        </we-button-group>\\n    </div>\\n\\n    <!-- Scroll to next section button (only for full height) -->\\n    <div data-js=\\"ScrollButton\\" data-selector=\\"section\\" data-exclude=\\"[data-snippet] :not(.oe_structure) &gt; [data-snippet], .s_instagram_page\\">\\n        <!-- Min height of section -->\\n        <we-button-group string=\\"Altura\\" data-show-scroll-button=\\"\\">\\n            <we-button data-name=\\"minheight_auto_opt\\" data-select-class=\\"\\" title=\\"Ajustar contenido\\">Auto</we-button>\\n            <we-button data-select-class=\\"o_half_screen_height\\" title=\\"Media pantalla\\">50%</we-button>\\n            <we-button data-select-class=\\"o_full_screen_height\\" title=\\"Pantalla completa\\" data-name=\\"full_height_opt\\" data-show-scroll-button=\\"true\\">100%</we-button>\\n        </we-button-group>\\n\\n        <we-input string=\\"Altura\\" class=\\"o_we_sublevel_1\\" data-name=\\"fixed_height_opt\\" data-dependencies=\\"minheight_auto_opt\\" data-select-style=\\"\\" data-unit=\\"px\\" data-css-property=\\"height\\" data-force-style=\\"\\"/>\\n            <!--    ↑ ↑ ↑\\n            For this setting, we need to always force the style (= if the block\\n            is naturally 800px tall and the user enters 800px for this setting,\\n            we set 800px as inline style anyway). Indeed, this snippet's style\\n            is based on the height that is forced but once the related public\\n            widgets are started, the inner carousel items receive a min-height\\n            which makes it so the snippet \\"natural\\" height is equal to the\\n            initially forced height... so if the style is not forced, it would\\n            ultimately be removed by mistake thinking it is not necessary.\\n            Note: this is forced as not important as we still need the height to\\n            be reset to 'auto' in mobile (generic css rules).\\n            -->\\n\\n        <we-checkbox string=\\"Botón para desplazarse hacia abajo\\" data-toggle-button=\\"true\\" data-no-preview=\\"true\\" data-dependencies=\\"full_height_opt\\" data-name=\\"scroll_button_opt\\"/>\\n        <we-row string=\\"Colores\\" class=\\"o_we_sublevel_1\\">\\n            <we-colorpicker data-select-style=\\"true\\" data-css-property=\\"background-color\\" data-color-prefix=\\"bg-\\" data-apply-to=\\".o_scroll_button\\" data-dependencies=\\"scroll_button_opt\\"/>\\n            <we-colorpicker data-select-style=\\"true\\" data-css-property=\\"color\\" data-color-prefix=\\"text-\\" data-apply-to=\\".o_scroll_button\\" data-dependencies=\\"scroll_button_opt\\"/>\\n        </we-row>\\n        <we-select string=\\"Espaciado\\" class=\\"o_we_sublevel_1\\" data-apply-to=\\".o_scroll_button\\" data-dependencies=\\"scroll_button_opt\\">\\n            <we-button data-select-class=\\"\\">Ninguno</we-button>\\n            <we-button data-select-class=\\"mb-1\\">Extra pequeño</we-button>\\n            <we-button data-select-class=\\"mb-2\\">Pequeño</we-button>\\n            <we-button data-select-class=\\"mb-3\\">Medio</we-button>\\n            <we-button data-select-class=\\"mb-4\\">Grande</we-button>\\n            <we-button data-select-class=\\"mb-5\\">Extra grande</we-button>\\n        </we-select>\\n    </div>\\n\\n    <t t-set=\\"_device_visibility_widgets\\">\\n        <we-button class=\\"o_we_device\\" data-toggle-device-visibility=\\"no_desktop\\" title=\\"Mostrar/ocultar en computadora\\" data-no-preview=\\"true\\" data-img=\\"/website/static/src/img/snippets_options/desktop_invisible.svg\\"/>\\n        <we-button class=\\"o_we_device\\" data-toggle-device-visibility=\\"no_mobile\\" title=\\"Mostrar/ocultar en celular\\" data-no-preview=\\"true\\" data-img=\\"/website/static/src/img/snippets_options/mobile_invisible.svg\\"/>\\n    </t>\\n    <div data-js=\\"ConditionalVisibility\\" data-selector=\\"section\\">\\n        <t t-set=\\"current_website\\" t-value=\\"request.env['website'].get_current_website()\\"/>\\n        <we-collapse>\\n            <we-row string=\\"Visibilidad\\">\\n                <t t-out=\\"_device_visibility_widgets\\"/>\\n                <we-select data-attribute-name=\\"visibility\\" data-no-preview=\\"true\\">\\n                    <we-button data-select-data-attribute=\\"\\">Sin condición</we-button>\\n                    <we-button data-select-data-attribute=\\"conditional\\" data-select-class=\\"o_snippet_invisible\\" data-name=\\"visibility_conditional\\">De forma condicional</we-button>\\n                </we-select>\\n            </we-row>\\n\\n            <t t-if=\\"request.geoip.country_code\\">\\n                <t t-call=\\"website.snippet_options_conditional_visibility\\">\\n                    <t t-set=\\"option_name\\">País</t>\\n                    <t t-set=\\"attribute_rule\\" t-valuef=\\"visibilityValueCountryRule\\"/>\\n                    <t t-set=\\"save_attribute\\" t-valuef=\\"visibilityValueCountry\\"/>\\n                    <t t-set=\\"attribute_name\\" t-valuef=\\"data-country\\"/>\\n                    <t t-set=\\"model\\" t-valuef=\\"res.country\\"/>\\n                    <t t-set=\\"call_with\\" t-valuef=\\"code\\"/>\\n                    <t t-set=\\"data_fields\\" t-valuef=\\"[&quot;code&quot;]\\"/>\\n                </t>\\n            </t>\\n            <t t-if=\\"len(current_website.language_ids) &gt; 1\\">\\n                <t t-call=\\"website.snippet_options_conditional_visibility\\">\\n                    <t t-set=\\"option_name\\">Idiomas</t>\\n                    <t t-set=\\"attribute_rule\\" t-valuef=\\"visibilityValueLangRule\\"/>\\n                    <t t-set=\\"save_attribute\\" t-valuef=\\"visibilityValueLang\\"/>\\n                    <t t-set=\\"attribute_name\\" t-valuef=\\"lang\\"/>\\n                    <t t-set=\\"model\\" t-valuef=\\"res.lang\\"/>\\n                    <t t-set=\\"call_with\\" t-valuef=\\"code\\"/>\\n                    <t t-set=\\"domain\\" t-translation=\\"off\\">[[\\"id\\", \\"in\\", <t t-out=\\"current_website.language_ids.ids\\"/>]]</t>\\n                    <t t-set=\\"data_fields\\" t-valuef=\\"[&quot;code&quot;]\\"/>\\n                </t>\\n            </t>\\n            <t t-call=\\"website.snippet_options_conditional_visibility\\">\\n                <t t-set=\\"option_name\\">Campaña UTM </t>\\n                <t t-set=\\"attribute_rule\\" t-valuef=\\"visibilityValueUtmCampaignRule\\"/>\\n                <t t-set=\\"save_attribute\\" t-valuef=\\"visibilityValueUtmCampaign\\"/>\\n                <t t-set=\\"attribute_name\\" t-valuef=\\"data-utm-campaign\\"/>\\n                <t t-set=\\"model\\" t-valuef=\\"utm.campaign\\"/>\\n                <t t-set=\\"call_with\\" t-valuef=\\"display_name\\"/>\\n            </t>\\n            <t t-call=\\"website.snippet_options_conditional_visibility\\">\\n                <t t-set=\\"option_name\\">Medio UTM</t>\\n                <t t-set=\\"attribute_rule\\" t-valuef=\\"visibilityValueUtmMediumRule\\"/>\\n                <t t-set=\\"save_attribute\\" t-valuef=\\"visibilityValueUtmMedium\\"/>\\n                <t t-set=\\"attribute_name\\" t-valuef=\\"data-utm-medium\\"/>\\n                <t t-set=\\"model\\" t-valuef=\\"utm.medium\\"/>\\n                <t t-set=\\"call_with\\" t-valuef=\\"display_name\\"/>\\n            </t>\\n            <t t-call=\\"website.snippet_options_conditional_visibility\\">\\n                <t t-set=\\"option_name\\">Fuente UTM</t>\\n                <t t-set=\\"attribute_rule\\" t-valuef=\\"visibilityValueUtmSourceRule\\"/>\\n                <t t-set=\\"save_attribute\\" t-valuef=\\"visibilityValueUtmSource\\"/>\\n                <t t-set=\\"attribute_name\\" t-valuef=\\"data-utm-source\\"/>\\n                <t t-set=\\"model\\" t-valuef=\\"utm.source\\"/>\\n                <t t-set=\\"call_with\\" t-valuef=\\"display_name\\"/>\\n            </t>\\n            <we-select string=\\"Usuarios\\" class=\\"o_we_sublevel_1\\" data-dependencies=\\"visibility_conditional\\" data-attribute-name=\\"data-logged\\" data-save-attribute=\\"visibilityValueLogged\\" data-no-preview=\\"true\\" data-attribute-default-value=\\"\\">\\n                <we-button data-select-value=\\"true\\">Visible para usuarios con sesión iniciada</we-button>\\n                <we-button data-select-value=\\"false\\">Visible para todos los usuarios</we-button>\\n                <we-button data-select-value=\\"\\">Visible para todos</we-button>\\n            </we-select>\\n        </we-collapse>\\n    </div>\\n\\n    <!-- Mobile/Desktop display options -->\\n    <div data-js=\\"DeviceVisibility\\" data-selector=\\"section .row &gt; div\\" data-exclude=\\".s_col_no_resize.row &gt; div, .s_masonry_block .s_col_no_resize\\">\\n        <we-row string=\\"Visibilidad\\">\\n            <t t-out=\\"_device_visibility_widgets\\"/>\\n        </we-row>\\n    </div>\\n\\n    <!-- Cookies Bar -->\\n    <div data-selector=\\"#website_cookies_bar\\" data-js=\\"CookiesBar\\" data-target=\\".modal\\">\\n        <we-select string=\\"Diseño\\" class=\\"o_we_inline\\">\\n            <we-button data-select-class=\\"o_cookies_discrete\\" data-select-layout=\\"discrete\\" data-trigger=\\"position_bottom,s_popup_size_full\\">Discreto</we-button>\\n            <we-button data-select-class=\\"o_cookies_classic\\" data-select-layout=\\"classic\\" data-trigger=\\"position_bottom,s_popup_size_full\\">Clásico</we-button>\\n            <we-button data-name=\\"layout_popup_opt\\" data-select-class=\\"o_cookies_popup\\" data-select-layout=\\"popup\\" data-trigger=\\"position_middle,s_popup_size_md\\">Ventana emergente</we-button>\\n        </we-select>\\n    </div>\\n\\n    <!-- Image position in grid -->\\n    <div data-js=\\"GridImage\\" data-selector=\\"img\\">\\n        <we-select string=\\"Posición\\">\\n            <we-button data-change-grid-image-mode=\\"cover\\">Portada</we-button>\\n            <we-button data-change-grid-image-mode=\\"contain\\">Contener</we-button>\\n        </we-select>\\n    </div>\\n\\n    <!-- Website Animate -->\\n    <div data-js=\\"WebsiteAnimate\\" data-selector=\\".o_animable, section .row &gt; div, img, .fa, .btn, .o_animated_text\\" data-exclude=\\"[data-oe-xpath], .o_not-animable, .s_col_no_resize.row &gt; div, .s_col_no_resize\\">\\n        <!-- Animation mode -->\\n        <we-row string=\\"Animación\\">\\n            <we-select data-dependencies=\\"!image_transform_opt\\" data-is-animation-type-selection=\\"true\\" data-no-preview=\\"true\\">\\n                <we-button data-animation-mode=\\"\\" data-select-class=\\"\\" data-name=\\"no_animation_opt\\">Ninguno</we-button>\\n                <we-button data-animation-mode=\\"onAppearance\\" data-force-animation=\\"true\\" data-select-class=\\"o_animate\\" data-name=\\"animation_on_appearance_opt\\">Cuando aparece</we-button>\\n                <we-button data-animation-mode=\\"onScroll\\" data-select-class=\\"o_animate o_animate_on_scroll\\" data-force-animation=\\"true\\" data-name=\\"animation_on_scroll_opt\\">Cuando se desliza</we-button>\\n                <we-button data-animation-mode=\\"onHover\\" data-select-class=\\"o_animate_on_hover\\" data-name=\\"animation_on_hover_opt\\">Al pasar el cursor por encima</we-button>\\n            </we-select>\\n            <we-button-group data-dependencies=\\"animation_on_scroll_opt\\" data-no-preview=\\"true\\" data-force-animation=\\"true\\">\\n                <we-button data-select-class=\\"\\">Entrada</we-button>\\n                <we-button data-select-class=\\"o_animate_out\\">Salida</we-button>\\n            </we-button-group>\\n        </we-row>\\n        <!-- Effect -->\\n        <we-select string=\\"Efecto\\" class=\\"o_we_sublevel_1\\" data-name=\\"animation_effect_opt\\">\\n            <we-button data-select-class=\\"\\" data-name=\\"o_anim_no_effect_opt\\" data-dependencies=\\"no_animation_opt\\">Ninguno</we-button>\\n            <we-button data-select-class=\\"o_anim_fade_in\\" data-trigger=\\"animation_direction_in_place_opt\\">Desvanecer</we-button>\\n            <we-button data-select-class=\\"o_anim_slide_in\\" data-name=\\"o_anim_slide_in_opt\\" data-trigger=\\"animation_direction_from_right_opt\\">Deslizar</we-button>\\n            <we-button data-select-class=\\"o_anim_bounce_in\\" data-trigger=\\"animation_direction_in_place_opt\\">Devuelto</we-button>\\n            <we-button data-select-class=\\"o_anim_rotate_in\\" data-name=\\"o_anim_rotate_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Rotar</we-button>\\n            <we-button data-select-class=\\"o_anim_zoom_out\\" data-trigger=\\"animation_direction_in_place_opt\\">Reducir</we-button>\\n            <we-button data-select-class=\\"o_anim_zoom_in\\" data-trigger=\\"animation_direction_in_place_opt\\">Ampliar</we-button>\\n            <we-button data-select-class=\\"o_anim_flash\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Flash</we-button>\\n            <we-button data-select-class=\\"o_anim_pulse\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Pulso</we-button>\\n            <we-button data-select-class=\\"o_anim_shake\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Agitar</we-button>\\n            <we-button data-select-class=\\"o_anim_tada\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Tada</we-button>\\n            <we-button data-select-class=\\"o_anim_flip_in_x\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Girar sobre eje X</we-button>\\n            <we-button data-select-class=\\"o_anim_flip_in_y\\" data-dependencies=\\"animation_on_appearance_opt\\" data-trigger=\\"animation_direction_in_place_opt\\">Girar sobre eje Y</we-button>\\n        </we-select>\\n        <!-- Direction -->\\n        <we-select string=\\"Dirección\\" class=\\"o_we_sublevel_1\\" data-name=\\"animation_direction_opt\\" data-force-animation=\\"true\\">\\n            <we-button data-select-class=\\"\\" data-name=\\"animation_direction_in_place_opt\\" data-dependencies=\\"!o_anim_slide_in_opt\\">En su lugar</we-button>\\n            <we-button data-select-class=\\"o_anim_from_right\\" data-name=\\"animation_direction_from_right_opt\\" data-dependencies=\\"!o_anim_rotate_opt\\">Desde la derecha</we-button>\\n            <we-button data-select-class=\\"o_anim_from_left\\" data-dependencies=\\"!o_anim_rotate_opt\\">Desde la izquierda</we-button>\\n            <we-button data-select-class=\\"o_anim_from_bottom\\" data-dependencies=\\"!o_anim_rotate_opt\\">Desde abajo</we-button>\\n            <we-button data-select-class=\\"o_anim_from_top\\" data-dependencies=\\"!o_anim_rotate_opt\\">Desde arriba</we-button>\\n            <we-button data-select-class=\\"o_anim_from_top_right\\" data-dependencies=\\"o_anim_rotate_opt\\">Desde arriba a la derecha</we-button>\\n            <we-button data-select-class=\\"o_anim_from_top_left\\" data-dependencies=\\"o_anim_rotate_opt\\">Desde arriba a la izquierda</we-button>\\n            <we-button data-select-class=\\"o_anim_from_bottom_right\\" data-dependencies=\\"o_anim_rotate_opt\\">Desde abajo a la derecha</we-button>\\n            <we-button data-select-class=\\"o_anim_from_bottom_left\\" data-dependencies=\\"o_anim_rotate_opt\\">Desde abajo a la izquierda</we-button>\\n        </we-select>\\n        <!-- Trigger -->\\n        <we-select string=\\"Activar\\" class=\\"o_we_sublevel_1\\" data-dependencies=\\"animation_on_appearance_opt\\" data-name=\\"animation_trigger_opt\\">\\n            <we-button data-select-class=\\"\\">Solo la primera vez</we-button>\\n            <we-button data-select-class=\\"o_animate_both_scroll\\">Siempre</we-button>\\n        </we-select>\\n        <!-- Intensity -->\\n        <we-range string=\\"Intensidad\\" class=\\"o_we_sublevel_1\\" data-name=\\"animation_intensity_opt\\" data-animation-intensity=\\"\\" data-min=\\"1\\" data-max=\\"100\\" data-step=\\"1\\" data-display-range-value=\\"true\\" data-no-preview=\\"true\\"/>\\n        <!-- Scroll Zone -->\\n        <we-row string=\\"Zona de desplazamiento\\" class=\\"o_we_sublevel_1\\">\\n            <we-input data-unit=\\"%\\" data-step=\\"1\\" data-dependencies=\\"animation_on_scroll_opt\\" data-no-preview=\\"true\\" data-select-data-attribute=\\"\\" data-attribute-name=\\"scrollZoneStart\\" data-force-animation=\\"true\\"/>\\n            <span class=\\"mx-2\\">a</span>\\n            <we-input data-unit=\\"%\\" data-step=\\"1\\" data-dependencies=\\"animation_on_scroll_opt\\" data-no-preview=\\"true\\" data-select-data-attribute=\\"\\" data-attribute-name=\\"scrollZoneEnd\\" data-force-animation=\\"true\\"/>\\n        </we-row>\\n        <!-- Start After -->\\n        <we-input string=\\"Iniciar después de\\" class=\\"o_we_sublevel_1 o_we_small_input\\" data-dependencies=\\"animation_on_appearance_opt\\" data-name=\\"animation_delay_opt\\" data-select-style=\\"0s\\" data-css-property=\\"animation-delay\\" data-unit=\\"s\\"/>\\n        <!-- Duration -->\\n        <we-input string=\\"Duración\\" class=\\"o_we_sublevel_1 o_we_small_input\\" data-dependencies=\\"animation_on_appearance_opt\\" data-select-style=\\"0.4s\\" data-css-property=\\"animation-duration\\" data-unit=\\"s\\"/>\\n    </div>\\n\\n    <!-- Text highlight effects -->\\n    <div data-js=\\"TextHighlight\\" data-selector=\\".o_text_highlight\\">\\n        <!-- Text highlight style -->\\n        <we-select string=\\"Resaltar\\" data-name=\\"text_highlight_opt\\" class=\\"o_we_select_grid\\">\\n            <div class=\\"grid gap-0\\">\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_underline\\" data-set-text-highlight=\\"underline\\" data-select-label=\\"Underline\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_freehand_1\\" data-set-text-highlight=\\"freehand_1\\" data-select-label=\\"Freehand 1\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_freehand_2 o_text_highlight_fill\\" data-set-text-highlight=\\"freehand_2\\" data-select-label=\\"Freehand 2\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_freehand_3 o_text_highlight_fill\\" data-set-text-highlight=\\"freehand_3\\" data-select-label=\\"Freehand 3\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_double\\" data-set-text-highlight=\\"double\\" data-select-label=\\"Double\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_wavy\\" data-set-text-highlight=\\"wavy\\" data-select-label=\\"Wavy\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_circle_1\\" data-set-text-highlight=\\"circle_1\\" data-select-label=\\"Circle 1\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_circle_2 o_text_highlight_fill\\" data-set-text-highlight=\\"circle_2\\" data-select-label=\\"Circle 2\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_circle_3 o_text_highlight_fill\\" data-set-text-highlight=\\"circle_3\\" data-select-label=\\"Circle 3\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_over_underline\\" data-set-text-highlight=\\"over_underline\\" data-select-label=\\"Over And Underline\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_scribble_1\\" data-set-text-highlight=\\"scribble_1\\" data-select-label=\\"Scribble 1\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_scribble_2 o_text_highlight_fill\\" data-set-text-highlight=\\"scribble_2\\" data-select-label=\\"Scribble 2\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_scribble_3 o_text_highlight_fill\\" data-set-text-highlight=\\"scribble_3\\" data-select-label=\\"Scribble 3\\"/>\\n                <we-button class=\\"g-col-4 text-black-50\\" data-select-class=\\"o_text_highlight_scribble_4 o_text_highlight_fill\\" data-set-text-highlight=\\"scribble_4\\" data-select-label=\\"Scribble 4\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_jagged\\" data-set-text-highlight=\\"jagged\\" data-select-label=\\"Jagged\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_cross\\" data-set-text-highlight=\\"cross\\" data-select-label=\\"Cross\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_diagonal\\" data-set-text-highlight=\\"diagonal\\" data-select-label=\\"Diagonal\\"/>\\n                <we-button class=\\"g-col-4\\" data-select-class=\\"o_text_highlight_strikethrough\\" data-set-text-highlight=\\"strikethrough\\" data-select-label=\\"Strikethrough\\"/>\\n                <we-button class=\\"g-col-4 text-black-50\\" data-select-class=\\"o_text_highlight_bold o_text_highlight_fill\\" data-set-text-highlight=\\"bold\\" data-select-label=\\"Bold\\"/>\\n                <we-button class=\\"g-col-4 text-black-50\\" data-select-class=\\"o_text_highlight_bold_1 o_text_highlight_fill\\" data-set-text-highlight=\\"bold_1\\" data-select-label=\\"Bold 1\\"/>\\n                <we-button class=\\"g-col-4 text-black-50\\" data-select-class=\\"o_text_highlight_bold_2 o_text_highlight_fill\\" data-set-text-highlight=\\"bold_2\\" data-select-label=\\"Bold 2\