1790	16	1789	1	1	new_page_template_about_s_three_columns	\N	website.new_page_template_about_s_three_columns	qweb	website/views/new_page_template_templates.xml	primary	{"en_US": "<data inherit_id=\\"website.new_page_template_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Our Story</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Our Mission</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Our Values</h3>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Step into our past and witness the transformation of a simple idea into an innovative force. Our journey, born in a garage, reflects the power of passion and hard work.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Our mission is to create transformative experiences and foster growth, driven by a relentless pursuit of innovation and a commitment to exceeding expectations.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Our values shape our culture, influence our decisions, and guide us in providing exceptional service. They reflect our dedication to integrity, collaboration, and client satisfaction.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_about_s_three_columns</attribute></xpath></data>", "es_AR": "<data inherit_id=\\"website.new_page_template_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Nuestra historia</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Nuestra misión</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Nuestros valores</h3>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Sumérjase en nuestro pasado y sea testigo de la transformación de una simple idea en una fuerza innovadora. Nuestra historia comenzó en un garaje, lo que refleja el poder de la pasión y el trabajo duro.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Nuestra misión es crear experiencias transformadoras y fomentar el crecimiento, gracias a una búsqueda constante de innovación y al compromiso de superar las expectativas.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Nuestros valores moldean nuestra cultura, influyen en nuestras decisiones y nos guían a la hora de ofrecer un servicio excepcional. Son el reflejo de nuestra dedicación a la integridad, la colaboración y la satisfacción del cliente.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_about_s_three_columns</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_s_three_columns" primary="True">\n    <xpath expr="//h3|//h4|//h5" position="replace">\n        <h3 class="card-title">Our Story</h3>\n    </xpath>\n    <xpath expr="(//h3|//h4|//h5)[2]" position="replace">\n        <h3 class="card-title">Our Mission</h3>\n    </xpath>\n    <xpath expr="(//h3|//h4|//h5)[3]" position="replace">\n        <h3 class="card-title">Our Values</h3>\n    </xpath>\n    <xpath expr="//p" position="replace">\n        <p class="card-text">Step into our past and witness the transformation of a simple idea into an innovative force. Our journey, born in a garage, reflects the power of passion and hard work.</p>\n    </xpath>\n    <xpath expr="(//p)[2]" position="replace">\n        <p class="card-text">Our mission is to create transformative experiences and foster growth, driven by a relentless pursuit of innovation and a commitment to exceeding expectations.</p>\n    </xpath>\n    <xpath expr="(//p)[3]" position="replace">\n        <p class="card-text">Our values shape our culture, influence our decisions, and guide us in providing exceptional service. They reflect our dedication to integrity, collaboration, and client satisfaction.</p>\n    </xpath>\n<xpath expr="." position="attributes"><attribute name="t-name">website.new_page_template_about_s_three_columns</attribute></xpath></data>\n\n	f	t	2026-10-30 15:04:32.762047	2026-10-30 15:04:32.762047	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f
1792	16	1791	1	1	new_page_template_landing_2_s_three_columns	\N	website.new_page_template_landing_2_s_three_columns	qweb	website/views/new_page_template_templates.xml	primary	{"en_US": "<data inherit_id=\\"website.new_page_template_landing_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Personalized Workouts</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Nutritional Guidance</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Progress Tracking</h3>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Our experienced fitness coaches design workouts that align with your goals, fitness level, and preferences.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Achieve holistic health with personalized nutritional advice that complements your workouts, promoting overall well-being.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">We monitor your progress meticulously, adjusting your plan as needed to ensure continuous improvement and results.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_landing_2_s_three_columns</attribute></xpath></data>", "es_AR": "<data inherit_id=\\"website.new_page_template_landing_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Rutinas personalizadas</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Orientación nutricional</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Seguimiento del progreso</h3>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Nuestros entrenadores expertos diseñan rutinas que se adaptan a sus objetivos, nivel de condición física y preferencias.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Consiga un estado de salud integral con consejos nutricionales personalizados que complementen sus entrenamientos, lo que le proporcionará un bienestar general.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Monitoreamos su progreso de forma meticulosa y ajustamos su plan según sea necesario para garantizar mejoras y resultados constantes.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_landing_2_s_three_columns</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_landing_s_three_columns" primary="True">\n    <xpath expr="//h3|//h4|//h5" position="replace">\n        <h3 class="card-title">Personalized Workouts</h3>\n    </xpath>\n    <xpath expr="(//h3|//h4|//h5)[2]" position="replace">\n        <h3 class="card-title">Nutritional Guidance</h3>\n    </xpath>\n    <xpath expr="(//h3|//h4|//h5)[3]" position="replace">\n        <h3 class="card-title">Progress Tracking</h3>\n    </xpath>\n    <xpath expr="//p" position="replace">\n        <p class="card-text">Our experienced fitness coaches design workouts that align with your goals, fitness level, and preferences.</p>\n    </xpath>\n    <xpath expr="(//p)[2]" position="replace">\n        <p class="card-text">Achieve holistic health with personalized nutritional advice that complements your workouts, promoting overall well-being.</p>\n    </xpath>\n    <xpath expr="(//p)[3]" position="replace">\n        <p class="card-text">We monitor your progress meticulously, adjusting your plan as needed to ensure continuous improvement and results.</p>\n    </xpath>\n<xpath expr="." position="attributes"><attribute name="t-name">website.new_page_template_landing_2_s_three_columns</attribute></xpath></data>\n\n	f	t	2026-10-30 15:04:32.762047	2026-10-30 15:04:32.762047	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f
