1795	16	1794	1	1	new_page_template_services_0_s_three_columns	\N	website.new_page_template_services_0_s_three_columns	qweb	website/views/new_page_template_templates.xml	primary	{"en_US": "<data inherit_id=\\"website.new_page_template_services_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Wellness Coaching</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Strength Training: </h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Weight Loss Transformation</h3>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Our Coaching combines personalized fitness plans with mindfulness practices, ensuring you achieve harmony in your body and peace in your mind.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">This coaching program offers specialized strength-focused workouts, nutrition guidance, and expert coaching. Elevate your fitness level and achieve feats you never thought possible.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">With personalized fitness plans, tailored nutrition guidance, and consistent support, you'll shed unwanted pounds while building healthy habits that last.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_services_0_s_three_columns</attribute></xpath></data>", "es_AR": "<data inherit_id=\\"website.new_page_template_services_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Coaching de bienestar</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Entrenamiento de fuerza: </h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Transformación de pérdida de peso</h3>\\n    </xpath>\\n    <xpath expr=\\"//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Nuestro asesoramiento combina planes personalizados de entrenamiento físico con prácticas de mindfulness para garantizar la armonía del cuerpo y de la mente.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[2]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Este programa de entrenamiento ofrece entrenamientos especializados centrados en la fuerza, orientación nutricional y asesoramiento especializado. Mejore su forma física y consiga logros que nunca creyó posibles.</p>\\n    </xpath>\\n    <xpath expr=\\"(//p)[3]\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Gracias a las rutinas y planes nutritivos personalizados, así como a un apoyo constante, podrá deshacerse de los kilos de más y crear hábitos saludables constantes.</p>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_services_0_s_three_columns</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_services_s_three_columns" primary="True">\n    <xpath expr="//h3|//h4|//h5" position="replace">\n        <h3 class="card-title">Wellness Coaching</h3>\n    </xpath>\n    <xpath expr="(//h3|//h4|//h5)[2]" position="replace">\n        <h3 class="card-title">Strength Training: </h3>\n    </xpath>\n    <xpath expr="(//h3|//h4|//h5)[3]" position="replace">\n        <h3 class="card-title">Weight Loss Transformation</h3>\n    </xpath>\n    <xpath expr="//p" position="replace">\n        <p class="card-text">Our Coaching combines personalized fitness plans with mindfulness practices, ensuring you achieve harmony in your body and peace in your mind.</p>\n    </xpath>\n    <xpath expr="(//p)[2]" position="replace">\n        <p class="card-text">This coaching program offers specialized strength-focused workouts, nutrition guidance, and expert coaching. Elevate your fitness level and achieve feats you never thought possible.</p>\n    </xpath>\n    <xpath expr="(//p)[3]" position="replace">\n        <p class="card-text">With personalized fitness plans, tailored nutrition guidance, and consistent support, you'll shed unwanted pounds while building healthy habits that last.</p>\n    </xpath>\n<xpath expr="." position="attributes"><attribute name="t-name">website.new_page_template_services_0_s_three_columns</attribute></xpath></data>\n\n	f	t	2026-10-30 15:04:32.762047	2026-10-30 15:04:32.762047	f	\N	\N	\N	\N	\N	\N	\N	\N	\N	f
1797	16	1796	1	1	new_page_template_team_0_s_three_columns	\N	website.new_page_template_team_0_s_three_columns	qweb	website/views/new_page_template_templates.xml	primary	{"en_US": "<data inherit_id=\\"website.new_page_template_team_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Tony Fred, CEO</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Mich Stark, COO</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Aline Turner, CTO</h3>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('card')]//p|//div[hasclass('card-wrapper')]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Founder and chief visionary, Tony is the driving force behind the company. He loves to keep his hands full by participating in the development of the software, marketing, and customer experience strategies.</p>\\n    </xpath>\\n    <xpath expr=\\"(//div[hasclass('card')])[2]//p|(//div[hasclass('card-wrapper')])[2]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Mich loves taking on challenges. With his multi-year experience as Commercial Director in the software industry, Mich has helped the company to get where it is today. Mich is among the best minds.</p>\\n    </xpath>\\n    <xpath expr=\\"(//div[hasclass('card')])[3]//p|(//div[hasclass('card-wrapper')])[3]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Aline is one of the iconic people in life who can say they love what they do. She mentors 100+ in-house developers and looks after the community of thousands of developers.</p>\\n    </xpath>\\n    <xpath expr=\\"//img\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_1\\" class=\\"card-img-top\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[2]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_2\\" class=\\"card-img-top\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[3]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_3\\" class=\\"card-img-top\\"/>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_team_0_s_three_columns</attribute></xpath></data>", "es_AR": "<data inherit_id=\\"website.new_page_template_team_s_three_columns\\" primary=\\"True\\">\\n    <xpath expr=\\"//h3|//h4|//h5\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Tony Fred, CEO</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[2]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Mich Stark, COO</h3>\\n    </xpath>\\n    <xpath expr=\\"(//h3|//h4|//h5)[3]\\" position=\\"replace\\">\\n        <h3 class=\\"card-title\\">Aline Turner, CTO</h3>\\n    </xpath>\\n    <xpath expr=\\"//div[hasclass('card')]//p|//div[hasclass('card-wrapper')]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Tony es el fundador y director, además también impulsa a la empresa. Le encanta participar en el desarrollo del software y en las estrategias de marketing y de experiencia del cliente.</p>\\n    </xpath>\\n    <xpath expr=\\"(//div[hasclass('card')])[2]//p|(//div[hasclass('card-wrapper')])[2]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Mich cuenta con varios años de experiencia como director comercial en el sector informático. Le encantan los desafíos y ha ayudado a la empresa a llegar hasta donde está hoy. En definitiva, tiene una de las mejores mentes.</p>\\n    </xpath>\\n    <xpath expr=\\"(//div[hasclass('card')])[3]//p|(//div[hasclass('card-wrapper')])[3]//p\\" position=\\"replace\\">\\n        <p class=\\"card-text\\">Aline es una de las personas icónicas en la vida que puede decir que ama lo que hace. Es mentora de más de 100 desarrolladores internos y supervisa a una comunidad de miles de desarrolladores.</p>\\n    </xpath>\\n    <xpath expr=\\"//img\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_1\\" class=\\"card-img-top\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[2]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_2\\" class=\\"card-img-top\\"/>\\n    </xpath>\\n    <xpath expr=\\"(//img)[3]\\" position=\\"replace\\">\\n        <img alt=\\"\\" src=\\"/web/image/website.s_company_team_image_3\\" class=\\"card-img-top\\"/>\\n    </xpath>\\n<xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">website.new_page_template_team_0_s_three_columns</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data inherit_id="website.new_page_template_team_s_three_columns" primary="True">\n    <xpath expr="//h3|//h4|//h5" position="replace">\n        <h3 class="card-title">Tony Fred, CEO</h3>\n    </xpath>\n    <xpath expr="(//h3|//h4|//h5)[2]" position="replace">\n        <h3 class="card-title">Mich Stark, COO</h3>\n    </xpath>\n    <xpath expr="(//h3|//h4|//h5)[3]" position="replace">\n        <h3 class="card-title">Aline Turner, CTO</h3>\n    </xpath>\n    <xpath expr="//div[hasclass('card')]//p|//div[hasclass('card-wrapper')]//p" position="replace">\n        <p class="card-text">Founder and chief visionary, Tony is the driving force behind the company. He loves to keep his hands full by participating in the development of the software, marketing, and customer experience strategies.</p>\n    </xpath>\n    <xpath expr="(//div[hasclass('card')])[2]//p|(//div[hasclass('card-wrapper')])[2]//p" position="replace">\n        <p class="card-text">Mich loves taking on challenges. With his multi-year experience as Commercial Director in the software industry, Mich has helped the company to get where it is today. Mich is among the best minds.</p>\n    </xpath>\n    <xpath expr="(//div[