und-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;\\">\\n                <tr><td valign=\\"top\\" style=\\"font-size: 13px;\\">\\n                    <div>\\n                        Apreciable <t t-out=\\"object.user_id.name or ''\\">Marc Demo</t>,<br> <br>\\n                        ¡Le damos la bienvenida al portal de <t t-out=\\"object.user_id.company_id.name\\">SuEmpresa</t>!<br><br>\\n                        Creamos una cuenta para usted, estos son los datos para iniciar sesión: <t t-out=\\"object.user_id.login\\">demo</t><br><br>\\n                        Haga clic en el botón de abajo para elegir una contraseña y activar su cuenta.\\n                        <div style=\\"margin: 16px 0px 16px 0px; text-align: center;\\">\\n                            <a t-att-href=\\"object.user_id.signup_url\\" style=\\"display: inline-block; padding: 10px; text-decoration: none; font-size: 12px; background-color: #875A7B; color: #fff; border-radius: 5px;\\">\\n                                <strong>Activar cuenta</strong>\\n                            </a>\\n                        </div>\\n                        <t t-out=\\"object.wizard_id.welcome_message or ''\\">Bienvenido al portal de nuestra empresa.</t>\\n                    </div>\\n                </td></tr>\\n                <tr><td style=\\"text-align:center;\\">\\n                  <hr width=\\"100%\\" style=\\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;\\">\\n                </td></tr>\\n            </table>\\n        </td>\\n    </tr>\\n    <!-- PIE DE PÁGINA -->\\n    <tr>\\n        <td align=\\"center\\" style=\\"min-width: 590px;\\">\\n            <table border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\" width=\\"590\\" style=\\"min-width: 590px; background-color: white; font-size: 11px; padding: 0px 8px 0px 8px; border-collapse:separate;\\">\\n                <tr><td valign=\\"mi