7	434	\N	\N	\N	1	1	account/data/mail_template_data.xml	{{ object.partner_id.lang }}	account.move	{{ (object.invoice_user_id.email_formatted or object.company_id.email_formatted or user.email_formatted) }}	\N	{{ object.partner_id.id }}	\N	\N	\N	\N	{"en_US": "Invoice: Sending", "es_AR": "Factura: Envío"}	{"en_US": "Sent to customers with their invoices in attachment", "es_AR": "Enviado a los clientes con las facturas adjuntas"}	{"en_US": "{{ object.company_id.name }} Invoice (Ref {{ object.name or 'n/a' }})", "es_AR": "{{ object.company_id.name }} Factura (Ref {{ object.name or 'n/a' }})"}	{"en_US": "<div style=\\"margin: 0px; padding: 0px;\\">\\n    <p style=\\"margin: 0px; padding: 0px; font-size: 13px;\\">\\n        Dear\\n        <t t-if=\\"object.partner_id.parent_id\\">\\n            <t t-out=\\"object.partner_id.name or ''\\">Brandon Freeman</t> (<t t-out=\\"object.partner_id.parent_id.name or ''\\">Azure Interior</t>),\\n        </t>\\n        <t t-else=\\"\\">\\n            <t t-out=\\"object.partner_id.name or ''\\">Brandon Freeman</t>,\\n        </t>\\n        <br><br>\\n        Here is your\\n        <t t-if=\\"object.name\\">\\n            invoice <span style=\\"font-weight:bold;\\" t-out=\\"object.name or ''\\">INV/2021/05/0005</span>\\n        </t>\\n        <t t-else=\\"\\">\\n            invoice\\n        </t>\\n        <t t-if=\\"object.invoice_origin\\">\\n            (with reference: <t t-out=\\"object.invoice_origin or ''\\">SUB003</t>)\\n        </t>\\n        amounting in <span style=\\"font-weight:bold;\\" t-out=\\"format_amount(object.amount_total, object.currency_id) or ''\\">$ 143,750.00</span>\\n        from <t t-out=\\"object.company_id.name or ''\\">YourCompany</t>.\\n        <t t-if=\\"object.payment_state in ('paid', 'in_payment')\\">\\n            This invoice is already paid.\\n        </t>\\n        <t t-else=\\"\\">\\n            Please remit payment at your earliest convenience.\\n            <t t-if=\\"object.payment_reference\\">\\n                <br><br>\\n                Please use the following communication for your payment: <strong t-out=\\"object.payment_reference or ''\\">INV/2021/05/0005</strong>\\n                <t t-if=\\"object.partner_bank_id\\">\\n                    on the account <strong t-out=\\"object.partner_bank_id.acc_number\\"></strong>\\n                </t>\\n                .\\n            </t>\\n        </t>\\n        <t t-if=\\"hasattr(object, 'timesheet_count') and object.timesheet_count\\">\\n            <br><br>\\n            PS: you can review your timesheets <a t-att-href=\\"'my/timesheets?search_in=invoice&amp;search=%s' % object.name\\">from the portal.</a>\\n        </t>\\n        <br><br>\\n        Do not hesitate to contact us if you have any questions.\\n        <t t-if=\\"not is_html_empty(object.invoice_user_id.signature)\\">\\n            <br><br>\\n            <t t-out=\\"object.invoice_user_id.signature or ''\\">--<br>Mitchell Admin</t>\\n        </t>\\n    </p>\\n</div>\\n            ", "es_AR": "<div style=\\"margin: 0px; padding: 0px;\\">\\n    <p style=\\"margin: 0px; padding: 0px; font-size: 13px;\\">\\n        Apreciable\\n        <t t-if=\\"object.partner_id.parent_id\\">\\n            <t t-out=\\"object.partner_id.name or ''\\">Brandon Freeman</t> (<t t-out=\\"object.partner_id.parent_id.name or ''\\">Azure Interior</t>),\\n        </t>\\n        <t t-else=\\"\\">\\n            <t t-out=\\"object.partner_id.name or ''\\">Brandon Freeman</t>,\\n        </t>\\n        <br><br>\\n        A continuación encontrarás tu\\n        <t t-if=\\"object.name\\">\\n            factura <span style=\\"font-weight:bold;\\" t-out=\\"object.name or ''\\">INV/2021/05/0005</span>\\n        </t>\\n        <t t-else=\\"\\">\\n            factura\\n        </t>\\n        <t t-if=\\"object.invoice_origin\\">\\n            (con referencia: <t t-out=\\"object.invoice_origin or ''\\">SUB003</t>)\\n        </t>\\n        por <span style=\\"font-weight:bold;\\" t-out=